/* AMERICAN DICTATOR, cs deck translations (lazy-loaded). Falls back to English per field. */
AD.CARDT.cs = {"a-let-this-go":{"t":"„Doufám, že to dokážete“","x":"Požádal jste všechny ostatní, aby opustili místnost. Ředitelka Quist tu ještě je. Vyšetřování vašeho poradce pro národní bezpečnost běží devět týdnů a vy se k němu chystáte něco říct.","c":[["„Doufám, že najdete způsob, jak to nechat být.“","O dvacet minut později si to zapíše ve svém autě, opatří datem a rozdá kopie třem lidem. Slovo „doufám“ se pak dva roky pitvá u soudu."],["O případu neříkejte nic. Mluvte o čemkoli jiném.","Jedenáct minut o politice vůči rukojmím. Odchází zmatená a nic si nezapíše, což je jediný výsledek, který vám skutečně pomůže."],["Zeptejte se jí oficiálně, se záznamem, za přítomnosti právníka.","Nevhodná otázka za přítomnosti svědka mění popíratelný rozhovor v zdokumentovaný, ale aspoň je to rozhovor, který dokážete obhájit."],["Požádejte ji, ať raději jako odvedení pozornosti vyšetřuje vás.","Otevře spis. Je to skutečný spis se skutečným číslem jednacím. V roce 2029 je stále otevřený a nikdo ze zúčastněných to takhle nechtěl."]]},"a-no-quid":{"t":"Tři slova","x":"Kaylee to spočítala: stejnou třízlovou latinskou frázi jste za čtyři dny použil jedenáctkrát. „Pane, tuhle frázi nikdo ve veřejném životě deset let nepoužil. Teď je na hrnku na kávu.“","c":[["Použijte ji znovu. Hlasitěji. Je to dobrá fráze.","Opakovaným popíráním něčeho, na co se nikdo neptal, si sami vymyslíte otázku. Do třetího týdne je fráze zkratkou přesně pro to, co popírá."],["Přestaňte ji úplně používat. Nikdy víc.","Mlčení to za devět dní umoří hlady. Je to správné rozhodnutí, a zevnitř se to cítí přesně jako prohra."],["Zveřejněte záznam hovoru a nechte si ho lidi přečíst.","Je horší než shrnutí a lepší než spekulace. Zveřejnění zabije čtyři konkurenční fámy a odstartuje jednu pravdivou."],["Prodávejte ten hrnek na kávu.","Čtyři sta tisíc kusů po 28 dolarech, druhý nejprodávanější artikl, jaký hnutí kdy vyrobilo, a přímo na boku má vytištěnou latinu pro „není to úplatek“."]]},"a-withheld-aid":{"t":"Pozastávka","x":"„Čtyři sta milionů dolarů, schválených, závazně přidělených, a teď pozastavených, přičemž stopa vede zpátky do téhle budovy.“ Lyle vzhlédne. „Nikdo na ministerstvu mi neumí říct, kdo pozastávku nařídil, ani proč.“","c":[["Ponechte pozastávku. Bez udání důvodu.","Nevysvětlená pozastávka schválených peněz vyvolá čtyři samostatná šetření, dvě z nich ze zákona povinná, a ani jednomu se nevyhnete."],["Uvolněte je. Řekněte, že šlo o kontrolu.","Uvolněny s 55denním zpožděním a dvouřádkovým vysvětlením. Auditor si zpoždění všimne. Nikdo jiný ne."],["Ponechte je a svažte to s výslovně formulovanou podmínkou.","Písemná podmínka je nástroj politiky. Nepsaná je laskavost. Sepsat ji je z obou špatných možností ta méně katastrofální."],["Uvolněte je v měně, kterou nemohou utratit.","Převod dorazí v jednotce, kterou nikdo nepoužil od roku 1971. Jejich ministerstvo financí stráví čtyři měsíce převodem a stejně pošle děkovný dopis."]]},"a-fifty-forty-eight":{"t":"Padesát ku čtyřiceti osmi","x":"Hal má sečteno: padesát pro, čtyřicet osm proti, a dva členové se rozhodnou až v poslední hodině. Slyšení bylo mimořádné způsobem, na který nikdo v místnosti nezapomene.","c":[["Prosaďte hlasování ještě dnes večer. Dva hlasy jsou většina.","Potvrzen o dva hlasy. Slouží třicet let a slyšení se pak přehrává u každého dalšího potvrzování, oběma stranami, z opačných důvodů."],["Pozastavte hlasování na týden kvůli doplňujícímu šetření.","Šetření nevyřeší nic ani jedním směrem. O devět dní později je potvrzen poměrem 53:45. Ten týden navíc vás nic nestojí a čtyřem senátorům kupuje politické krytí."],["Stáhněte ho. Nominujte dalšího kandidáta.","Náhradník je potvrzen 61:39 a je podle všech měřítek spolehlivěji na vaší straně. Vaše základna vnímá stažení jako naprostou, neodpustitelnou porážku."],["Nominujte oba. Dvě místa, jedno hlasování.","Volné místo je přesně jedno. Druhá nominace se přesto podá a čtyři roky visí v senátním kalendáři, formálně, věčně nevyřízená."]]},"a-eight-days":{"t":"Osm dní do voleb","x":"Soudce zemřel osm dní před volbami. Bo: „Žádné pravidlo tomu nebrání. Existuje ale výrok, který v roce 2016 pronesli čtyři senátoři a teď si ho budou muset postupně, na kameru, spolknout.“","c":[["Potvrďte ho před volbami. Osm dní je osm dní.","Složí přísahu se šesti dny v rezervě. Čtyři senátoři si postupně na kameru spolknou svůj starý výrok, a přesto jsou všichni znovu zvoleni."],["Nominujte teď, potvrďte až potom. Stejný výsledek, méně kritiky.","Identický výsledek o čtrnáct dní později a se třetinovým mediálním pokrytím. Ukázalo se, že jedinou proměnnou, na které záleželo, bylo načasování, a bylo cennější než celá argumentace."],["Nechte to na tom, kdo vyhraje.","Prohrajete volby i to místo. Je to nejzásadovější věc, kterou za čtyři roky uděláte, a stojí vás to čtyři vztahy uvnitř vlastní strany."],["Potvrďte ho na místo, které není volné.","Desátý soudce je potvrzen k soudu, který má devět míst. Dostaví se, dostane kancelář a čtyři roky nenápadně dělá právní výzkum."]]},"a-order-struck":{"t":"Zrušeno natrvalo","x":"Soudkyně natrvalo zrušila váš příkaz proti firmě, v odůvodnění, které devětkrát použije slovo „protiústavní“. Sy: „Nezakázala ho, pane. Zneplatnila ho. Není proti čemu se odvolat.“","c":[["Napadněte rozhodnutí. Podepište téměř identický příkaz.","Druhý příkaz zneplatní za jedenáct dní tatáž soudkyně, obsáhle citující vlastní odůvodnění a přikládající první příkaz jako důkazní materiál."],["Podřiďte se. Obnovte prověrky. Neříkejte nic.","Firma je do čtrnácti dnů plně odškodněna. Čtyři jiné firmy, které už tiše ustoupily, své ústupky odvolají, což je ta skutečná cena."],["Podřiďte se, ale útočte na firmu přes zadávání zakázek.","Žádný příkaz, žádné rozhodnutí, žádné titulky, jen smlouvy, které se přestanou tiše obnovovat. Funguje to a žádný soudce nemá co zneplatnit."],["Najměte tu soudkyni.","Odmítne dopisem o čtyřech větách. Dopis je založen do spisu, zveřejní se a stane se nejvtipnějším dokumentem podaným za celý rok."]]},"a-accountability-order":{"t":"Příkaz o odpovědnosti","x":"„Příkaz nařizující agenturám prošetřit chování jmenovaných bývalých úředníků.“ Bo otočí stránku. „Pane, čtyři z těch jmen vás osobně vyšetřovali. Jednomu je 81 let a je v důchodu.“","c":[["Podepište ho. Všechna jména.","Nejdřív prověrky, pak osobní spisy, pak revize penzí. Nikdy nikdo není obžalován. Přesto se udělá všechno, protože nic z toho obžalobu nevyžadovalo."],["Podepište ho, ale vyškrtněte ty v důchodu.","Ušetřit toho 81letého je v médiích celý rozdíl mezi „politikou“ a „vendetou“, a v ničem jiném vůbec."],["Nepodepisujte. Místo toho nařiďte revizi revizí.","Metarevize podá zprávu za čtrnáct měsíců, najde procesní nesrovnalosti na všech stranách a neuspokojí nikoho, což je přesně k čemu revize slouží."],["Podepište ho a přidejte na seznam i vlastní jméno.","Prošetří vás vlastní ministerstvo podle vašeho vlastního příkazu. Za devět týdnů vás očistí a to očištění má hodnotu přesně takovou, kolik stálo ho vyrobit."]]},"a-ethics-divest":{"t":"Brífink o odprodeji majetku","x":"Miriam Applewhiteová předkládá standardní balíček: buď majetek rovnou prodat, nebo ho svěřit do skutečného slepého fondu spravovaného cizí osobou. „Existuje ještě třetí věc, které lidé říkají slepý fond a přitom ji svěří vlastním dětem. Není slepá, pane. Je to jen fond.“","c":[["Fond. Spravovaný rodinou. Nazvěte ho slepým.","O jeho výnosech se dozvídáte u večeře. Ve všech podáních se označuje za slepý a všechna podání jsou, formálně vzato, přesná co do papírování."],["Úplný odprodej. Prodejte všechno.","Stojí to jmění a natrvalo to eliminuje celou kategorii kauz. Ocenit to dokážete tak za tři roky."],["Ponechte si všechno. Prezident nemůže mít střet zájmů.","Právní pozice se skutečnou oporou v zákoně, ale bez jediné opory v padesáti letech praxe. Miriam v březnu rezignuje a v červnu svědčí."],["Svěřte ho fondu spravovanému cizí osobou, kterou pak zaměstnáte.","O jedenáct týdnů později je jmenován do federální poradní rady. Čtyři novináři si toho všimnou téhož odpoledne a ani jeden nedokáže prokázat souvislost."]]},"a-gift-log":{"t":"Evidence darů","x":"Jedenáct set inauguračních darů od zahraničních vlád. Cokoli nad stanovený limit ze zákona patří státu, ne vám. Položka 402 je kůň z ryzího zlata. Položka 403 je ještě větší.","c":[["Zapište je do evidence. Koně si odkupte za odhadní cenu.","Naprosto legální, plně zdokumentované, a stojí to 600 000 dolarů za dva zlaté koně, které jste nikdy nechtěl a nemáte je kde v budově vystavit."],["Zapište je jako vystavené v rezidenci. Ponechte si je.","Rezidence je vaše. „Vystavení“ je chodba. Podle jakéhokoli běžného výkladu toho slova si koně prostě ponechal."],["Vydražte celou sbírku ve prospěch veteránů. Veřejně.","Za odpoledne se vybere 2,1 milionu dolarů. Ceremoniální dýka připadne dvanáctiletému dítěti, což vyvolá krátký, upřímně roztomilý mezinárodní incident."],["Nechte koně roztavit. Razte z nich mince s vaší tváří.","Darující vláda si vyžádá fotografii koní pro vlastní archiv. Místo toho jí pošlete fotografii mincí."]]},"a-property-billing":{"t":"Ceník","x":"Duane má faktury. Ochranka zaplatila vašemu vlastnímu resortu za čtyři měsíce 1,1 milionu dolarů na ubytování. „Pane, musíme bydlet tam, kde bydlíte vy. A cenu určujete vy.“","c":[["Ponechte cenu. Je to tržní sazba.","Daňový poplatník teď platí prezidentovi za to, že chrání prezidenta v prezidentově vlastním hotelu. Je to zveřejněné, položkově vyčíslené, naprosto legální, a v tom je celý problém."],["Účtujte jim jeden dolar ročně.","Levné, teatrální a zdrcujícím způsobem účinné gesto, které zabije celou kauzu za cenu jednoho sendviče."],["Bydlete někde, co nevlastníte.","Camp David tři různí poradci označí za „vlastně fajn“. Po druhé návštěvě se tam už nikdy nevrátíte."],["Účtujte jim, a pak si sami sobě naúčtujte za způsobené nepříjemnosti.","Faktura od vás, vám, proplacená vládou, za obtíže způsobené vaší vlastní ochrankou. Projde. Nikdo nedokáže zjistit, kdo ji schválil."]]},"a-family-desk":{"t":"Stůl v Západním křídle","x":"Ivy by ráda dostala kancelář v Západním křídle, bezpečnostní prověrku a neplacený vyšší titul. Prověrka je ta část, na kterou dvakrát písemně upozornili kariérní bezpečnostní pracovníci.","c":[["Všechny tři. Přehlédněte varování.","Je skutečně schopná a to místo by nemohlo připadnout nikomu, kdo by nebyl vaše dcera. Obojí je pravda, a do novin se dostane jen jedno z toho."],["Titul a kancelář. Bez prověrky.","Na porady stejně chodí, ze židle u dveří, a předčí čtyři potvrzené úředníky, aniž by kdy viděla utajovanou stránku."],["Žádní příbuzní v budově.","Správné rozhodnutí, tečka. Zároveň to připraví o jediného živého člověka, který by vám v malé místnosti řekl pravdu."],["Dejte jí prověrku, a zároveň prověřte i ta varování.","Dva kariérní úředníci, kteří vznesli námitky, jsou zasvěceni přímo do toho programu, proti kterému protestovali. Oba okamžitě protestují znovu, tentokrát podstatně podrobněji."]]},"a-columbia":{"t":"Druhá univerzita","x":"Čtyři sta milionů dolarů, jedna univerzita, a seznam požadavků ohledně politiky protestů a dohledu nad katedrami. Ollis: „Ta první se zlomila rychle. Tahle má větší nadační fond a horšího právníka.“","c":[["Zrušte to. Celých čtyři sta milionů.","Za devět týdnů se zlomí a přijmou externí dohled nad jednou katedrou. Jedenáct dalších univerzit si přečte dohodu a rovnou přeskočí telefonát."],["Zrušte polovinu. Lékařský výzkum nechte být.","Ušetřit onkologické laboratoře odstraní jediný argument, který na veřejnost skutečně zabíral. Stejná páka, žádná fotka zavřené klinické studie."],["Financujte v plné výši. Útočte místo toho jen slovně.","Slova nic nestojí a nic nemění. Univerzita vás naprosto ignoruje a počet přihlášek stejně stoupne o 14 procent."],["Zrušte financování a přihlaste se tam na seminář.","Absolvujete čtyři lekce kurzu ústavního práva na instituci, kterou zrovna odřezáváte od peněz. Přepis se objeví v roce 2044 a nečekaně se dobře čte."]]},"a-minors-care":{"t":"Věková hranice","x":"Dr. Pike má návrh. „Podmiňuje to federální financování tím, že nemocnice ukončí určitou kategorii péče pro osoby mladší 19 let. Čtyři dětské nemocnice ve státech, které jste vyhrál, přestanou fungovat v den, kdy to podepíšete.“","c":[["Podepište to. Devatenáct let a méně, bez výjimek.","Devět nemocnic se do čtrnácti dnů zastaví, u některých pacientů uprostřed léčby. Dva soudy to částečně pozastaví, ale nemocnice se stejně znovu nerozjedou, protože nemocnice se nikdy znovu nerozjedou."],["Podepište to s výjimkou pro pokračující léčbu.","Nikdo není odříznut uprostřed léčby. Dosáhne se cíle politiky, aniž by vznikly ty čtyři konkrétní případy, které by ji definovaly ve všech titulcích."],["Žádný příkaz. Místo toho financujte dlouhodobou studii.","Výsledky přijdou za devět let, s největším souborem dat, jaký kdy kdo sestavil. Obě strany ho selektivně citují a ani jedna neustoupí ani o píď."],["Nastavte věkovou hranici na 47.","Pokyn k formulaci vzal doslovně někdo, kdo se nechtěl ptát. Chyba se odhalí při kontrole po čtyřech dnech a kauza úplně neumře nikdy."]]},"a-military-dei":{"t":"Příkaz o bojeschopnosti","x":"Tarrant položí vedle sebe příkaz a data o udržení personálu. „Provedu, cokoli podepíšete, pane. Musím vás ale upozornit, že nábor do čtyř z pěti nejhůře obsaditelných specializací probíhá právě přes úřady, které se tímto ruší.“","c":[["Podepište ho. Zrušte všechny úřady.","Nábor do těch čtyř specializací klesne za dva roky o 19 procent. Zpráva, která to dokazuje, je utajena na úrovni, jež ji drží mimo rozpočtové slyšení."],["Zrušte úřady. Náborové kanály zachovejte.","Cedule zmizí, funkce zůstane, jen se přejmenuje. Každý dostane přesně to, co říkal, že chce, a vůbec nic se ve skutečnosti nezmění."],["Nepodepisujte. Nejdřív nařiďte prověrku bojové připravenosti.","Prověrka shledá programy mírně přínosnými a mírně nákladnými. O devět měsíců později podepíšete užší příkaz a nikdo se neobtěžuje protestovat."],["Podepište ho a nahraďte úřady jediným seržantem.","Seržant Alvarez zdědí pracovní zátěž čtyř set lidí, zvládá to lépe než všech čtyři sta dohromady a za rok je dvakrát povýšen."]]},"a-passports":{"t":"Označení","x":"Muriel: „Žádosti o změnu označení se pozastavují. Ne zamítají, pozastavují. Je jich jedenáct tisíc a čtyři sta lidí má tento měsíc rezervovanou cestu.“","c":[["Pozastavte je na neurčito. Nevydávejte žádný pokyn.","Pozastavení bez rozhodnutí se nedá odvolat, protože formálně nebylo nic rozhodnuto. Je to nejúčinnější zamítnutí v dějinách ministerstva."],["Zamítněte je formálně. Dejte jim něco, proti čemu se mohou odvolat.","Formální zamítnutí lze žalovat, a taky se žaluje. Za čtrnáct měsíců prohrajete, což jsou, podotýkáme, čtrnáct měsíců."],["Vyřiďte je. Politiku změňte jen do budoucna.","Jedenáct tisíc žádostí je vyřízeno za šest týdnů a nové pravidlo platí pro všechny další. Nikomu neuletí letadlo a nikdo si toho ani nevšimne."],["Vydávejte všechny pasy úplně bez označení.","Čtyři země ty doklady na hranicích odmítají uznat. Ministerstvo stráví devět měsíců vyjednáváním o uznání kolonky, kterou samo úmyslně smazalo."]]},"a-ninety-day":{"t":"Devadesátidenní pauza","x":"Čtyři dny propadů. Lyle má plán: pozastavit sazby specifické pro jednotlivé země na devadesát dní a zvýšit tu vůči vašemu největšímu rivalovi na číslo, jaké nikdo nepoužil od třicátých let.","c":[["Pozastavte všechno. Jednu sazbu zvyšte na 125 procent.","Trhy vyletí za odpoledne o 9 procent nahoru. Pár lidí, kteří o pauze věděli o čtyřicet minut dřív, se pořádně obohatí, a čtyři vyšetřování toho nikam nedojdou."],["Pozastavte všechno. Nic nezvyšujte.","Čistý ústup, správně tak i vnímaný. Nárůst na trhu je stejně velký a vaše základna zuří kvůli číslu, které už neexistuje."],["Nic nepozastavujte. Držte linii.","Za týden odpadne dalších 6 procent. Penzijní účty ránu vstřebají a vaše preference u lidí nad 60 let udělají něco, čemu průzkumníci odborně říkají „geologické“."],["Pozastavte je a oznamte tu pauzu čtyřikrát.","Čtyři samostatná oznámení téže pauzy během devíti dní, každé z nich pohne trhem. Obchodní časopis to nazve nejvýnosnějším koktáním ve finanční historii."]]},"a-retaliation":{"t":"Odpověď","x":"Odpověděli dva partneři. Jeden zasáhl čtyři zemědělské státy s chirurgickou přesností. Druhý neudělal nic oficiálního, jeho občané prostě přestali kupovat americké výrobky.","c":[["Eskalujte proti oběma.","Přesně mířené odvetné cla se přes noc zdvojnásobí. Bojkot, který nemá žádný oficiální status, s nímž by se dalo vyjednávat, se nedá utišit a táhne se jedenáct let."],["Vyjednávejte se státem. Bojkot ignorujte.","S vládou se dohodnete za čtyři měsíce. Spotřebitelské nálady se zotavují devět let a žádná dohoda se jich ani nedotkne."],["Zrušte cla. Prohlaste, že jste dokázal svoje.","Vše se za šest týdnů odvine zpět. Dva drobné ústupky za jedenáct měsíců chaosu, poctivý, i když nepůsobivý výsledek."],["Bojkotujte je taky. Osobně. Na kameru.","Veřejně se zřeknete jejich čtyř nejslavnějších produktů. Domácí prodeje všech čtyř stoupnou. Jedna země vám pošle zdarma bednu s velmi krátkým vzkazem."]]},"a-strike-timing":{"t":"Časový plán","x":"Váš ministr obrany zveřejnil okna pro odpal a seznamy cílů v komerční chatovací aplikaci dvě hodiny předtím, než letadla vzlétla. Tarrant: „Kdyby se to dostalo k nepovolané osobě, pane, tento týden bych psal kondolenční dopisy.“","c":[["Nikoho nepotrestáme. Dopadlo to dobře.","Skutečně to dopadlo dobře. Poučení, které si z toho odnese každý důstojník, se týká následků, ne aplikace."],["Odvolejte ho. Řekněte přesně proč.","Odpovědnost, vyslovená jasně, jednou. Čtyři spřátelené zpravodajské služby tiše obnoví sdílení informací, které minulý měsíc pozastavily."],["Ponechte ho ve funkci. Zakažte tu aplikaci v celé vládě.","Systémová oprava bez personální. Vyřeší to tento konkrétní incident a přesně nula z důvodů, proč k němu došlo."],["Přidejte posádku letadel do chatu, ať to dostanou rychleji.","Někdo se o to skutečně pokusí, než ho fyzicky zastaví. Pokus skončí ve zprávě generálního inspektora jako číslované zjištění."]]},"a-war-plans":{"t":"„Nikdo nic nepsal esemesky“","x":"Vy i ministr jste na kameru shodně prohlásili, že nikdo nic takového nepsal. Kaylee: „Pane, časopis má snímky obrazovky. V šest je zveřejní v plném znění.“","c":[["Držte linii. Popírejte to i po zveřejnění.","Snímky obsahují doslovný text. Popírání poté, co jsou důkazy veřejné, mění bezpečnostní selhání v selhání důvěryhodnosti, natrvalo."],["Připusťte fakta. Rozporujte jejich závažnost.","Spor o to, jestli to bylo vážné, je bitva, kterou přežijete. Spor o to, jestli se to vůbec stalo, není, a moudře se do druhé nepouštíte."],["Předběhněte to. Zveřejněte zprávy sám ve čtyři.","Předčasné zveřejnění zabije jedním tahem jak senzaci, tak nařčení z utajování. Časopis svůj článek stejně otiskne, ale jen třetinu tak dlouhý, jak měl v plánu."],["Tvrďte, že snímky jsou z jiného chatu.","Obsahují vaše vlastní zobrazované jméno a profilovou fotografii. Na to upozorní během čtyř minut, živě, přímo osoba, která snímky drží."]]},"a-cabinet-praise":{"t":"Kolem stolu","x":"Chet navrhuje zahájit televizní zasedání vlády tak, že se postupně obejde stůl a každý ministr řekne, co pro něj osobně sloužit vám znamená. „Zlidští to tým,“ říká a dívá se přitom přímo na vás.","c":[["Udělejte to. Obejděte stůl dvakrát.","Čtyřicet jedna minut, kdy dospělí lidé v přímém přenosu děkují jednomu muži za výsadu pracovního poměru. Profesor srovnávací politologie zastaví záznam a nahlas, do prázdné místnosti, řekne: „Tady to máme.“"],["Udělejte to, ale po čtyřech to ukončete.","Čtyři stačí na to, aby se rituál ustavil, aniž by vznikl kompletní sestřih k výsměchu. Chet si to číslo poznamená a založí."],["„Tohle dělat nebudeme. Podejte zprávu o svých úřadech.“","Skutečně produktivní jednání s devíti reálnými rozhodnutími. Chet celou hodinu píše do malého notesu, netuše, co se to vlastně stalo."],["Obejděte stůl a místo toho poděkujte vy jim.","U každého z dvaadvaceti jmenujete jednu konkrétní věc, kterou udělal. Trvá to padesát minut, čtyři jsou viditelně dojatí a Chet vůbec nechápe, co to sleduje."]]},"a-crowd-number":{"t":"Letecké snímky","x":"Letecké fotografie jsou venku. Dav je skutečný, nadšený a zhruba tak velký jako oblastní psí výstava. Noviny otiskly obě léta vedle sebe, pro případ, že by to někomu uniklo.","c":[["Pošlete tam Kaylee, ať řekne, že to byl vůbec největší dav v historii. Tečka.","Řekne to s plným nasazením. Nikdo tomu nevěří ani slovo, ale všichni si všimnou, že to řekla, a přesně o to od začátku šlo."],["„Davy jsou posedlost médií.“ Další otázka.","Kauza za čtyřicet minut umře. Něco ve vás umře spolu s ní."],["Nařiďte správě parků, ať zveřejní opravená čísla.","Kariérní fotoarchivář je přeložen do místnosti bez oken v Suitlandu. Nové číslo, 1,9 milionu, je sepsané a oficiální."],["Spočítejte je sám. V televizi. Nahlas.","Dostanete se ke čtyřem stům jedenácti, než se úplně ztratíte. Vysílá se to celé a stane se to zdaleka nejsledovanějším příkladem počítání v dějinách televize."]]},"a-misspellings":{"t":"Katalog","x":"Ověřovací oddělení jedenáct měsíců katalogizuje vaše pravopisné chyby. Seznam má už 340 položek. Brayden si myslí, že vás to zlidšťuje. Kaylee si myslí, že to vypadá, jako byste psal ve čtyři ráno, což děláte.","c":[["Přispívejte dál bez úprav. Je to autentické.","Katalog naroste na 900 položek. Zároveň je to opravdu důvod, proč čtyři miliony lidí věří, že příspěvky píšete sám, což bohužel děláte."],["Nechte příspěvky před zveřejněním zkontrolovat.","Míra zapojení klesne za měsíc o 22 procent. Správný pravopis působí jako práce komise, a komise pro vaši základnu vypadá jako všichni ostatní."],["Jedno slovo pište vždy úmyslně chybně. Přiznejte se k tomu.","Stane se to podpisem, pak poznávacím znamením. Příznivci vám to začnou psát stejně špatně zpátky a ověřovatelé to tiše přestanou počítat."],["Prohlaste, že se mýlí slovník.","Čtyři lexikografové reagují s upřímným potěšením a jeden napíše překvapivě dobrou esej o deskriptivismu, která se nečekaně stane virální."]]},"a-khan":{"t":"Rodiče","x":"Otec vojáka, který zahynul při ochraně své jednotky, vás ze pódia kritizoval a přitom v ruce držel kapesní vydání ústavy. Tarrant přichází s jednou větou: „Pane, neexistuje verze odpovědi jemu, která by dobře skončila.“","c":[["Odpovězte mu. Zpochybněte matčino mlčení.","Kauza se táhne jedenáct dní. Čtyři členové vaší vlastní strany se od vás veřejně distancují jménem a doslechne se to každý sloužící důstojník, většina z nich mlčí, což je samo o sobě vzkaz."],["Neříkejte vůbec nic. Pošlete soukromý dopis.","Dopis se nikdy nezveřejní. O léta později se otec zmíní, že byl psaný rukou a lepší, než čekal, a víc už k tomu neřekne."],["Na příští akci vyzdvihněte syna jménem.","Bez poznámek přesně uvedete hodnost i jednotku. Trvá to třicet vteřin a je to jednoznačně nejúčinnější věc, kterou ten měsíc uděláte."],["Kupte čtyři tisíce kapesních ústav a rozdejte je.","Do týdne se vyprodají po celé zemi. Vydavatel vám napíše poděkování. Čtyři z vašich vlastních příkazů se vám pak citují zpátky, z výtisků, které jste sám zaplatil."]]},"a-deferred-resignation":{"t":"Nabídka","x":"„E-mail všem federálním zaměstnancům. Rezignujte hned, plat vám poteče do září, bez otázek.“ Deborah má právní poznámku. „Pane, na výplatu do září nemáme schválené prostředky.“","c":[["Pošlete to všem 2,3 milionu. Peníze vyřešíme později.","Přijme to sedmdesát sedm tisíc lidí. Jako první odejdou ti, kteří mají kam jít, řízení letového provozu, jaderná bezpečnost, sledování nákaz, protože to tak vždycky bývá."],["Pošlete to jen tam, kde skutečně chcete snížit počty.","Přesnost místo brokovnice. Stejné snížení počtu lidí, ale jen tam, kde jste ho skutečně chtěl, a inspektoři reaktorů zůstávají na místě."],["Neposílejte to. Snižujte přirozeným odchodem.","Počet zaměstnanců klesá o 4 procenta ročně, aniž by odešel jediný e-mail. Pomalejší, levnější a nevyvolá to naprosto žádné soudní spory."],["Pošlete to, a pak pošlete druhý e-mail s odvoláním.","Do té doby, než dorazí odvolání, už jedenáct tisíc lidí stihlo rezignovat. Čtyři odmítnou rezignaci vzít zpět ze zásady a napořád zůstanou, s pocitem, že udělali dobře."]]},"a-thirty-days":{"t":"Třicetidenní lhůta","x":"„Zákon vyžaduje třicetidenní písemné oznámení Kongresu, než odvoláte generálního inspektora. Jedna věta.“ Sy pokrčí rameny. „Žádný sankční paragraf tam není. Kontroloval jsem to čtyřikrát.“","c":[["Přeskočte oznámení. Odvolejte ho dnes večer e-mailem.","Soudkyně to za osm měsíců prohlásí za protiprávní, ale nikoho nevrátí do funkce s odůvodněním, že byste ho stejně podruhé vyhodil správně. Má pravdu a přímo to v rozsudku napíše."],["Dodržte třicet dní. Pak ho odvolejte.","Papírování je bezvadné a výsledek stejný. Deborah na ubrousek napíše „elegantní“ a sní ho."],["Ponechte ho ve funkci. Místo toho mu seškrtejte rozpočet.","Jeho zprávy teď chodí s jedenáctiměsíčním zpožděním, černobíle, nesvázané. Nikdo je nečte, což byl zjevně celý požadavek."],["Dodržte lhůtu u jednoho a ostatní vyhoďte rovnou.","To jedno řádně provedené odvolání se pak cituje ve všech podáních jako důkaz dobré víry. Jeden ze sedmnácti se ukáže jako překvapivě účinný poměr."]]},"a-rule-count":{"t":"Devadesát osm v řadě","x":"Cassandra má tabulku. „Devadesát osm předpisů by se dalo zrušit. Jednotlivě je každý z nich technická novela, o které nikdo nepíše. Dohromady je to největší změna v ochraně životního prostředí od roku 1970, a o té taky nikdo psát nebude.“","c":[["Všech devadesát osm. Jeden týdně. Nikdy je neoznamujte.","Dva roky oznámení ve Sbírce federálních předpisů. O čtyřech se napíše. Souhrnný dopad je měřitelný z orbity a ani jednou se nedostane na titulní stranu."],["Těch dvanáct, co skutečně stojí pracovní místa. Ty hájte nahlas.","Obhajitelná pozice, se kterou v televizi skutečně můžete vyhrát, což je mimochodem devět desetin hodnoty jakékoli pozice vůbec."],["Žádný. Financujte transformaci v postižených okresech.","Ve čtyřech státech, které jste vyhrál, se otevře jedenáct tisíc rekvalifikačních míst. Funguje to, pomalu, a slavnostní pásku pak přestřihne váš nástupce."],["Zrušte devadesát osm předpisů a napište devadesát devět nových.","Nová sada je delší, přísnější a sepsali ji titíž kariérní úředníci. V budově si toho jedenáct měsíců nikdo nevšimne."]]},"a-smoot":{"t":"Srovnání","x":"Lyle má jednu stránku. „Každý oslovený ekonom sáhl po stejném srovnání s rokem 1930. Ne většina z nich, pane. Všichni. Včetně čtyř, kteří formálně pracují pro vás.“","c":[["Přijměte to srovnání. Ta cla zemi vybudovala.","Nevybudovala. Je to nejzkoumanější politické selhání v americké ekonomické historii a všichni čtyři vaši vlastní ekonomové to týž týden napíší, písemně."],["Odmítněte srovnání. Argumentujte rozdíly.","Skutečné rozdíly existují a argumentujete jimi kompetentně. Nejobsažnějších dvacet minut vašeho prezidentství, se strašnou sledovaností."],["Zakažte to srovnání v oficiální komunikaci.","Slovo se ve skutečnosti zakázat nedá. Jeho používání za čtrnáct dní vzroste o 400 procent, čistě proto, že jste se o to pokusil."],["Pojmenujte nová cla úmyslně po těch z roku 1930.","Přivlastnit si srovnání dřív, než ho stihne udělat někdo jiný, je buď geniální, nebo katastrofální, a čtyři různé knihy nakonec dojdou ke čtyřem různým závěrům, které z toho platí."]]},"a-first-of-many":{"t":"„První, snad, z mnoha“","x":"Dva tisíce vojáků je v jednom městě. Novinář se zeptal, jestli budou další. Tarrant potichu: „Pane, odpověď na tuhle otázku je celá politika. Ne nasazení. Odpověď.“","c":[["„První, snad, z mnoha.“","Čtyři guvernéři preventivně aktivují vlastní Národní gardu, jen aby vám vzali záminku. Jedna věta právě změnila vojenské rozmístění třetiny země."],["„Tohle jedno. Kvůli tomuhle. A víc nic.“","Nasazení skončí za tři týdny a nic po něm nenásleduje. Omezující formulace je nejlevnější dostupná deeskalace a stojí vás přesně jednu větu na mítinku."],["Odmítněte odpovědět. Ať hádají.","Záměrná nejednoznačnost odvede práci hrozby, aniž byste za hrozbu nesl odpovědnost. Každý guvernér počítá s nejhorším a ani jeden vás nemůže citovat."],["„První ze přesně tří.“ Jmenujte ty tři.","Bez přípravy jmenujete tři města. Všechna tři vás do týdne zažalují. Jedno z nich nebylo na žádném seznamu, který by kdokoli reálně připravil."]]},"b-motives":{"t":"Otázka pohnutky","x":"„Rozsudek dělá něco, co si lidi ještě neuvědomili.“ Sy má to místo označené třemi barvami. „Nejde jen o to, že úřední úkony jsou imunní. Jde o to, že se soud nemůže ptát, *proč* jste je udělal. Pohnutka už není přípustná. Pane, pohnutka byla celý ten případ.“","c":[["Tak to řekněte nahlas v každém příkazu. Pohnutka nepodléhá přezkumu.","Jedenáct příkazů teď bez vyzvání začíná touto doktrínou vytištěnou tučně. Nikdo tu formulaci nevyžadoval. Právě to z ní dělá hrozbu."],["Využijte to. Nikdy o tom nemluvte.","Štít funguje mlčky úplně stejně dobře a nikdo nenapíše sloupek o doktríně, kterou jste byl příliš zdvořilý na to, abyste se jí chlubil."],["Nechte právníky argumentovat úzkou verzí, pro případ, že by se hodila později.","Sy podá tak skromné podání, že mu dva soudci osobně poděkují. Ukládá si tak argument na den, kdy bude mít větší cenu."],["Prohlaste všechny své úkony za úřední, včetně snídaně.","Zveřejněný harmonogram označuje za úřední úkon každou hodinu, kdy nespíte. Je založen do spisu a posměšně citován v devíti samostatných nesouhlasných stanoviscích."]]},"b-emergency-docket":{"t":"Dvacet devět žádostí","x":"„Dvacet devět nouzových žádostí za toto období.“ Sy otočí stránku. „Pro srovnání, dvě předchozí administrativy podaly dohromady osm, za šestnáct let. Pane, my už tu výjimku nepoužíváme. Vydláždili jsme ji a postavili tam pouliční osvětlení.“","c":[["Podejte další. Výjimka je teď silnice.","Většinu vyhrajete. Každé vítězství přichází bez podpisu, bez odůvodnění, v devět večer, a zavazuje celou zemi, dokud si někdo nenajde volné odpoledne, aby vysvětlil proč."],["Podávejte jen tam, kde byste stejně vyhráli i ve věci samé.","Devět žádostí místo dvaceti devíti, a každá z nich pak obstojí. Nudné, trvanlivé a žádný právnický časopis o tom nikdy nenapíše."],["Projděte si normálním soudním řízením jako všichni ostatní.","Trvá to dva roky místo dvou týdnů. Dvě ze čtyř politik přežijí plné projednání, což jsou o dvě víc než obvykle."],["Podejte jednu žádost obsahující všech dvacet devět.","Čtyři sta stránek, jeden nadpis, devět nesouvisejících otázek. Podatelna to vrátí s poznámkou, kterou si později dají do rámečku a pověsí na zeď."]]},"b-unsigned":{"t":"Bez podpisu, bez odůvodnění","x":"Předsedkyně Nejvyššího soudu Stoneová volá kvůli něčemu jinému než rozsudku. „Dvacet tři z vašich dvaceti osmi žádostí dopadlo ve váš prospěch. Skoro žádná neuvedla proč. Soud, který se neodůvodňuje, není soud, pane prezidente. Je to úřad, který razítkuje povolení.“","c":[["„To zní jako vnitřní záležitost soudu.“","Je to vnitřní záležitost soudu, a soud tu při sobě prohrává, tiše, veřejně, v poznámkách pod čarou, které nikdo nečte, dokud nezačnou být důležité."],["Veřejně požádejte o odůvodněné stanovisko u každé z nich.","Odůvodnění fungují na obě strany a vaše vypadají hůř napsaná než vyřčená. Ze čtyř dalších případů dva prohrajete a soudnictví si vrátí něco, co pomalu ztrácelo."],["Neříkejte vůbec nic. Berte si povolení.","Mlčení je zadarmo a rozhodnutí dál přicházejí. Stoneová napíše souhlasné stanovisko, které vždycky chtěla napsat, a přečtou si ho čtyři lidé."],["Nabídněte, že jim to odůvodnění napíšete sám.","Vypracovaný text odůvodnění je kurýrem doručen soudu a vrátí se neotevřený, s lístkem s pozdravem, což dopadne nějak hůř než přímé pokárání."]]},"b-humphreys":{"t":"Devadesátiletý precedens","x":"„Právě jste odvolal úředníky ze čtyř agentur, které Kongres zřídil výslovně proto, abyste to nemohl udělat.“ Sy zní téměř obdivně. „Existuje precedens z roku 1935, který říká, že nemůžete. Soud nechal stát každé odvolání a ani jednou ho necitoval. Přehlasovává se to mlčením, pane. Nikdo nikdy neviděl provést ten trik tak čistě.“","c":[["Pokračujte v odvolávání. Mlčení je nejužitečnější druh povolení.","Devět agentur za rok. Precedens z roku 1935 zůstává formálně platným právem a už ho necituje naprosto nikdo, v ničem, nikdy."],["Požádejte je, ať to zruší řádně, věcně a otevřeně.","Případ přijmou a rozhodnou ve váš prospěch poměrem 6:3, s odůvodněním. Získáte tutéž pravomoc plus deset let legitimity, kterou jste v úterý ještě neměl."],["Zastavte se u čtyř. Ostatní nechte být.","Čtyři se čtou jako série rozhodnutí. Devět by se čtlo jako politika. Jen jedno z toho se dá žalovat jako vzorec chování."],["Odvolejte úředníky a pak je znovu jmenujte, abyste zjistil, jestli to funguje.","Všichni čtyři se vrátí ke stejným stolům s novým jmenováním a podstatně horší jistotou zaměstnání. Tři vám za to poděkují, což je na tom nejznepokojivější."]]},"b-kagan-dissent":{"t":"Nesouhlasné stanovisko","x":"Bylo zveřejněno nesouhlasné stanovisko obsahující větu, která je teď na transparentech. Varuje, že nouzový mechanismus se používá k přesunu pravomocí z Kongresu na prezidenta. Kaylee: „Pane, vytiskli ji na plátěnou tašku. Dvakrát se vyprodala.“","c":[["Útočte na autorku stanoviska jménem. Opakovaně.","Její další nesouhlasné stanovisko je delší, ostřejší a přednesené nahlas ze soudcovské lavice, což devět let nedělala, a teď to díky vám dělá pravidelně."],["„Nesouhlasná stanoviska jsou způsob, jak soud diskutuje sám se sebou.“ Jděte dál.","Jen přístup, který to bere jako běžnou věc, z toho běžnou věc udělá. Za čtyři dny to zmizí z titulní strany, aniž by to komukoli chybělo."],["Nechte to zástupce vlády u soudu zodpovědět v příštím podání.","Poznámka pod čarou reagující na nesouhlasné stanovisko je zdaleka nejestablišmentovější věc, jakou vaše administrativa kdy udělala, a funguje to přesně tak, jak establishmentové věci fungují."],["Kupte si tu tašku. Nechte se s ní vyfotit.","Na nějakých devět dní to celou kauzu zneškodní. V její kanceláři to prý považují za velmi vtipné, ale oficiálně to nepotvrdí."]]},"b-marshal":{"t":"Exekutoři soudu","x":"Soudce nařídil něco, co nemáte v úmyslu udělat. Bo prověřil, jak to funguje. „Soud nemá armádu. Výkon rozhodnutí zajišťuje exekutivní služba soudu. Ta odpovídá mému ministerstvu. Které odpovídá vám. Pane, upřímně si přeju, abyste se mě na tohle nebyl ptal.“","c":[["Sdělte exekutivní službě, že příkaz je v přezkumu.","Nic se neodmítne a nic se neudělá. Čtyři bývalí soudci nezávisle na sobě napíší stejný komentář a dojdou ke stejnému slovu: dutý."],["Podřiďte se, pomalu, a mezitím se odvolávejte.","Zdržování je poslušnost s časovým rozvrhem. Ztratíte čtyři měsíce, ale zachováte si to podstatné, být účastníkem sporu, ne jeho terčem."],["Podřiďte se plně, ještě dnes, a hlasitě to oznamte.","Veřejně a okamžitě uposlechnete příkaz, který nesnášíte. Stojí vás to týden, ale dalších jedenáct rozhodnutí máte předplacených."],["Požádejte exekutivní službu, ať doručí příkaz soudci.","Zástupce skutečně dorazí k soudní budově, než to zachytí někdo výše postavený. Soudce kopii přijme s bezvadnou zdvořilostí a založí ji do spisu."]]},"b-facilitate":{"t":"Jedno slovo, jednomyslně","x":"Devět nula. Ne šest ku třem, ne pět ku čtyřem, devět nula. Příkaz obsahuje přesně jedno sloveso: *zajistit*. Muriel: „V devíti nulách není žádný prostor k manévrování, pane. Je tam jen to slovo. A jejich právníci s našimi teď stráví rok tím, co znamená.“","c":[["„Zajistit“ znamená, že nebráníme. Nedělejte nic.","Slovo zvolené kvůli jednomyslnosti se ukáže jako slovo zvolené kvůli nejednoznačnosti. Nižší soudce to písemně, dvakrát, přesně tak i nazve."],["Posaďte ho tento týden do letadla a mějte to za sebou.","Za jedenáct dní je po všem. Vaše základna to správně nazve kapitulací, a zároveň je to poslední den, kdy se ten případ dostane na titulní stranu."],["Vyjednejte předání přes třetí zemi. Dejte si na to tři měsíce.","Řešení, které zachrání tvář a splní příkaz bez jediné fotky letadla. Diplomacie se za celé funkční období vyplatí zhruba jednou, a je to teď."],["Zajistěte to tak, že mu pošlete jízdní řád autobusu.","Vládní podání skutečně přiloží vytištěný jízdní řád trasy, která nepřekračuje oceán. Je založen do spisu jako důkaz C."]]},"b-sotomayor":{"t":"Věta v poznámce pod čarou","x":"„Naše stanovisko v podání je, že rozhodnutí o vyhoštění nepodléhá přezkumu, tečka.“ Sy přestane číst nahlas. „Nesouhlasné stanovisko upozorňuje, že naše stanovisko ani jednou nepoužije slovo ,osoba bez občanství‘. Podle naší vlastní teorie, pane, se to nezastaví u pasu.“","c":[["Nechte podání tak, jak je. Teorie je aktivum.","Argument vytvořený pro jednu kategorii je teď na papíře platný pro všechny. Vašemu nástupci ho pak citují zpátky v případu, který si tady nikdo nedokázal představit."],["Upravte podání. Slovo „bez občanství“ tam napište čtyřicetkrát.","Omezující zásada dnes nic nestojí a ukáže se jako jediný důvod, proč doktrína přežije i druhé desetiletí."],["Teorii úplně stáhněte. Argumentujte fakty.","Případ vyhrajete na faktech a prohrajete doktrínu. Sy to nazve správnou výměnou a pro jednou to nemyslí diplomaticky."],["Přidejte poznámku pod čarou slibující, že k tomu budete přistupovat rozumně.","Podání k nejvyššímu soudu země obsahuje větu „v praxi bychom to nedělali“. Při ústním jednání se přečte nahlas. Pomalu."]]},"b-injunction-scope":{"t":"Procesní vítězství","x":"„Vyhráli jsme.“ Bo nevypadá jako muž, který vyhrál. „Omezili celostátní soudní zákazy. Jeden soudce už nemůže zmrazit politiku pro celou zemi. To je obrovské.“ Otočí stránku. „Je to ale čistě procesní. Neřekli, že politika je zákonná, a naše šance, až se k tomu dostanou, se mi vůbec nelíbí.“","c":[["Vyhlaste totální vítězství. Zaveďte to všude, okamžitě.","O čtrnáct měsíců později se dostanou k věci samé a poměrem 6:3 to zruší. Všechno zavedené se musí odvinout zpět, a to odvíjení je pak celá kauza."],["Vezměte si procesní vítězství. Zaveďte to jen tam, kde jste vyhrál.","Mozaika, které rozumí právníci a nikdo jiný. Ošklivé, obhajitelné, a přežije to."],["Pozastavte politiku, dokud se nerozhodne ve věci samé.","Zdrženlivost, za kterou nezískáte žádné uznání. Znamená to ale taky, že když prohrajete, prohrajete plán, ne už rozjetý program."],["Oslavte procesní vítězství přehlídkou.","Alegorické vozy, kapela, transparent s nápisem SOUDNÍ ZÁKAZ JE MRTEV. Jediná přehlídka v americké historii věnovaná občanskému soudnímu řádu."]]},"b-framers":{"t":"„Jedině Kongres“","x":"Šest ku třem, a předseda ho napsal osobně. Všichni citují větu, že tvůrci ústavy svěřili tuto pravomoc jedině Kongresu. Lyle: „Dva z vašich vlastních jmenovaných soudců hlasovali s většinou, pane. Tohle není soud, který je politický. Tohle je soud, který je záměrně soudem, v tu nejhorší možnou chvíli pro nás.“","c":[["Napadněte soud. Řekněte, že ho ovládla druhá strana.","Útočíte na soud, který jste sám sestavil, kvůli rozsudku, který napsal muž, jehož jste osm let po sobě chválil. I vaše vlastní televize odvysílá časovou osu proti vám."],["Podřiďte se a požádejte Kongres, ať cla schválí řádně.","Zákon projde na dvou třetinách sazby, kterou jste chtěl, za devět měsíců, s datem ukončení platnosti. Zato ho žádný soud už nikdy nezruší."],["Tento zákon dodržte. Do pátku najděte jiný.","Užší pravomoc, menší číslo, a žádný rozsudek, který by šlo porušit. Lyle to nazve jedinou skutečně chytrou věcí, kterou letos kdokoli udělal."],["Zeptejte se, který konkrétně tvůrce ústavy, a žádejte, ať vám ho ukážou.","Otázka je písemně předložena úřadu zástupce vlády u soudu. Někdo tam na ni velkoryse odpoví v plném rozsahu, i s daty."]]},"b-vought":{"t":"„Žádné nezávislé agentury neexistují“","x":"Váš ředitel rozpočtu to bez vyzvání oficiálně prohlásil v pěti slovech: žádné nezávislé agentury neexistují. Deborah: „Pane, to je celá teorie jednotné exekutivy podaná jako pokrčení rameny. Devět hlavních právních poradců už volalo, jestli to bylo schváleno.“","c":[["Potvrďte to. Je to teorie a je to plán.","Vyslovit to nahlas mění právní argument v politický program a dává každému odpůrci jednu jasnou větu, kolem které se lze zorganizovat."],["„Popisoval odpovědnost, ne kontrolu.“","Rozlišení bez jakéhokoli praktického obsahu, což je přesně důvod, proč vydrží dva roky."],["Veřejně ho opravte. Některé agentury nezávislé jsou.","Oprava je upřímná a vaše vlastní strana ji vnímá jako zradu. Čtyři komisaři tiše přestanou aktualizovat svá životopisy."],["Udělejte ho šéfem všech nezávislých agentur najednou.","Jedenáct souběžných funkcí pověřeného ředitele v rukou jednoho muže s jedním diářem. Diář je předvolán jako důkaz a stane se nejvtipnějším dokumentem celého období."]]},"b-probationary":{"t":"Šestnáct tisíc","x":"Šestnáct tisíc zaměstnanců ve zkušební době propuštěno podle šablony, během týdne. Deborah má následnou zprávu. „Jedna agentura se tiše pokusila čtyři sta z nich znovu přijmout, protože se ukázalo, že dělali přesně to, kvůli čemu agentura existuje. Jedenáct dalších řeklo ne.“","c":[["Žádné zpětné přijímání. Nikde. Číslo je to podstatné.","Počet zaměstnanců drží a čtyři zákonem dané funkce tiše přestanou fungovat. Devatenáct měsíců si toho nikdo nevšimne, a pak si toho všimnou všichni najednou."],["Nechte agentury tiše přijmout zpět ty, které nutně potřebují.","Číslo v tiskové zprávě zůstává stejné. Lidé se vracejí zadními dveřmi s novými smlouvami. Obojí je pravda a hlásí se jen jedno z toho."],["Zvraťte to. Omluvte se těm čtyřem stům jmenovitě.","Jmenovité uvedení je to, co skutečně zapůsobí. Dva z nich se rozpláčou v přímém přenosu a reportáž se vysílá celý týden."],["Přijměte je zpět jako neplacené dobrovolníky.","Nabídkový dopis je skutečný a je rozeslán čtyřem stům lidí. Devět ho přijme, což je na tomhle příběhu ta opravdu znepokojivá statistika."]]},"b-usaid":{"t":"Agentura, která tu v pondělí ještě byla","x":"Muriel má seznam věcí, které se zastavily. „Jedenáct klinik, čtyři zásobovací linky pro boj s hladomorem, chladicí řetězec pro vakcíny ve třech zemích. A dvě miliardy dolarů dlužné za už dokončenou práci, dodavatelé, kteří dodali, vyfakturovali a teď nás žalují. Pane, oni tu práci odvedli. To se nedá rozporovat.“","c":[["Nikomu neplaťte. Ať žalují.","Žalují a vyhrají, protože dokončená smlouva je dokončená smlouva všude kromě téhle budovy. Stejně to nakonec zaplatíte, později, s úroky a přiloženým rozsudkem."],["Zaplaťte dokončené faktury. Vše budoucí zrušte.","Vyrovnat se s minulostí a zrušit budoucnost odstraní jediný argument, který u soudu skutečně fungoval, a politicky vás to nic nestojí."],["Zachovejte agenturu. Přejmenujte ji a zmenšete o polovinu.","Poloviční agentura s vaším jménem na dveřích odvede sedmdesát procent práce za padesát procent peněz a nevyvolá jediný soudní spor."],["Nahraďte celou instituci telefonní linkou.","Jedno číslo, obsluhované dvěma lidmi, pokrývající humanitární potřeby čtyřiceti zemí. První den zaznamená jedenáct tisíc hovorů."]]},"b-130-days":{"t":"Den sto třicet","x":"Roscoe Vandermeer počítá. „Sto třicet dní je zákonný limit pro to, čím jsem. Dnes je den sto dvacet šest.“ Usmívá se způsobem, kterému jste se naučil nevěřit. „Takže buď skončím, nebo se stanu něčím jiným, nebo někdo prostě přestane počítat.“","c":[["Udělejte z něj trvalého úředníka. Ať to stojí, co chce.","Buď potvrzení, které nepřežije, nebo jmenování žalované dva roky. Vyberete druhou možnost a žaluje se tři roky."],["Nechte čas vypršet. Vřele mu poděkujte.","Odejde přesně v den sto třicet, a stroj, který postavil, běží dál i bez něj, což vlastně nikdy nebyl plán."],["Ponechte ho i po vypršení limitu. Nikdo to nikdy nevymáhal.","Skutečně to nikdo nevymáhá. Přesto se úplně vše, co podepíše po dni 130, napadne z tohoto důvodu, a čtyři z toho padnou."],["Vynulujte počítadlo tím, že mu dáte nové jméno.","Podá se papírování na muže s jiným prostředním iniciálem. Projde to. Letní stážista to odhalí o devět měsíců později, v jedno klidné úterý."]]},"b-doge-exit":{"t":"Roztržka","x":"Zvrtlo se to veřejně a rychle. Napsal o vás čtyři příspěvky, vy jste o něm napsal šest. Deborah ze dveří: „Pane, on ví, kde je co uloženo. Osobně drží přístupové záznamy pro devět ministerstev. Tohle není normální roztržka.“","c":[["Eskalujte. Napište další příspěvek. Zrušte mu smlouvy.","Začne dávat rozhovory plné konkrétních dat. Data sedí, a přesně na to vaši právníci nemají naprosto nic."],["Neříkejte už nic. Ať to vyhasne.","Za jedenáct dní to vyhasne nedostatkem pozornosti. Napíše ještě dva příspěvky do naprostého ticha a přestane."],["Zavolejte mu. Vyřešte to v soukromí. Něco mu dejte.","Nákladný, nedůstojný a naprosto účinný telefonát. Co se přesně vyměnilo, se nikdo nikdy nedozví."],["Jmenujte ho velvyslancem někam, kde mají špatný internet.","Přijme okamžitě, zjevně upřímně. Místo má satelitní připojení a on ho najde do čtyř hodin."]]},"b-eo-count":{"t":"Sedm celá dvě desetiny krát","x":"Deborah má číslo, které dnes ráno zveřejnil jeden think tank. „Sto čtyřicet tři příkazů za sto dní. To je 7,2násobek historického průměru, víc než trojnásobek vašeho předchůdce. Pane, neříkají tomu protiprávní. Říkají tomu graf.“","c":[["Překonejte ten graf. Dvě stě do pátku.","Objem se stane výsledkem, takže se o kvalitu tiše přestane starat kdokoli. Jedenáct nových příkazů si odporuje s dřívějšími a čtyři jsou na první pohled nerealizovatelné."],["Zpomalte na normální tempo. Zajistěte, ať ty stávající obstojí.","Konsolidace je neviditelná a trvanlivá. Po dvou letech osmdesát procent vašich příkazů stále platí, číslo, na které žádná předchozí administrativa nedosáhla."],["Udržte tempo. Ať každý příkaz nejdřív projde právníky.","Sy najme devět lidí a míra zrušených příkazů klesne o polovinu. Je to nejlevnější dostupná systémová oprava a nikdo si jí nevšimne."],["Podepište exekutivní příkaz o počtu exekutivních příkazů.","Příkaz číslo 144 stanoví limit na 143. V den svého podpisu je tak sám sebou porušen, jako svůj vlastní 144. případ."]]},"b-recess":{"t":"Desetidenní okno","x":"Hal Grimes našel díru v zákoně. „Pokud komora přeruší zasedání na víc než deset dní, můžete jmenovat kohokoli na jakoukoli pozici bez hlasování. Přerušení dokážu zařídit.“ Odmlčí se. „Taky ho ale nemusím zařídit, a rád bych, aby bylo pro záznam poznamenáno, že jsem tuhle možnost zmínil.“","c":[["Zařiďte to. Obsaďte jedno odpoledne čtyřicet jedna pozic.","Čtyřicet jedna úředníků bez jediného hlasu za sebou a s trvanlivostí měřenou počtem podaných žalob. Největší jednorázový přesun jmenovací pravomoci za století."],["Použijte to jednou, pro tu jednu pozici, na které skutečně záleží.","Jedno jmenování, obhajitelné nutností, se kterým se nikomu nechce bojovat. Precedens si koupíte za cenu, kterou si skutečně můžete dovolit."],["Předložte nominace. Nechte je hlasovat. Některé prohrajte.","Dvacet devět potvrzeno, dvanáct zamítnuto. Těch dvacet devět je napadnutelných nula do konce jejich přirozeného života, což se nakonec ukáže důležitější než těch dvanáct."],["Přerušte zasedání Kongresu sám a uvidíte, kdo bude protestovat.","Existuje ustanovení, které to při neshodě mezi komorami sporně umožňuje. Žádná neshoda ale neexistuje. Jednu si vyrobíte ještě před obědem."]]},"b-prosecutors-fired":{"t":"Ti, kdo měli na starosti ty případy","x":"„Žalobci, kteří měli na starosti případy nepokojů.“ Bo posune přes stůl seznam. „Úplně všichni. A dvěma tisícům agentů byl rozeslán dotazník s otázkou, na čem přesně pracovali. Pane, to není personální proces. To je sestavování seznamu, a každý, kdo ten dotazník dostane, to ví.“","c":[["Propusťte je všechny. Rozešlete dotazník.","Vzkaz dorazí přesně tam, kam měl. Čtyři sta agentů odmítne odpovědět, jedenáct rezignuje a úřad stráví desetiletí náborem, který bojuje se vzpomínkou na tento týden."],["Místo propuštění je přeřaďte. Žádný dotazník.","Stejní lidé, jiné stoly, žádná papírová stopa. Dosáhne se celého cíle a vyvolá to přesně jeden odstavec v médiích."],["Nechte je být. Žalobci žalují, co jim přistane na stole.","Ministerstvo, které se vás nebojí, jedná rychleji, a čtyřikrát za toto období pracuje ve váš prospěch. O těch případech se nikdy nedozvíte."],["Rozešlete dotazník nejdřív sám sobě.","Vyplníte ho celý, upřímně, vlastním rukopisem. Stane se to zdaleka nejusvědčujícím dokumentem, jaký kdy vaše administrativa vytvořila."]]},"b-sanctions":{"t":"Zákon, který říká musí","x":"„Kongres to schválil poměrem 98 ku 2. Nestojí tam ‚může‘. Stojí tam ‚musí‘.“ Lyle to odloží. „Pane, ministerstvo má návrhy sankcí sepsané a připravené. Leží v šuplíku, a každý týden, co tam leží, je týden, kdy neplníme zákon.“","c":[["Nechte je v šuplíku. Na neurčito.","Zákon schválený 98 ku 2 se prostě, tiše, nestane skutečností. Neexistuje mechanismus, jak to vynutit, a to je tady to zjištění, a není příjemné."],["Sankcionujte dva z jedenácti. Nazvěte to postupným řešením.","Částečné splnění je nevyvratitelné splnění. Dva předsedové výborů napíší rozzlobené dopisy a nikdo věrohodně nemůže tvrdit, že se zákon ignoruje."],["Naplňte zákon v plném rozsahu. Je to zákon.","Jedenáct sankcí ještě před obědem. Stojí vás to zahraniční vztah, na kterém vám záleželo, ale kupujete si tím Kongres, který vás přestane sledovat tak zblízka."],["Sankcionujte ten šuplík.","Sankce je skutečně sepsána proti kartotéce, jako vtip, vyčerpaným úředníkem ve dvě ráno. Omylem se odešle."]]},"b-apology":{"t":"Omluva a knihovna","x":"Patnáct milionů dolarů, omluva na obrazovce, a peníze putují rovnou do vaší budoucí knihovny. Kaylee: „Jejich vlastní právníci mysleli, že vyhrají, pane. Přesto se dohodli, protože mají u téhle vlády rozjednáno jedenáct dalších věcí. A přesně o tom se bude psát.“","c":[["Vezměte to. Trvejte na tom, aby se omluva odvysílala dvakrát.","Odvysílá se dvakrát. Čtyři další média tu transakci správně přečtou a začnou se dohadovat o věcech, o které by dřív bojovaly do posledního dolaru."],["Vezměte peníze. Vzdejte se omluvy.","Peníze bez obřadu jsou zlomkem té kauzy. Zároveň to odstraní jediný detail, díky kterému to vypadalo jako rituální oběť."],["Odmítněte to. Doveďte to k rozsudku.","Za devatenáct měsíců prohrajete ve věci samé. Odnesete si ale něco, co žádné vyrovnání nekoupí: možnost říct, že jste ty peníze nikdy nevzal."],["Přijměte platbu výhradně v reklamních spotech.","Patnáct milionů dolarů ve vysílacím čase u televize, která vás pomluvila, naplánovaném jimi, vysílaném ve tři ráno, jedenáct měsíců v kuse."]]},"b-merger":{"t":"Fúze na stole","x":"Šestnáct milionů, žádná omluva, a šek je proplacen ve stejném týdnu, kdy jejich osmimiliardová fúze potřebuje podpis regulátora, kterého jste jmenoval. Kaylee velmi pečlivě nic neříká. Řekne to za ni Sy: „Pane, nikdo nemusí dokazovat souvislost. Kalendář je ta souvislost.“","c":[["Vezměte peníze. Schvalte fúzi. Ve stejném týdnu.","Dva legální úkony, čtyřicet osm hodin od sebe, které se pro každého jediného člověka v zemi s kalendářem čtou jako jedna transakce."],["Vezměte peníze. Fúzi odložte o čtyři měsíce.","Čtyři měsíce odstupu vás nic nestojí a celá kauza zmizí. Nejlevnější věc, kterou celý rok uděláte."],["Úplně se z rozhodování o fúzi vylučte.","Písemné vyloučení, založené a veřejné. Fúze je stejně schválena, na základě svých vlastních kvalit, a není o čem psát."],["Schvalte fúzi a peníze vezměte v akciích.","Nyní osobně vlastníte podíl ve firmě, kterou jste právě schválil. Čtyři etičtí úředníci rezignují v jednom jediném odpoledni, rekord, který stále platí."]]},"b-license":{"t":"Pět dopisů","x":"Váš regulátor zahájil nebo pohrozil kontrolami u pěti vysílatelů, včetně obou veřejnoprávních stanic. Žádná z nich neskončila. Deborah: „To je záměr, pane. Kontrola, která nikdy neskončí, je ruka na rameni, která se nikdy nezvedne.“","c":[["Zahajte čtyři další. Veřejně řekněte, že licence by měly být ohroženy.","Ve skutečnosti se nikdy nic neodebere. Každá zúčastněná redakce přidá na ranní poradu právníka a ranní porada je teď místo, kde kauzy umírají."],["Kontroly ponechte. Už se o nich nezmiňujte.","Nezmíněný tlak funguje lépe než oznámený tlak, protože se proti ničemu nedá zorganizovat protest."],["Zavřete všech pět. Veřejně.","Uzavření je zprávou na jeden den. Mrazivý efekt taje asi čtyři měsíce a nikdy úplně nezmizí."],["Zažádejte si o licenci sám.","Žádost je podána řádně a zařadí se do fronty za pěti kontrolami, které jste sám zahájil. Váš vlastní regulátor teď o ní musí rozhodnout."]]},"b-global-media":{"t":"Vysílače","x":"„Mezinárodní vysílání.“ Muriel zvedne vysílací harmonogram. „Jedenáct jazyků, čtyři z nich do zemí, kam nikdo jiný nevysílá nic pravdivého. Pokud to zrušíme, pane, frekvence neztichne. Do čtvrtka na ní bude vysílat někdo jiný.“","c":[["Zrušte to celé. Není naší úlohou vysílat do zahraničí.","Čtyři frekvence obsadí do měsíce stanice, které jsou z toho velmi, veřejně potěšené. Nejlevnější strategický dárek celého funkčního období."],["Zrušte anglické vysílání. Jedenáct jazyků zachovejte.","Domácí úspory jsou reálné, strategická hodnota přežije, a nikdo, komu záleželo na kterékoli straně, není plně spokojen."],["Financujte je v plné výši. Dejte na záhlaví svoje jméno.","Vaše jméno nad redakčně nezávislou stanicí, která do dvou let odvysílá o vás něco, co budete upřímně nesnášet."],["Nahraďte všech jedenáct stanic jedním podcastem.","Nahráváno ve sklepě, jen v angličtině, a stane se to opravdu docela populární ve dvou zemích, které s vámi už souhlasily."]]},"b-pool-slot":{"t":"Židle, která tu vždycky byla","x":"„Místo pro tiskovou agenturu bylo v tom novinářském poolu ještě předtím, než jsme se oba narodili.“ Kaylee se přímo nehádá. „Právě to místo dělá z poolu pool, a ne pozvánkový seznam. Odeberte ho, pane, a pool se stane něčím, co si skládáte ručně.“","c":[["Odeberte ho. Pool je náš k sestavení.","To místo se už nikdy nevrátí, ani za vás, ani za nikoho po vás. Zdaleka nejtrvalejší věc, kterou tisku uděláte, a stačí na to jeden pokyn."],["Židli zachovejte. Kdo v ní sedí, ať se střídá.","Instituce přežije, osoba v ní se stane rozhodnutím, které obnovujete každý týden. Většina moci, žádný boj."],["Nechte pool přesně tak, jak vždycky byl.","Nic se nestane, což je uspořádání tisku fungující správně, a proto to není zpráva nikde na světě."],["Nahraďte tiskovou židli skutečným křeslem.","V první řadě se instaluje kožené ušák křeslo. Nikdo se v něm nemůže nechat vyfotit, aniž by nevypadal směšně, což byl, po zvážení, celý smysl."]]},"b-own-appointee":{"t":"Váš vlastní soudce","x":"Soudní zákaz obnovující přístup tiskové agentury vydal soudce, kterého jste sám jmenoval. Sy si poslední větu přečte dvakrát. „Byl na vašem vlastním užším seznamu, pane. Osobně jste ho vyslýchal. Napsal devět stránek o diskriminaci na základě názoru a nemýlí se ani v jedné z nich.“","c":[["Napadněte ho. Řekněte, že to byla chyba.","Tu větu si přečte každý soudce, kterého jste kdy jmenoval. Čtyři z nich do roka rozhodnou proti vám a toho vzorce si všimnou všichni."],["Podřiďte se bez komentáře. Je to dobrý soudce.","Zdrženlivost vás stojí den vzteku a kupuje výhodu pochybnosti ve jedenácti pozdějších případech. Nejlepší obchod na stole, a celou dobu se cítí příšerně."],["Odvolejte se. Vyhrajte částečné odložení. Nikdy se o něm nezmiňte.","Částečné odložení je částečné vítězství a nevznikne z toho citovatelná věta žádným směrem, což byl vždycky celý cíl."],["Povyšte ho někam, kde nejsou žádné případy s tiskem.","Povýšení odmítne dvouřádkovým dopisem a zůstane přesně tam, kde je, projednávat přesně tyhle případy, dalších jedenáct let."]]},"b-gasoline":{"t":"„Benzín“","x":"Organizace monitorující svobodu tisku použila slovo benzín a frázi „koordinovaná válka proti svobodě tisku od prvního dne v úřadu“. Kaylee: „Nejsou to nepřátelské médium, pane. Hodnotí sto osmdesát zemí a loni jsme byli padesátí sedmí.“","c":[["Odbyjte je jako zahraniční lobbistickou skupinu.","Útok na toho, kdo počítá skóre, skóre nezmění. Propadnete o dalších sedm míst a sám propad se stane další titulkou."],["Neříkejte nic. Žebříčky jsou žebříčky.","Ignorování žebříčku ho připraví o domácí spor, který by z něj doma udělal zprávu. Vysílá se v zahraničí a tiše umírá nikde jinde."],["Obnovte místo pro tiskovou agenturu a tiše zavřete dvě kontroly.","Následující rok postoupíte o čtyři místa. Nikdo na vaší straně se nikdy nedozví, že jste s tím něco udělal, což je přesně důvod, proč to bylo možné."],["Zveřejněte vlastní žebříček. Sebe umístěte na první místo.","Oddíl o metodice má jednu větu. Čtyři země žádají o zařazení a tři z nich jsou uraženy tím, kam se umístily."]]},"b-nonprofit":{"t":"Prověrka statusu","x":"„Čtyři organizace, které vedou kampaň proti vám, mají status obecně prospěšné organizace.“ Lyle to řekne bez okolků. „Prověřit to je legální. Oznámit, že to prověřujeme, je taky legální. Pane, ta druhá část je celá zbraň, a nic nás nestojí ji vypálit.“","c":[["Oznamte prověrky všech čtyř. Ještě dnes.","Žádná o status nepřijde. Všechny čtyři přijdou o dárce, protože dárce přispívá na věc, ne na právní argument, a každý fundraiser v zemi to už dávno ví."],["Zahajte jednu tichou prověrku u té, kde jsou skutečné nesrovnalosti.","Skutečný případ, řešený běžným způsobem, který skončí skutečným zjištěním. Nenapadnutelný přesně proto, že je nudný."],["Nařiďte úřadu, ať politické skupiny úplně nechá být.","Písemná politika nezasahování, která zavazuje spolu s vámi i vaše nástupce. Zdaleka nejzávažnější pokyn celého funkčního období."],["Přiznejte status obecně prospěšné organizace vlastní kampani.","Žádost popisuje uvedený veřejně prospěšný účel jako „obecné prosazování veřejného blaha“. Schválí ji někdo, kdo pak nedokáže vysvětlit proč."]]},"b-memecoin-collapse":{"t":"Devadesát sedm procent","x":"Token dosáhl na vrcholu pomyslného ocenění patnácti miliard dolarů a teď má hodnotu kolem čtyř set milionů. Lyle: „Vy jste si vzal svůj podíl z emise a z poplatků při cestě nahoru, pane, takže vás se to osobně nedotýká. Zhruba dvě stě tisíc lidí, kteří nejste vy, se to dotýká extrémně.“","c":[["Řekněte, že trh je trh. Vypusťte druhý token.","Druhý token se chová identicky jako první. Teď už je to vzorec chování místo incidentu, a přesně kvůli vzorcům chování regulátoři existují."],["Už se k tomu nikdy nevyjadřujte.","Za šest týdnů to zmizí ze zpráv pro nedostatek čerstvého vyjádření od vás. Ztráty odnikud nezmizí."],["Odškodněte deset tisíc nejmenších držitelů z vlastní kapsy.","Stojí to jmění a kupuje se tím něco jinak nekoupitelného: jedna věrohodná věta o tom, že jste udělal slušnou věc."],["Nařiďte znovuzavedení za starou cenu dekretem.","Prohlášení stanoví hodnotu soukromého tokenu na jeho bývalém vrcholu. Trh nesouhlasí během devíti vteřin a nesouhlasí dál."]]},"b-dinner":{"t":"Nejlepších dvě stě","x":"Miriam Applewhiteová drží seznam hostů co nejdál od sebe. „Kritériem pro pozvání je, kolik čí drží vašeho tokenu. To je celé kritérium. Pane, neexistuje způsob, jak to popsat, aby to nevypadalo jako prodej večera s prezidentem.“","c":[["Uspořádejte to. Dvě stě dvacet hostů. Fotografie.","Čtyři z hostů se ukážou být cizí státní příslušníci s vyřizovanými záležitostmi u této vlády, neprověření, protože jediným kritériem byla peněženka."],["Uspořádejte to. Nejdřív každého hosta prověřte. Seznam zveřejněte.","Jedenáct jmen se při prověrce tiše vyřadí. Zveřejněný seznam působí nudně, a nudný seznam není zpráva."],["Zrušte to. Odškodněte za ten dojem.","Zrušení je samo o sobě přiznáním a přesně tak se o něm i píše. Přesto levnější, než by byly ty fotografie."],["Večeři uspořádejte, ale nezúčastněte se jí.","Dvě stě dvacet lidí sní vynikající jídlo v pronajatém sále a hledí přitom na prázdnou židli s jmenovkou."]]},"b-stablecoin":{"t":"Dvě miliardy","x":"„Suverénní fond vkládá dvě miliardy dolarů do stablecoinu, a stablecoin provozuje firma s jménem vaší rodiny na dveřích.“ Lyle volí slova opatrně. „Poplatek z toho vychází zhruba na sto milionů ročně. Vám. Od nich. Za naprosto nic.“","c":[["Vezměte to. Je to obchodní ujednání.","Je to obchodní ujednání stejně jako je obchodním ujednáním paušál pro právníka na pohotovosti. Čtyři výbory otevřou spisy a žádný nedokáže pojmenovat skutečný zločin."],["Vezměte to. Nasměrujte to přes slepou strukturu.","Struktura je opravdu slepá a přitom plně dohledatelná, protože dvoumiliardový vklad se ve skutečnosti neschová."],["Odmítněte to po dobu, co jste v úřadu.","Odmítnete sto milionů dolarů ročně a věta „odmítl to“ se stane klíčovou u čtyř kauz, které teprve přijdou."],["Přijměte to v jejich měně a odmítněte to konvertovat.","Dvě miliardy dolarů dorazí v měně s týdenním limitem na vývoz. Přesun trvá devět let a stále probíhá."]]},"b-927":{"t":"Devět set dvacet sedm stránek","x":"Přiznání majetku má 927 stránek. Miriam je přečetla všechny, což neudělá nikdo jiný na světě. „Dvě celé dvě miliardy příjmů za rok, pane. Jedna celá čtyři miliardy z tokenů. Všechno je to zveřejněné. To je obhajoba, a je dobrá, a zároveň je to celá ta kauza.“","c":[["Zveřejněte to v pátek v pět odpoledne a neříkejte nic.","Čtyři novináři si to o víkendu stejně přečtou, protože 927 stránek je pro tenhle konkrétní druh lidí výzva, ne odstrašující prostředek."],["Zveřejněte to na tiskové konferenci. Proveďte je tím.","Dvě hodiny otázek, na všechny odpovězeno. Nejhorší odpoledne roku, ale zabije to kauzu přesně za to jedno odpoledne."],["„Vydělávají na tom všichni. Trh roste.“","Ta věta se čtrnáct dní objevuje vedle toho čísla. Stane se zdaleka nejcitovanější větou vašeho prezidentství, a myslel jste to vážně, každé slovo."],["Zveřejněte to jako audioknihu, kterou sám nahrajete.","Padesát jedna hodin. Umístí se v žebříčcích. Někdo si to celé poslechne a najde nesrovnalost na straně 611, kterou by nikdo jiný na planetě nikdy nenašel."]]},"b-shutdown-two":{"t":"Druhý shutdown","x":"Den dvacet devět. Lyle už přestal odhadovat konec. „Čtyři agentury běží z peněz, které jsme přesunuli z míst, kam je výslovně umístil Kongres. Pane, potřebuji, abyste pochopil, že nezákonná je ten přesun, ne samotný shutdown.“","c":[["Pokračujte v přesunech peněz. Řiďte vládu z rezidence.","Vláda dál funguje, financovaná prezidentem místo rozpočtovým opatřením. Nejčistší možná odpověď na to, čím se tento úřad tiše stal."],["Přesouvejte peníze jen na mzdy a bezpečnostní funkce.","Obhajitelná nouzová linie, kterou přijmou čtyři soudy a jeden ne. Řídící letového provozu dostanou zaplaceno a politické hodiny přestanou tikat."],["Přijměte dohodu, která je na stole. Ukončete to dnes večer.","Dohoda je horší než ta, kterou jste odmítl čtvrtý den. Dvacet pět dní nekoupilo naprosto nic, což je obvyklý výsledek tohoto konkrétního tahu."],["Vyhlaste shutdown státním svátkem.","Osm set tisíc lidí se dozví, že jejich nucené volno je teď svátek. Čtyři agentury se vyzdobí. Je to ponuré a je to důkladně zdokumentované."]]},"b-wall-money":{"t":"Přeprogramování","x":"Tarrant má seznam toho, co se zastaví, pokud se peníze přesunou. „Škola na základně v Kentucky. Nemocniční křídlo v Německu. Kasárna ve čtyřech státech.“ Odloží ho. „Přesunu to, jakmile mi to nařídíte. Chtěl bych, aby ten seznam byl při tom veden v záznamu.“","c":[["Přesuňte to. Všechno. Seznam ať jde do šuplíku.","Škola se nepostaví. Nestojí ani o devět let později a pořád je na seznamu, který každý březen nahlas přednáší kongresman z Kentucky na plénu."],["Přesuňte polovinu. Školu a nemocnici nechte být.","Volba, které projekty zemřou, je celý rozdíl mezi politikou a osobní zlobou, a Tarrant se postará, aby ta volba byla zdokumentovaná."],["Nepřesouvejte to. Postavte to, co bylo schváleno.","Devadesát mil toho, co jste sliboval, plus škola, nemocniční křídlo a čtvery kasárna. Fotka, kterou nikdo nechce být viděn, jak pořizuje."],["Přesuňte peníze a pojmenujte zeď po té škole.","Pamětní deska vzdává hold vzdělávacímu zařízení, které bylo zrušeno kvůli tomu, aby se ta deska zaplatila. Instaluje se. Pozoruhodně tam pořád visí."]]},"b-crime-emergency":{"t":"Nouzový stav kvůli kriminalitě","x":"Duane Krisp má příkaz. „Federalizuje jak gardu okresu, tak jeho policejní sbor. Oboje. Pane, čísla kriminality klesla meziročně o dvacet dva procent. Je to v našem vlastním briefingu. Na první stránce.“","c":[["Podepište ho. O čísla vůbec nejde.","Městská policie teď odpovídá prezidentovi. Dvakrát se to prodlouží, stojí to třetinu miliardy dolarů, a čísla kriminality dál klesají přesně stejným tempem jako vždycky."],["Federalizujte jen gardu. Policii nechte na pokoji.","Poloviční příkaz a čtvrtinové pobouření. Policejní ředitelka si udrží velitelský řetězec a tiše vás stejně informuje."],["Žádný nouzový stav. Místo toho financujte vlastní sbor města.","Kriminalita klesne o dalších devět procent a starostka vám na kameru poděkuje, což pro vaše hnutí neznamená nic, ale pro vás osobně dost."],["Vyhlaste nouzový stav kvůli samotným číslům kriminality.","Prohlášení označí klesající čísla samotná za podezřelá. Statistik z úřadu justiční statistiky rezignuje e-mailem ve čtyři ráno."]]},"b-332":{"t":"Tři sta třicet dva milionů","x":"Zaměstnanci opozice ve výboru vyčíslili nasazení na 332 milionů dolarů do února. Lyle: „Je to odhad, a přiznají to. Zároveň je to jediné číslo, jaké kdo vyprodukoval, pane, což znamená, že teď je to to číslo.“","c":[["Zpochybněte to číslo. Vlastní nepředkládejte.","Zpochybnit číslo, aniž byste nabídl vlastní, ponechá to původní stát, jen s přišroubovaným slovem „sporné“, což nezmění přesně nic."],["Zveřejněte skutečnou cenu. Je nižší.","Je to 291 milionů dolarů, což je zároveň nižší i obrovské. Oprava je přesná a naprosto nepomůže."],["Ukončete nasazení. Odvolejte se na náklady.","Stažení z fiskálních důvodů je jediný odchod, který nepůsobí jako ústup. Nabízí se to zhruba šest dní, a vy toho využijete."],["Naúčtujte to městu.","Faktura na 332 milionů dolarů je zaslána městské správě s ročním rozpočtem nižším, než je toto číslo. Její finanční ředitel si ji dá do rámečku."]]},"b-quick-reaction":{"t":"Specializovaná jednotka","x":"„Specializovaná jednotka plus stálá celostátní rychlá reakční síla pro civilní nepokoje.“ Tarrant si to přečetl čtyřikrát. „Pane, stálá síla s domácí misí je úplně jiné zvíře než nasazení. Nasazení jednou skončí. Tohle je věc, která prostě existuje.“","c":[["Zřiďte ji. Celostátně. Natrvalo.","Stálá federální síla pro domácí nepokoje, v pohotovosti, navždy. Čtyři generálové v důchodu napíší společný dopis, a to je ta nejmírnější reakce, jakou dostanete."],["Zřiďte jednotku. Bez stálé celostátní síly.","Schopnost bez stálého poslání je nástroj, ne postoj. Tarrant podepíše tuto verzi bez zaváhání, jaké měl u té druhé."],["Ani jedno. Garda existuje a odpovídá guvernérům.","Stávající uspořádání funguje, protože ho navrhli lidé, kteří o tom skutečně přemýšleli. Nikdo nikomu neděkuje za systém, který prostě pokračuje."],["Zřiďte ji a obsaďte ji výhradně vojenskými hudebníky.","Čtyři sta hudebníků je přeřazeno na povinnosti spojené s civilními nepokoji. Podle všech pozdějších svědectví si počínají znepokojivě disciplinovaně."]]},"b-state-guard":{"t":"Guvernérka řekla ne","x":"Guvernérka Vasquez-Moore písemně odmítla a dopis zveřejnila. „Její garda, její stát, její rozhodnutí, pokud je nefederalizujete, v kterémžto případě jsou vaše a ona jen přihlíží.“ Tarrant dodává: „Pane, ať tak či onak, je to titíž vojáci. Mění se jen hlavička.“","c":[["Federalizujte je. Její námitka je vzata na vědomí a je bezvýznamná.","Do čtyř hodin vás žaluje. Ať dopadne rozsudek jakkoli, každý guvernér v zemi teď ví, že jedinou ochranou byla vždycky jen ta hlavička."],["Federalizujte gardu jiného státu a pošlete ji tam.","Vojáci z jednoho státu hlídkující v druhém přes námitky obou guvernérů. Legální, bezprecedentní, a fotky obletí celý svět."],["Přijměte její odmítnutí. Místo toho nabídněte federální financování.","Vezme si peníze a vyřeší to sama, kompetentně, za devět dní. Nedostane se vám žádné zásluhy ani žaloby, naprosto férová výměna."],["Federalizujte samotnou guvernérku.","Právníků se vážně zeptají, jestli lze federalizovat osobu. Odpovědní memorandum má čtyři slova a jedno z nich je „ne“."]]},"b-poll-worker":{"t":"Okresní komise","x":"„Certifikace je funkce státu. Provádějí ji okresní komise, dobrovolníci, penzionovaní učitelé, chlapík, co opravuje kotle.“ Bo je neklidný. „Můžeme proti kterémukoli z nich zahájit federální šetření. Ne kvůli obžalobě. Jen aby se jim to dělo, ve čtyřech týdnech před certifikací.“","c":[["Zahajte šetření v jedenácti nejtěsnějších okresech.","Nikdo není obžalován. Čtyři komise úplně ztratí usnášeníschopnost, protože dobrovolníci raději rezignují, než aby byli vyšetřováni, a usnášeníschopnost je přesně to, co certifikace vyžaduje."],["Zahajte jedno, tam, kde existuje skutečné podání.","Skutečný případ, řešený běžně. Skončí až po certifikaci a najde administrativní chybu, čímž tyhle věci téměř vždy skončí."],["Místo toho pošlete pozorovatele. Žádná šetření.","Federální pozorovatelé jsou stará, nudná instituce, kterou obě strany používají šedesát let. Nikdo nerezignuje a všechno se certifikuje včas."],["Federalizujte toho chlapíka od kotlů.","Devět dní před certifikací mu je nabídnuto federální jmenování. Odmítne, certifikuje a pak poskytne jeden mimořádně suchý rozhovor."]]},"b-fisa":{"t":"Prodloužení","x":"Errol Hance má návrh na obnovení zmocnění. „Míří to do zahraničí. Mimoděk se tím ale ve velkém sbírají data o Američanech, a pravidla pro dotazování se nastavují interně.“ Odmlčí se. „Mnou. Což v praxi znamená vámi, a jediné, co stojí mezi těmi dvěma větami, je formulář.“","c":[["Uvolněte pravidla pro dotazování. Rozšiřte kategorie.","Domácí dotazy do roka vzrostou jedenáctinásobně. Zpráva o dodržování předpisů, která to dokládá, je utajena, založena, a přečte si ji celkem devět lidí."],["Ponechte pravidla. Obnovte to beze změny.","Nudné obnovení nudné pravomoci. Errolovi se viditelně uleví, což je nejvíc informací, kolik vám kdy dobrovolně poskytl."],["Zpřísněte je. Vyžadujte soudní příkaz pro domácí dotazy.","Stojí to agentury čtyři dny provozu a kupuje to pravomoci dalších dvacet let politického přežití. Errol to vděčně napíše, písemně."],["Vyhledejte sebe sama a podívejte se, co vyjde.","Podstatně víc, než jste čekal. Už se o tom nikdy nezmíníte, stejně jako nikdo jiný v místnosti, a záznam zůstává přesně tam, kde je."]]},"b-ai":{"t":"Model","x":"„Data držíme legálně. Všechna, oddělěně, z různých důvodů.“ Errol otočí notebook. „Nové je, že model teď dokáže přečíst všechno najednou a říct vám, kdo pravděpodobně něco chystá. Pane, na tohle nikdo nenapsal pravidlo, protože nikdo nevěřil, že to bude opravdu fungovat.“","c":[["Spusťte to. Celostátně. Dejte mi seznam.","Jedenáct tisíc jmen, seřazených podle čísla, které nikdo nedokáže vysvětlit, ani lidé, kteří to postavili. Čtyři sta z nich jsou novináři."],["Spusťte to jen na zahraničních sítích. Domácí data oddělte firewallem.","Firewall je skutečný a drží přesně tak dlouho, dokud je za jeho udržování někdo placený. Errol se postará, aby ten někdo dostával plat jedenáct let."],["Nestavte to. Napište pravidlo, které to zakáže.","Pravidlo má čtyři odstavce a je důvodem, proč tahle schopnost v roce 2040 stále neexistuje. Nikdo se nikdy nedozví, že to byla volba."],["Zeptejte se modelu, kdo by podle něj měl být prezidentem.","Odpoví okamžitě, s naprostou jistotou. Odpověď nejste vy. Přepis je zničen a dvakrát rekonstruován."]]},"b-margins":{"t":"Padesát tři, čtyřicet sedm","x":"Hal má aritmetiku na ubrousku. „Padesát tři, čtyřicet sedm v Senátu. Dvě stě dvacet, dvě stě patnáct tady, a rozdíl se zmenšuje pokaždé, když někdo zemře. Obstrukce zůstává nedotčená. Pane, máte ovládnutí obou komor i úřadu, ale to není totéž co většina, která dokáže něco skutečně prosadit.“","c":[["Tak nic nelegislativujte. Dělejte všechno příkazy.","Nic z toho, co vybudujete, nemá pod sebou zákon, takže to všechno může za jedno odpoledne smazat kdokoli přijde po vás. Víte to, a stejně to uděláte."],["Věnujte funkční období čtyřem zákonům. Skutečným zákonům.","Dva projdou. V roce 2049 jsou pořád zákonem, což je asi dvacetkrát déle, než přežije cokoli jiného, čeho se dotknete."],["Zrušte obstrukci.","Čtyři vaši vlastní senátoři veřejně na plénu odmítnou. Poprvé za toto funkční období vám vlastní strana řekne ne a myslí to vážně."],["Nechte místo toho těch dvě stě patnáct přísahat jako poradce.","Celému opozičnímu poslaneckému klubu se rozešlou dopisy s nabídkou neplacených poradních rolí. Devět jich přijme, čistě ze zvědavosti, a nikdy jim není přiděleno jediné téma, ke kterému by měli radit."]]},"b-abdication":{"t":"„Přihlížel a nedělal nic“","x":"Dr. Weirová má studii. „Argument nezní, že Kongres byl poražen. Zní, že Kongres odmítl.“ Fráze zní „přihlížel a nedělal nic“. Vzhlédne. „Pane prezidente, tahle studie je o vašich odpůrcích, ne o vás, a pro vás je to podstatně horší, než kdyby byla o vás.“","c":[["Rozešlete ji. Zarámujte ji. Je to kompliment.","Čtyři členové si přečtou svou vlastní nečinnost popsanou akademicky, chladným tiskem, a vůbec se jim to nelíbí. Dva začnou skutečně chodit na slyšení."],["Neříkejte nic. Akademická studie je akademická studie.","Za pět let je citována devět set krát a v téhle budově se o ní nikdy nezmíní, což je přesně to, jak tyhle věci obvykle dopadají."],["Pozvěte předsedy výborů. Dejte jim něco k dohledu.","Nepřátelskému výboru předáte čtyři skutečné dokumenty. Dohled se obnoví, je únavný a chrání vás před devíti pozdějšími obviněními."],["Nechte Kongres schválit usnesení popírající, že nic nedělá.","Projde poměrem 388 ku 41. Je to jediná věc, kterou komora celý týden udělá, což si řádně poznamená každý jediný, kdo o tom informuje."]]},"b-article-48":{"t":"Srovnání v poznámce pod čarou","x":"Dr. Weirová má odborný právnický článek. „Tvrdí, že vaše nouzové zákony fungují jako americká obdoba otevřeného nouzového ustanovení, a konkrétně jmenuje to výmarské.“ Zavře ho. „Autor je opatrný. Ta poznámka pod čarou není obvinění. Je to varování před tou architekturou.“","c":[["Napadněte autora. Nazvěte to srovnáním s nacisty.","Článek se za čtrnáct dní dostane ze čtyř tisíc čtenářů na čtyři sta tisíc a ta poznámka pod čarou je teď titulek."],["Ignorujte to. Je to právnický časopis.","Přečte si to devět lidí a jeden z nich je zaměstnanec Senátu, což je přesně způsob, jak se z poznámky pod čarou za tři roky stane zákon."],["Požádejte Kongres, ať do nouzových zákonů vloží doložky o automatickém zániku.","Doložky projdou. Každá nouzová pravomoc, kterou máte, teď vyprší k danému datu, včetně těch, na které jste se tiše spoléhal, a sám jste to podepsal."],["Vyhlaste nouzový stav kvůli tomu srovnání.","Prohlášení číselně odkazuje přímo na to samé ustanovení, ke kterému se přirovnává, rovnou ve vlastním oddíle o právním základu. Dr. Weirová si to nechá zalaminovat."]]},"b-emergency-stack":{"t":"Čtyřicet jedna aktivních nouzových stavů","x":"„Aktuálně platí čtyřicet jedna celostátních nouzových stavů.“ Sy to spočítal. „Třicet čtyři existovaly ještě před vámi. Jeden se obnovuje každý rok od roku 1979, a země, které se týká, se dnes jmenuje jinak. Pane, nikdo je nekontroluje. Prostě se automaticky obnovují, rok co rok.“","c":[["Obnovte je všechny. Přidejte dalších šest.","Čtyřicet sedm souběžných nouzových stavů, každý odemyká pravomoci, které nikdy nikdo neprověřil. Nejmocnější věc v této budově, a je celá udělaná z papírování."],["Obnovte je. Ten z roku 1979 tiše ukončete.","Ukončení mrtvého nouzového stavu nic nestojí a krátce se o tom napíše jako o vzácném záchvatu pořádkumilovnosti."],["Prověřte všech čtyřicet jedna. Zveřejněte, které jsou opravdové.","Prověrku přežije jedenáct. Dobrovolně jste se vzdal třiceti souborů stálých pravomocí, a ani vaši nástupci vám za to nepoděkují."],["Sloučte všech čtyřicet jedna do jednoho velmi velkého nouzového stavu.","Jedno jediné prohlášení pokrývající vše od íránských aktiv po invazní brouky. Sy tomu říká „ten balík“ a odmítá se dál rozepisovat."]]},"b-education-injunction":{"t":"Poloviční soudní zákaz","x":"Bernadette Ollisová má rozsudek. „Blokuje tu část, která přesouvá portfolio studentských půjček. Neblokuje tu část, která zavírá jedenáct oblastních úřadoven. Ministerstvo tak formálně stále existuje, pane, ale v Denveru už nikoho nemá.“","c":[["Zavřete všechno, co soudní zákaz výslovně nejmenoval.","Ministerstvo existující na papíře a nezvedající žádný telefon. Čtyři státy si zřídí vlastní úřady, aby tu práci dělaly, a naúčtují to federální vládě."],["Podřiďte se v plném rozsahu. Celý útlum pozastavte.","Pozastavit všechno, dokud se jedna část projednává u soudu, je to, co by udělala normální administrativa, a obě strany to berou jako přiznání porážky."],["Zavřete úřady. Odvolejte se ohledně portfolia půjček.","Vezmete si vítězství, které vám bylo předáno, a zbytek řádně dosoudíte. Nudné, legální, a za čtrnáct měsíců získáte většinu z toho, co jste chtěl."],["Přesuňte celé ministerstvo do Denveru.","Jedenáct set zaměstnanců dostane pokyn přestěhovat se do úřadu, který jste se právě pokoušel zavřít. Čtyři sta jich rezignuje, což všichni tiše chápali jako záměr."]]},"b-anticipatory":{"t":"Nikdo jim nevolal","x":"Dr. Weirová má seznam čtyř institucí, které tento měsíc změnily politiku. „Firma, univerzita, filmové studio, banka.“ Odloží ho. „Pane prezidente, nikdo z nich nebyl kontaktován. Ani jeden. Existuje pro to název, předběžná poslušnost, a je to nejlevnější druh moci, jaký existuje.“","c":[["Neříkejte nic a nechte to šířit.","Dalších devět institucí se do čtvrtletí podvolí, zcela nevyzváno, a není proti čemu se odvolat, protože žádný příkaz vlastně nikdy neexistoval."],["Veřejně jim řekněte, že je o to nikdo nežádal.","Dvě ze čtyř do týdne couvnou. Vyslovit to nahlas je jediné, co to kdy zlomí, a stojí vás to celý ten mechanismus."],["Vřele je jmenovitě pochvalte.","Chvála je přesně to potvrzení, na které čekaly další čtyři instituce. Účinnější než jakákoli hrozba, a nedá se popsat jako hrozba."],["Požádejte je všechny, ať uposlechnou něco, co jste si ještě nevymyslel.","Vyjde prázdný pokyn. Dvě organizace ho písemně uposlechnou, a nikomu, včetně nich samotných, není jasné, s čím vlastně souhlasily."]]},"b-university-out":{"t":"Univerzita, která byla požádána, aby odešla","x":"Ollisová si přečetla, jak se to dělalo jinde. „Nikdo tu univerzitu nezavřel. Změnili akreditační pravidlo a vízové pravidlo, a univerzita odešla sama, takže všichni zúčastnění mohli pravdivě říct, že nic nezavřeli.“ Vzhlédne. „Tady bychom to mohli zvládnout do čtvrtka.“","c":[["Změňte obě pravidla. Ať se rozhodnou odejít sami.","Do roka se přestěhují do jiné země. Žádný příkaz nebyl podepsán, nic nebylo zakázáno, a není proti čemu se odvolat, protože žádné rozhodnutí nikdy nepadlo."],["Změňte jen vízové pravidlo.","Dost tření, aby to bylo cítit, ne dost na to, aby to bylo smrtelné. Nábor pedagogů klesne o třicet procent a nikdy se o tom nenapíše."],["Ani jedno. Místo toho na ně útočte v projevech.","Rétorika nic nezmění a nic nestojí. Jejich nadační fond roste, přihlášek přibývá a vy přednesete tentýž projev ještě čtyřikrát."],["Založte konkurenční univerzitu a sám ji akreditujte.","Otevře se se čtyřmi sty studenty, jedenácti fakultami a mramorovou vstupní halou. Její první absolventský ročník je podle jakéhokoli měřítka extrémně loajální."]]},"b-savings-audit":{"t":"Číslo úspor","x":"Roscoe oznámil úspory ve výši 180 miliard dolarů. Čtyři nezávislá média to teď ověřila. Deborah: „Číslo, které skutečně obstojí, je asi devět miliard, pane, a zhruba třetina z toho je smlouva, která byla zrušena ještě předtím, než jste nastoupil do úřadu.“","c":[["Trvejte na tom čísle. Opakujte ho denně.","Propast mezi oběma čísly se stane trvalou kauzou a u každé budoucí úspory, kterou oznámíte, se teď oprávněně předpokládá, že je to dvacetina toho, co tvrdíte."],["Zveřejněte podkladovou účetní knihu. Celou.","Skutečné číslo je devět miliard a je ověřitelné, což se ukáže jako podstatně cennější než sto osmdesát neověřitelných."],["Opravte ho na devět miliard. Řekněte, že se zlepšila metodika.","Tichá oprava, které si všimnou čtyři lidé. Je to jediný druh opravy, který kdy skutečně funguje, a nikoho nebaví ji dělat."],["Místo toho oznamte 1,8 bilionu dolarů.","Přidat nulu je rychlejší než obhajovat původní číslo, a u davu to zabere naprosto stejně dobře, což je na tom to skutečně znepokojivé zjištění."]]},"b-rehire-order":{"t":"Vraťte je zpátky","x":"Soudce nařídil znovupřijetí do zaměstnání. Deborah má praktickou poznámku. „Čtyři agentury to zvládnou podřídit do pátku. Dvě ne, protože už předaly kancelářské prostory a smazaly přístupy do systémů, a smazání trvalo jedenáct minut, zatímco obnova trvá devět měsíců.“","c":[["Podřiďte se tam, kde je to snadné. Jinde se odvolávejte na nemožnost.","Nemožnost, kterou jste si sám vyrobil unáhleností, je v očích zákona pořád nemožnost, a funguje to. Soudce o tom napíše odstavec a Kongres si ho přečte nahlas."],["Podřiďte se všude. Obnovte systémy.","Stojí to osmdesát milionů dolarů a devět měsíců na odčinění jedenácti minut unáhlenosti. Poučení je drahé, správné, a nikdy si ho nikdo neosvojí."],["Znovu je přijměte na papíře. Nedávejte jim žádnou práci.","Formálně vyhovující zaměstnání bez povinností, bez přístupů a bez stolu. Čtyři z nich žalují znovu, a tentokrát si s sebou přinesou první rozsudek."],["Znovu je přijměte a povyšte je nad lidi, kteří je vyhodili.","Organizační schéma je teď fakticky diagram pomsty. Produktivita ve dvou agenturách měřitelně stoupne a nikdo o tom nechce mluvit."]]},"b-loyalty-questionnaire":{"t":"Otázka jedenáct","x":"Nový přijímací dotazník má jedenáct otázek. Deset je normálních. Deborah přečte tu jedenáctou nahlas a v půlce se zastaví. „Pane, ptá se, kterou z vašich politik uchazeč obdivuje nejvíc. Tohle je na místo inspektora mostů.“","c":[["Ponechte otázku jedenáct. Použijte ji všude.","Mosty inspektují lidé, kteří vás obdivují. Inspekce je v průměru o něco horší, a to zjištění tady zahrnuje jeden konkrétní most."],["Ponechte ji pro politické funkcionáře. U kariérních zaměstnanců ji zrušte.","Rozlišení, které existuje od roku 1883, které nikdo v této budově nemusel vymýšlet, protože tu práci už za nás udělal někdo jiný."],["Smažte ji. Přijměte nejlepšího uchazeče.","Inspektorát mostů obsadí čtyři místa, která byla volná dva roky. Žádný most se nezřítí. Nikdo to s ničím nespojuje."],["Udělejte z otázky jedenáct jedinou otázku.","Přihláška s jedinou otázkou pro celou federální vládu. Počet přihlášek vzroste o čtyři sta procent a úroveň je přesně taková, jakou byste čekal."]]},"b-inspector-vacancies":{"t":"Prázdné úřady","x":"Miriam má přehled. „Sedmnáct odvoláno, a jedenáct z těch úřadů je i po čtrnácti měsících pořád prázdných. Ne blokovaných, pane. Prázdných. Nikdo nebyl ani nominován. Kontroly, které měly proběhnout, prostě neproběhly, a nikde není záznam o tom, že neproběhly.“","c":[["Nechte je prázdné. Na neurčito.","Dohledová funkce přestane existovat, aniž by byla kdy formálně zrušena. Zdaleka nejefektivnější věc, jakou kdo za toto období udělá, a vyžadovalo to nulovou akci."],["Obsaďte je pověřenými úředníky zevnitř.","Pověření inspektoři, kteří odpovídají přímo lidem, jež mají inspektovat. Čtyři z nich přesto dělají práci pořádně, což je pro všechny zúčastněné skutečné překvapení."],["Nominujte jedenáct skutečných inspektorů. Pošlete je ke schválení.","Devět je schváleno. Dva do roka vypracují zprávy, které jsou pro vás mimořádně špatná zpráva, a zbylých sedm vypracuje zprávy o zadávání zakázek."],["Jmenujte jednoho generálního inspektora pro všech jedenáct agentur.","Jedna osoba, jedenáct agentur, čtyři sta tisíc zaměstnanců. Devět měsíců dře na doraz a pak zveřejní něco pozoruhodného."]]},"b-settlement-culture":{"t":"Čtvrté vyrovnání","x":"„Čtvrtá firma se vyrovnala v případu, o kterém její vlastní právníci tvrdili, že ho vyhraje.“ Syovi se to vůbec nelíbí. „Teď už je v tom vzorec, pane, a vzorec je přípustný jako důkaz způsobem, jakým čtyři samostatné případy nikdy nejsou. Někdo, někde, ho použije u soudu.“","c":[["Zažalujte pátou. Vzorec je produkt.","Vyrovnají se za jedenáct dní bez jednání. Občanskoprávní žaloba je teď prostě poplatek za to, že o vás informovali, a všichni už znají aktuální sazbu."],["Do konce funkčního období nikoho dalšího nežalujte.","Vzorec potřebuje pátý případ, aby se z něj skutečně stal vzorec. Odepřít mu ho je zadarmo a tiše to umře už ve fázi sepisování něčí žaloby."],["Nasměrujte veškeré budoucí výnosy na charitu, kterou nekontrolujete.","Odstranění osobního prospěchu odstraní většinu argumentu. Zároveň to odstraní většinu smyslu, a čtyři lidé si toho okamžitě všimnou."],["Zažalujte sám sebe, abyste ustavil příznivý precedens.","Obě strany zastupují vládní právníci. Případ je zamítnut pro nedostatek sporu devítislovým usnesením, které je široce, téměř s něhou, obdivováno."]]},"b-schedule-list":{"t":"Seznam k reklasifikaci","x":"\"Seznam k reklasifikaci.\" Deborah ho opatrně pokládá na stůl. \"Padesát tisíc kariérních míst přesunutých do kategorie s nulovou ochranou před propuštěním. Meteorologové. Posuzovatelé grantů. Dvě stě statistiků.\" Odmlčí se. \"Statistiky bych se bál nejvíc, pane.\"","c":[["Reklasifikovat všech padesát tisíc.","Nikdo nemusí být vyhozen. Padesát tisíc lidí teď prostě ví, že by mohli být, a statistiky, které produkují, se začnou nepatrně, samy od sebe zlepšovat."],["Reklasifikovat jen politické posty. Technické nechat být.","Hranice mezi politikou a měřením, stará sto čtyřicet let, existuje přesně kvůli tomuhle."],["Seznam úplně stáhnout.","Meteorologové dál předpovídají a statistici dál počítají, a za devatenáct měsíců vám jeden z těch součtů zachrání volby."],["Reklasifikovat je a nechat je reklasifikovat vás.","Recipročním formulářem, který koluje jako vtip, vyplní za jeden den jedenáct tisíc federálních zaměstnanců. Výsledky nikdy nikdo nezveřejní."]]},"b-weyland":{"t":"Nesouhlasný badatel","x":"Dr. Weirová vám přinesla něco nečekaného. \"Vážený vědec, který tvrdí opak konsenzu, že instituce drží, že poplach je přehnaný, že tohle přejde.\" Podává vám to. \"Pane prezidente, chci mít jasno, že jsem to přinesla, protože je to dobrá práce, ne proto, že s ním souhlasím.\"","c":[["Dát ho do všech pořadů. Je to protiargument.","Je to opatrný muž, který říká opatrné věci, a tím, že si ho osvojíte, přijde přesně o tu vlastnost, díky které stálo za to si ho osvojit."],["Přečíst si to pořádně. Nic neměnit.","Je to nejzajímavější hodina vašeho prezidentství. Nic z ní neplyne a dr. Weirová se k tomu už nikdy nevrátí."],["Nechat ho debatovat s konsenzem, naživo, a sám se do toho nemíchat.","Dvě hodiny opravdové debaty před devíti miliony lidí. Nic to nevyřeší, ale je to zdaleka nejzdravější věc, co se ten rok stane."],["Jmenovat ho, ať prověří, jestli jste autoritář.","Přijme to pod podmínkou plného přístupu a práva na zveřejnění. Obojí mu písemně přiznáte, aniž byste si zjevně přečetl to druhé."]]},"c-defiance":{"t":"Příkaz, který neuposlechnete","x":"Šest ku třem, a napsáno tak, že by to pochopilo i dítě. Sy přestal dělat poznámky. \"Pane, do dneška každý spor byl o tom, co příkaz *znamená*. Tenhle znamená jen jedno. Pokud ho budete ignorovat, poprvé to tak udělá někdo. A každý badatel, co se tímhle živí, to už napsal černé na bílém: tohle je ta hranice.\"","c":[["Neuposlechnout. Říct to nahlas.","Republika toho odpoledne nepadne. Stane se místo toho něco tišího: každá instituce v zemi si v soukromí přepočítá, na co se může spolehnout, a žádná tu novou hodnotu nezveřejní."],["Uposlechnout, a rok denně útočit na soud.","Poslušnost okořeněná pohrdáním vás strukturálně nic nestojí a koupí vám rok obsahu plného křivd. Je to tah, který udělal každý váš předchůdce, jen nikdy tak nahlas."],["Uposlechnout. Plně. Říct, že to bylo správné rozhodnutí.","Přijdete o politiku i o ten týden. Čtyři badatelé, kteří už napsali, že neuposlechnete, tiše vydají opravu, a ta oprava se ukáže jako to nejcennější, co vlastníte."],["Uposlechnout ve státě, který neexistuje.","Žádost o splnění příkazu uvádí jurisdikci, která není na žádné mapě. Přesto ji zaevidují. Čtyři úředníci stráví čtrnáct dní debatou, jestli je to překlep, nebo manifest."]]},"c-postpone":{"t":"Datum","x":"Deborah za sebou zavřela dveře. \"Existuje argument, špatný, ale argument, že mimořádné pravomoci sahají až na správu federálních voleb.\" Nesedá si. \"Pane, pracuju pro vás čtyři roky. Chci mít v záznamu, že jsem vám řekla, že tohle je ta chvíle.\"","c":[["Odložit je. O devadesát dní. Kvůli bezpečnosti.","Čtyři guvernéři oznámí, že volby uspořádají stejně, v původním termínu, podle státního práva, na které mají plné právo. Jediná otevřená otázka je, jestli je někdo přijde zastavit."],["Volby uspořádat. Napadnout každý těsný okres potom.","Bojovat proti sčítání je boj uvnitř systému. Zrušit sčítání ne. Ten rozdíl vás nic nestojí a ukáže se, že je to celý rozdíl."],["Uspořádat je v termínu. V případě prohry uznat porážku.","Tu větu vyslovíte nahlas, předem, před kamerou. Převáží nad vším, co jste za čtyři roky řekl, a vaše vlastní hnutí vám to, že jste to myslel vážně, tak úplně neodpustí."],["Uspořádat volby o týden dřív, jako překvapení.","Čtyři státy se to dozví poštou. Účast tam skončí na 19 procentech a všechny výsledky se zruší, aniž by to musel kdokoli žalovat, protože se pro jednou všichni okamžitě shodli."]]},"c-jail-opponent":{"t":"Obžaloba","x":"Bo má na Cordelii Ruiz-Bloomovou spis a drží ho, jako by byl ještě teplý z tiskárny. \"Nesrovnalost v podání z roku 2019 a procesní argument, za který bych se styděl, kdybych ho měl vyslovit nahlas. Před soudem by to neobstálo.\" Odkládá ho. \"Nemusí to obstát před soudem, aby ji to udrželo v soudní síni dva roky.\"","c":[["Obvinit ji. Dnes. Proces je trest.","Za dvacet šest měsíců ji zprostí viny a do té doby je nejslavnější opoziční osobností na polokouli. Čtyři země, kterým běžně kážete o právním státu, ji dají jako první příklad."],["Vyšetřovat. Neobviňovat. Nechat to viset.","Otevřený spis bez obvinění je verze, která skutečně funguje: všechen stín, žádný proces, a nic, proti čemu by se dalo odvolat."],["Zavřít spis. Říct jí, že jste ho zavřel.","Devět měsíců vám nevěří. Když nakonec uvěří, řekne to veřejně, a stojí vás to čtyři body ve státě, který jste potřeboval."],["Obvinit ji jen z chyby v podání z roku 2019 a z ničeho jiného.","Národní opoziční vůdkyně stojí obviněná kvůli úřednímu formuláři. Maximální trest je pokuta 400 dolarů, kterou zaplatí v hotovosti na schodech soudu, před kamerou, a účtenku si nechá."]]},"c-enabling":{"t":"Zmocňovací zákon","x":"Hal Grimes něco navrhl a vypadá, jako by ho to zaživa zžíralo. \"Čtyři stránky. Dávají vám pravomoc měnit nebo pozastavit jakýkoli zákon během vyhlášeného stavu nouze, a stav nouze vyhlašujete vy.\" Odkládá to. \"Dokážu to protlačit touhle komorou, pane. Přesně to mě děsí.\"","c":[["Schválit ho. Obě komory. Tento měsíc.","Zákonodárný sbor, který si odhlasuje pryč vlastní funkci, byl poslední položkou na seznamu každého badatele. Teď je to jediná odškrtnutá položka."],["Schválit verzi se dvouletou doložkou o zániku platnosti.","Doložka o zániku platnosti je celý rozdíl mezi delegací a abdikací. O dva roky později tiše vyprší, protože ji všichni zapomenou obnovit."],["Nepředkládat ho. Místo toho žádat čtyři konkrétní zákony.","Běžným hlasováním dostanete tři ze čtyř. Jsou trvalé, nenapadnutelné, a nikdo o nich nikdy nenapíše kapitolu do knihy."],["Schválit ho a pravomoc rovnou delegovat zpátky Kongresu.","Zákon, který na vás přenáší pravomoc, a příkaz, který ji hned přenáší zpátky, oba podepsané téhož odpoledne. Čtyři ústavní právníci tomu říkají \"smyčka\" a moudře to tam nechají."]]},"c-vote-machines":{"t":"Certifikace","x":"Čtyři státy dosud necertifikovaly výsledky. Jejich guvernéři jsou z obou stran a řekli přesně totéž: certifikace je pravomoc státu a sčítání je sčítání. Bo: \"Můžeme vydat federální pokyn, ať to pozastaví. Nemá to žádnou právní sílu. Má to obrovské množství té druhé.\"","c":[["Vydat pokyn. Nařídit všem čtyřem pozastavení.","Tři přesto do dne certifikují. Čtvrtý pozastaví na jedenáct dní a jeho zákonodárný sbor je na vlásku od něčeho, o čem se soudí ještě v roce 2039."],["Poslat federální pozorovatele. Žádný pokyn.","Pozorovatelé sledují sčítání a napíší zprávu, že to skutečně bylo sčítání. Je to nejstarší a nejnudnější nástroj v bedně a funguje přesně proto, že takový je."],["Neříkat nic. Certifikace je jejich věc.","Všechny čtyři státy certifikují podle plánu. O čtyři roky později je tohle fakt, na který se při vaší obhajobě odvolávají nejčastěji, a to lidé, u kterých byste to nečekal."],["Certifikovat výsledky sám, odsud.","Podepsaný federální certifikát pro státní volby se pošle do státu, který už vydal vlastní. Jeho tajemník ho založí do složky \"korespondence\"."]]},"c-electors":{"t":"Alternativní volitelé","x":"\"Ve třech státech byla sestavena druhá sada volitelů.\" Sy čte z dokumentu, o kterém zjevně přál, aby mu nikdy nepřistál na stole. \"Žádný právní základ. Podepsané formuláře. Pane, celá teorie je, že podepsaný formulář vytvoří spor, a spor vytvoří volbu.\"","c":[["Předat všechny tři sady. Ať si vybere Kongres.","Čtyři z lidí, kteří ty formuláře podepsali, jejich vlastní státy do dvou let stíhají. Nikdo z nich nedostal informaci, že tohle je na stole."],["Předat je, ale zbavit se jakéhokoli právního účinku.","Sada volitelů zbavená účinku je tisková zpráva s ověřeným podpisem. Vyvolá veškerou nevoli a žádná obvinění."],["Odmítnout sady. Veřejně. Jmenovitě.","Tiše uchráníte čtyřicet jedna lidí trestní odpovědnosti, o které se nikdy nedozvědí, protože věc, které jste zabránil, nikdy nedostane jméno."],["Sestavit třetí sadu, která hlasuje pro opozici.","Předloženo čistě proto, aby to zamotalo záznamy, a povede se to nad veškerá rozumná očekávání. Nikdo, na žádné straně, si to nedokáže vysvětlit devět měsíců."]]},"c-third-term-poll":{"t":"Otázka v průzkumu","x":"Nadia Fisková spočítala čísla. \"Čtyřicet jedna procent vašich vlastních voličů říká, že byste měl zůstat i po skončení funkčního období. Ne 'zvážil bych to'. 'Měl by.'\" Zvedne oči. \"Pane, tu otázku jsem do průzkumu nedala já. Někdo z vašeho týmu mě o to požádal, a chci to mít v záznamu.\"","c":[["Zveřejnit číslo. Nechat ho, ať odvede práci.","Číslo není návrh, a právě proto je užitečnější než návrh. Nikdo ho nemusí hájit a všichni na něj musí reagovat."],["Průzkum zamést pod koberec. Tu otázku už nikdy nepokládat.","Nadia sama smaže data. O čísle vědí čtyři lidé v budově a žádný z nich ho už nikdy nevysloví nahlas."],["\"Dvě funkční období, to je smysl úřadu.\" Říct to jednou.","Jedna jasná věta ukončí devět měsíců spekulací v jednom zpravodajském cyklu. Vaše hnutí to oplakává jako smrt v rodině."],["Zeptat se i na čtvrté funkční období.","Podpora je 29 procent, což je záhadně zároveň nižší i vyšší, než kdokoli čekal. Nadia tomu říká \"nejhorší číslo, jaké jsem kdy sama vyprodukovala\"."]]},"c-term-reset":{"t":"Dodatek, který vynuloval hodiny","x":"Dr. Weirová přinesla srovnávací materiál. \"Bylo to uděláno pořádně. Ústavní dodatek, referendum, opravdová většina. Hodiny se vynulovaly a už odsloužená funkční období jednoduše přestala počítat.\" Zavírá složku. \"Pane prezidente, to není převrat. To je papírování.\"","c":[["Zahájit proces schvalování dodatku. Veřejně.","Vyžaduje třicet osm států a vy máte devatenáct. Pokus je pro vás cennější, než by kdy byl dodatek sám, a všichni zúčastnění to vědí."],["Nechat přátelský zákonodárný sbor státu, ať to navrhne. Sám se do toho nemíchat.","Vy jste o nic nežádal. Bylo to navrženo. Ten rozdíl je nosnou zdí celého podniku a drží celé dva roky."],["\"To dělají jiné země.\" Nechat to tak.","Táhnout čáru u cizí ústavy je nejlevnější vlastenectví, co je k mání, a v tomhle konkrétním případě je navíc upřímné."],["Navrhnout dodatek, který zkrátí funkční období na dva roky.","Nikdo nedokáže určit, jestli je to blaf, past, nebo opravdové přesvědčení. Získá to čtyři spolupředkladatele a tiše to zemře ve výboru, aniž by to kdy kdo vysvětlil."]]},"c-gold-room":{"t":"Renovace","x":"Alvin má připravené faktury a fotky před a po. \"Zlaté lišty na římse, kolem dveří, na krbové římse a orlu. Reverzibilní, pane, v tom smyslu, že se to teoreticky dá zase odloupnout.\" Zaváhá. \"Každý návštěvník to hned vyfotí.\"","c":[["Víc zlata. Lišty, zrcadlo, rámy.","Místnost, která působí jako trůnní sál, v budově výslovně navržené tak, aby žádný neměla. Objeví se v devíti stech zahraničních zpravodajstvích do roka."],["Zastavit, kde to je. Stačí to.","Střídmé množství zlata působí jako vkus. Velké množství působí jako argument, a vy jste se zastavil o jednu vrstvu laku před tím, než byste ho vyslovil."],["Zbavit se ho. Obnovit místnost.","Alvin osobně dohlíží na obnovu a poprvé za čtyři roky vypadá opravdu šťastně. Nikdo mimo budovu si toho vůbec nevšimne."],["Pozlatit i zasedačku kabinetu, chodbu a výtah.","Výtah je detail, který napáchá skutečnou škodu. Čtyři sta tisíc lidí si posílá jednu fotku pozlaceného výtahu a ani jeden z nich není na vaší straně."]]},"c-birthday":{"t":"Den volného vstupu","x":"Boyd Hackler má připravenou a podepsatelnou proklamaci. \"Volný vstup do všech národních parků a památníků, na váš narozeniny, navždy.\" Přešlápne. \"Pane, volný vstup do parků je opravdu populární. Problém je jen v datu, a existuje tři sta šedesát čtyři jiných možností.\"","c":[["Podepsat to. Moje narozeniny.","Čtyři miliony lidí dostanou den volného vstupu do parku, vybraný kvůli jednomu muži. Většina z nich zažije nádherné odpoledne, a každou fotku z toho doprovodí krutý popisek."],["Podepsat to místo toho na Den nezávislosti.","Identická politika, univerzálně oblíbená, nepřipsaná nikomu konkrétnímu. Boyd si to založí jako výhru a v soukromí to oplakává jako prohru."],["Žádný svátek. Místo toho pořádně financovat parky.","Dokončí se jedenáct zpožděných údržbových projektů. V Montaně se přestaví most. Nikdo nikdy nevystopuje jediný trám zpátky k vám."],["Podepsat to a účast udělat povinnou.","Slovo \"povinná\" přežije čtyři koncepty a dvě právní kontroly, než ho konečně někdo odchytí v jedenáct večer, noc před tiskem."]]},"c-name-on-buildings":{"t":"Smlouva na cedule","x":"\"Smlouva na cedule pro čtyři sta federálních budov.\" Deborah čte specifikaci nahlas. \"Vaše jméno, nad dveřmi, bronzové, metr vysoké. Pane, ty budovy jsou pojmenované po lidech, kteří jsou mrtví. Není to pravidlo. Je to prostě to, co se historicky vždycky dělalo.\"","c":[["Všech čtyři sta. Bronz. Metr.","Čtyři sta budov teď nese jméno žijícího muže. Sundat je později stojí 60 milionů dolarů, číslo, které bude každá budoucí administrativa ráda opakovat."],["Čtyři budovy. Ty, co jsme opravdu postavili.","Pojmenovat po sobě něco, co jste postavil, je nenápadné. Pojmenovat po sobě něco, co jste nepostavil, vyznívá úplně jinak, a tomu jste se vyhnul."],["Žádná. Budovy si nechají svá jména.","Deborah zaznamená rozhodnutí do spisu jediným slovem, \"zamítnuto\", a je to záznam, na který je za čtyři roky nejpyšnější."],["Pojmenovat je všechny po svých předchůdcích, podle abecedy.","Matoucí, nákladné a nějak úplně okouzlující. Čtyři historické spolky napíšou, že si toho váží, a jeden pošle dort."]]},"c-invasion-within":{"t":"Místnost plná generálů","x":"Každý vlajkový důstojník ve službě je v jedné místnosti, protože jste si je osobně vyžádal. Tarrant má návrh projevu a jednu poznámku. \"Pane, ta fráze je 'invaze zevnitř'. Řeknete ji čtyřem stům lidí, kteří celou kariéru studovali, na koho přesně smí, a na koho nesmí, namířit zbraň.\"","c":[["Říct to. Sledovat místnost.","Nikdo nevstane. Nikdo neodejde. Čtyři sta důstojníků sedí v naprostém tichu a každý z nich to ten samý večer komukoli vytočí."],["Říct to, pak dodat, že myslíte politický argument.","Vysvětlení zapadne pod frázi, jak to vysvětlení vždycky udělá, ale přežije v přepisu, a Tarrant se postará, aby se rozšířilo."],["Vyškrtnout to. Mluvit o náboru a platech.","Dvacet minut o bytových příspěvcích čtyřem stům generálů. Nejlépe přijatý projev celého funkčního období a nedostane se mu naprosto žádného pokrytí."],["Zeptat se místnosti, kdo z nich je ta invaze.","Jeden generál zvedne ruku. Dodnes se neurčilo, jestli to byla neposlušnost, nebo vtip, a on odmítl to vyjasnit."]]},"c-monarch":{"t":"\"Fakticky monarcha\"","x":"Historik v televizi použil dvě slova: fakticky monarcha. Dr. Weirová to sledovala. \"Nemyslel to sprostě, pane prezidente. Myslel to strukturálně, úřad, na kterém neběží žádná účinná kontrola. Řekl to smutně, a přesně proto to zapůsobilo.\"","c":[["Přijmout to. Nechat to vytisknout.","Řada merchandise postavená na varovném štítku. Prodává se výjimečně dobře a citují ji, zcela bez ironie, ve třech zahraničních parlamentech při debatě o vlastních vůdcích."],["Odmítnout to. Vyjmenovat věci, které vás zastavily.","Přesně, zpaměti, jmenujete čtyři prohry u soudu a jeden neúspěšný zákon. Nejpřesvědčivější věc, co za rok uděláte, a vaše základna nenávidí každou slabiku."],["Neříkat nic. Je to jeden historik.","Za jedenáct měsíců se to stane názvem kapitoly a za tři roky názvem knihy, a do té doby už vaše mlčení nikoho nezajímá."],["Formálně, písemně požádat o korunu.","Memorandum úřadu kurátora se ptá, co by to obnášelo. Čtyřsetslovná odpověď bere otázku s naprostou, znepokojivou vážností."]]},"c-restored-republic":{"t":"Obnovení republiky","x":"\"Vrátil to všechno.\" Dr. Weirová popisuje muže mrtvého dva tisíce let. \"Veřejně, formálně, v senátu, každou mimořádnou pravomoc, vzdal se jí na místě. Pak si dvě obyčejné podržel doživotně, a ty dvě se ukázaly jako dostatečné.\" Odmlčí se. \"Je to nejúspěšnější politický manévr v dějinách, pane prezidente, a vypadal přesně jako rezignace.\"","c":[["Udělat to. Vzdát se mimořádných pravomocí. Podržet si ty dvě, na kterých záleží.","Pokrytí je nadšené a téměř úplně mylné. Vzdal jste se třiceti devíti věcí, které jste nikdy nepoužil, a tiše si podržel dvě, které dělají tu práci."],["Vzdát se všech. Doopravdy.","Ne manévr. Skutečné obnovení, provedené pořádně, a stojí vás to všechno, co jste za čtyři roky nashromáždil. Dr. Weirová o tom píše zbytek kariéry."],["Nechat si všechno. Divadlo je pro slabší muže.","Muž z toho příběhu si nechal všechno otevřeně a vlastní senát ho za to probodl. Dr. Weirová to zmíní; vy jí řeknete, že to byla úplně jiná situace."],["Vzdát se jich v latině.","Proklamace je vydána jen v latině. Čtyři klasičtí filologové najdou tři gramatické chyby a jeden napíše 6000 slov jen o konjunktivu."]]},"c-acerbo":{"t":"Pravidlo dvou třetin","x":"Halovi ukázali něco z roku 1923 a už to nedokáže odestat. \"Změna volebního zákona. Kdo skončí první, jakkoli těsně, jakkoli malým rozdílem, dostane dvě třetiny mandátů.\" Je bledý. \"Schválil to parlament, kterému pak nezbylo nic dalšího ke schválení. Pane, ukazuju vám to, abyste to viděl.\"","c":[["Připravit americkou verzi. Předložit ji.","Neprojde. Bude předložena, což znamená, že teď existuje, což znamená, že může být předložena znovu, jednou, někým se skrupulemi menšími než vy."],["Místo toho agresivně přeskupit volební obvody. Stejný výsledek, běžné nástroje.","Devět států předělaných až na hranici zákona. Naprosto konvenční, naprosto brutální, a obě strany to dělají už dvě stě let."],["Nic. Buď mandáty vyhrát, nebo ne.","Přijdete o jedenáct mandátů, které byste jinak měl. Zbyde komora, která vám ještě dokáže technicky říct ne, a za devatenáct měsíců to udělá."],["Přiznat dvě třetiny mandátů tomu, kdo skončí druhý.","Navrženo čistě proto, aby to ilustrovalo tu svévoli. Čtyři poslanci se k tomu upřímně připojí a jeden pronese v jeho prospěch skutečně dojemný projev."]]},"c-judicial-purge":{"t":"Čtyři tisíce","x":"Předsedkyně Nejvyššího soudu Stoneová přišla osobně a přinesla výtisk. \"Čtyři tisíce soudců a žalobců odvoláno během jediného roku, v zemi, kde se pořád konají volby. Sto padesát novinářů uvězněno.\" Položí to na stůl. \"Neobviňuju vás z ničeho, pane prezidente. Říkám vám, jak to vypadá zevnitř, protože lidé, kterým se to stalo, to taky neviděli přicházet.\"","c":[["Zahájit přezkum chování federálních soudců. Celé.","Nikdo není odvolán. Devět set soudců je teď prostě lidí se spisem, a soudce se spisem rozhoduje jinak, což byl jediný výsledek, který kdo kdy potřeboval."],["Přezkoumat jedenáct, kteří proti nám rozhodli nejčastěji.","Cílit na viditelné je horší než cílit na všechny, protože vzorec je od prvního dne jasně čitelný a devět médií zveřejní seznam do oběda."],["Poděkovat jí. Neudělat vůbec nic.","Už to nikdy nezmíní. O dva roky později, v případu, který zoufale potřebujete, napíše nečekané souhlasné stanovisko, a vy se nikdy nedozvíte proč."],["Nabídnout, že se necháte přezkoumat soudní mocí místo toho.","Formální žádost, aby soudní konference prošetřila vaše vlastní chování. Přijmou ji. Zprávu podá za čtyři roky, kdy už to bude problém někoho jiného."]]},"c-crossed-over":{"t":"Text, který říká, že jsme to překročili","x":"Dr. Weirová má ten text. \"Tvrdí, že země přestala být plnou demokracií, ne že se stala diktaturou, ale že sklouzla do jiné kategorie úplně. A říkají, že ten obrat byl rychlejší než první rok čtyř případů, které jmenují.\" Pokládá to. \"Pane prezidente, jejich slovo je *soutěživá*. Volby jsou pořád skutečné. To je celý ten rozdíl a odvádí to spoustu práce.\"","c":[["Dokázat, že mají pravdu. Naplno se do toho opřít.","Text dostane nový oddíl v druhém vydání. Citují vás čtyřicet jednou, a ani jedna citace není laskavá."],["Dokázat, že se mýlí. Udělat jednu věc, o které řekli, že neuděláte.","Podřídíte se rozsudku, kterému jste se snadno mohl vzepřít, a přijdete o politiku, kterou jste chtěl. Dva ze čtyř autorů to veřejně zaznamenají, jediná oprava, kterou o vás kdy vydají."],["Napadnout metodologii. Financovat konkurenční index.","Váš index řadí zemi na čtvrté místo na světě. Nikdo ho necituje, nakonec ani lidé, které jste zaplatil, aby ho vytvořili."],["Zeptat se jich, jaké skóre by to napravilo, a přesně to obejít.","Odpoví upřímně a podrobně, protože to akademici dělají. Vylepšíte devět ukazatelů, aniž byste změnil jedinou skutečnou věc, a skóre se posune o čtyři body nahoru."]]},"c-index-drop":{"t":"Padesáté první","x":"Muriel má otevřený index. \"Z dvacátého na padesáté první místo za jeden rok. Poprvé za víc než padesát let mimo nejvyšší klasifikaci.\" Otočí stránku. \"Věta, kterou pořád dokola čtou na každém zahraničním ministerstvu, je ta o *rychlosti*, pane. Říkají tomu bezprecedentní v moderních dějinách.\"","c":[["Vystoupit z organizace, která ten index financuje.","Je to akademické konsorcium na švédské univerzitě, a vy ho nefinancujete. I tak se pokus o jeho zrušení dostane do titulků ve čtyřiceti zemích."],["Zpochybnit žebříček. Ignorovat rychlost.","O žebříčku samotném se nikdo nechystal hádat. Šlo vždycky o tempo poklesu, a vy jste se právě rozhodl o tom nevést spor."],["Zveřejnit dílčí skóre a napravit tři nejhorší.","Nezávislost soudnictví, přístup tisku, kapacita dohledu. Náprava tří ukazatelů trvá jedenáct měsíců a vrátí vás na třicáté čtvrté místo."],["Požádat o zařazení do úplně jiné kategorie.","Formální žádost, aby byla země hodnocena jako rozvíjející se demokracie místo etablované. Zdvořile zamítnuto ve čtyřech různých jazycích."]]},"c-insurrection-act":{"t":"Zákon bez definice","x":"\"Zákon nikde nedefinuje povstání.\" Tarrant to konstatuje suše, spíš jako fakt než argument. \"Říká, že smíte jednat, jakmile usoudíte, že nějaké probíhá. Žádný test, žádná hranice, a žádný soud tu volbu nikdy nezpochybnil.\" Čeká. \"Pane, to je nejširší pravomoc, jaká v americkém právu zbývá, a byl byste první za padesát osm let, kdo ji takhle skutečně použije.\"","c":[["Použít ho. Celostátně.","Řadové jednotky v amerických ulicích na základě zákona bez definice a bez kontrolora. Je to nejzákonnější věc, co jste kdy udělal, a přitom se nepodobá ničemu z toho, co jste dělal dřív."],["Použít ho pro jedno město. Na dvacet jedna dní. Písemný limit.","Limit, který si sám uložíte, je jediný limit kdekoli v celém zákoně. Tarrant tu dvaceti jednodenní lhůtu vepíše do příkazu osobně a děkuje vám za to."],["Nepoužívat ho. Nasadit gardu pod velením státu.","Pomalejší, a přece to funguje, protože guvernéři se zájmem na výsledku se ukážou být užitečnější než vojáci s příkazem v ruce."],["Použít ho proti počasí.","Proklamace prohlásí hurikán za povstání. FEMA a Severní velitelství svolají společný hovor jen proto, aby zjistili, kdo z nich to teď má za úkol."]]},"c-registry":{"t":"Seznam úplně všech","x":"Duane Krisp má návrh od dodavatele. \"Sloučit všechny federální databáze. Daně, dávky, cestování, licence, imigrační status. Každá zvlášť zákonná.\" Odkládá to. \"Pane, dohromady je to jeden spis o tři sta čtyřiceti milionech lidí, a o tom dohromady nikdy nikdo nehlasoval.\"","c":[["Postavit to. Celé. Jeden soubor.","Funguje to přesně, jak slibovali, a v prvním roce se do toho dotáže devět milionů dotazů. Čtyři z nich se později ukáží jako dotazy na novináře."],["Sloučit jen sady relevantní pro imigraci.","Užší systém s deklarovaným účelem, jediný druh, který kdy přežije soudní přezkum. Dělá to taky 80 procent toho, co jste vlastně chtěl."],["Zabít to. Napsat pravidlo proti sloučení.","Pravidlo přežije vaši administrativu o desítky let a dodavatel žaluje za náklady na vývoj a prohraje na plné čáře."],["Postavit to a dát to na veřejné webové stránky.","Radikální transparentnost dotažená do logického konce. Zůstane to online jedenáct minut, což je o devět minut déle, než trvalo, než to bylo archivováno navždy."]]},"c-data-center":{"t":"Zařízení v poušti","x":"Errol Hance má plán lokality. \"Úložiště je teď v podstatě neomezené. Můžeme uchovávat všechno, navždy, na základě teorie, že to jednou možná budeme potřebovat.\" Nesedá si. \"Pane, pravidla byla napsaná v době, kdy bylo úložiště drahé. Pravidla počítala s tím, že si stejně budeme muset vybírat.\"","c":[["Uchovat všechno. Navždy. Rozhodnout proč později.","Trvalý záznam o celé zemi, uchovávaný pro účel, který ještě nikdo nevymyslel. Zdědí ho čtyři budoucí administrativy a ani jedna z nich nesmaže jediný bajt."],["Uchovat to, s pětiletým plánem výmazu.","Lhůta uchovávání je jediná smysluplná brzda takového systému, a nestojí nic, dokud je budova napůl prázdná."],["Sbírat jen s určeným účelem.","Errol proti tomu dvacet minut v kuse argumentuje, pak to bezchybně provede, přesně to, co dělá s každým rozhodnutím, které prohraje."],["Naplnit zařízení místo toho papírovými spisy.","Čtyři miliony krychlových stop tištěných záznamů, dovezených vlakem během devíti měsíců. Naprosto bezpečné a naprosto neprohledatelné, což jistí lidé rozhodně upřednostňují."]]},"c-church":{"t":"Národní bohoslužba","x":"Reverend Dale Muncy přišel s návrhem a neobvykle váhá. \"Týdenní bohoslužba, v budově, vysílaná, s kanceláří placenou z rozpočtu.\" Obrací klobouk v rukou. \"Pane, přišel bych. Chci být upřímný, že si nejsem tak úplně jistý, jestli mám být ten, koho se ptáte.\"","c":[["Financovat kancelář. Vysílat bohoslužbu. Týdně.","Čtyři denominace, které vás podporovaly, protestují první a nejhlasitěji, protože o téhle historii toho přečetly podstatně víc než kdokoli u vás v kanceláři."],["Konat bohoslužbu. Bez federálního financování, bez kanceláře.","Soukromá bohoslužba v soukromém sídle, přesně to, na co má každý obyvatel té budovy vždycky nárok."],["Pozvat jedenáct vyznání na rotaci. Nefinancovat žádné.","Rotace, která rovnoměrně otravuje všechny a zákonně neurazí nikoho. Dale si vezme čtvrtou neděli a nazve to nejspravedlivější nabídku na stole."],["Prohlásit se hlavou nové denominace.","Zakládací listina je doslova podaná v Delaware. Devět tisíc lidí se přihlásí do čtrnácti dnů a Dale ten samý den odpoledne rezignuje."]]},"c-broadcast-license":{"t":"Slyšení o obnovení licence","x":"Blíží se obnovení licence a váš regulátor svolal slyšení o \"veřejných zájmových povinnostech\". Kaylee: \"Obnovení je rutina, pane. Rutina je to už šedesát let. Naplánovat kvůli tomu slyšení je celé to sdělení, a všichni v oboru ho dostali už před devátou ráno.\"","c":[["Slyšení uspořádat. Skutečně ohrozit licenci.","Licence se obnoví. Za jedenáct měsíců, co to trvalo, síť tiše vyměnila dva moderátory a jednoho výkonného producenta, a nikdo je o to nemusel žádat."],["Slyšení uspořádat. Obnovit ji na konci.","Proces s předem daným výsledkem je stojí rok právního rozpočtu a rok opatrnosti, což je většina toho, co jste stejně chtěl."],["Obnovit ji automaticky, jako posledních šedesát let.","Nic se nestane. Je to učebnicové vyřízení obnovy licence a neobjeví se to přesně v žádných novinách na světě."],["Udělit licenci síti, která neexistuje.","Fiktivní žadatel s poštovní schránkou vyhraje licenci na velký trh. Čtyři měsíce vysílá zkušební obraz, než si toho na úřadu někdo všimne."]]},"c-cabinet-25":{"t":"Dvacátý pátý dodatek","x":"Chet Danforth požádal o soukromou schůzku a nikoho s sebou nepřivedl. \"Existuje mechanismus,\" říká opatrně, \"který potřebuje mě a většinu kabinetu. Chci, abyste věděl, že se mnou o tom čtyři lidi už mluvili, a já jsem všem čtyřem řekl ne.\" Odmlčí se. \"Říkám vám, že jsem jim řekl ne.\"","c":[["Vyměnit ty čtyři. A vyměnit Cheta.","Kabinet teď vybraný výhradně pro neochotu vás odvolat. Každé rozhodnutí, které od teď udělá, dělají lidé vybraní přesně pro tuhle vlastnost."],["Vyměnit ty čtyři. Cheta nechat na dohled.","Zůstane, protože jednou řekl pravdu v práci, kde se právě ukázalo, že to lze přežít. Než skončí funkční období, udělá to ještě dvakrát."],["Poděkovat mu. Nic neměnit.","Mechanismus už od nikoho nikdy nezazní, po zbytek funkčního období. Jestli je to loajalita, nebo prostá aritmetika, se nikdy úplně nedozvíte."],["Použít ho proti sobě, ať vidíte, co se stane.","Sepíše se, a katastrofálně skutečně odešle, dopis o vaší vlastní nezpůsobilosti. Chet je úřadujícím prezidentem padesát jednu minutu a nedělá s tím vůbec nic."]]},"c-treaty":{"t":"Dohoda, která nebyla smlouvou","x":"Muriel má dokument. \"Práva na základnu, klauzule o vzájemné bezpečnosti, čtyřicetiletá platnost. Nazvete to smlouvou a potřebujete šedesát sedm senátorů, které nemáte. Nazvete to výkonnou dohodou a stačí váš podpis.\" Zvedne oči. \"Pane, je to identický dokument tak jako tak.\"","c":[["Podepsat to jako výkonnou dohodu. Čtyřicet let.","Čtyřicetiletý závazek vzájemné bezpečnosti, uzavřený jedním mužem za odpoledne. Druhá země to považuje za závazné, a to je ta část, kterou už nikdy nikdo nemůže vzít zpět."],["Poslat to jako smlouvu. Bojovat o těch šedesát sedm.","Po devíti ponižujících měsících vyjednávání seženete sedmdesát jedna hlasů. Nezrušitelné žádným nástupcem, což se výkonné dohodě nikdy nepovedlo."],["Podepsat pětiletou verzi. Zbytek nechat na Kongresu.","Krátká dohoda, která kupuje čas na pořádnou smlouvu později. Muriel tomu říká profesionální odpověď a myslí to jako skutečnou pochvalu."],["Podepsat to jako smlouvu, dohodu i memorandum zároveň.","Tři dokumenty, stejný text, tři různé právní statusy. Druhá země ratifikuje všechny tři, možnost, se kterou nikdo vlastně nepočítal."]]},"c-emergency-extend":{"t":"Obnovení, které nikdo nečte","x":"\"Vyhlášení se automaticky obnovuje, pokud neřeknete jinak, a Kongres to může ukončit usnesením, což neudělá.\" Sy má formulář připravený. \"Jeden podpis, pane. Čtvrté obnovení. Původní stav nouze v jakémkoli obyčejném slova smyslu skončil zhruba před dvěma lety.\"","c":[["Obnovit ho. A těch dalších jedenáct taky.","Dvanáct stavů nouze, z nichž žádný není nouzí, všechny nosné. Pravomoci jsou teď prostě způsob, jak se země vede, a nikdo pro to nikdy nehlasoval."],["Obnovit jen ty čtyři, které opravdu ještě fungují.","Nechat osm propadnout se u vašich lidí interpretuje jako slabost, u ostatních jako zdravý rozum. Obojí čtení je k dispozici a ani jedno není chybné."],["Nechat je všechny propadnout. Vládnout podle zákonů.","Dobrovolně se vzdáte toho aparátu. Čtyři politiky se okamžitě zhroutí a dvě, které přežijí, se ukážou jako jediné dvě, které kdy byly skutečné."],["Obnovit ho na sto let.","Nástroj uvádí datum vypršení někdy ve dvaadvacátém století. Zveřejní se to. Ve Federálním registru to nemá nikdo pravomoc zpochybnit."]]},"c-lincoln":{"t":"Precedens, který byste preferoval","x":"\"Vaši obhájci pořád sahají po jednom konkrétním prezidentovi,\" říká dr. Weirová. \"Pozastavil habeas corpus, fakticky ignoroval sedícího soudce Nejvyššího soudu a zvažoval odklad voleb.\" Nechá to viset ve vzduchu. \"Pane prezidente, srovnání je přesné. Je to ale taky srovnání s mužem, který tohle všechno dělal během občanské války, a na vašem místě bych ho používal velmi opatrně.\"","c":[["Spoléhat se na to pořád. Má pravdu.","Každý oslovený historik odpoví stejnými třemi slovy o té válce, a ta tři slova jsou nezvratná, a vy k tomu srovnání přesto pořád sahá."],["Srovnání zavrhnout. Najít mírové.","Žádné neexistuje, což je to skutečné zjištění, a dr. Weirová se to ani neobtěžuje vyslovit nahlas, protože nemusí."],["Tvrdit, že nouze *skutečně existuje*, a pojmenovat ji.","Pojmenovat stav nouze je nutný předpoklad pro všechno, co následuje, a jednou pojmenovaná se už nikdy tiše neodpojmenuje, aniž byste se toho vzdal celého."],["Zeptat se jí, kterému prezidentovi se nejvíc podobáte.","Odpoví okamžitě, bez sebemenšího zaváhání, jménem někoho z padesátých let 19. století, o kom v místnosti nikdo nikdy neslyšel. Čtyři dny trvá pochopit, jak kruté to bylo."]]},"c-fdr":{"t":"Čtyři funkční období","x":"Dr. Weirová má připravené další srovnání. \"Dvanáct let, čtvery volby, celá federální vláda přebudovaná od základu, a internace. Taky se pokusil rozšířit soud a jeho vlastní strana ho veřejně odmítla.\" Dodává: \"To odmítnutí je ta část, kterou vaše strana nikdy necituje, pane prezidente, a je to ta část, na které záleželo.\"","c":[["Zkusit rozšíření soudu. Zjistit, jestli vás tahle strana odmítne.","Devět vašich vlastních senátorů odmítne do týdne. Největší jednorázový akt odporu z vaší vlastní strany za čtyři roky, a nikdy se z toho úplně nezotavíte."],["Nezkoušet to. Přijmout ten bod.","Zdržíte se pokusu o něco, co byste stejně jen prohrál. Nikdo si nevšimne věci, ke které nedošlo, a proto se zdrženlivost nikdy neoceňuje."],["Rozšířit místo toho nižší soudy. Tam se nikdo nedívá.","Šedesát tři nová okresní soudcovská místa obsazená za čtrnáct měsíců. Zlomek pokrytí za mnohonásobný skutečný efekt."],["Zmenšit soud na sedm.","Zákon zmenšující lavici odvoláním jeho dvou nejnověji potvrzených členů. Oba jste potvrdil vy, fakt, který na plénu zazní ve velké délce."]]},"c-uncommon-momentum":{"t":"Malá energie na legislativu","x":"Hal má žlutě zvýrazněnou větu z think-tanku. \"'Neobvyklé rané tempo', a pak tohle: 's malou energií vynaloženou na legislativní cesty.'\" Kouká přes okraj stránky. \"Pane, to je zdvořilý způsob, jak říct, že nic z toho není zajištěné, a říkám vám to už dva roky, jen míň zdvořile.\"","c":[["Zachovat tempo. Zajišťovat věci je pomalé.","Všechno, co jste vybudoval, stojí jen na vašem podpisu. Váš nástupce zruší 80 procent toho za jedno odpoledne, přesně tím stejným nástrojem, co vy."],["Poslední dva roky věnovat proměně příkazů na zákony.","Čtyři návrhy zákonů, dva projdou. Jsou to jediné části vašeho prezidentství, které za dvacet let ještě stojí, a nikdo si nepamatuje, že jsou vaše."],["Dělat obojí. Prosadit ty čtyři, co záleží, ostatní vydat příkazem.","Přístup, který nepotěší nikoho z obou stran, a s odstupem dvaceti let se ukáže jako naprosto správný."],["Nechat Kongres schválit jeden zákon, který ratifikuje všechny příkazy naráz.","Dvě stě sedmnáct příkazů ratifikovaných v jednom hlasování, poslanci, kteří mezi sebou přečetli čtyři z nich. Projde o jedenáct hlasů a je napaden hned další ráno."]]},"c-succession-machine":{"t":"Hnutí po vás","x":"Chet má vnitřní čísla a viditelně z nich radost nemá. \"Hnutí má podporu padesát čtyři procent. Vy máte čtyřicet jedna.\" Nechá to chvíli viset. \"Pane, přerostlo vás. To je buď to nejlepší, co jste kdy vybudoval, nebo poslední problém, jaký kdy budete mít, a já upřímně nevím, co z toho.\"","c":[["Svázat ho se sebou. Přísahy loajality, moje jméno na všem.","Hnutí, které vás nemůže přežít, taky nemůže vás přežít, a obě fakta se stanou pravdou v ten samý den, který jste si nevybral."],["Vybudovat instituci. Nechat ji přežít mě.","Stranický aparát s pravidly, pokladnou a procesem nástupnictví. Vyhraje tři z dalších pěti voleb a od druhých voleb vás už skoro nezmiňuje."],["Předat ho teď Chetovi, dokud si mohu vybrat.","Přijme to vděčně a kompetentně, a do jedenácti týdnů udělá rozhodnutí, aniž by se vás nejdřív zeptal, a nic se mu za to nestane."],["Nechat hnutí odhlasovat, jestli vás ještě potřebuje.","Nadia vás prosí, ať to nedělá. Přesto to zadáte. Číslo se vrátí na 38 procent a unikne do čtyř dnů, a ten únik je zdaleka nejmenší z vašich problémů."]]},"c-what-was-it-for":{"t":"Otázka ve dveřích","x":"Je pozdě a Deborah už ani nepředstírá, že drží složku. \"Čtyři roky. Dvě stě sedmnáct příkazů, jedenáct stavů nouze, čtyři sta budov s vaším jménem.\" Není v tom žádná krutost. \"Pane, kdybych se zeptala, co z toho vás přežije, co byste vlastně řekl?\"","c":[["\"Všechno. Protože nikam neodcházím.\"","Zapíše si to. Je to věta, kterou začíná každý popis téhle administrativy napsaný v následujících čtyřiceti letech, a je to ona, komu se přisuzuje, že ji zachytila."],["\"Soudci. Soudci přežijí všechny.\"","Je to správná odpověď. Dvě stě třicet jedna doživotních jmenování, průměrný věk čtyřicet šest, jediná věc tady, která je opravdu trvalá."],["\"Upřímně? Ty dva zákony. Možná.\"","Deborah chvíli mlčí. Pak řekne \"ano\" a odejde, a je to nejblíž, co za čtyři roky dostanete ke schválení."],["\"Ten sál.\"","Je, uznejme, velmi pravděpodobné, že bude ještě stát. Uzná ten bod, a ani jeden z vás se k tomu rozhovoru už nikdy nevrátí."]]},"c-lame-duck":{"t":"Slovo, které nikdo neříká","x":"Nadia má to znamení. \"Čtyři předsedové výborů tento týden nevrátili hovor. Ne nepřátelsky, jen zaneprázdněně. Pane, přesně takhle to vypadá. Nikdo neoznámí, že se vás přestal bát. Jen se najednou stane hrozně, hrozně zaneprázdněným.\"","c":[["Udělat z jednoho z nich příklad. Veřejně.","Přežije primárky o devět bodů, a ostatní tři prostě přestanou vůbec zvedat telefon. Strach je měna a vy jste právě zjistil, že kurz je špatný."],["Dát jim, co chtějí. Koupit si poslední dva roky.","Čtyři obvodní projekty a předsednictví výboru. Transakční, neefektní a koupí to jedenáct dalších měsíců fungující většiny."],["Ignorovat to. Vládnout příkazy až do posledního dne.","Na příkaz je nepotřebujete, a přesně proto je příkaz cenný podstatně méně než ta věc, kterou od nich už nedostanete."],["Zavolat všem čtyřem ve tři ráno, jestli jsou v pořádku.","Všichni čtyři to zvednou. Všichni čtyři jsou velmi znepokojeni. Tři z nich pak šest měsíců vracejí každý hovor; čtvrtý si jednoduše změní číslo."]]},"c-library":{"t":"Knihovna","x":"Miriam má otevřené účty nadace. \"Čtyři sta deset milionů, pane. Z vyrovnání, od dárců s věcmi projednávanými před vládou, a od čtyř cizích státních příslušníků.\" Pokládá to. \"Je to knihovna. Žádná povinnost zveřejnění vůbec. To není mezera v zákoně. Je to prostě zákon.\"","c":[["Vzít to všechno. Je to knihovna.","Nikdo nikdy nikoho úspěšně nenapadl kvůli knihovně. Je to nejčistší způsob, jak dostat peníze v americkém veřejném životě, a vždycky tomu tak bylo."],["Zveřejnit všechny dárce dobrovolně.","Jedenáct dárců se do čtrnácti dnů stáhne, což leccos napovídá o těch jedenácti. Zbylý seznam je nudný a naprosto neotřesitelný."],["Odmítnout zahraniční peníze. Zbytek vzít.","Jedna linka, vedená někam, kde se snadno hájí a snadno ověřuje. Miriam tomu říká \"minimum\" a schválí to."],["Postavit knihovnu bez jediné knihy.","Zařízení o 90 000 čtverečních stopách obsahující čtyři sta fotografií, obchod se suvenýry a repliku kanceláře. Návštěvnost prvního roku předčí každou předpověď."]]},"c-pardon-list":{"t":"Seznam na poslední stránce","x":"Sy má milostný seznam připravený. \"Čtyřicet jedna jmen. Devět z nich pro vás pracovalo. Čtyři odmítli spolupracovat s vyšetřováním proti vám.\" Nekomentuje to. \"Pane, ta pravomoc je nepřezkoumatelná. Žádný soud, žádné hlasování, žádné odvolání. Je to jediná věc v celé ústavě, na kterou vůbec žádná kontrola neplatí.\"","c":[["Podepsat všech čtyřicet jedna. Poslední ráno.","Nepřezkoumatelné znamená nepřezkoumatelné. Nikomu z nich se nikdy nic nestane, a vzkaz všem, kdo ještě sedí na nějakém tajemství, dorazí naprosto jasně."],["Podepsat těch devět se skutečně nepřiměřenými tresty.","Devět obhajitelných případů, každý s vlastním memorandem. Dvě advokátní skupiny, které vás nesnáší, vydají prohlášení podpory, což nikdo nečekal, oni nejméně."],["Nepodepsat žádnou.","Čtyři lidé, kteří kvůli vám mlčeli, přesto jdou do vězení. Jestli je to integrita, nebo nevděk, se dohaduje třicet let."],["Preventivně omilostnit úplně všechny v zemi.","Plošná proklamace všeobecné milosti pro každý federální trestný čin. Podepsáno ve čtyři ráno, zrušeno v sedm, existovalo to celkem tři hodiny."]]},"c-guardrails":{"t":"Co vydrželo","x":"Dr. Weirová přišla se rozloučit a přinesla přesně jednu stránku. \"Závěr literatury, k dnešnímu dni: soudy proti vám pořád rozhodovaly a vy jste je občas poslechl. Volby se konaly a opozice tu a tam vyhrála. Na tisk se tlačilo a přesto dál publikoval.\" Podává to. \"Pane prezidente, každá z těch vět je o něčem, co se nestalo. To je, co znamená hráz.\"","c":[["Pak najít tu, která ještě nebyla testovaná.","Vždycky nějaká existuje. Zbytek funkčního období strávíte hledáním, a samo to hledání se ukáže jako nejnebezpečnější věc, co za celé volební období uděláte."],["Nechat je stát. Vzít si výhru, kterou máte.","Nakonec jste prezident, který úřad enormně rozšířil, a přesto ho nechal fungovat. Nejméně uspokojivý dostupný výsledek, a nejvzácnější."],["\"Vydržely, protože jsem to dovolil.\" Říct to veřejně.","Je to chvástání, které naráz přizná úplně všechno. Čtyři badatelé to citují jako nejodhalující větu celé administrativy, a žádný z nich se nemýlí."],["Požádat ji, ať to sepíše jako seznam, abyste to mohl projít.","Odmítne, poprvé za čtyři roky, jediným slovem. Pak zvedne kabát a naposledy opustí budovu."]]},"e-covfefe":{"t":"To slovo","x":"Usnul jste uprostřed příspěvku a věta se prostě zastaví, po slovu, které není slovo, před jedenácti miliony lidí. Brayden má čísla. \"Čtyři sta tisíc sdílení, pane. Je to nejsledovanější věc, co jste kdy napsal, a nikdo, včetně vás, neví, co to znamená.\"","c":[["Nechat to tam. Říct, že jen vy víte, co to znamená.","Slovo, které neznamená nic, se stane heslem, tričkem a nakonec dostihovým koněm, a přežije všechny politické úspěchy vašeho funkčního období dohromady."],["Smazat to a zveřejnit dokončenou větu.","Dokončenou myšlenku o obchodních deficitech si přečtou čtyři tisíce lidí. Ten překlep měl jedenáct milionů a dokončení nepotřeboval."],["Podrobně vysvětlit, že to byl překlep.","Vysvětlovat vtip, který jste nechtěl udělat, je jediný známý způsob, jak ho zhoršit. Brayden to sleduje s viditelnou tělesnou bolestí."],["Zařadit ho do slovníku výnosem.","Výnos to definuje jako \"stav pohotovostní bdělosti\". Čtyři lexikografové reagují s upřímným nadšením a jeden napíše esej lepší než cokoli jiného, co vaše administrativa ten rok vyprodukuje."]]},"e-hamberders":{"t":"Bufet","x":"Personál kuchyně je na nucené dovolené, tak jste osobně koupil tisíc rychlých hamburgerů a rozložil je na stříbře pod lustry. Alvin je řadí podle výšky. Ve vašem oznamovacím příspěvku je přeškrtnuté jediné slovo, na kterém záleží.","c":[["Nechat pravopis. Zveřejnit fotku té hromady.","Fotka je opravdu radostná, ten překlep opravdu nesmrtelný, a jedenáct mistrovských sportovců nezávisle na sobě prohlásí, že to byl nejlepší večer jejich života."],["Opravit příspěvek. Nechat hamburgery.","Správný pravopis, stejné hamburgery, čtvrtina pokrytí. Někde v komunikačním oddělení je jeden člověk tiše potěšen a všichni ostatní se posunuli dál."],["Zrušit to. Kuchyni na jednu noc znovu otevřít.","Čtyři propuštění kuchaři dostanou příplatek za vaření pro jedenáct sportovců uprostřed rozpočtového výpadku, a někdo nevyhnutelně spočítá cenu za talíř."],["Podávat je na státním porcelánu.","Sada z roku 1918 po Wilsonovi, pod ohřívacími lampami, obložená cheeseburgery. Kurátorova hlášení má čtyři stránky a čte se jako výhrůžný dopis."]]},"e-misspell-count":{"t":"Běžící součet","x":"Někde je stůl, kde celé funkční období počítají vaše pravopisné chyby. Kaylee má dnešní číslo. \"Devět set čtyři, pane. Mají teď kategorie. Existuje podkategorie pro slova, která jste napsal špatně víc než jedním způsobem.\"","c":[["Zveřejňovat neupravené. Navždy. Je to důkaz, že je píšu já.","Je to důkaz, a čtyři miliony lidí tomu věří přesně z toho důvodu, a shodou okolností mají pravdu. Zapojení je o 22 procent vyšší než u čehokoli, co zveřejní zaměstnanec."],["Nechat je před odesláním číst někoho jiného.","Správný pravopis vyznívá jako výbor, a výbor vyznívá jako všichni ostatní. Účet se přes noc stane nerozeznatelným od čtyř set jiných."],["Jedno slovo pokaždé úmyslně přepsat, navždy.","Stane se to podpisem, pak heslem poznávacím. Podporovatelé to vám začnou přeříkávat zpátky a počítající úřad tu kategorii tiše zruší."],["Vydat vázané opravené vydání vlastních příspěvků.","Dva pevně vázané svazky, profesionálně korigované, prodají se v 90 000 kusech a dostanou seriózní recenzi ve třech literárních přílohách."]]},"e-503":{"t":"Pět set tři","x":"Ověřovací organizace zveřejnila součet za celé funkční období. Kaylee to čte bez emocí. \"Třicet tisíc pět set sedmdesát tři, pane. Zhruba dvacet jedna denně. Denní rekord je pět set tři a padl v pondělí.\"","c":[["Rekord překonat. Úmyslně. Ve čtvrtek.","Do oběda máte přes šest set. Proměnit tabulku ve vlastní skóre ji zničí jako kritiku, a přesně proto to funguje."],["Zpochybnit metodologii. Vydat vyvrácení.","Vyvrácení napadá čtyři sta z třiceti tisíc a zbytek prostě mlčením přizná, a přesně to je ta část, kterou všichni pokryjí."],["Neříkat nic. Číslo je jen číslo.","Zpráva žije den a půl. Nic, co byste mohl říct, by to nezkrátilo, a leccos by to naopak natáhlo na týden."],["Zaměstnat všechny ověřovatele.","Nabídky jdou celému oddělení. Dva přijmou, dostanou se do interní revize, a vytvoří memorandum tak přesné, že je do týdne utajené."]]},"e-stable-genius":{"t":"Sebehodnocení","x":"Ve třetí větě příspěvku jste se písemně popsal jako velmi stabilní génius. Dr. Prine je tu kvůli něčemu jinému a přečetl si to z telefonu ve dveřích. \"Pane, chtěl bych mít v záznamu, že jsem to nepotvrdil.\"","c":[["Zopakovat to. Přidat \"jako fakt hrozně chytrý\".","Obě fráze vstoupí do jazyka natrvalo, a žádnou z nich už nikdy nikdo kromě vás nepoužije upřímně."],["Nechat to být. Neopakovat to.","Řečeno jednou, je to chvástání. Řečeno dvakrát, je to symptom. Zůstanete u jednou, což tady v budově nikdo nečekal."],["Nechat Prina udělat skutečný kognitivní test.","Skórujete naprosto normálně, což polovina země nahlásí jako skandál a druhá polovina jako triumf, ze stejného čísla."],["Objednat test IQ a zveřejnit jen obálku.","Zapečetěná obálka projede čtyři shromáždění a nikdy se neotevře. Jako kus politického divadla je téměř dokonalá."]]},"e-sharpie":{"t":"Opravená předpověď","x":"Řekl jste, že bouře zasáhne stát, který nikdy nebyl v predikovaném kuželu. Mapa předpovědi na stole má teď navíc dokreslenou smyčku černým fixem. Kaylee: \"Pane. Ta mapa je federální vědecký produkt. Její úprava je trestný čin. Někdo ji upravil. Fixem.\"","c":[["Ukázat mapu na kameru. Smyčku nezmiňovat.","Všichni tu smyčku vidí. Nikdo o ní čtyři minuty přímého vysílání nahlas nemluví, a stane se z toho definující obraz roku."],["Nechat meteorologický úřad vydat podpůrné prohlášení.","Nepodepsané prohlášení na vaši podporu vyjde v devět večer. Každý meteorolog v úřadu se ten samý večer dozví, k čemu je úřad teď skutečně."],["\"Dostal jsem raný odhad.\" Jít dál.","Je to dokonce technicky pravda, jeden raný odhad ten stát skutečně zahrnoval. Kdybyste to řekl první den, skončilo by to; čtvrtý den to neskončí."],["Překreslit celé pobřeží, když už u toho jste.","Upravená mapa posune dva státy do vnitrozemí. Vyfotí ji, zarámují, a na katedře meteorologie visí dodnes jako varovný exponát."]]},"e-mortality":{"t":"Číslo z univerzity","x":"Univerzita vypočítala odhad nadúmrtnosti po hurikánu: zhruba tři tisíce. Dr. Pike má metodologii. \"Je to standardní postup, pane, ten samý, který vaše vlastní administrativa používá pro všechno ostatní. Zpochybnit tohle číslo znamená zpochybnit metodu, na kterou spoléháme.\"","c":[["Zpochybnit ho. Říct, že bylo vymyšlené, aby vám uškodilo.","Tři tisíce rodin slyší prezidenta nazvat jejich mrtvé příbuzné politickým konstruktem. Čtyři z nich vystoupí na kameru a příspěvek se vysílá týden."],["Číslo přijmout. Říct, že reakce byla přesto dobrá.","Obhajitelný argument, který skutečně můžete vyhrát, podaný hned vedle čísla, se kterým jste se rozhodl nebojovat. Je to nejkratší možná verze tohoto příběhu."],["Nařídit federální přezkum, ať vyprodukuje vlastní číslo.","Za jedenáct měsíců se vrátí s 2 975, což je pro vás horší než původní číslo, protože teď je oficiálně vaše."],["Házet další papírové utěrky.","Druhá návštěva, druhá tělocvična, druhé házení podpaží. Někdo, kdo byl v místnosti poprvé, je tam znovu, a řekne to na kameru."]]},"e-war-hero":{"t":"Zajatý muž","x":"Před lety jste řekl, že preferujete lidi, kteří se nenechali zajmout. Ten muž je teď mrtvý a dnes ráno, přímo dotázán, jste řekl, že jste nikdy nebyl jeho fanoušek a nikdy nebudete. Styčný důstojník pro veterány si vyžádal čtyři minuty a ještě si nesedl.","c":[["Trvat na tom. Byl přeceňovaný a řekl jsem to.","Čtyři senátoři z vaší vlastní strany zareagují jmenovitě do hodiny. Dva z nich jsou veteráni a jeden vede Senát."],["Dál nic neříkat. Nikdy.","Mlčení to za devět dní utiší. Je to nejlevnější dostupná odpověď a zároveň ta jediná, kterou je pro vás nejtěžší skutečně dát."],["Navštívit hrob. Bez kamer. Bez prohlášení.","Hrobník to o čtyři měsíce později nevyžádaně zmíní reportérovi, který píše o něčem úplně jiném. Zapůsobí to víc, než by dokázalo jakékoli prohlášení."],["Udělit mu posmrtnou medaili za to, že byl zajat.","Text vyznamenání píše někdo na Pentagonu s naprostou upřímností. Je to opravdu dojemné a nemožné přijmout s grácií."]]},"e-parade":{"t":"Obrněnci na třídě","x":"Tarrant má technické posouzení. \"Hlavní bojové tanky váží sedmdesát tun. Třída na tu zátěž není dimenzovaná a mosty taky ne.\" Otočí stránku. \"Dá se to udělat. Silnici budeme opravovat až do října a účet za opravu vyjde dráž než ta přehlídka.\"","c":[["Tanky. Všechny. Dolů po třídě.","Fotografie jsou výjimečné a doletí dál než cokoli jiného, co za rok uděláte. Čtyři spojenecké ambasády pošlou nevyžádané zprávy jen o té symbolice."],["Jen přelet. Žádné obrněnce.","Letadla jsou zdarma, oblíbená a nezanechávají koleje. Stejná přehlídka, desetina ceny, a žádné z titulků, které by vynesly tanky."],["Žádná přehlídka. Peníze do bydlení pro veterány.","Postaví se jedenáct set bytů. Stuhu za čtyři roky přestřihne někdo jiný a vaše jméno na budově nikde nebude."],["Řídit jeden tank osobně.","Seržant vám dá čtyři hodiny výcviku a viditelně si každou minutu užívá. Sejmete pouliční lampu. Vysílá se to živě."]]},"e-greenland-nasty":{"t":"\"Absurdní\"","x":"Nabídl jste koupi jejich území. Jejich premiérka použila slovo absurdní, anglicky, na kameru. Muriel má diář. \"Státní návštěva je za jedenáct dní, pane. Zrušit ji kvůli jednomu přídavnému jménu je možnost. Není to dobrá možnost, ale je to možnost.\"","c":[["Zrušit návštěvu. Nazvat ji protivnou.","Čtyři sta let starý spojenec je veřejně urážen kvůli jedinému slovu. Jejich parlament to den debatuje a jejich turistický úřad hlásí rekordní počet amerických rezervací."],["Jet stejně. Udělat si z toho vtip na večeři.","Sám otevřete tím slovem a místnost se opravdu zasměje. Je to nejlepší diplomatický večer vašeho funkčního období, a nikdo doma o něm neinformuje."],["Nabídku úplně stáhnout. Nikdy ji už nezmiňovat.","Úplně zmizí, osud každého nápadu, který nikdo nebrání. Čtyři poradci se uleví a jeden je, potichu, zklamaný."],["Nabídnout koupi premiérky místo toho.","Myšleno jako vtip, přenesené jako depeše, přijaté jako formální návrh. Odpověď jejich ministerstva zahraničí je mistrovské dílo zdvořilého úžasu."]]},"e-fell-in-love":{"t":"\"Zamilovali jsme se\"","x":"Popsal jste svou korespondenci s dědičným diktátorem frází \"zamilovali jsme se\". Muriel má přepis a tlustou složku reakcí spojenců. \"Pane, čtyři smluvní partneři se zvlášť ptali, jestli tohle znamená změnu politiky.\"","c":[["Zopakovat to. Ty dopisy byly krásné.","Podle každého, kdo je skutečně četl, jsou to kompetentně lichotivé formulářové dopisy sepsané výborem někde v suterénu."],["Zarámovat to jako osobní chemii sloužící národnímu zájmu.","Profesionálně znějící verze totožného tvrzení. Čtyři ministerstva zahraničí s tím dokážou pracovat a ani jedno tomu nevěří ani slovo."],["Vzít to zpět. Osobní vřelost není politika.","Ústup se nahlásí jednou. Ta fráze se hlásí deset let. Je to standardní směnný kurz a nikdy se nezlepší."],["Zveřejnit dopisy v plném znění.","Ukážou se nudnější, než si kdo dovedl představit, a dvakrát zmiňují golfové hřiště. Zveřejnění příběh okamžitě ukončí a zklame naprosto všechny."]]},"e-riviera":{"t":"Přestavba","x":"Navrhl jste, aby Spojené státy převzaly válkou poškozené území a přestavěly ho na letovisko. Muriel drží reakční depeši a ruka se jí netřese ustáleně. \"Devět spojeneckých vlád, pane. Všech devět. Dvě použily slovo 'vysídlení' a jedna mnohem starší slovo.\"","c":[["Rozvinout to. Ukázat vizualizace.","Architektonická vizualizace přímořského letoviska na masovém hrobě se objeví na tiskovce a koluje roky jako doklad číslo jedna něčeho."],["Přerámovat to jako fond na obnovu.","Nudný, obhajitelný, naprosto konvenční návrh pomoci, který čtyři spojenci okamžitě spolupodepíšou. Stejné peníze, žádné pobouření."],["Stáhnout to. Říct, že to byla myšlenka, ne plán.","\"Myšlenka, ne plán\" je přiznání, že prezident řekl věc bez toho, aby ji promyslel, což je menší příběh než ta alternativa, jen o vlásek."],["Nabídnout přestavbu na golfové hřiště místo toho.","Osmnáct mistrovských jamek, navržených za čtyři dny někým, kdo zjevně neměl ponětí, co pod nimi nedávno bylo."]]},"e-fifty-first":{"t":"\"Guvernére\"","x":"Oslovil jste sousedního premiéra veřejně čtyřikrát \"guvernére\" a nahlas uvažoval o hospodářském nátlaku. Muriel: \"Pane, jejich maloobchodní bojkot amerického zboží je teď na devíti procentech dovozu a stoupá, a je naprosto dobrovolný, což znamená, že není s kým to vyjednat pryč.\"","c":[["Dál mu říkat guvernére. Zjevně to funguje.","Jejich domácí politika se přeskupí kolem toho, že nechtějí být anektováni. Strana, která byla čtrnáct bodů pozadu, vyhraje jasně, kampaň staví skoro výhradně na vás."],["Přestat. Oslovovat ho premiérem a myslet to vážně.","Bojkot postupně slábne asi dva roky. Nikdy úplně neskončí, protože nákupní zvyk přežije clo o pořádnou míli."],["Eskalovat na cla. Udělat z toho vtipu nákladnou záležitost.","Dvě propojené ekonomiky se rozpojí o čtyři procenta za rok. Čtyři pohraniční města na vaší vlastní straně ztratí svého největšího zaměstnavatele."],["Formálně je pozvat, ať zažádají o členství ve federaci.","Skutečná přihláška je doručena kurýrem na jejich ambasádu, vyplněná do posledního políčka jako vtip, a vrácena. Nikdy se nezjistilo, kdo ji vyplnil."]]},"e-currency":{"t":"Portrét na bankovce","x":"Lyle má odpověď mincovny a čte ji jako muž, který něco odzbrojuje. \"Neexistuje zákon zakazující žijící osobu na měně. Existuje sto padesát let stará praxe, interní směrnice a velmi dlouhé ticho, když jsem se zeptal proč.\"","c":[["Stovku. Udělat to.","Každá transakce v zemi teď nese vaši tvář. Čtyři země, jejichž měna to dělá, jsou jmenovány v každém článku, který se kdy napíše."],["Pamětní minci. Omezený náklad.","Vyprodá se za devět hodin a obchoduje se za čtyřnásobek nominální hodnoty. Legální, populární, a stojí to přesně jeden odstavec kritiky."],["Ani jedno. Měna na to není.","Lyle vydechne způsobem, který jste od něj nikdy neslyšel. Směrnice přežije ještě jednu administrativu, což je maximum, čeho směrnice kdy dosáhne."],["Dát svou tvář jen na jednocentovou minci.","Nejmenší nominální hodnota, ta, kterou už i tak ruší. Vyznívá to buď jako mimořádná skromnost, nebo kolosální omyl, a nikdo se neshodne, co z toho."]]},"e-arts-board":{"t":"Schůze rady","x":"Deborah má připravené dopisy. \"Rada odvolána, nová rada dosazena, a vy jako předseda. Je to v mezích vaší jmenovací pravomoci.\" Odmlčí se. \"Pane, rezignace začnou přicházet do hodiny, a u dvou z nich to budou lidé, kterých je opravdovými fanoušky vaše vlastní rodina.\"","c":[["Odeslat je všechny. Osobně předsedat první schůzi.","Čtyři významní umělci odstoupí do týdne od sezóny. Budova si udrží program tím, že najme lidi, kteří si nemohli dovolit odmítnout."],["Vyměnit radu. Předsednictví si nenechat.","Stejná kontrola, minus fotografie. Nikdo nerezignuje kvůli radě, kterou nikdy nepotkal a nedokáže jmenovat."],["Radu nechat být. Přijít místo toho na premiéru.","Sedíte čtyři hodiny na moderním tanci s viditelnou statečností. Umělecká ředitelka řekne čtyřem lidem, že to byl nejpřekvapivější večer její kariéry."],["Předsedat a sám sestavit program sezóny.","Vaše sezóna je devět poctových koncertů, kouzelník a symfonický orchestr hrající filmovou hudbu. Prodá se o 40 procent víc než minulá sezóna, fakt, o kterém nikdo zúčastněný nechce mluvit."]]},"e-rename-water":{"t":"Vodní plocha","x":"Nařízení přejmenovává vodní plochu ohraničenou třemi zeměmi. Muriel má praktickou poznámku. \"Můžeme ji přejmenovat na vlastních mapách, pane. Na cizích mapách ne, a mezinárodní hydrografický úřad rozhodne o čemkoli tak za jedenáct let.\"","c":[["Podepsat to. Naše mapa je jediná, na které záleží.","Dvě sousední země to odmítnou převzít. Každá letecká mapa na světě teď nese obě jména, oddělená lomítkem, trvalý pomník sporu."],["Podepsat to pro domácí použití. Netlačit to v zahraničí.","Domácí mapy se změní, zahraniční vztahy ne, a celá akce stojí 400 000 dolarů na přetisk."],["Nepodepsat to. Má jméno.","Nic se nestane, což je správný výsledek pro návrh přejmenovat moře, a nahlásí se to přesně nikde."],["Pojmenovat ji po sobě.","Čtyři kartografové to písemně odmítnou. Jeden to udělá, následně nesežene práci, a mapa se do deseti let stane sběratelským kouskem."]]},"e-wire-ban":{"t":"Redakční příručka","x":"Tisková agentura pořád používá staré jméno té vody, protože to říká její redakční příručka, a ta příručka řídí čtyři tisíce redakcí. Kaylee: \"Můžeme je vyloučit z místnosti, pane. Nemůžeme je vyloučit z příručky, a příručka je to skutečné bojiště.\"","c":[["Vyloučit je. Ze všeho. Dnes.","Žalují, vyhrají, částečně prohrají v odvolání, a příručky se nikdy nedotknou. Strávil jste jedenáct měsíců přesouváním jednoho slova uvnitř jedné budovy."],["Vyloučit je jen z malé místnosti. Velké akce zachovat.","Dost na to, aby to udělalo dojem, ne dost na to, aby to založilo žalobu. Jejich právníci žalobu o zasedací pořádek nedoporučí."],["Nechat to být. Je to redakční příručka.","Staré jméno zůstane standardem všude na světě. Vždycky by tomu tak bylo, a vy jste právě ušetřil soudní řízení a rok života."],["Vydat federální redakční příručku a nařídit ji.","Čtyři sta stran, vydaných všem úřadům, jedenáct pravidel o vašem jméně a jedno o oxfordské čárce, což je jediné pravidlo, které vyvolá vzpouru."]]},"e-complicated":{"t":"\"Nikdo to nevěděl\"","x":"Řekl jste na kameru, že nikdo nevěděl, že zdravotnictví může být tak komplikované. Dr. Pike drží hromadu papíru. \"Pane, tohle je žádost o výjimku jednoho jediného státu. Má jedenáct set stran. Všichni to věděli. V určitém smyslu je to jediná věc, kterou kdokoli poslední třicet let vůbec ví.\"","c":[["Trvat na tom. Nikdo mi neřekl, že je to tak zlé.","Prezident veřejně přizná, že nevěděl, že centrální otázka domácí politiky jeho kariéry je komplikovaná. Obě strany to citují navždy, z opačných důvodů."],["\"Myslel jsem, že mi to nikdo poctivě nevysvětlil.\" Obrat.","Záchrana, která je zároveň obratná i přibližně pravdivá. Pike, který to vysvětluje poctivě dvacet let, tentokrát výjimečně mlčí."],["Sednout si s Pikem na čtyři hodiny a fakt se to naučit.","Vyjdete z toho schopen bez poznámek vysvětlit rizikové skupiny pojištěnců. Je to nejužitečnější odpoledne vašeho prezidentství, a nikdo o tom nikdy nenapíše."],["Prohlásit zdravotnictví za jednoduché výnosem.","Výnos má šedesát jedna stránek definic ustanovujících, co jednoduchost znamená. Ironii zaznamená úplně každý, kdo to čte."]]},"e-light":{"t":"Ta druhá věc na brífinku","x":"Nešlo jen o tu první poznámku. Na stejném brífinku jste se ptal, jestli by se do těla nedalo přivést velmi silné světlo. Dr. Pike je tu s jednostránkovou poznámkou. \"Pane, čtyři nemocnice přijaly hovory. Ne mnoho. Ale čtyři.\"","c":[["Říct, že jste to myslel sarkasticky.","Přepis nezní jako sarkasmus, ani video ne. Tvrzení se stane vlastním, menším, déle trvajícím příběhem než ta poznámka sama."],["Nechat Pika vydat jasný pokyn. Sám neříkat nic.","Jednostránková klinická poznámka dorazí na každé pohotovostní oddělení v zemi do šesti hodin. Hovory ustanou."],["Přestat s brífinky.","Brífinky vám byly hodné čtyř bodů týdně a stály zhruba stejně. Ukončit je je remíza, kterou nikdo na žádné straně vlastně nechtěl."],["Nechat světelný nápad pořádně prozkoumat.","Skutečná rešerše se vrátí s popisem čtyř skutečných nitrožilních světelných terapií a zdvořile uzavře, že tohle žádná z nich nebyla."]]},"e-testing":{"t":"Zpomalit testování","x":"Řekl jste, že když se testuje v takovém rozsahu, najde se víc případů, a proto jste požádal, ať se testování zpomalí. Dr. Pike úplně ztuhne. \"Pane, byl to vtip? Mám čtyři ředitele zdravotnictví ze států, kteří se mě ptají, a já upřímně nevím, co jim mám říct.\"","c":[["Nebyl to vtip. Testování zpomalit.","Testování se ve skutečnosti nezpomalí, protože ho provádí státy a nemocnice, ne vy. Ta věta přežije danou politiku o dobrou dekádu."],["\"Byl jsem sarkastický.\" Nechat to tak.","Čtyři z vašich vlastních úředníků do dne veřejně řeknou, že jste nebyl, protože pokyn už dostali a jednali podle něj."],["Testování zdvojnásobit a čísla hlásit denně.","Počet případů prudce stoupne, protože je teď skutečně nacházíte. Pike tomu říká nejodvážnější politické rozhodnutí, jaké kdy viděl, a stojí vás to devět bodů."],["Testovat jen lidi, u kterých je pravděpodobný negativní výsledek.","Někdo to v dobré víře sepíše a rozešle jako návrh protokolu, než ho odchytí. Návrh přežije v archivu dodnes."]]},"e-send-her-back":{"t":"Skandování","x":"Dav začal skandovat o sedící kongresmance a je to tři slova dlouhé. Přestal jste mluvit. Deborah do sluchátka: \"Zatím třináct vteřin, pane. Cokoli uděláte v příštích pěti, je to, co se bude přehrávat.\"","c":[["Počkat. Nechat to doznít. Pak pokračovat.","Třináct vteřin ticha, vysílaných živě. Čtyři vaši vlastní členové se od toho jmenovitě distancují a vy strávíte týden vysvětlováním jedné pauzy."],["Přerušit to. \"Tohle u nás neděláme.\"","Dav okamžitě přestane, což dokazuje, že by přestal okamžitě kdykoli během předchozích třinácti vteřin, kdybyste ho o to požádal."],["Mluvit skrz to. Změnit téma uprostřed věty.","Žádná konfrontace, žádné schválení. Je to zbabělá volba a s velkým odstupem ta nejúčinnější na stole."],["Zahájit jiné skandování. Okamžitě. Jakékoli.","Začnete skandovat o infrastruktuře. Dav se přidá, zmatený, ale loajální, a třicet tisíc lidí stráví devadesát vteřin křikem o mostech."]]},"e-stand-by":{"t":"Odpověď z debaty","x":"Vyzván, ať je odsoudíte, jste jim řekl, ať ustoupí a jsou připraveni. Kaylee má dopad. \"Vytiskli si to na merchandise, pane. Do hodiny. Berou to jako pokyn, a upřímně, gramaticky je to pokyn.\"","c":[["Odmítnout to upřesnit. Nechat je, ať si to vykládají, jak chtějí.","Ozbrojená skupina teď věří, že má od prezidenta pohotovostní rozkazy. Na tomhle uspořádání se během následujících měsíců nic nezlepší."],["Odsoudit je jmenovitě příští ráno.","Jmenovitě, bez vyzvání, jednou větou. Merchandise se přestane prodávat a čtyři organizátoři veřejně řeknou, že se cítí opuštěni, což byl ten záměr."],["Odsoudit \"veškerý extremismus\", aniž byste kohokoli jmenoval.","Odsouzení, které nikoho nejmenuje, slyší všichni jako odsouzení nikoho, což je přesně a doslova to, čím je."],["Nařídit jim, ať ustoupí *dopředu*, aby otestovali tu teorii.","Vysvětlení je v každém měřitelném ohledu horší než originál. Čtyři sta lidí to do dne vezme naprosto doslova."]]},"e-hostages":{"t":"Slovo pro ně","x":"Začal jste odsouzené výtržníky nazývat rukojmími. Sy: \"Pane, čtyři se přiznali. U soudu. S obhájcem. Přiznání viny je věc, kterou rukojmí fyzicky nemůže učinit, a přepisy jsou veřejné dokumenty.\"","c":[["Pokračovat v tom. Pouštět jejich telefonáty na shromážděních.","Nahrávka odsouzených vězňů zpívajících hraje předtím, než vejdete na pódium, čtyřicetkrát, a nikdy nepřestane být mimořádná."],["Místo toho tvrdit, že tresty byly nepřiměřené.","Argument o výši trestu je aspoň argument. Čtyři z těch trestů opravdu byly dlouhé, a kdybyste řekl jen tohle, ten bod byste si skutečně vybojoval."],["Přestat to slovo používat.","Vaše hnutí si toho do dne všimne a bere to jako první krok zrady, což v jejich pojetí víceméně je."],["Nabídnout jejich výměnu za skutečné rukojmí.","Návrh se odešle na ministerstvo zahraničí, které to vůbec nečekalo. Jejich odpověď upřímně žádá o vyjasnění podmínek."]]},"e-acting":{"t":"Pověřený","x":"Deborah má organizační schéma a většina jména je kurzívou. \"Jedenáct vedoucích úřadů je pověřených. Čtyři jsou pověřeni už přes rok. Pověřený úředník slouží zcela podle vaší libosti a dá se vyměnit do oběda, proto ho máte rád, a proto je zákonná lhůta už dávno překročená.\"","c":[["Nechat je všechny pověřenými. Natrvalo.","Vláda lidí, kteří se dají okamžitě odvolat. Všechno funguje trochu hůř a nic se nikdy neodmítne, což byla vždycky ta výměna."],["Nominovat ty čtyři, které by potvrdili.","Čtyři potvrzení ministři s nezávislým postavením, každý vám za rok jednou řekne ne. Všechny čtyřikrát jste se mýlil."],["Nominovat všechny. Přijmout ztráty.","Sedm potvrzeno, čtyři odmítnuti. Odmítnutí bolí a potvrzení jsou trvalá, a trvalost je ta věc, kterou jste si dosud jen půjčoval."],["Jmenovat jednu osobu pověřenou pro všech jedenáct rolí.","Je to na chvíli zákonné. Zastává jedenáct ministerstev devět dní a pak o tom napíše knihu, se kterou se hodně těžko polemizuje."]]},"e-loyalty-lunch":{"t":"Oběd","x":"Je večeře a jste tam sami dva. Ředitelka Quistová si už všimla dvou prostřených míst v místnosti pro čtyřicet. Chystáte se použít slovo, které vám Bo dvakrát, písemně, zakázal používat.","c":[["\"Potřebuju loajalitu. Očekávám loajalitu.\"","Místo toho vám nabídne upřímnost. Ta výměna se do hodiny sepíše, s datem, na parkovišti, a do roka se přečte nahlas výboru."],["Požádat o nezávislost, a myslet to vážně.","Řekne to veřejně o měsíc později, nevyžádaně, pod přísahou. Je to nejcennější věta, kterou o vás kdo za celé funkční období pronese."],["Mluvit o jídle. Neptat se na nic.","Devadesát minut o vínu. Odejde zmatená a nesepíše nic, což je jediný výsledek, který vám tady vlastně pomůže."],["Požádat ji, ať podá loajalitu.","Vtip, špatně podaný, přesně v okamžiku, kdy usoudila, že ten večer je neškodný. Zapíše si ho přesto, doslovně, s otazníkem."]]},"e-witch-hunt":{"t":"Ta fráze","x":"Kaylee zase počítala. \"Čtyři sta jedenáct použití stejných dvou slov za osmnáct měsíců. Teď je s vámi spojenější než se sedmnáctým stoletím.\" Zaváhá. \"Pane, vyšetřování se za chvíli zveřejní, a ta fráze bude to, co budou lidé mít místo zprávy.\"","c":[["Říct to ještě čtyři sta krát.","Funguje to naprosto. Zpráva vyjde a 61 procent země už ji má zaškatulkovanou pod frází, kterou slyšeli dřív, než slyšeli cokoli jiného."],["Přestat to říkat. Napadnout raději zjištění.","Hádat se s dokumentem je těžší, než dokument odmítnout, a podstatně účinnější u těch čtyř procent, co vlastně rozhodují volby."],["Plně spolupracovat a neříkat vůbec nic.","Vyjde včas, najde míň, než chtěla obě strany, a nepřečte si to nikdo, standardní osud jakéhokoli dokumentu, o kterém nikomu neřekli, ať se o něj zajímá."],["Nechat si tu frázi zaregistrovat jako ochrannou známku.","Přihláška se podá vážně a zamítne se s odůvodněním, že termín je běžně užívaný, hlavně díky vám."]]},"e-hotel-booking":{"t":"Rezervace delegace","x":"Miriam má rezervace. \"Čtyři zahraniční delegace, všechny ve vašem hotelu, všechny čtrnáct dní před svými obchodními jednáními.\" Odkládá je. \"Nikdo je o to nepožádal. To je ta část, kterou pořád nedokážu jasně vysvětlit: nikdo se nemusel ptát.\"","c":[["Vzít ty rezervace. Je to hotel.","Platba od cizího státu prezidentovi, za zveřejněnou cenu, za skutečný pokoj. Je to nejčistší možná verze nejstaršího možného problému."],["Vzít je. Zisk poslat do státní pokladny.","Dobrovolný, neověřitelný odhad možného zisku, zveřejňovaný ročně, odstraní 90 procent kritiky za zlomek nákladů."],["Nařídit hotelu odmítat rezervace zahraničních států.","Pokyn se sepíše a dodrží. Stojí to zhruba 12 milionů dolarů ročně a je to jediná položka na tomhle seznamu, která opravdu něco řeší."],["Naúčtovat jim čtyřnásobek a nazvat to clem.","Dvě delegace to bez námitek zaplatí, což je nejalarmnější dostupný výsledek a všimnou si ho čtyři zpravodajské služby."]]},"e-jet":{"t":"Letadlo","x":"Cizí vláda nabídla letadlo. Tarrant má bezpečnostní posouzení a pečlivě volí slova. \"Zbavit ho vnitřního vybavení a přestavět na náš standard trvá čtyři roky a stojí víc, než koupit nové rovnou. A pane, formulace je sporná. Oni tvrdí, že bylo nabídnuto. Někdo z naší strany se zeptal první.\"","c":[["Přijmout to. Nazvat to nevyžádaným darem.","Záznam o tom, kdo koho oslovil jako první, vyjde na povrch do čtrnácti dnů, protože vždycky vyjde, a slovo \"nevyžádaný\" se místo letadla stane příběhem."],["Přijmout ho pro letectvo. Ne osobně.","Dar státu státu, řádně převedený, nakonec do muzea. Je to nudná odpověď, a přežije každý výbor, který se jí dotkne."],["Odmítnout ho. Koupit vlastní.","Stojí to čtyři miliardy dolarů, trvá to šest let, a nezbývá o tom naprosto nic napsat. Tarrant tomu říká dobře utracené peníze."],["Přijmout ho a odletět s ním do muzea osobně.","Nemáte kvalifikaci na ten typ letadla. Sednete si na levé sedadlo, na zemi, na fotku, a popisek napíše někdo, kdo si to napřed ověřil."]]},"e-poll-numbers":{"t":"Data z průzkumů","x":"Nadia má skutečná čísla a ta, která jste citoval. Liší se o devatenáct bodů. \"Ten, co používáte, je online dobrovolný průzkum mezi vašimi vlastními podporovateli, pane. Vím, kdo ho zadal, protože mě požádali, ať ho navrhnu, a já jsem odmítla.\"","c":[["Citovat dál ten dobrý. Existuje.","Skutečně existuje, což ho dělá spíš nevyvratitelným než pravdivým, a nevyvratitelnost se na volném trhu, jak se ukazuje, cení podstatně víc."],["Citovat ten skutečný. Říct, že máte práci.","Upřímnost k číslu je vám za čtvrtletí čtyři body vydatnější, než kdy dodalo falešné číslo."],["Přestat vůbec citovat čísla.","Nadia tomu říká nejzdravější rozhodnutí funkčního období. Vydrží jedenáct dní."],["Objednat průzkum, jestli jsou průzkumy vůbec přesné.","Šedesát jedna procent řekne ne, což citujete jako důkaz, že průzkumy ukazující vaši prohru jsou chybné, použití zjištění, se kterým Nadia opravdu nepočítala."]]},"e-rally-length":{"t":"Devadesátá minuta","x":"Jste devadesát čtyři minuty do čtyřicetiminutového slotu. Boyd Hackler v zákulisí dělá gesto, o kterém jste se rozhodl, že znamená \"pokračujte\". Aréna se musí uvolnit pro hokejový zápas a venku v mrazu stojí čtyři tisíce lidí s lístky na něj.","c":[["Ještě čtyřicet minut. Přišli si pro tohle.","Hokejový zápas začne o devadesát minut později. Jeho fanoušci, dotázaní cestou dovnitř, mají na to velmi jasný názor."],["Zabalit to do pěti minut. Silný závěr.","Sevřený, úderný konec, který v televizi zabírá líp než předchozích devadesát čtyři minut. Boyd si čas poznamená a nikdo si toho nevšimne."],["Skončit teď a zůstat podávat ruce místo toho.","Dvě hodiny podávání rukou čtyřem tisícům lidí, cennější než ten projev, a žádná kamera kvůli tomu nezůstane."],["Zůstat na pódiu a sledovat hokej.","Sledujete tři třetiny ze skládací židle u mantinelu. Je to nejoblíbenější věc, co za rok uděláte, a to o míle."]]},"e-golf-count":{"t":"Účetní kniha odpolední","x":"Někdo vede webovou stránku počítající vaše odpoledne na vlastních hřištích. Kaylee má číslo. \"Dvě stě osmdesát jedna dní, pane, a stránku teď citují jako zdroj i tiskové agentury, což znamená, že povýšila z koníčku na fakt.\"","c":[["Jít víc. Oznamovat každé.","Přiznat to odstraní úder a nahradí ho číslem, které veřejně jen dál roste, což se ukáže jako podstatně horší."],["Chodit dál, ale přestat účtovat vládě detaily.","Náklad byl vždycky ten skutečný příběh. Odstraňte ho, a zbyde muž hrající golf, což není příběh nikde na světě."],["Omezit to. Na čtvrtletí pracovat i o víkendech.","Tři měsíce viditelné práce vám přinesou čtyři body podpory navíc a učiní vás na celé čtvrtletí nesnesitelným."],["Konat schůze kabinetu na hřišti.","Jedenáct ministrů ve flotile golfových vozíků, zapisujících poznámky. Přijmou se dvě opravdu užitečná rozhodnutí a poznámky se nikdy nenajdou."]]},"e-enemy-phrase":{"t":"Nepřátelé lidu","x":"Dr. Weirová si vyžádala pět minut kvůli jedné frázi. \"Pane prezidente, nejsem tu, abych vám řekla, ať neútočíte na tisk. Jsem tu, abych vám řekla, odkud přesně ta konkrétní formulace pochází, protože myslím, že to nikdo neudělal, a nepochází to odnikud, odkud byste chtěl.\"","c":[["Nechat si to. Zabírá to a vím, odkud to pochází.","Čtyři historici napíšou nezávisle na sobě stejný sloupek. Její pointa nikdy nebyla, že to selže; bylo to, že to zabere, a řekne vám to cestou ven ze dveří."],["Přejít na \"fake news\". Stejný boj, žádná genealogie.","Identický efekt, žádná poznámka pod čarou, žádní historici. Je to nejúčinnější úprava, kterou za čtyři roky ve svém slovníku uděláte."],["Frázi i celý ten boj opustit.","Pokrytí se nezlepší. Nikdy by se nezlepšilo. Ten boj byl vždycky ta věc, co skutečně fungovala, a vy jste v ní právě přestal."],["Zeptat se jí, které režimy to používaly, a dělat si poznámky.","Odpoví podrobně, s daty, dvacet minut. Popíšete čtyři stránky poznámek. Ona stráví zbytek života přemýšlením, k čemu to bylo."]]},"e-vermin":{"t":"Návrh s tím zvířecím slovem","x":"Gideon Poe označil podstatné jméno v zítřejším projevu. \"Je to slovo pro zvíře, použité na občany, ve větě o životě mezi námi.\" Nezvedá oči. \"Pane, já to nenapsal. Snažím se zjistit, kdo to napsal, a nedaří se mi to, což je samo o sobě odpověď.\"","c":[["Nechat to. Přednést to přesně, jak je napsáno.","Historici zareagují do hodiny, ve velkém počtu, citují tři stejné režimy. Je to nejcitovanější věta vašeho prezidentství, a nikdy ne pochvalně."],["Vyměnit to podstatné jméno. Nechat větu.","Stejná reakce sálu, žádné archivní záběry, žádné sloupky. Gideon tomu říká nejlevnější úprava, jakou kdy udělal, a myslí to naprosto vážně."],["Vyškrtnout celý ten úsek.","Projev je o čtyři minuty kratší a podstatně lepší. Nikdo si nevšimne absence, ta trvalá, nevděčná tragédie dobré redakce."],["Přednést to, ale o vlastní straně.","Sál neví, co s tím. Dva lidé zatleskají. Je to nejopravdověji znepokojivých devadesát vteřin celého funkčního období."]]},"e-tylenol":{"t":"Rada z pódia","x":"Spojil jste běžný lék proti bolesti s vývojovou poruchou a navrhl rozvolnit dětské očkování. Dr. Pike přijde bez pozvání. \"Pane, čtyři velké studie tvrdí opak a mohu vám je mít na stole do hodiny. Pediatrická sdružení už píšou stanoviska.\"","c":[["Zopakovat to. Hlasitěji. Lidé to musí slyšet.","Termíny očkování klesnou za čtvrtletí o devět procent ve čtyřech státech. Číslo se zveřejní, přisoudí, a už se nikdy nevrátí zpátky."],["\"Nejsem lékař. Zeptejte se svého.\" Jít dál.","Šest slov napraví většinu škody. Pike poté řekne, že to byla správná odpověď a že od vás nečekal, že ji skutečně uslyší."],["Nechat Pika, ať vede brífink místo vás, od teď.","Nudný muž dvakrát týdně po rok čte fakta. Dvanáct měsíců v kuse se nic nezvrtne, a nikdo za to nikomu nepoděkuje."],["Vzít si lék na kameru, ať dokážete, že je v pořádku.","Vezmete si dva, naživo v televizi, poté, co jste je právě nazval nebezpečnými. Nikdo v místnosti nedokáže vymyslet doplňující otázku."]]},"e-blago":{"t":"Velmi slušný člověk","x":"Zmírnil jste trest guvernérovi odsouzenému za pokus prodat senátorské křeslo a popsal ho potom jako velmi slušného člověka. Sy: \"Porota ho odsoudila za prodej veřejného úřadu. Pane, to je ten trestný čin. To je přesně to, co udělal.\"","c":[["Zopakovat to. Zacházeli s ním nespravedlivě.","Dalších čtyři lidé žádající o milost si najme stejného právníka, jakého použil on, což je tržní signál, a přesně tak se to i nahlásí."],["Zmírnit trest potichu. O tom muži neříkat nic.","Zmírnění trestu bez přívlastku je rutinní akt milosti. Ten přívlastek byl vždycky celý ten příběh."],["Stáhnout to. Byl to špatný případ.","Udělenou milost nelze vzít zpátky. Sy to vysvětluje a vy strávíte celé čtyři minuty odmítáním tomu uvěřit."],["Jmenovat ho do něčeho.","Federální poradní rada pro veřejnou integritu. Jmenování je skutečné, oznámí se v pátek, a trvá jedenáct dní."]]},"e-antifa":{"t":"Označení","x":"Duane má návrh výnosu a jeden problém. \"Označuje organizaci. Pane, žádná organizace to není. Žádné členství, žádné vedení, žádný bankovní účet, a nic, na co by šlo doručit soudní obsílku. Úřad se písemně ptá, koho přesně mají zatýkat.\"","c":[["Podepsat to. Nechat úřad, ať vyřeší podrobnosti.","Bez organizace, kterou by šlo skutečně obžalovat, se označení začne uplatňovat na jednotlivce podle jejich názorů, což byl vždycky jediný způsob, jak to mohlo fungovat."],["Označit čtyři konkrétní skupiny, které skutečně existují.","Jmenované entity s bankovními účty a vedením, stíhatelné podle stávajícího zákona. Do dvou let následují čtyři odsouzení a ani jedno se neruší."],["Nepodepisovat to. Použít zákony, které máme.","Stávající zákony fungují dobře, protože politické násilí je nezákonné už dvě stě let a mezera v zákoně nikdy neexistovala."],["Označit sám sebe, ať otestujete standard.","Papíry se sepíšou jako demonstrace a, katastrofálně, opravdu podají. Strávíte devět dní na seznamu, než si toho někdo všimne."]]},"e-shithole-confirm":{"t":"O osm let později","x":"Před osmi lety jste popřel to slovo. Dnes ráno, nevyžádaně, v rozhovoru o něčem úplně jiném, jste ho použil znovu a potvrdil původní tvrzení. Kaylee má oba záznamy připravené a nepouští je. \"Pane, právě jste potvrdil zprávu, kterou jste celý rok nazýval smyšlenou.\"","c":[["Říct, že jste to vždycky tvrdil a měl jste pravdu.","Oba záznamy běží vedle sebe čtrnáct dní. Novináři, které jste rok nazýval lháři, jsou nakonec nezvykle velkorysí, když to celé skončí."],["Říct, že popírání se týkalo přesného znění.","Je to, technicky, přesně to, co původní popření řeklo. Obhajoba \"technicky co to řeklo\" nikdy nefungovala, a nezačne teď."],["Omluvit se novinářům jmenovitě.","Čtyři jména, nahlas, nevyžádaně. Vaše hnutí to bere jako zradu, a dva ze čtyř novinářů veřejně řeknou, že to nic nezměnilo, a přece na tom záleželo."],["Tvrdit, že jste citoval někoho jiného v místnosti.","Každý další v té místnosti je pořád naživu, a čtyři z nich se do hodiny na to zeptají. Všichni čtyři odmítnou stejnou opatrnou větou."]]},"e-invasion-word":{"t":"Podstatné jméno pro příchozí","x":"Gideon má graf četnosti. \"To slovo se objevuje v každém projevu šest týdnů, a jen v šesti týdnech před volbami. Pane, to není popis, to je harmonogram, a někdo tenhle graf zveřejní.\"","c":[["Používat ho víc. Funguje to, protože je to pravda.","Graf se zveřejní. Korelace s volebním kalendářem je přesná, což je horší než jakékoli jednotlivé použití toho slova."],["Používat ho dál i po volbách.","Konzistence úplně odstraní obvinění z cynismu a nic vás nestojí, protože to slovo dělá stejnou práci v březnu jako v říjnu."],["Zavrhnout ho. Mluvit místo toho o mzdách a bydlení.","Ekonomický argument, obhajitelný a nudný. Přesvědčí o čtyři sta tisíc lidí víc a nikoho naprosto nenadchne."],["Použít to slovo na něco jiného úplně.","Špatnou pylovou sezónu dvakrát popíšete jako invazi, s naprostým přesvědčením. Čtyři alergologické spolky vydají prohlášení, a jeden vám poděkuje."]]},"e-lee":{"t":"Generál na podstavci","x":"Nazval jste ho skvělým generálem. Dr. Weirová nezpochybňuje to vojenské hodnocení a řekne to na rovinu. \"Byl schopný velitel, pane prezidente. Byl schopný velitel armády postavené na tom, aby lidi drželi jako majetek, a socha vznikla šedesát let po jeho smrti, kvůli lidem, kteří si tím dělali poznámku o něčem, co se dělo přesně tehdy.\"","c":[["Nařídit ochranu soch. Všech.","Federální ochrana pomníků postavených jako politická prohlášení, obhajovaná jako historie. O komentář požádají čtyři historiky a všichni čtyři citují to samé datum."],["Nechat to na obcích. Dál nic neříkat.","Čtyřicet jedna obcí rozhodne čtyřicet jedna odlišnými způsoby za čtyři roky, a nic z toho se nestane celostátní zprávou."],["Chválit vojáka, podporovat odstranění.","Rozlišení, které čtyři historici pokládají za intelektuálně poctivé a vaše základna za přímou zradu, ze stejných dvou faktů."],["Nahradit je všechny sochami sebe.","Jedenáct podstavců se přestaví. Čtyři z nových soch spadnou do deseti let, stejným procesem, se stejnými argumenty, a nikomu to tehdy nepřijde vtipné."]]},"e-crowd-again":{"t":"Letecký snímek, znovu","x":"Jiná akce, jiná letecká fotografie, stejný spor. Kaylee má oba roky vedle sebe. \"Pane, tenhle boj jste vedl už počtvrté. Nikdo ho nikdy nevyhrál. Fotku pořizuje satelit a satelit nemá názor.\"","c":[["Bojovat s tím. Znovu. Nařídit opravená čísla.","Archivář z povolání je podruhé za čtyři roky přeložen, do té samé budovy bez oken, a číslo je opět oficiální."],["\"Davy jsou posedlost médií.\" Další otázka.","Příběh zemře za čtyřicet minut. Něco ve vás s ním zemře taky a Kaylee si poznamená, ať tu větu použije znovu příště."],["Zveřejnit vlastní záznam z dronu. Nechat lidi počítat.","Záběry ukazují velký, skutečný, nadšený dav, zhruba třetinu udávané velikosti. Zveřejnit ho je nejlepší dostupná verze prohry."],["Uspořádat příští shromáždění tam, kde nejde nafotit z letadla.","Hala s tvrdou kapacitou devět tisíc lidí, kterou pak oznámíte, že navštívilo osmdesát tisíc."]]},"e-cabinet-italics":{"t":"Rezignační dopis","x":"Dva členové rady odstoupili a zveřejnili své dopisy. Deborah má oba. \"Zdvořilé, konkrétní, čtyři odstavce dlouhé. Ani jeden vás jménem nezmiňuje, pane, což je přesně ta věc, díky které se rozletí do světa.\"","c":[["Osobně napadnout oba dva.","Jmenovat lidi, kteří odmítli jmenovat vás, celou tu výměnu obrátí naruby. Jejich dopisy se čtou nahlas ve čtyřech pořadech; váš v žádném."],["Přijmout rezignace bez komentáře.","Rezignace, na kterou nikdo nereaguje, je jen rezignace. Rezignace, na kterou někdo reaguje, je skandál, a vy jste se rozhodl tu druhou polovinu nedodat."],["Požádat je, ať zůstanou. Osobně. Telefonem.","Jedna zůstane. Řekne o tom hovoru čtyřem lidem, a příběh se změní na prezidenta, který zvedl telefon, což se nikdy předtím nestalo."],["Přijmout rezignace a oběma nabídnout něco lepšího.","Oba odmítnou, písemně, se zjevnými obtížemi. Jedna si dopis s nabídkou schová a zmíní ho o jedenáct let později v memoárech."]]},"e-birthday-parade":{"t":"Náhoda","x":"Boyd má problém s datem. \"Přehlídka k výročí ozbrojených sil padá na vaše narozeniny. Doopravdy, je to skutečné výročí a skutečná náhoda.\" Pohne se. \"Nikdo mimo tuhle místnost tomu neuvěří, pane. Kalendář jsem si sám ověřil čtyřikrát, protože jsem tomu taky nevěřil.\"","c":[["Uspořádat ji. Zmínit narozeniny z pódia.","Skutečná náhoda se jedinou větou promění v úmyslnou, před jedenácti tisíci sloužícími vojáky."],["Uspořádat ji. Narozeniny nikdy nezmínit.","Výročí se oslaví řádně. Čtyři média zmíní shodu dat v devátém odstavci a nikdo nikdy nečte devátý odstavec."],["Přesunout přehlídku na jiný víkend.","Přesunout dvěstěpadesátileté výročí kvůli implikaci je samo implikací, a Boyd to poznamená, správně, ale příliš pozdě."],["Přesunout vlastní narozeniny.","Proklamace určí jiné oficiální datum. Podepíše se. Čtyři úřady si opraví záznamy a jeden pak posílá přání od té doby oba dny."]]},"e-pen-set":{"t":"Pera","x":"Alvin má tác. \"Dvaadvacet per na podpis, pane, a vy jste podepsal sto čtyřicet tři příkazů.\" Provede výpočet, aniž by ho o to kdo žádal. \"Tři tisíce sto čtyřicet šest per. Ty dobré nám došly, a rezerva je zásoba z roku 1974.\"","c":[["Objednat čtyřicet tisíc dalších. Zlatých. S mým podpisem.","Dorazí za jedenáct týdnů. Podpis je na všech čtyřiceti tisících mírně mimo střed, a nikdo se to neodváží zmínit."],["Použít zásobu z roku 1974. Někdo by měl.","Pero z úplně jiného prezidentství podepíše příkaz, který by jeho původního majitele ohromil. Alvina to baví víc než kohokoli jiného."],["Jedno pero na podpis. Nechat si je všechna.","Kompletní sada, v pořadí, v pouzdru, se stane nejcennějším předmětem, jaký kdy z téhle budovy kdo odnese."],["Podepisovat vším navždy stejným perem.","Dojde mu inkoust u příkazu číslo devadesát jedna, uprostřed podpisu, před kamerami. Příkaz zůstane technicky nedokončený čtyři hodiny, než si toho někdo všimne."]]},"e-nickname":{"t":"Přezdívka pro něj","x":"Brayden má na kartě čtyři možnosti. \"V testech si vedou o jedenáct až devatenáct bodů lépe než jeho skutečné jméno, pane. Ta nejúspěšnější je zároveň nejkrutější, což není náhoda, a já už dávno přestal předstírat, že je.\"","c":[["Tu nejkrutější. Použít v každém příspěvku.","Uchytí se tak dokonale, že o čtyři roky později musí seriózní periodika upřesňovat, kterého muže mají na mysli, když použijí jeho skutečné jméno."],["Tu nejmírnější. Pořád funguje.","Jedenáct bodů místo devatenácti, a žádný záznam, jak něco říkáte o mužově rodině. Správná směna, pokaždé."],["Použít jeho skutečné jméno. Útočit na jeho skutečné hlasování.","Věcný útok na reálný hlas, který skutečně odevzdal. Je to nejzničující věc, kterou o něm kdokoli za celý rok řekne, a získá to čtvrtinu pozornosti médií."],["Dát mu místo toho lichotivou přezdívku.","Začnete mu říkat něco upřímně pochvalného a odmítáte vysvětlit proč. Viditelně ho to zneklidňuje celé čtyři měsíce."]]},"e-doctor-note":{"t":"Dopis od lékaře","x":"Doktor Prine sepsal výroční lékařskou zprávu. Má čtyři odstavce a slovo \"mimořádný\" v ní použije dvakrát. \"Pane, tohle není dopis, který bych napsal já. Je to dopis, který mám podepsat, a rád bych věděl, který z těch dvou nakonec skutečně vyjde ven.\"","c":[["Ten, co dostal. Podepsat ho.","Podpis lékaře pod superlativy někoho jiného. Čtyři lékařské asociace se vyjádří k etice celé věci, a Prine si přečte všechny čtyři."],["Ten, který by napsal sám.","Píše se v něm, že jste muž svého věku v přiměřené kondici se dvěma zvladatelnými potížemi. Naprosto nezajímavé, a proto se to už nikdy nezmíní."],["Zveřejnit obě verze a nechat lidi vybrat.","Radikální transparentnost jako vtip, který se ukáže být opravdu funkční politikou. Prine si dvoustránkové prohlášení dá zarámovat."],["Nechat ho potvrdit, že jste nejzdravější prezident v historii.","Odmítne, písemně, s odkazem na čtyři prezidenty, kteří běhali maratony. Z odmítavého dopisu se stane dokument jistého historického významu."]]},"e-intern-photo":{"t":"Fotografie","x":"Madison vyfotila chodbu a fotku zveřejnila, už má čtyři sta tisíc zhlédnutí. Nic tajného na ní není. Je na ní vidět vy, zezadu, jak sami procházíte chodbou v deset večer, a je to nejlidštější snímek, jaký o vás kdo za čtyři roky pořídil.","c":[["Zakázat veškeré fotografování personálu. Zabavit telefony.","Zákaz je titulek na tři dny, fotografie je titulek na tři roky. Madison není propuštěna a už nic dalšího nezveřejní."],["Nechat to být. Ať klidně dál fotí.","Naprostou náhodou se z ní stane nejúčinnější komunikační zbraň v celé budově. Nikdo z tiskového oddělení to nedokáže zopakovat, ačkoliv se o to čtyři z nich pokusí."],["Ať fotí víc. Oficiálně. Podle zadání.","Ve chvíli, kdy to dostane zadání, přestane to fungovat. Zapojení diváků klesne za čtrnáct dní o 80 procent, a Madison to, ke cti jí budiž řečeno, otevřeně přizná."],["Zveřejnit na oplátku fotku jí, zezadu.","Prezident fotící stážistku, která fotí prezidenta. Je to opravdu půvabné, a čtyři lidé z právního oddělení nad tím musí pořádně přemýšlet."]]},"e-usher-book":{"t":"Jednačtyřicet let","x":"Alvin odchází do důchodu. Jednačtyřicet let, sedm prezidentů. Nikdy nedal jediný rozhovor, a tento měsíc mu čtyři nakladatelství nabídla smlouvu. Říká vám to jen ze zdvořilosti, nikdo mu to neukládal.","c":[["Nechat právní oddělení poslat mu dohodu o mlčenlivosti.","Bez námitek ji podepíše a osobně vrátí. Čtyři ze sedmi prezidentů, kterým sloužil, mu do týdne zavolají, a vám nezavolá ani jeden."],["Popřát mu vše dobré. O knize se nezmiňovat.","Nikdy ji nenapíše. Příteli o léta později prozradí, že jediným důvodem bylo, že ho o to nikdy nikdo nepožádal."],["Udělit mu medaili. Ve Východním sále. Všichni přítomni.","Čtyři sta hostů, včetně tří bývalých prezidentů, na nejsrdečnější akci, jakou ta budova za deset let zažila, a nestojí vás to vůbec nic."],["Nabídnout se jako spoluautor.","Čtyři dny to vážně zvažuje, pak to odmítne jedinou větou, která je zároveň nesmírně laskavá a zcela definitivní."]]},"t2-unleashed":{"t":"Odstraněná brzda","x":"Deborah má jednu stránku a nečte z ní. \"Každá brzda, která na vás v prvním období fungovala, pramenila z jediné věci: měl jste znovu kandidovat.\" Odloží ji. \"Teď nekandidujete. Pane, nikdo v téhle budově si není úplně jistý, co se s prezidentem stane, když tohle zmizí, ani lidé, kteří jsou placení za to, aby to studovali.\"","c":[["Tak přestat předstírat. Všechno, okamžitě.","Čtyři roky pomalu odkládaných nařízení se podepíší během čtrnácti dnů, a systém, po kterém se chce, aby tolik věcí spolkl tak rychle, to prostě nezvládne."],["Stejný program. Rychleji. Bez porad.","Žádný projev, žádná doktrína, žádná tisková zpráva, jen vláda, která potichu přestala žádat o svolení a nikdy to neoznámila."],["Věnovat to věcem, které potřebují osm let.","Čtyři programy příliš velké na jedno období se dokončí za dvě, a ukáže se, že to je jediný poctivý argument, jaký kdy kdo pro druhé období vznesl."],["Oznámit, že budete vládnout, jako by volby pořád existovaly.","Nikdo tomu nevěří, Deborah nejméně ze všech, ale vydrží to zhruba devět měsíců, o osm déle, než na co v budově kdokoli vsadil."]]},"t2-architecture":{"t":"Konstrukce","x":"Sy přinesl čtyřletou složku. \"Začalo to jedním rozsudkem o jednom trestním stíhání. Od té doby jsme ho citovali v téměř třetině našich naléhavých návrhů.\" Otočí ji k vám. \"Pane, už to není štít. Čtyři roky podání na tom vystavěly konstrukci, a ta konstrukce je nosná.\"","c":[["Stavět dál. Citovat to úplně ve všem.","Z rozsudku o jednom stíhání se potichu stane doktrína o všem, jedno nenápadné podání za druhým."],["Přestat to citovat. Argumentovat věcně.","Vyhrajete méně, ale udržíte si víc. Čtyři z výher jsou nenapadnutelné způsobem, jaký nic postaveného na štítu nikdy nebylo."],["Citovat to jen tam, kde bychom jinak prohráli.","Šetřit to na skutečnou potřebu je přesně k tomu, k čemu štít slouží, a je to jediná verze, která přežije vaši vládu."],["Požádat soud, ať konstrukci písemně potvrdí.","Případ přijmou. Nález je nakonec užší, než čtyři roky vašich vlastních podání předpokládaly, a potichu zbourá zhruba polovinu konstrukce."]]},"t2-eighty-seven":{"t":"Osmdesát sedm slov","x":"\"Vytiskl jsem to. Je to osmdesát sedm slov.\" Sy položí na stůl jediný list papíru. \"Omezuje to, aby byl někdo *zvolen* víckrát než dvakrát. Lidé vám pořád tvrdí, že existuje argument pro to být *dosazen*. Pane, ty argumenty jsem četl a styděl bych se je nahlas přednést v místnosti, kde je soudce.\"","c":[["Nechat právníky přesto rozpracovat argument pro dosazení.","Vznikne memorandum, pečlivé, důkladné a nepřesvědčivé. Za devět týdnů unikne na veřejnost a prodá se lépe než kterákoli skutečná politika, kterou jste podepsal."],["Přečíst to nahlas. Veřejně. Všech osmdesát sedm slov.","Trvá to třicet jedna vteřin. Je to nejúčinnější věc, kterou za celý rok uděláte, a vaše hnutí to prožívá jako ztrátu blízkého."],["Nevyjadřovat se k tomu vůbec, žádným směrem.","Nejednoznačnost nic nestojí a udržuje čtyři sta tisíc lidí v naději, což má mnohem větší cenu než kterákoli z obou odpovědí."],["Nechat to zarámovat a pověsit nad pracovní stůl.","Každý návštěvník si to vyfotí. Nikdo nedokáže zjistit, jestli je to závazek, nebo výzva, a vy to opakovaně a s potěšením odmítáte upřesnit."]]},"t2-term-reset":{"t":"Vynulované hodiny","x":"Doktorka Weir má srovnávací případ a vůbec ji netěší ho přednášet. \"Bylo to udělané zcela podle pravidel. Ústavní dodatek, skutečné hlasování, a doložka, že už odsloužená období se nezapočítávají.\" Zvedne oči. \"Pane prezidente, hodiny se nezastavily. Vrátily se na nulu. A nic z toho nebylo protizákonné.\"","c":[["Připravit dodatek. Odsloužená období se nezapočítávají.","Potřebuje ratifikaci třiceti osmi států a nikdy je nezíská. Samotný pokus má pro vás větší cenu, než by kdy měl samotný dodatek, a všichni zúčastnění to vědí."],["Nechat o to požádat čtyři zákonodárné sbory států. Sám do toho nezasahovat.","Vy jste o nic nežádal. Bylo to požádáno. Tenhle rozdíl je nosnou zdí celého podniku, a vydrží zhruba dva roky."],["\"Tohle dělají jiné země.\" A tím to uzavřít.","Odmítnout cizí ústavní model je nejlevnější dostupné vlastenectví, a tentokrát to dokonce myslíte upřímně."],["Navrhnout to, ale s vynulováním pro úplně všechny.","Všeobecná amnestie na omezení funkčních období pro veškeré úřady v zemi. Čtyři sta úřadujících politiků, kteří vás v soukromí nesnášejí, potají doufá, že to projde."]]},"t2-referendum":{"t":"Otázka na hlasovacím lístku","x":"Nadia to namodelovala. \"Jediná celostátní otázka: má se posílit prezidentský úřad. Žádný kandidát, žádná strana, jen jedna otázka.\" Zaváhá. \"V průzkumech je na čtyřiceti osmi procentech a posune se o devět bodů, pokud se v předchozích čtrnácti dnech stal nějaký incident. Pane, chci, aby bylo zaznamenáno, že bych radši to číslo nikdy nespočítala.\"","c":[["Vypsat otázku. Vybrat si těch čtrnáct dní.","Skutečná většina, ve skutečném hlasování, pro natrvalo silnější úřad. Je to nejdemokratičtější věc, jakou kdy uděláte, a zdaleka i nejnebezpečnější."],["Vypsat otázku. Vzít termín, jaký přijde.","Neprojde to o čtyři body v obyčejné úterý. Čistě prohrát se pro úřad ukáže cennější, než by kdy bylo špinavě vyhrát."],["Žádné referendum. Ústava má postup pro dodatky.","Ten postup existuje, je záměrně obtížný, a vy odmítnete ho obcházet. Nadia model smaže a řekne vám to nahlas."],["Vypsat čtyři otázky a nechat lidi kombinovat.","Voliči dvě schválí, jednu zamítnou, a u čtvrté se rozdělí přesně napůl, což vyprodukuje ústavní uspořádání, které nikdo nenavrhl a žádný právník nedokáže rozklíčovat."]]},"t2-perpetuo":{"t":"Bez časového omezení","x":"\"Ten úřad byl skutečný a legální a měl limit, šest měsíců, a pak jste ho vrátili.\" Doktorka Weir popisuje muže mrtvého dva tisíce let. \"On si úřad podržel a limit zrušil. Nic neuzurpoval. Prostě smazal datum vypršení platnosti.\" Odmlčí se. \"Pane prezidente, jeho vlastní senát ho do měsíce zabil, a každý jeden z nich pro něj předtím hlasoval.\"","c":[["Tak si podržet úřad a zrušit limit.","Historická paralela se opakuje tak často, že přestane být varováním a stane se harmonogramem. Čtyři členové vaší vlastní strany přestanou zvedat telefon."],["Zachovat limit. Uvnitř něj úřad zesílit.","Silnější úřad s termínem konce je varianta, která přežije, právě proto, že termín konce je důvod, proč se proti ní nikdo neobtěžuje organizovat."],["Zeptat se jí, co udělal ten druhý.","Vypráví vám o jeho nástupci, který vše okázale vrátil, podržel si přitom všechno podstatné, a zemřel v posteli v pětasedmdesáti, spokojen se sebou samým až do konce."],["Nastavit si limit na šest měsíců a sledovat, kdo si toho všimne.","Vyjde prohlášení zavádějící pro vás šestiměsíční funkční období. Nikdo nepozná, jestli je to vtip, takže to potichu vyprchá, aniž by to kdokoli oplakal."]]},"t2-most-powerful":{"t":"\"Na cestě stát se\"","x":"Vážený historik veřejně prohlásil, že se chystáte stát nejmocnějším prezidentem v americké historii. Doktorka Weir přišla to zkomplikovat. \"Řekl *chystáte se*, pane prezidente. Je to předpověď, je podmíněná, a ta podmínka je zcela závislá na tom, co uděláte v příštích dvanácti měsících.\"","c":[["Splnit tu podmínku. Celou.","Ukáže se, že měl pravdu, a řekne to bez sebemenšího náznaku potěšení. Ta věta se do čtyř let objeví na obálce devíti knih, a ani jedna z nich to nemyslí jako poklonu."],["Neustále tu větu citovat. Nedělat nic, čím byste si ji zasloužil.","Předpověď opakovaná dost často začne působit jako fakt, což přináší většinu výhod bez jakéhokoli ústavního rizika."],["Poukázat na to, že dva váleční prezidenti udělali víc.","Přesné, velkorysé, a jednoznačně nejodzbrojující věta, kterou za celé funkční období řeknete. Čtyři historici s vámi veřejně souhlasí, mírně se přitom mračíce."],["Požádat, ať vás formálně změří proti celému seznamu.","Vznikne oficiální žebříček. Skončíte jedenáctý, což neuspokojí nikoho, a o metodice se bude přít celé desetiletí."]]},"t2-nixon":{"t":"Daleko za hranicí","x":"Kaylee má ten článek. \"Srovnání není s vaším prvním obdobím. Je s vládou, která razila termín 'imperiální prezidentství', a verdikt zní, že jste ji daleko překonal.\" Odloží ho. \"Pane, ten prezident tehdy odstoupil, a autor moc dobře ví, že to víme taky.\"","c":[["Přijmout to jako kompliment. Říct, že byl slabý.","Příznivé srovnání sebe sama s mužem, který raději odstoupil, než aby ho odvolali, je věta, kterou čtyři historici dají do prvního odstavce úplně všeho, co o vás kdy napíšou."],["\"On porušil zákon. Já ne.\" Nechat to tak.","Obhajitelná pozice, přesně dokud někdo nepředloží seznam, a sestavovat seznamy je přesně to, čím se celý novinářský sbor živí."],["Nic neříkat. Je to srovnání, ne obvinění.","Článek vydrží na titulní straně jeden den. Jakákoli vaše reakce by ho udržela celý týden."],["Pozvat autora dovnitř a provést ho celou budovou.","Přijme, stráví v budově devět hodin, a napíše něco podstatně jemnějšího a zhruba čtyřikrát zničujícího."]]},"t2-still-in-place":{"t":"Pořád na svém místě","x":"Doktorka Weir přinesla větu, která nejvíc dráždí vaše kritiky. \"'Mnoho klíčových prvků systému je stále na svém místě. Soudy proti němu rozhodují, a jeho administrativa se těmto rozhodnutím občas podřídí.'\" Zvedne oči. \"Pane prezidente, tohle napsali lidé, kteří jsou znepokojení. Je to nejsilnější věc, jakou kdo řekl na vaši obranu, a přitom to není obhajoba vůbec žádná.\"","c":[["Tak zjistit, které klíčové prvky nejsou nosné.","Jsou čtyři. Tři z nich za osmnáct měsíců otestujete, a čtvrtý je nakonec ten, který vás zastaví, a nikdo nehádal, že to bude zrovna on."],["Neustále tu větu citovat jako ospravedlnění.","Citovat vlastní přiznání svých kritiků je nejstarší trik v politice, a funguje přesně na lidi, kteří si stejně nikdy nedělali starosti."],["Nechat klíčové prvky být. Vystačit si s obdobím, které máte.","Vládnete tvrdě uvnitř systému, který odmítáte rozbít. Je to nejméně uspokojivý výsledek ze všech nabízených a jediný, který za padesát let ještě bude stát."],["Požádat ji, ať ty klíčové prvky sepíše, abyste je měl.","Odmítne, rovnou, bez jakéhokoli zjemnění. Je to teprve podruhé za pět let, co vám řekla ne, a ani jednou to nevysvětlila."]]},"t2-still-free":{"t":"Osmdesát jedna ze sta","x":"Muriel má výsledné skóre. \"Osmdesát jedna ze sta, pokles z osmdesáti čtyř. O dvanáct bodů níž, než kde jsme byli před dvaceti lety.\" Otočí stránku. \"Pane, pořád jsme v kategorii 'svobodný'. To je dobrá zpráva, a je to zároveň jediná zpráva, protože ta kategorie má dno, a my se k němu blížíme naprosto měřitelným tempem.\"","c":[["Ignorovat trend. Zveřejnit kategorii.","\"Pořád svobodní\" je heslo dobré přesně na jeden mediální cyklus. Číslo z příštího roku dorazí podle plánu a heslo se potichu samo odloží."],["Napravit tři ukazatele, ve kterých jsme nejhorší.","Nezávislost soudnictví, kapacita dohledu, přístup pro tisk. Zabere to čtrnáct měsíců, stojí vás to dvě politiky, a koupí to zpátky čtyři body skóre."],["Zpochybnit index a financovat konkurenční.","Váš vlastní index hodnotí zemi na devadesát čtyři body. Schvalně ho citují čtyři vlády, jejichž citaci byste si radši odpustil, a doslova nikdo jiný."],["Zeptat se, jaké skóre by nás srazilo do nižší kategorie.","Odpoví podrobně, protože metodiku zveřejňují jako dospělí lidé. To číslo je napsané na kartičce v šuplíku, a o jeho existenci ví čtyři lidé."]]},"t2-too-reductive":{"t":"\"Příliš zjednodušující\"","x":"Doktorka Weir přinesla odmítnutí. \"Napsala knihu o silných vůdcích, řadí vás pevně do té linie, a odmítá o vás použít slovo na F. Nazývá to označení příliš zjednodušující.\" Odloží knihu. \"Pane prezidente, to není obhajoba. Říká tím, že by vás to slovo pustilo příliš snadno, protože by se lidé přeli o slovo místo o to, co jste skutečně udělal.\"","c":[["Neustále to slovo používat. \"Dokonce i oni říkají, že nejsem.\"","Funguje to přesně, jak předpověděla: devět měsíců hádek o slovníku a žádná o skutcích, což bylo přesně to riziko, na které upozorňovala."],["Nic neříkat. Netýkat se toho.","Odmítnutí zůstává nedotčené, nikým si ho nikdo nepřivlastní, potichu koná přesně tu práci, jakou zamýšlela. Citováno ve čtyřech stech článcích, a ani jednou jako omluva."],["Pozvat ji, ať to podrobně a oficiálně vysvětlí.","Devadesát minut vysvětluje, jaké slovo by naopak sedělo. Je to nejzničující rozhovor celého vašeho prezidentství, a osobně jste si ho objednal."],["Zeptat se jí, jaké slovo by použila ona.","Dá vám tři, ve vzestupném pořadí přesnosti. Všechna tři si budete pamatovat do konce života a ani jedno z nich nikdy nevyslovíte nahlas."]]},"t2-lawsuit-count":{"t":"Sedm set padesát tři","x":"Sy má přehled. \"Sedm set padesát tři případů. Máme osmnáct odkladů od nejvyššího soudu a u nižších soudů zhruba stejně proher jako výher.\" Zavře složku. \"Pane, poctivé shrnutí zní, že je to smíšené, což neprodává ani jedna strana, a přesně to skutečná bilance říká.\"","c":[["Tvrdit, že vyhráváme všechno. Nikdo to nepočítá.","Někdo to počítá. Přehled je veřejný, aktualizuje se týdně, a rozdíl mezi tvrzením a číslem se stane vlastním pravidelným tématem."],["Zveřejnit vlastní bilanci výher a proher. Přesně.","Opravdu smíšená bilance, zveřejněná vámi samotným, zabije celou debatu na místě. Čtyři média to otisknou, a ani jedno nenajde háček."],["Přestat se odvolávat u případů, které stejně prohrajeme.","Vést spory jen tam, kde je šance vyhrát, zvedne úspěšnost a sníží zviditelnění, což je přesně to, jak zvenčí vypadá kompetentní právní tým."],["Podat protižalobu proti všem sedmi stům padesáti třem.","Jen soudní poplatky vyjdou na 190 000 dolarů. Čtyři z protižalob se náhodou ukážou být proti úřadům vaší vlastní vlády."]]},"t2-shield":{"t":"Štít","x":"\"Milost udělovaná v prvním období nikdy nebyla o minulosti.\" Sy je neobvykle přímočarý. \"Každý, kdo teď zvažuje, že pro vás něco udělá, už dopředu ví, co se stane potom. Je to nejlevnější program loajality, jaký kdy kdo vymyslel, a pane, nemusel jste kvůli tomu, aby fungoval, vypustit jediné slovo.\"","c":[["Říct to nahlas. Slib udělat výslovný.","Výslovný předem daný slib milosti je z právního hlediska úplně jiné zvíře než pouhý vzorec chování, a čtyři žalobci to tak začnou brát ještě před obědem."],["Nic neříkat. Vzorec mluví sám za sebe.","Nevyslovené je to nežalovatelné a stejně účinné. Devět lidí jedná na základě ujištění, které jim nikdo nikdy skutečně nedal."],["Veřejně prohlásit, že by s tím nikdo neměl počítat.","Čtyři lidé, kteří se chystali udělat něco krajně nerozumného, to potichu přestanou dělat. Jejich jména ani to, oč šlo, se nikdy nedozvíte."],["Vydat milosti předem, nevyplněné, bez data.","Nedatovaná milost pro neurčené budoucí trestné činy se do roka ocitne u soudu, a padne hned v první větě prvního rozsudku."]]},"t2-old-hands":{"t":"Už se nikdo neptá","x":"Deborah si něčeho všimla a čekala čtrnáct dní, než to nadhodí. \"Tento měsíc se staly čtyři věci, které jste nenařídil. Nikdo se neptal, jestli je to povolené. Staly se, protože si někdo dole odvodil, co byste chtěl.\" Zarazí se. \"Pane, přesně o tomhle jsou dějepisné knihy. Není to o tom, co uděláte vy. Je to o tom, co lidé udělají, aniž by jim to kdy kdo nařídil.\"","c":[["Podporovat to. Pochválit všechny čtyři jmenovitě.","Pochvala je přesně to potvrzení, na které čekalo dalších dvacet lidí. Funguje to lépe než jakýkoli příkaz a nedá se to jako příkaz zdokumentovat."],["Nic neříkat. Nechat to plynout.","Mlčení se čte jako souhlas a nic vás nestojí. Tempo se během následujícího čtvrtletí zhruba zdvojnásobí, aniž by padl jediný příkaz."],["Sdělit budově otevřeně, že o tohle nikdo nežádal.","Dvě ze čtyř věcí jsou do týdne zvráceny. Vyslovit to nahlas se ukáže být jediná věc, která to kdy dokáže zastavit, a stojí vás to celý mechanismus."],["Zeptat se, kterou ze čtyř věcí podle nich chtěl jste nejméně.","Přijde memorandum řadící vaše domnělá přání podle míry jistoty. Je nepříjemně přesné a do hodiny se utají."]]},"t2-old-enemy":{"t":"Ta, co pořád je tady","x":"Cordelia Ruiz-Bloom přežila čtyři samostatné pokusy ukončit její kariéru a požádala o schůzku. Přijde sama, posadí se a řekne: \"Vaše vláda mě vyšetřuje už šest let. Nikdy z ničeho nebyla obviněna. Nejsem tu, abych si stěžovala, pane prezidente. Jsem tu, protože bych ráda věděla, jestli to teď skončí, nebo jestli to poběží ještě čtyři další roky.\"","c":[["\"Pokračuje to.\" Říct jí to do očí.","Zapíše si to v autě, opatří datem, a dá kopie třem lidem. Je to citováno v jejích pamětech, na slyšení, a nakonec i v soudním rozsudku."],["\"Skončilo to.\" Uzavřít všechny spisy ještě to odpoledne.","Devět měsíců vám nevěří. Když nakonec uvěří, řekne to veřejně a bez vyzvání, a má to větší cenu, než jakoukoli reklamní kampaň, kterou byste si mohl koupit."],["Neříct vůbec nic. Nechat ji odejít v nejistotě.","Nejistota je levnější než kterákoli z odpovědí a odvede většinu práce té horší, což je přesně důvod, proč zvolíte tuhle možnost."],["Nabídnout jí místo.","Odmítne to čtyřmi slovy a pak, z důvodů, které si ani jeden z vás neumí vysvětlit, zůstane ještě hodinu a povídá si s vámi o svém otci."]]},"t2-heir":{"t":"Jméno na druhé kartě","x":"Chet má dvě kartičky. \"Tohle je hnutí bez vás: padesát jedna. Tohle je já, kdybych ho vedl: třicet tři.\" Položí je vedle sebe. \"Pane, ten rozdíl není otázkou osobnosti. Osmnáct bodů toho hnutí je jeden jediný člověk, a člověka nikomu nepředáte. Přestal jsem předstírat opak.\"","c":[["Tak to nikdo nezdědí. Skončí to se mnou.","Hnutí, které vás nemůže přežít, vás také nemůže nahradit, a obojí se stane pravdou téhož dne, dne, který si nevyberete sám."],["Podpořit Cheta hned a dva roky pro něj vést kampaň.","Osm z osmnácti bodů dožene za dvaadvacet měsíců. Je to nejtěžší politická práce, jakou kdo za vaší vlády odvede, a většinu z ní odvedete vy sám."],["Vybudovat místo toho stroj. Pravidla, pokladnu, nástupnictví.","Instituce místo dědice. Vyhraje tři z příštích pěti voleb a přestane zmiňovat vaše jméno zhruba kolem druhých z nich."],["Podpořit čtyři lidi zároveň.","Všichni čtyři jedenáct měsíců v kuse vedou kampaň jako pomazaný nástupce a citují přitom stejnou větu. Následné primárky jsou nejzábavnější za celé století."]]},"t2-final-court":{"t":"Poslední jmenování","x":"Předsedkyně Nejvyššího soudu Stone přišla kvůli uvolněnému místu a zůstane kvůli něčemu jinému. \"Jmenoval jste pětinu federálních soudců. Průměrný věk čtyřicet šest let.\" Nic nezjemňuje. \"Pane prezidente, každé nařízení, které jste podepsal, lze zrušit za jediné odpoledne. Tohle se zrušit nedá vůbec. Tohle je prezidentský úřad. Všechno ostatní je jen počasí.\"","c":[["Jmenovat nejmladší kvalifikované jméno ze seznamu.","Devětatřicet let, potvrzen o dva hlasy, a u soudu zhruba do roku 2065. Nic dalšího, co jste udělal, do té doby nebude ještě fungovat."],["Jmenovat nejlepšího právníka ze seznamu, ať je to kdokoli.","V prvním roce proti vám rozhodne dvakrát, a schvalně ji citují další čtyři desetiletí. Stone vám jednou potichu řekne, že to bylo správné rozhodnutí."],["Nechat místo prázdné. Ať ho obsadí příští prezident.","Dobrovolně ponechané prázdné místo je neslýchané, skoro každý to čte jako slabost, a čtyři lidé to čtou jako jednoznačně nejústavnější čin celého vašeho období."],["Jmenovat sám sebe.","Nic v samotném textu ústavy to technicky nezakazuje, což čtyři komentátoři zaznamenávají s rostoucím znepokojením, dokud se nominace potichu nestáhne."]]},"t2-net-worth":{"t":"Zhruba dvojnásobek","x":"Miriam má osmileté srovnání a rozložila ho na stůl. \"Zhruba se to zdvojnásobilo, pane, a pak to vzrostlo ještě víc. Všechno přiznané. Všechno na formulářích, které jste osobně podepsal.\" Narovná stránky. \"To je obhajoba, a je to skutečná obhajoba, a je to zároveň přesně to, díky čemu to všichni vědí.\"","c":[["Tvrdit, že úřad s tím neměl nic společného.","Jediná největší položka je token, který před vaší inaugurací neexistoval. Čtyři novináři to zjistí ještě před obědem, a jeden z nich přinese graf."],["\"Trh šel nahoru. Vydělali všichni.\"","Postavena vedle skutečného čísla se ta věta stane nejcitovanější větou celých vašich osmi let v úřadu. Myslel jste to zcela upřímně, a přesně to je to, co zasáhne nejvíc."],["Zveřejnit celé osmileté srovnání sám.","Dvě hodiny otázek, všechny zodpovězeny, najednou. Je to nejhorší odpoledne celého vašeho druhého období, a přesně to odpoledne celou kauzu i uzavře."],["Vložit celý nárůst do nadace vaší knihovny.","Největší charitativní převod v dějinách americké politiky, a míří do entity, kterou osobně kontrolujete, detail, který si čtyři novináři všimnou do hodiny."]]},"t2-quiet-year":{"t":"Rok, kdy se nic nestalo","x":"Nadia má zvláštní zjištění. \"Jedenáct měsíců žádná krize. Žádné nasazení, žádné nařízení, kvůli kterému by nás někdo žaloval, žádná pohroma.\" Zamračí se nad vlastním listem papíru. \"Podpora vzrostla o devět bodů, pane. A slovo, které lidé pořád opakují ve skupinových rozhovorech, je, že to zase působí *normálně*, což je poprvé za osm let tohoto výzkumu, co se tohle slovo vůbec objevilo.\"","c":[["Ukončit ten klid. Devět bodů není cíl.","Trvá to čtyři dny prošustrovat jedenáct měsíců nastřádané přízně. Nadia si ten list papíru schová a ukazuje ho lidem do konce kariéry."],["Zachovat klid. Vládnout. Nepodepisovat nic dramatického.","Klidný, kompetentní, zcela nenápadný rok. Je to nejlépe hodnocené období obou vašich funkčních období, a vaše hnutí to přesně a případně nazve zradou."],["Navenek zachovat klid. V zákulisí pokračovat dál.","Nic se neoznámí, všechno pokračuje. Je to nejúčinnější čtvrtletí celého vašeho prezidentství, a není o něm doslova co hlásit."],["Vyhlásit výjimečný stav kvůli absenci výjimečných stavů.","Prohlášení cituje právě těch jedenáct klidných měsíců jako důkaz nebezpečné sebeuspokojenosti. Vyjde to, a Nadiina křivka podpory klesne za čtrnáct dní o devět bodů."]]},"t2-first-draft":{"t":"První seriózní historie","x":"Doktorka Weir přinesla vlastní rukopis, aniž by o to kdo žádal. \"Osm let. Mám závěr a nebudu vám ho zjemňovat.\" Podá vám ho. \"Nejrozsáhlejší uplatnění jednostranné výkonné moci v moderní době míru, opravdu znepokojivé, rozkládající kvalitu demokracie, a stále fungující uvnitř systému, který ho brzdil. Všechny čtyři části té věty, pane prezidente. Ne jenom tři.\"","c":[["Nechat právníky prověřit, jestli se to dá zastavit.","Nedá. Pokus se objeví ve druhém vydání jako čtyřstránková příloha a stane se jednoznačně nejcitovanější částí celé knihy."],["Napsat předmluvu zpochybňující čtvrtou část.","Tvrdit tiskem, že vás systém ve skutečnosti nebrzdil, je přesně ta část, které jste se měl úplně vyhnout, a přesně to říká každý recenzent."],["Napsat předmluvu. Uznat čtvrtou část.","Prezident tiskem přiznává, že brzdy fungovaly. Je to jednoznačně nejcennější odstavec, jaký byl o vás kdy napsán, a napsal jste ho vy sám."],["Požádat, jestli byste mohl sám napsat závěrečnou kapitolu.","Souhlasí, pod podmínkou, že vyjde needitovaná a jasně podepsaná. Má čtyři strany a je zdaleka nejhůř hodnocenou částí celé knihy."]]},"t2-last-day":{"t":"Poslední ráno","x":"Alvin má program na ráno, je to jedna stránka. \"Káva v sedm. Auto v jedenáct. Druhá rodina dorazí v jedenáct patnáct.\" Je naprosto klidný, tohle už zažil sedmkrát. \"Pane, připravil jsem všechno, oč jste žádal. Přejete si, abych ještě něco udělal?\"","c":[["\"Zrušte tu jedenáct patnáct.\"","Alvin řekne \"Ano, pane\" a nepohne se. Po chvíli to zopakuje, stále se nehne, a přesně tak zjistíte, kde přesně byla ta hranice."],["\"Nic. Děkuji, Alvine.\"","Odjedete v jedenáct. Je to jednoznačně nejobyčejnější věc, co se za celé desetiletí stane, a je to důvod, proč tu ještě zbyla země, ve které lze být obyčejný."],["Nechat v psacím stole dopis pro toho, kdo přijde po vás.","Čtyři odstavce, ručně psané, zcela bez zloby. Nikdy nezveřejněný. Adresát se o něm jednou zmíní o dvacet let později a odmítne říct víc."],["Zeptat se ho, kdo ze sedmi to zvládl nejlíp.","Dlouho vážně přemýšlí a pak odpoví upřímně. Nejste to vy. Řekne to laskavě, a vy víte, že je lepší nežádat vysvětlení."]]},"f-entry-ban":{"t":"Seznam","x":"Duane má nařízení zakazující vstup ze šesti jmenovitě uvedených zemí, účinné okamžikem podpisu. Žádné oznámení leteckým společnostem, žádné letištím. \"Pane, právě teď jsou lidé nad Atlantikem, kteří ještě nevědí, že mají zákaz vstupu.\"","c":[["Podepsat. Účinné dřív, než uschne inkoust.","Čtyři tisíce lidí stráví noc na podlaze terminálu, včetně tlumočníka, který za vaši armádu prolil krev v cizí poušti. Právníci dorazí do hodiny s tiskárnami běžícími na plné obrátky. Do devíti dnů to soud pozastaví."],["Podepsat s třicetidenní lhůtou na zavedení.","Stejná politika, nula fotografií. Přezkum přežije, protože nikdo nestihl vyfotit batole spící na pásu na zavazadla."],["Přepsat to na základě skutečných bezpečnostních hodnocení.","Zpravodajská komunita vrátí seznam dvou zemí. Obhajitelné, účinné, a k skandování k ničemu."],["Zakázat vstup ze země, kterou nikdo nenajde na mapě.","Populace jedenáct tisíc, nula přímých letů. Čtyři televizní diskuzní pořady o tom debatují celý týden a jejich velvyslanec se na chvíli stane nejslavnějším žijícím mužem."]]},"f-separation":{"t":"Politika","x":"\"Stíhat každého dospělého, kdo hranici překročí, znamená, že děti s ním nemohou zůstat. To není vedlejší účinek té politiky, pane. To je ta politika. Musím to nahlas říct přesně jednou.\"","c":[["Udělat to. Odstrašující účinek funguje jen, pokud se to všichni dozví.","Dva tisíce osm set dětí. Nikdo nevytvořil evidenční systém, protože nikdo neplánoval je vracet. Čtyři sta z nich se v roce 2031 pořád nepodařilo spojit s rodinou."],["Stíhat dospělé. V zajištění nechat rodiny pohromadě.","Vyžaduje to zařízení pro rodiny, která zatím neexistují, takže se z toho potichu stane stavební projekt. Pomalejší, dražší, a o sádrokartonu nikdo netočí dokument."],["Zastavit to dřív, než to začne.","Bo zavře složku s viditelnou úlevou. Je to jediný případ za čtyři roky, kdy ho to uvidíte udělat."],["Oznámit to, a pak trvat na tom, že jste to nikdy neoznámil.","Memorandum nese vaše iniciály. Před kamerou to popíšete jako zákon, který schválila opozice. Obě verze kolují čtyři roky, ani jedna nevítězí."]]},"f-countries":{"t":"Soukromá poznámka","x":"Na uzavřené poradě jste popsal několik zemí výrazy, které Deborah nezopakuje, a zeptal se, ne řečnicky, proč nepřichází víc lidí odněkud, kde je zima. Dva z jedenácti lidí v místnosti už zavolali novináři.","c":[["Popřít to slovo. Ne postoj.","Popření dost přesné na to, aby bylo technicky pravdivé, a dost mlhavé na to, aby bylo k ničemu. Jedenáct velvyslanců žádá o vysvětlení a dostane čtyři různé odpovědi, žádná z nich se neshoduje."],["Přiznat to. \"Řekl jsem to a myslel jsem to vážně.\"","Čtyři africké země si stáhnou velvyslance na konzultace. Vaše podpora u vlastních voličů vzroste o dva body, což byl vždycky ten skutečný ukazatel."],["Omluvit se. Jmenovitě. Daným zemím.","Konkrétní omluva, bez vytáček, bez \"pokud se někdo cítil dotčen\". Je to tak neslýchané, že to vede zprávy v devíti zemích, a vaši voliči berou tu nahrávku jako záznam z únosu."],["Tvrdit, že jste probíral průměrné zimní teploty.","Bílý dům skutečně vydá klimatickou tabulku. Je to nejsurrealističtější dokument celé vlády a nepřesvědčí naprosto nikoho."]]},"f-director":{"t":"Ředitel","x":"Ředitel úřadu, který vede vyšetřování dotýkající se vás, má desetileté funkční období, právě proto, aby žádný prezident nemohl udělat to, co se chystáte udělat. Deborah: \"Můžete ho odvolat. Nic vám v tom nebrání. Existuje jen to, co potom řeknete, a v tom jste špatný.\"","c":[["Odvolat ho. Pak vysvětlit proč v televizi.","Skutečný důvod prozradíte v rozhovoru, protože se prostě fyzicky neudržíte. O osm dní později je jmenován zvláštní žalobce, a rozhovor se stane důkazem číslo jedna."],["Odvolat ho a držet se oficiální záminky.","Záminka vydrží jedenáct týdnů. Jeho dobové poznámky vydrží podstatně déle, protože je začal psát hned v noci po vaší první společné večeři."],["Nechat ho na místě. Nechat vyšetřování doběhnout.","Skončí za devatenáct měsíců bez obvinění proti vám. Nikdo si to nepamatuje, protože se nic nestalo, což byl celý smysl toho ho nechat doběhnout."],["Povýšit ho někam bez telefonu.","Ředitel federálních zařízení, Antarktický program. Přijme to, odslouží jedenáct měsíců, a vydá překvapivě dobře hodnocené paměti o tučňácích a institucionální integritě."]]},"f-witch-hunt":{"t":"Vyšetřování","x":"Byl jmenován zvláštní žalobce. Sy poznamenává, že nejrychlejší cesta, jak vyšetřování právně přežít, je neříkat nic, a nejrychlejší cesta, jak ho politicky přežít, je říct něco, zhruba devět set krát.","c":[["Denně na to útočit. Stejná dvě slova. Devět set krát.","Než zpráva vyjde, 44 procent země už má hotovo, že je nelegitimní. Zpráva má 448 stran. Ta dvě slova zůstávají dvěma slovy."],["Plně spolupracovat a veřejně mlčet.","Skončí to potichu, závěry jsou smíšené, a nikdo si je nepřečte. Mlčení je jednoznačně nejúčinnější právní strategie, jaká existuje, a zároveň jednoznačně nejnesnesitelnější politická."],["Spolupracovat, ale každé předvolání dva roky soudně napadat.","Nikdy nic přímo neodmítnete. Prostě nikdy nedokončíte plnění ničeho, a kalendář udělá to, co by jinak udělalo odmítnutí."],["Najmout žalobce jako konzultanta. Zjistit, jestli je to dovolené.","Není to dovolené. Čtyři etické komise to písemně potvrdí do jednoho dne, a samotný pokus je postoupen dál a stane se bodem devět něčeho."]]},"f-the-call":{"t":"Laskavost","x":"Jste na telefonu s prezidentem, jehož země potřebuje balíček pomoci, který leží na vašem stole. Muriel poslouchá. Právě jste použil frázi \"i když bych chtěl, abyste nám prokázal laskavost\".","c":[["Požádat o vyšetřování. Jmenovitě.","Na lince je jedenáct lidí. Jeden z nich ještě to odpoledne podá stížnost správným kanálem. Všechno, co se za dalších čtrnáct měsíců stane, se stane kvůli tomu jednomu člověku."],["Naznačit. Jméno nikdy nevyslovit.","Náznak nezanechá žádný problém v přepisu a má naprosto stejný účinek na vládu, která potřebuje 400 milionů dolarů. Tohle je verze, která funguje."],["Uvolnit pomoc. O nic nežádat.","Pomoc odejde podle plánu, využije se, a lidé, kteří by jinak zemřeli, nezemřou. Není tu žádný příběh, což je svým způsobem zázrak."],["Požádat ho, ať vyšetří někoho, kdo neexistuje.","Jeho žalobci stráví čtyři měsíce honbou za mužem bez rodného listu. Výsledná zpráva, sepsaná v ukrajinštině, je potichu jedním z nejvtipnějších dokumentů v dějinách diplomacie."]]},"f-impeach-one":{"t":"Žalobní bod","x":"Sněmovna odhlasovala. Hal má senátní matematiku: potřebujete udržet 34 z 53, a máte 53 z 53, protože každý z nich se podíval na vlastní voliče v primárkách a spočítal si úplně to samé.","c":[["Prosadit stranicky jednotné zproštění viny. Toho, kdo se odchýlí, udělat za příklad.","Jeden senátor hlasuje pro vinu. Jeho vlastní stranická organizace ho do týdne odsoudí a on se už znovu neuchází o zvolení. Všichni ostatní teď viděli ceník."],["Postavit skutečnou obhajobu na věcných argumentech.","Vaši právníci jsou dobří a případ proti vám je skutečně napadnutelný. Jste zproštěn viny na základě argumentů, ne matematiky, což má mnohem větší cenu, a nikdo ten rozdíl nezaznamená."],["Odmítnout se účastnit. Prohlásit celou věc za neplatnou.","Jste stejně zproštěn viny. Odmítnutí postavit obhajobu dokazuje, že jste ji nikdy nepotřeboval, což je fakt spíš o senátu než o vás."],["Osobně se dostavit a sledovat to z galerie.","Žádný prezident ještě nikdy naživo nesledoval vlastní proces v senátu z místnosti. Čtyři senátoři se nedokážou přinutit zvednout oči. Funguje to naprosto skvěle a zůstává to hluboce podivné."]]},"f-find-votes":{"t":"To číslo","x":"Na lince je státní úředník z vaší vlastní strany. Sy je v místnosti a přestal psát. Chystáte se říct konkrétní počet hlasů a požádat ho, aby je našel.","c":[["Říct to číslo. Požádat ho, ať je najde.","Nahrává hovor, protože mu právníci řekli, ať nahrává úplně každý hovor. O čtyři dny později to celých jedenáct minut běží na všech stanicích."],["Požádat ho, ať se \"podívá znovu\". Neříct žádné číslo.","Podívá se znovu. Najde stejný výsledek. Neexistuje žádná nahrávka, která by cokoli znamenala, což se ukáže být jediný skutečný rozdíl mezi touhle a tou druhou variantou."],["Pogratulovat mu k čistému sčítání.","Je tak zaskočený, že poděkuje dvakrát. Jakmile hovor unikne na veřejnost, vaši voliči ho vezmou jako jednoznačně největší zradu celé vlády."],["Požádat ho, ať najde jeden hlas. Jenom jeden. Jako gesto.","Trpělivě vysvětlí, že jeden podvodný hlas je přesně stejně nezákonný jako čtyři tisíce. Řeknete, že rozumíte. Ani jeden z vás tomu druhému nevěří."]]},"f-certify":{"t":"Certifikace","x":"Chet předsedá sčítání hlasů. Jeho role je podle každého seriózního výkladu čistě ceremoniální. Dostal čtyři memoranda tvrdící opak, drží je všechna čtyři v ruce, a nepoložil je.","c":[["Nařídit mu, ať odmítne kandidátní listiny. Veřejně, aby to nemohl potichu odmítnout.","Neudělá to. Napíše to do dvoustránkového dopisu zveřejněného pár minut před zasedáním, jednoznačně nejzávažnějšího dokumentu celého vašeho prezidentství, a vy jste v něm nenapsal ani slovo."],["Zeptat se ho v soukromí. Přijmout, ať odpoví cokoli.","Jemně odmítne. Nikdy se to nedostane na veřejnost. Ve zbývajících čtrnácti dnech k sobě zůstanete zdvořilí a pak spolu už nikdy nepromluvíte."],["Říct mu, že je to čistě ceremoniální, ať to prostě odbaví.","Sčítání proběhne za čtyři hodiny. Nic se nestane. Je to nejnudnější odpoledne v dějinách té budovy, a se zpětným pohledem celá podstata celé věci."],["Předsedat tomu osobně. Jde to vůbec?","Nejde. Čtyři různé úřady vysvětlí proč. Požádáte každý z nich, ať to ověří znovu, a každý to udělá, a odpověď se odmítá změnit."]]},"f-hostages":{"t":"Slovo pro ně","x":"Brayden chce, abyste lidem odsouzeným za vpád do budovy říkal \"zadržení\". Ne \"obžalovaní\". Ne \"odsouzenci\". Otestoval to na skupinách a číslo se posunulo o jedenáct bodů.","c":[["Použít to. V každém projevu. Zahajovat tím každé shromáždění.","Do roka to slovo používá třetina země, aniž by si všimla, že ho vůbec převzala. Jazyk je nejlevnější infrastruktura, jaká existuje, a vy jste právě vylil kilometry betonu."],["Použít to jen u těch nenásilných.","Rozdíl, který je opravdu obhajitelný a který se, na žádné straně, nikdo neobtěžuje udržet déle než čtyři týdny."],["Nazvat je tak, jak je nazvala porota.","Čtyři slova. Vaši voliči to prožívají jako zradu, a Brayden si ten večer aktualizuje životopis."],["Vymyslet slovo, které neznamená vůbec nic.","\"Odročení.\" Bezvýznamné, nevyvratitelné, nemá se s čím přít. Dva deníky ho zprvu převezmou v uvozovkách, a do třetího roku bez nich."]]},"f-it-will-go":{"t":"Křivka","x":"Doktorka Pike má model a není to ani zdaleka příznivé. \"Pane, počet případů se zdvojnásobuje každých šest dní. Neexistuje žádná varianta příštích osmi týdnů, ve které to zůstane malé.\"","c":[["\"Zmizí to. Jako zázrakem.\"","Nezmizí to. Ta věta se vám pak dva roky pouští znovu a znovu, s běžícím počtem obětí na obrazovce. Pike je z pódia venku už do března."],["Říct zemi pravdu a smířit se s ránou.","Podpora klesne za čtrnáct dní o devět bodů a za šest týdnů se zotaví výš než předtím, protože jste měl pravdu a každý si to mohl ověřit."],["Říct, že je to vážné, a pak Pike na každém brífinku podkopávat.","Dvě zprávy z jednoho pódia, denně, celý rok. Ochota dodržovat opatření se do jedenácti dnů rozdělí podle stranické příslušnosti a už se nikdy nesejde zpátky."],["Dát model na obří graf a naživo se s ním přít.","Čtyřicet minut, kdy se prezident hádá s exponenciální křivkou na stojanu. Křivka vyhraje. Skončí na obálce čtyř učebnic."]]},"f-the-cure":{"t":"Lék","x":"Lék s nadějnými historkami a nulovými daty z klinických studií vám zmínili tři lidé, žádný z nich lékař. Admirál Prine: \"Možná to funguje. Nevíme to. To je celá věta, za kterou si troufám stát.\"","c":[["Propagovat to z pódia. Opakovaně.","Zásoby zmizí za devět dní, včetně u lidí, kteří to berou na úplně jinou nemoc. Klinické studie za čtyři měsíce oznámí: nefunguje to."],["Financovat rychlou, obrovskou, řádně vedenou studii.","Za čtyři měsíce vydá definitivní výsledek, a odpověď zní ne. Znát tu odpověď se ukáže cennější, než samotná odpověď."],["Zmínit to jednou, s výhradou, a jít dál.","Výhrada z pódia není výhrada. Prodeje vzrostou o 400 procent na síle jediné podmiňovací věty."],["Brát to sám, před kamerou, denně.","Prine odmítne to předepsat a je obejit lékařem, jehož jméno nikdo nezná. Vám nic není. Čtyři sta tisíc lidí vás napodobí, a měřitelnému počtu z nich něco je."]]},"f-testing":{"t":"Číslo z testování","x":"Počet případů je funkcí objemu testování. Pike to vysvětluje dvakrát. Nahlas jste poznamenal, že kdyby se testovalo méně, bylo by méně případů.","c":[["Říct to na shromáždění. Je to technicky pravda.","Je to technicky pravda stejně jako to, že nevážit se je technicky dieta. Ten záznam se pouští čtyři roky a Pike se na to od té doby ptají na každém slyšení."],["Zdvojnásobit kapacitu testování a zveřejnit úplně všechno.","Počet případů zdánlivě vyskočí, protože je konečně počítáte. Vysvětlíte to jasně, čtyřikrát, a zhruba polovina země to pochopí."],["Pokračovat v testování. Změnit způsob hlášení případů.","Definice případu se pozmění v technickém věstníku. Číslo přes noc klesne o 22 procent, aniž by se zrušil jediný test."],["Testovat jen lidi, o kterých je jasné, že budou v pořádku.","Někdo skutečně sepíše kritéria, než čtyři různí úředníci pochopí, oč jde, a jeden po druhém to odmítnou."]]},"f-accord":{"t":"Dohoda","x":"Muriel má připravený nástroj k odstoupení. \"Nezávazné cíle, žádná vymahatelnost, žádný postih za jejich nesplnění. Odstoupení nás právně nestojí nic a diplomaticky úplně všechno, což je neobvyklý poměr.\"","c":[["Odstoupit. Oznámit to v Růžové zahradě.","Přidáte se ke dvěma dalším zemím mimo dohodu. Jedenáct amerických států oznámí, že cílů dosáhne stejně, což je buď federalismus, nebo pohlavek, podle toho, koho se zeptáte."],["Zůstat v dohodě a prostě cíle nesplnit.","Žádné vystoupení, žádný titulek, žádné plnění. Je to nejcyničtější varianta na stole, a čtyři další signatáři to už potichu dělají taky."],["Zůstat a vyjednat cíle znovu, směrem dolů.","Získáte horší dohodu se svým jménem pod ní, což je lepší než lepší dohoda s cizím jménem."],["Odstoupit, a hned příští týden požádat o opětovný vstup.","Návrat trvá podle smlouvy 30 dní. Po 23 z nich jsou Spojené státy formálně mimo dohodu, o jejíž opětovný vstup už samy požádaly."]]},"f-rollback":{"t":"Devadesát osm nařízení","x":"Cassandra Doyle má seznam devadesáti osmi nařízení zralých ke zrušení. \"Každé samo o sobě je technická novela, o které nikdo nenapíše. Dohromady je to největší demontáž ochrany životního prostředí za padesát let.\"","c":[["Všech devadesát osm. Jedno týdně, potichu.","Devadesát osm oznámení ve federálním věstníku za dva roky. O čtyřech se napíše. Kumulativní efekt je viditelný z oběžné dráhy a ani jednou se nedostane na titulní stranu."],["Těch devět, které skutečně stojí pracovní místa. Hlasitě je obhajovat.","Obhajitelný, argumentovatelný postoj, který můžete vyhrát v televizi, což je devět desetin hodnoty, jakou kdy jaký postoj má."],["Ponechat je. Místo toho financovat přechod.","Jedenáct tisíc rekvalifikačních míst ve čtyřech státech, které jste vyhrál. Funguje to, pomalu, a zásluhy sklidí váš nástupce."],["Zrušit jedno nařízení devadesát osmkrát.","Administrativní pokyn skutečné krásy. Stejné nařízení se ruší, obnovuje, a znovu ruší, dokud se soudce písemně nezeptá, co se to vlastně děje."]]},"f-aid-agency":{"t":"Agentura pro pomoc","x":"Vandermeer chce, aby agentura pro zahraniční pomoc do pátku přestala existovat. Deset tisíc zaměstnanců, sto třicet zemí, a platební systém, který udržuje čtyři miliony lidí na antiretrovirové léčbě.","c":[["Zrušit do pátku. Přeživší zaměstnance přesunout pod ministerstvo zahraničí.","Platební systém se zastaví v úterý. Kliniky se to dozví, až peníze nepřijdou. Soud za pět týdnů nařídí obnovení, jenže dodavatelské řetězce už jsou do té doby rozprodané."],["Snížit to o polovinu během osmnácti měsíců.","Poloviční agentura, kompetentně utlumená, lékový program vyčleněný a chráněný. Nikdo nezemře a nikdo si toho nevšimne."],["Ponechat ji. Je to čtyři desetiny procenta rozpočtu.","To procento citujete na shromáždění. Je to jednoznačně nejúčinnější fakt celého vašeho prezidentství a nepřesvědčí nikoho v sále."],["Přejmenovat ji. Stejní zaměstnanci, stejný rozpočet, nová cedule.","Úřad americké štědrosti. Stojí to 9 milionů dolarů za hlavičkové papíry, a Vandermeer na živém přenosu vyhlásí totální vítězství."]]},"f-rehire":{"t":"Nařízení o znovupřijetí","x":"Soudce nařídil znovupřijmout šestnáct tisíc propuštěných zaměstnanců ve zkušební době, včetně doplacení mezd. Bo: \"Nařízení je jasné. Otázka, kterou se mě chystáte zeptat, zní, jak pomalu ho můžeme uposlechnout.\"","c":[["Znovu je přijmout, a pak je všechny poslat na administrativní volno.","Na papíře úplné splnění. Šestnáct tisíc lidí, zaměstnaných, placených, a poučených, ať nechodí do práce. Soudce zuří a nedokáže najít jediné porušení."],["Řádně to splnit. Přivést je zpátky k jejich stolům.","Vrátí se. Čtyři z nich se ukážou být jediní žijící lidé, kteří rozumí systému dávek napsanému v roce 1974."],["Odvolat se, a během odvolání je znovu propustit, tentokrát správně.","Druhé propuštění dodrží do písmene každé procesní pravidlo. Je nenapadnutelné. Právě jste zjistil, že postup nikdy nebyl tou překážkou."],["Znovu je přijmout do jediné kanceláře ve Wyomingu.","Šestnáct tisíc federálních zaměstnanců formálně přiděleno do budovy se čtyřmi sty pracovními stoly. Oznámení o přesunu je napadeno do jednoho dne."]]},"f-independent":{"t":"Nezávislé úřady","x":"\"Jedenáct úřadů bylo vytvořeno tak, aby prezident nemohl jejich funkcionáře odvolávat podle libosti. Chrání je precedens z roku 1935.\" Sy pokrčí rameny. \"Byl čtyřikrát zúžen. Nikdy nebyl zrušen.\"","c":[["Odvolat z každého jednoho. Vynutit si rozhodnutí.","Naléhavý senát nechá odvolání v platnosti do přezkumu, nepodepsáno, v jedenáct večer. Precedens z roku 1935 nikdy formálně nepadne. Od té noci prostě přestane platit."],["Odvolat toho jednoho, u kterého existuje skutečný důvod k výkonu.","Obhajitelné odvolání na doložených základech. Zavádí pravomoc, aniž by ji kdy otestovala, a přesně tahle verze přežije."],["Nechat je být. Právě nezávislost je důvod, proč fungují.","Čtyři z nich později rozhodnou proti vaší vládě, a dvě z těch rozhodnutí vás zachrání před podstatně horším výsledkem."],["Jmenovat sám sebe do všech jedenácti rad.","Pro devět z nich nesplňujete podmínky, a zbylé dvě vyžadují potvrzení prezidenta senátem, senátem, což nikdo neumí naplánovat."]]},"f-emergency-docket":{"t":"Nočně vyřízená agenda","x":"\"Dvacet devět naléhavých návrhů za toto období. Historicky vláda podá osm za osm let.\" Bo odloží statistiku. \"Vyhráli jsme dvacet tři. Ani jeden neměl ústní jednání. Ani jeden nevysvětlí proč.\"","c":[["Od teď podávat úplně všechno touhle cestou. Nikdy nežádat věcné projednání.","Přesunul jste americké ústavní právo na agendu bez slyšení, bez odůvodnění, a bez vysvětlení pro poražené. Je to čistě procesní, a je to celá hra."],["Ty velké případy dovést k plnému projednání. Vyhrát řádně.","Dva prohrajete a tři vyhrajete, s písemnými nálezy, které zavazují vaše nástupce. Výhry mají čtyřnásobnou hodnotu toho, co vám dá nepodepsané usnesení."],["Podávat méně. Vybírat lépe.","Devět návrhů, osm vyhověno. Pověst, že podáváte jen tehdy, když máte pravdu, je lepší než pověst, že podáváte pořád."],["Podat jeden ve čtyři ráno s žádostí, ať rozhodnou o všem najednou.","Devět set stran žádajících opatření ve čtyřiceti jedné nesouvisející věci. Zamítnuto jednou větou, o čtyři slova delší, než si návrh zasloužil."]]},"f-the-index":{"t":"Index","x":"Monitorovací organizace v Göteborgu poprvé za padesát let vyřadila Spojené státy z nejvyšší kategorie. Muriel má tu zprávu. Má 300 stran a jmenuje vás hned v prvním odstavci.","c":[["Uvalit sankce na organizaci. Zpochybnit její financování.","To, že národní vláda formálně napadá švédský akademický index, je samo o sobě ukazatelem v příští metodice. Reakcí jste tím číslem sám pohnul."],["Úplně to ignorovat. Nikdy o tom nemluvit.","Dva dny se o tom píše v médiích, která vaši voliči nečtou, a třicet let se to cituje v knihách lidí, co píšou učebnice."],["Zveřejnit vyvrácení. Zapojit se do diskuze o metodice.","Vaše vyvrácení je seriózní, podrobné, a částečně správné. V příštím vydání upraví dva ukazatele, a žebříček se nepohne ani o píď."],["Zadat vytvoření konkurenčního indexu. Skončit v něm první.","Index Vynikající Svobody hodnotí Spojené státy jako první ze sto devadesáti tří zemí. Jeho metodika má čtyři řádky, a jeden z nich je osobně o vás."]]},"f-press-rank":{"t":"Padesátý sedmý","x":"Index svobody tisku posunul zemi o sedm míst dolů, na 64. místo. Kaylee: \"Vklíněni mezi dvě země, které jste veřejně nazval diktaturami. To bude titulek.\"","c":[["Tvrdit, že žebříček je útok zahraničních zájmů.","Organizace přidá do profilu země větu o oficiálních odvetách. Každá vaše reakce se pak taky bodově zaznamená."],["Udělat jednu konkrétní věc: vrátit místo tiskové agentuře.","Jedna židle, jedna akreditace, jedno odpoledne. Žebříček se příští rok zlepší o čtyři místa, a nikdo z vašeho úřadu nepřizná souvislost mezi těmi dvěma fakty."],["Nic. Je to jenom seznam.","Je to jenom seznam, a příštích čtyřicet let se cituje v každém článku napsaném o vašem prezidentství, k čemu jsou seznamy koneckonců dobré."],["Poukázat na to, že 64. místo je pořád v horní třetině.","Aritmeticky správné, a jednoznačně nejzničující věta, jakou kdo z vlády kdy pronese, a ještě k tomu vesele."]]},"f-stablecoin":{"t":"Dvě miliardy","x":"Suverénní investiční fond přesune 2 miliardy dolarů přes token vydaný společností, kterou ovládá vaše rodina. Lyle: \"Poplatek za ten tok je zhruba 100 milionů dolarů ročně, placený vám cizím státem, nepřímo, navždy.\"","c":[["Vzít to. Je to soukromá obchodní dohoda.","Celou práci odvádí dvě slova: \"soukromá\" a \"nepřímo\". Ani jedno nepřežije předvolání v roce 2032, kdy jsou peníze už dávno utracené."],["Vzít to, ale měsíčně zveřejňovat tok peněz.","Úplné zveřejnění neobhajitelné dohody ji téměř úplně zneškodní. Každý to vidí, takže se to nikomu nechce vyšetřovat."],["Odmítnout. Některé peníze mají zpáteční adresu.","Lyle si odmítnutí napíše sám a schová si doma kopii, což u žádného jiného dokumentu za čtyři roky neudělal."],["Vzít to a hned to půjčit zpátky za horší úrok.","Kolotoč, ze kterého vyjdou všichni o něco chudší, kromě prostředníka, kterým náhodou je spolubydlící vašeho zetě."]]},"f-net-worth":{"t":"Přiznání majetku","x":"Výroční přiznání má 927 stran. Miriam Applewhite je přečetla všechny. \"Váš čistý majetek se v úřadu zhruba zdvojnásobil. Každý řádek je legální. Přesně to z toho dělá téma.\"","c":[["Podat to v šest večer v pátek před svátky.","Standardní praxe, kterou všichni chápou, vám koupí jedenáct dní. Tisková agentura si stejně přečte všech 927 stran, protože přesně to je náplní práce jednoho novináře."],["Podat to a uspořádat kvůli tomu tiskovou konferenci.","Devadesát minut otázek o dokumentu, který jste sám dobrovolně předložil. Mučivé, a téma to jediné odpoledne uzavře."],["\"Akciový trh šel nahoru. Vydělávají všichni.\"","Medián majetku domácností za stejné období vzrostl o 1,4 procenta. Čtyři různá média to srovnání zveřejní, jako zdroj použijí vaše vlastní přiznání."],["Podat to písmem, které nikdo nepřečte.","927 stran písmem velikosti šest bodů. Dobrovolnický přepisovací projekt to za devět dní dokončí, a prohledatelná verze vám ublíží mnohem víc než originál."]]},"f-two-orders":{"t":"Hromádka","x":"Deborah má na první den připravená čtyři nařízení. Každé je krátké, každé je okamžitě napadnutelné u soudu, a každé je navržené tak, aby bylo nejprobíranější věcí v zemi přesně na jeden zpravodajský cyklus.","c":[["Všechna čtyři. Podepsat před kamerou. Ukázat do místnosti.","Čtyři nařízení, čtyři žaloby, čtyři týdny nasycujícího zpravodajství. Dvě z nich soud zruší, ale do té doby už dávno splnila jediný účel, kvůli kterému vznikla."],["Jedno po druhém, s odstupem čtrnácti dnů.","Vytrvalé místo okázalé. Každé dostane vlastní cyklus, a souhrnné zpravodajství má čtyřnásobný objem toho, co by vzniklo při společném podpisu."],["Nepodepsat ani jedno. Celou složku poslat Kongresu.","Tři zemřou ve výboru. Jedno projde v pozměněné podobě a skutečně přežije vaše prezidentství, což by žádné z originálních neudělalo."],["Podepsat čtyři prázdné listy a doplnit je později.","Fotografie existují, nařízení ne. Devět dní se země hádá o obsahu čtyř kusů prázdného papíru."]]},"f-service-ban":{"t":"Sloužící vojáci","x":"Tarrant má čísla: patnáct tisíc v aktivní službě, čtyři sta nasazených, a přehled bojeschopnosti z minulé vlády, který nenašel absolutně žádný operační dopad.","c":[["Podepsat. Mají devadesát dní.","Čtyři sta lidí je odvoláno z nasazení. Jejich náhradníky trvá vycvičit šest měsíců. Tarrant zaznamená náklad na bojeschopnost do memoranda, které si nikdy nepřečtete."],["Udělit výjimku všem, kdo právě slouží.","Politika se pak nevztahuje na nikoho skutečně existujícího. Tisková zpráva s právní citací, a u soudu obstojí přesně proto, že nic nedělá."],["Řídit se přehledem bojeschopnosti.","Tarrant řekne \"děkuji, pane\" tónem, jaký jste od něj ještě nikdy neslyšel. Patnáct tisíc lidí si udrží místo, a naprosto nic se nestane."],["Zakázat kategorii, která v ozbrojených silách nikdy neexistovala.","Nařízení zakazuje sloužit komukoli s dědičným cizím šlechtickým titulem. Týká se nula lidí. Čtyři sta tisíc lidí to schvalně sdílí, aniž by si to ověřili."]]},"f-nuclear-deal":{"t":"Dohoda","x":"\"Dodržují to. Naši vlastní inspektoři to potvrzují, spojenci to potvrzují, a dohoda funguje podle jediného měřítka, pro které byla sepsaná.\" Muriel zavře složku. \"V kampani jste sliboval, že ji roztrháte.\"","c":[["Roztrhat ji. Znovu zavést všechno.","Za čtrnáct měsíců obnoví obohacování. Tři evropští signatáři se dva roky snaží dohodu udržet pohromadě, pak to potichu vzdají."],["Zůstat v ní a žádat navazující dohodu.","Navazující jednání trvají čtyři roky a vyprodukují něco nepatrně lepšího s vaším jménem pod tím, což si nikdo z vašich voličů nikdy nepřečte."],["Zůstat v ní a neustále porušovat její ducha.","Veškerá páka, žádný kolaps. Je to sofistikovaná verze, a na shromáždění je naprosto neviditelná."],["Roztrhat ji a zveřejnit kousky.","Fotografie roztrhané smlouvy skončí přetištěná ve čtyřech národních osnovách jako ilustrace něčeho, a to něco se v každé zemi liší."]]},"f-fell-in-love":{"t":"Dopisy","x":"Hance má složku. Dopisy ze Severní Koreje jsou podle jeho odborného posouzení \"sepsané výborem tak, aby lichotily jednomu konkrétnímu člověku\". Vy jste je popsal jako nádherné.","c":[["Říct, že jste se zamiloval. Nahlas. Na shromáždění.","Čtyři spojenecké zpravodajské služby potichu omezí, co s vámi sdílejí. Dopisy chodí dál. K žádné denuklearizaci nedojde, a dva summity vyprodukují společné prohlášení o 79 slovech."],["Ponechat kanál otevřený. Veřejně neříkat nic vřelého.","Diplomacie je skutečná, lichotky zůstávají soukromé, a výsledkem je moratorium na testy, které vydrží tři roky."],["Zveřejnit dopisy. Všechny.","Mimořádné dokumenty, hluboce trapné pro oba signatáře. Historikové jsou nadšeni. Kanál se do čtrnácti dnů uzavře."],["Odepsat veršem.","Jedenáct nerýmovaných řádků, sepsaných Gideonem Poeem pod protestem. Odpověď přijde ve stejném duchu, delší a se znatelně lepší veršovou stavbou."]]},"f-gold-star":{"t":"Rodina","x":"Rodiče vojáka padlého v boji vás veřejně kritizovali, jmenovitě, na televizní akci. Tarrant přišel říct přesně jednu věc: \"Pane. Neexistuje žádná varianta hádky s nimi, ve které byste vyhrál.\"","c":[["Reagovat. Nikdo s vámi takhle nemluví.","Táhne se to jedenáct dní. Čtyři senátoři z vaší vlastní strany se s vámi veřejně rozejdou. Podle úplně každého měřítka, jaké průzkumníci mají, je to nejhorší týden vašeho prezidentství."],["Neříct vůbec nic. Poslat soukromý dopis.","Dopis se nikdy nezveřejní. O léta později krátce zmíní, že byl ručně psaný a lepší, než čekali."],["Zavolat jim. Poslouchat, jak dlouho budou chtít.","Devadesát minut, většinou mluví oni. Svůj názor na vás nezmění a řeknou to veřejně, ale zároveň řeknou, že jste je poslouchal, a citují se obě poloviny."],["Nechat to celé vyřídit viceprezidenta.","Chet to samozřejmě zvládne dokonale, nechá se vyfotit s matkou, a tu fotku si nechá. Všimnete si, že si ji nechává."]]},"f-war-hero":{"t":"Senátor","x":"Senátor z vaší vlastní strany, vyznamenaný veterán, pět let vězněný jako válečný zajatec, hlasoval proti vám. Brayden má připravenou hlášku o jeho válečné minulosti. Kaylee přestala psát.","c":[["Použít tu hlášku. O zajetí.","Mělo by to ukončit vaši kariéru. Neukončí. To, že neukončí, je jednoznačně nejvýznamnější politický fakt celého desetiletí, a všichni v místnosti to okamžitě pochopí."],["Útočit na hlasování. Nikdy na jeho minulost.","Normální, tvrdý, naprosto konvenční politický útok. Funguje, a nikdo o něm nenapíše knihu."],["Pochválit jeho minulost a přijmout prohru.","Čtyři váhající senátoři pak u příštího zákona hlasují s vámi, a ani jeden z nich to pořádně neumí vysvětlit."],["Udělit mu medaili. Velkou. Okamžitě.","Přijme ji s bezvadnou zdvořilostí a o jedenáct dní později proti vám znovu hlasuje, s medailí v ruce, a zmíní to."]]},"f-governor-pardon":{"t":"Guvernér, který prodal senátorské křeslo","x":"Bývalý guvernér si odpykal osm ze čtrnácti let za pokus prodat senátorské křeslo. Sy poznamenává, že byl usvědčen nahrávkou, na které dělá přesně tu věc, vlastním hlasem.","c":[["Zkrátit mu trest. Nazvat ho velmi slušným člověkem.","Do týdne je v televizi a nazývá stíhání politickým. Následující měsíc podají žádost čtyři další odsouzení funkcionáři, s odkazem přesně na tento precedens."],["Zkrátit mu trest potichu, bez prohlášení.","Páteční seznam jedenácti jmen. Devět dní si toho nikdo nevšimne, a do té doby je to spíš procesní zpráva než morální."],["Nechat to být. Byl při tom nahraný.","Úřad pro udělování milostí místo toho zpracuje 14 000 čekajících žádostí od lidí bez právníků, a 900 z nich vyřídí kladně."],["Udělit mu milost pod podmínkou, že už nikdy veřejně nepromluví.","Podmínka je nevymahatelná, a poruší ji do čtyř dnů, v podcastu, obšírně, s poděkováním vám jmenovitě."]]},"f-activist-pardons":{"t":"Blokáda","x":"Třiadvacet lidí odsouzených za fyzické zablokování kliniky. Bo: \"Znali zákon, byli toho dne varováni, a to odsouzení chtěli. Je to strategie mučednictví, pane, a dobrá.\"","c":[["Udělit milost všem třiadvaceti. Pozvat je dovnitř.","Fotografie na schodech se čtyři roky objevuje v každém e-mailu na sbírku peněz, na obou stranách. Má větší cenu pro vaše odpůrce než pro vás, a oba to víte."],["Udělit jim milost. Bez ceremonie, bez fotky.","Neinscenovaná milost je zpráva na jeden den. Vaši voliči dostanou, co chtěli, a nikdo jiný nedostane obrázek."],["Nic. Zákon je zákon.","Čtyři náboženští vůdci, kteří vás deset let obhajovali, přestanou napořád zvedat vaše hovory, kvůli třiadvaceti lidem."],["Udělit milost jim i lidem, které blokovali.","Druhá skupina nikdy z ničeho obviněna nebyla. Milost dostanou stejně, za nic, a čtyři z nich si osvědčení dají zarámovat."]]},"f-stand-by":{"t":"Otázka z debaty","x":"Byl jste v přímém přenosu, v celostátní televizi, požádán, abyste jmenovitě odsoudil ozbrojenou skupinu. Brayden je ve vašem sluchátku. Devadesát milionů lidí sleduje a máte zhruba čtyři vteřiny vysílacího času.","c":[["\"Buďte v pohotovosti.\" Říct to a jít dál.","Skupina si to do devadesáti minut vytiskne na trička. Další čtyři dny strávíte vysvětlováním, že ta dvě slova znamenala pravý opak toho, co zjevně znamenala."],["Odsoudit je. Bez obalu. Jmenovitě.","Čtyři vteřiny jednoznačné angličtiny. Nestojí vás to nic, co byste jinak potřeboval, a smaže to celý rok zpravodajství."],["Odsoudit \"veškeré násilí\" a nikoho nejmenovat.","Klasický únik. Neuspokojí nikoho, neurazí nikoho, a úplně každý to správně pochopí, což je přesně smysl toho."],["Odsoudit skupinu, která neexistuje.","Rázně odsoudíte Kolektiv západního předvoje. Čtyři ověřovatelé faktů potvrdí, že nikdy neexistoval. Jedenáct tisíc lidí do něj do měsíce stejně vstoupí."]]},"f-rat-infested":{"t":"Volební obvod","x":"Předseda výboru si předvolal vaše finanční záznamy. Brayden sepsal příspěvek o jeho volebním obvodu, jeho kriminalitě, jeho bytovém fondu, a jednom přídavném jméně, které odvádí veškerou tu práci.","c":[["Zveřejnit to. Přídavné jméno zůstává.","Dobrovolníci následující víkend uklidí čtyři bloky toho obvodu a zveřejní fotky. Je to nejlépe zorganizovaná reakce, jakou kdy jaký váš příspěvek vyvolal."],["Zveřejnit statistiky kriminality. Bez přídavného jména.","Čísla jsou skutečná, vyznění je brutální, a nikdo s tím nic nezmůže. Podstatně účinnější, a naprosto necitovatelné."],["Zajet tam. Vyhlásit federální bytový program.","Při příjezdu vás vypískají a při odjezdu vám tleskají. Předvolání se nestáhne, a program stejně postaví devět set bytů."],["Napsat místo toho o vlastním obvodu.","Žádný obvod nemáte. Popíšete ten, ve kterém jste vyrůstal, nelaskavě, a jeho současní obyvatelé zareagují ve velkém počtu."]]},"f-death-toll":{"t":"Počet obětí","x":"Akademická studie odhadla počet obětí hurikánu na tomto území na téměř tři tisíce, daleko nad původní oficiální počet. Duane má metodiku. Je solidní.","c":[["Zpochybnit to číslo. Tvrdit, že bylo vymyšlené, aby vám uškodilo.","Tři tisíce lidí se stanou řečnickou pozicí. Území na to nezapomene, a nezapomene na to ani jediná rodina jmenovaná v příloze."],["Přijmout to. Nařídit úplný rozbor události.","Rozbor odhalí čtyři systémová selhání, tři z nich existovala už před vámi. Náprava stojí 2 miliardy dolarů a odhadem zachrání jedenáct set životů při příští bouři."],["Přijmout to číslo. Neříkat nic dalšího. Nikdy.","Mlčení o počtu obětí je jediná důstojná varianta na stole, a je to za den vyřízené."],["Zeptat se, jestli se to číslo dá přepočítat na inflaci.","Otázka padne upřímně, na poradě jedenácti lidí. Nikdo na ni neodpoví. Dva z nich to mlčení později, nezávisle na sobě, popíšou v rozhovorech."]]},"f-health-body":{"t":"Celosvětová organizace","x":"Vystoupení vyžaduje dvanáctiměsíční výpovědní lhůtu a 400 milionů dolarů v nedoplatcích. Pike: \"Napsali jsme většinu jejích protokolů. Opustili bychom instituci, kterou jsme vybudovali, kterou vedeme, a kterou pořád využíváme.\"","c":[["Podat výpověď hned první den.","Ztratíte přístup k síti pro sdílení chřipkových kmenů, která určuje složení vakcíny. V den podpisu to nikdo v místnosti neví."],["Zůstat v ní a zadržet polovinu financování.","Veškerá páka, žádný odchod. Čtyři reformy, které jste skutečně chtěl, se přijmou do dvou let."],["Zůstat. Místo toho žádat rezignaci generálního ředitele.","Do osmnácti měsíců je pryč, nahrazen někým, s kým souhlasíte, což byl celou dobu ten skutečný cíl."],["Založit konkurenční organizaci se čtyřmi členy.","Celosvětová zdravotní aliance svobodných. Zakládající členové: vy, a tři země, jejichž souhrnná populace je menší než Ohio."]]},"f-education":{"t":"Ministerstvo","x":"Ollis: \"Ministerstvo zřízené zákonem nemůžete zrušit. Můžete ho zredukovat na telefonní ústřednu. Ta ústředna by ale pořád musela posílat 28 miliard dolarů ročně školám, protože i to je dané zákonem.\"","c":[["Zredukovat na ústřednu. Zbytek propustit.","Peníze pořád odcházejí, protože musí. Co se zastaví, je vymáhání podmínek k nim připojených, což byla celá ta práce."],["Ponechat ho. Změnit, co ty podmínky vyžadují.","Stejné ministerstvo, stejní zaměstnanci, stejných 28 miliard dolarů, úplně jiné podmínky. Rychlejší, levnější, a naprosto neviditelné."],["Poslat zákon o zrušení Kongresu a nechat ho zemřít.","Získá 189 hlasů. Čtyři roky kampaňujete s těmi 189 a ani jednou nezmíníte, že jste potřeboval 218."],["Zrušit ho a ústřednu přesunout na poštu.","Poštovní služba je ústavně samostatná a nelze jí to přidělit. Čtyři právníci to vysvětlí. Přesto se to zkusí a ztroskotá to na technikálii o poštovních zásilkách."]]},"f-roe-credit":{"t":"Zásluha","x":"Soud zvrátil padesátiletý precedens. Reverend Muncy je v místnosti a pláče. Nadia má průzkumy: zvrat je neoblíbený o jedenáct bodů, a vaše role v tom je téměř neznámá.","c":[["Přihlásit se k tomu. \"Já jsem toho dokázal docílit.\"","Osobně se spojíte s nejméně oblíbeným institucionálním činem celého desetiletí. Vaši voliči jsou u vytržení, a čtyři příměstské okresy se přikloní o jedenáct bodů na druhou stranu."],["Připsat zásluhu soudcům a neříkat nic víc.","Zdrženlivost, od vás, právě u tohoto tématu. Muncy si toho všimne a řekne to z kazatelny, což má větší cenu, než by kdy mělo přihlášení se k zásluze."],["Tvrdit, že rozhodl soud a vy jste s tím neměl nic společného.","Není to pravda, tři z nich jste jmenoval a v té době jste to sám řekl, a archivní záznam běží vedle toho popření do jednoho dne."],["Přihlásit se k zásluze za rozhodnutí, které šlo proti vám.","Prohru 6:3 popíšete jako osobní vítězství, a to natolik podrobně, že dvě televizní stanice si ověřují, jestli náhodou nemají špatný název případu."]]},"f-political-scientists":{"t":"Průzkum","x":"Doktorka Weir má průzkum mezi devíti sty politology. Jejich hodnocení kvality americké demokracie kleslo za deset měsíců víc, než za předchozích čtyřicet let dohromady. \"Žádal jste mě o poctivý materiál, pane.\"","c":[["Nechat prověřit jejich federální granty.","Prověrka nic nenajde. Příští rok se do průzkumu přidá otázka o zastrašování výzkumníků, a skóre klesne znovu, rychleji."],["Pozvat si čtyři z nich dovnitř. Zeptat se, co by to vrátilo zpátky.","Dají vám jedenáct konkrétních, nudných, dosažitelných odpovědí. Dvě z nich uskutečníte. Obě fungují."],["Ignorovat to. Je to jen devět set profesorů.","Je to devět set profesorů, a je to soubor dat, ze kterého vychází úplně každé dějepisné dílo o tomto období."],["Vyplnit ten průzkum sám a odeslat ho anonymně.","Zemi ohodnotíte výš než kterýkoli jiný respondent, o čtyřicet bodů. Odeslání se do týdne vystopuje podle IP adresy."]]},"f-anticipatory":{"t":"Nikdo je nežádal","x":"\"Advokátní kancelář přislíbila 100 milionů dolarů bezplatné práce pro věci, které máte rád. Univerzita změnila přijímací politiku. Televize zrušila pořad.\" Deborah zvedne oči. \"Pane, o nic z toho jsme nežádali.\"","c":[["Nic neříkat a přijmout to všechno.","Žádné nařízení k napadení, žádná hrozba k prokázání, žádné memorandum k předvolání. Instituce vyčítající si náladu z místnosti se ukáže být nejúčinnější forma moci, jaká kdy byla vynalezena."],["Pochválit je jmenovitě. Povzbudit ostatní.","Jejich jmenování promění neviditelný proces na viditelný, což je pro vás horší, a mnohem rychlejší."],["Veřejně jim říct, že to nebylo nutné.","Dva ze tří do čtrnácti dnů své rozhodnutí zvrátí. Je to jednoznačně nejvíce zklidňující věta, jakou lze pronést, a stojí vás to nesmírně mnoho."],["Požádat je o něco obrovského a zjistit, jestli řeknou ano.","Dva ze tří řeknou ano. Třetí se zdvořile zeptá, jestli je žádost písemná. To, že není, se ukáže vysvětlit úplně všechno."]]},"f-generals-room":{"t":"Sál plný generálů","x":"Na vaši žádost byli do jednoho sálu svoláni všichni vysocí důstojníci ozbrojených sil. Gideon má návrh projevu, který čtyřikrát použije frázi \"nepřítel uvnitř\". Tarrant si ho přečetl.","c":[["Přednést to tak, jak je to napsané.","Nikdo v sále nevstane. Nikdo taky neodejde. Čtyři z nich to ticho popíšou ve svých pamětech, o desetiletí od sebe, a všechny čtyři popisy se shodují."],["Vyškrtnout tu frázi. Přednést zbytek.","Silný, konvenční, naprosto zapomenutelný projev k důstojnickému sboru. Tarrant vám pak poděkuje za konkrétní vynechání a neřekne za jaké."],["Zeptat se jich místo toho, co potřebují. Vzít si otázky.","Devadesát minut otázek od lidí, kteří se normálně nikdy neptají. Přímým důsledkem se změní čtyři rozhodnutí o pořízení techniky."],["Přednést to, ale o konkrétním hmyzu.","Jedenáct minut o krasci čtyřtečném, přednesených s naprostým přesvědčením čtyřem stům admirálů. Milovaný, matoucí, a citovaný po celou generaci."]]},"g-blocked-seat":{"t":"Podržené křeslo","x":"Hal držel jedenáct měsíců křeslo u Nejvyššího soudu prázdné, na základě teorie, že by nejdřív měli rozhodnout lidé. Teď se uvolnilo místo ve vašem vlastním posledním roce. \"Pane, ten argument nikdy nebyl o kalendáři. Byl o tom, čí je to kalendář.\"","c":[["Obsadit ho. Ještě dnes. Neuvádět žádný princip.","Potvrzeno za rovných dvacet sedm dní, s odkazem jen na matematiku toho, kdo právě drží kladívko, což se ukáže být princip dostatečný."],["Obsadit ho, a vymyslet úhledný rozdíl podle toho, který je to rok.","Rozlišení má čtyři věty a zhroutí se hned pod první doplňující otázkou, na kterou odpovíte jiným, stejně dočasným rozlišením."],["Nechat ho volné. Řídit se pravidlem, které jste sám vytvořil.","Obsadí ho místo toho váš nástupce. Čtyři právní historikové to později citují jako poslední zaznamenaný případ, kdy se americký politik nechal vázat vlastním precedentem."],["Obsadit ho člověkem, kterého Hal před jedenácti lety zablokoval.","Je mu jedenasedmdesát, potvrzen poměrem osmdesát devět ku jedenácti, a čtyři roky je puntičkářsky, k zbláznění spravedlivý ke všem, což obě strany shledávají nesnesitelným."]]},"g-nationwide":{"t":"Jeden soudce, celá země","x":"\"Jeden jediný okresní soudce dokáže zmrazit celostátní politiku. Argumentovali jsme, že je to protiústavní.\" Bo obrátí stránku. \"Pokud tento argument vyhrajeme, pane, zmrazí to taky úplně každou politiku, kterou se váš nástupce kdy pokusí podepsat.\"","c":[["Přesto to vyhrát. Trvale odstranit ten nástroj ze stolu.","Vyhrajete. Celostátní soudní opatření se prudce omezí, a o čtyři roky později je to jednoznačně největší překážka pro zrušení čehokoli, co jste vybudoval, přesně jak bylo naplánováno."],["Argumentovat úzce. Jen u tohoto jednoho případu.","Výjimka, ne doktrína. Koupí vám to tuhle jednu politiku a nechá zbraň plně nabitou ve stojanu i pro příští vládu."],["Vzdát se argumentu. Bojovat na základě věcné podstaty.","Prohrajete případ a vyhrajete instituci, směna, za kterou v celé zaznamenané historii nebyl žádný politik ani jednou pochválen."],["Zeptat se, který soudce. Pak ho nechat zvát na akce.","Všechna čtyři pozvání písemně odmítne, poznámky přepošle soudní konferenci, a o devět dní později proti vám rozhodne, obsáhleji, než bylo nezbytně nutné."]]},"g-immunity":{"t":"Oficiální úkony","x":"\"Soud rozhodl, že žádný soud nesmí zkoumat vaši pohnutku u oficiálního úkonu.\" Sy odloží rozsudek, jako by mohl vybuchnout. \"Pane, tahle jedna věta teď odvádí víc práce, než zbytek amerického práva dohromady.\"","c":[["Postavit na tom úplně všechno. Citovat to v každém podání.","Třetina vašich naléhavých návrhů se teď opírá právě o to. Stavíte celou konstrukci na jediné větě, a každá nová cihla dělá tu větu nosnější."],["Použít to jednou, na něco malého, a stanovit tím rozsah.","Bezvýznamný testovací případ, podaný potichu, který nevytáhne žádné titulky a natrvalo urovná hranice. Je vám teď k dispozici do konce přirozeného života."],["Nikdy se na to neodvolávat. Štít, který používáte, se stává terčem.","Sy je, proti veškerému profesionálnímu instinktu, ohromen. Ochrana zůstává úplná a naprosto neotestovaná, což je nejsilnější možná forma, jakou hrozba může mít."],["Prohlásit čištění zubů za oficiální úkon.","Podáno s kamennou tváří, v poznámce pod čarou, čistě proto, aby se zjistilo, jak daleko ta kategorie sahá. Soudce to zaznamená v souhlasném stanovisku s viditelnou, zdokumentovanou únavou."]]},"g-complicated":{"t":"Nikdo to nevěděl","x":"Doktorka Pike vám čtyřikrát samostatně vysvětlila dotace na burzy zdravotního pojištění. Právě jste sálu guvernérů řekl, že nikdo netušil, jak složité zdravotnictví může být.","c":[["Zopakovat to veřejně znovu. Je to upřímné.","Každý, kdo pracuje ve zdravotnické politice, to věděl. Je to koneckonců celá jejich práce. Ten záznam se deset let pouští na čtyřech konferencích ročně, vždy pro přesně stejný smích."],["Přiznat se k učení. Klást veřejně lepší otázky.","Prezident, který se viditelně před kamerou něco učí, je natolik vzácný, že to vede dva zpravodajské pořady. Pike dostane devět minut bez přerušení a využije každou jednu z nich."],["Svést tu složitost na minulou vládu.","Ta složitost je starší o čtyřicet let a sahá ke kompromisu, který vyjednala vaše vlastní strana v roce 1974, což tři ověřovatelé faktů zveřejní ještě před večeří."],["Vyřešit to naživo, na tabuli, za devadesát minut.","Tabuli vyfotí ze všech úhlů. Čtyři zdravotní ekonomové to vážně prostudují a dojdou k závěru, že by to stálo dva biliony dolarů a pokrylo o jedenáct lidí méně."]]},"g-briefing-podium":{"t":"Pódium","x":"Admirál Prine stojí po vaší levici, generální chirurg po pravici, a pódium je vaše na devadesát minut denně. Prine: \"Pane, cokoli tady nahoře řeknete, se do oběda stane lékařským doporučením, ať už jím je, nebo ne.\"","c":[["Vzít si celých devadesát minut. Každý den.","Sledovanost je mimořádná. Stejně tak i nárůst volání na toxikologické centrum během čtyř dnů po jedné konkrétní úvaze o domácích chemikáliích."],["Zahájit to, předat slovo Prine, opustit místnost.","Ochota dodržovat zdravotní doporučení vzroste za čtrnáct dní o čtrnáct bodů, zcela proto, že je teď přednáší člověk se skutečným lékařským titulem."],["Zůstat, ale neodpovídat na nic lékařského.","Skutečná disciplína, vydržená jedenáct dní, a porušená dvanáctého dne jedinou otázkou o doplňku stravy."],["Přinést si místo toho graf vlastní podpory v průzkumech.","Devět minut zdravotního brífinku strávíte čísly vlastní podpory. Generální chirurg celých těch devět minut studuje podlahu."]]},"g-power-plan":{"t":"Nařízení o uhlí","x":"\"Můžete to zrušit, ale nemůžete to zrušit do prázdna, soud bude žádat náhradu.\" Cassandra pokrčí rameny. \"Takže jediná skutečná otázka zní, jak slabá ta náhrada může být, než se právně přestane počítat za náhradu vůbec.\"","c":[["Nahradit to něčím, co nic nezmění.","Náhrada má čtyři sta stran, a její vlastní povinná analýza dopadů přiznává, že dosahuje jednoho procenta účinku originálu. Tohle přiznání teď napořád zůstává v záznamu."],["Nahradit to něčím skromným a obhajitelným.","Přežije to soudní přezkum, na rozdíl od předchozích čtyř pokusů kohokoli, a v roce 2041 to pořád, nenápadně, stojí."],["Ponechat to. Přihlásit se k zásluze za elektrárny, které už zavírají.","Ty elektrárny zavíraly kvůli ekonomice, ne kvůli regulaci, a vy to víte, a stejně si tu zásluhu přivlastníte, což je poctivější, než většina věcí, co říkáte."],["Nahradit to nařízením o palivu, které nikdo nepoužívá.","Komplexní celostátní normy pro velrybí olej. Právně nenapadnutelné, nedosahuje naprosto ničeho, a sepsání toho někomu sežere jedenáct měsíců jediného života."]]},"g-refuge":{"t":"Rezervace","x":"Pobřežní planina je uzavřená pro těžbu od roku 1980. Cassandra: \"Prodej těžebních práv se může uskutečnit. Jestli se vůbec někdo přihlásí, je otázka samostatná, čtyři velké společnosti už oznámily, že se nepřihlásí.\"","c":[["Uspořádat prodej. Smysl je v tom, že se to stalo.","Přihlásí se dva zájemci, jedním z nich je státní agentura, která práva koupí přímo proto, aby zabránila těžbě. Vynese to čtrnáct milionů dolarů proti plánovaným 1,8 miliardám, a precedens je navždy."],["Uspořádat ho a vylepšit podmínky, dokud se někdo nepřihlásí.","Sazby licenčních poplatků nastavené tak nízko, že by vláda na úspěšné vrtu prodělala. Přihlásí se tři zájemci. Nikdo nevyvrtá jedinou díru."],["Nechat to uzavřené. Otevřít někde, kde už je průmysl.","Čtyři brownfieldy vyprodukují víc skutečné těžby, než by rezervace kdy za deset let dala, a ani jedna žaloba."],["Pronajmout to ochranářskému fondu, který nikdy nebude těžit.","Zaplatí plnou cenu za právo s tím absolutně nic nedělat. Je to legální, je to skutečný prodej, a je to nejvtipnější výklad těžební smlouvy, jaký kdy vznikl."]]},"g-send-her-back":{"t":"Skandování","x":"Před čtyřmi dny jste řekl něco o kongresmance. Dav před vámi z toho teď udělal skandování, třináct vteřin dlouhé a pořád sílící. Brayden přestal dýchat.","c":[["Nechat to plynout. Nic neříkat. Vyčkat, až to odezní.","Třináct vteřin se stane celým příběhem. Čtyři členové vaší vlastní strany to jmenovitě odsoudí, a vy strávíte týden vysvětlováním mlčení."],["Přerušit to. \"Ne, ona je Američanka.\"","Šest slov do živého mikrofonu, na vlastním shromáždění. Dav se skutečně zastaví. Je to jednoznačně nejodvážnější věc, kterou před svými příznivci uděláte, a nikdy vám ji úplně neodpustí."],["Přemluvit to, dokud to neustane.","Profesionální tah: žádný záznam, kde se přidáváte, žádný záznam, kde to zastavujete. Obě strany si tu nahrávku nárokují, a ani jedna ji vlastně nemůže použít."],["Spustit jiné skandování. Okamžitě. Jakékoli.","Místo toho začnete skandovat o infrastruktuře. Jedenáct tisíc lidí se k vám čistě ze setrvačnosti přidá. Je to nejpodivnější záchrana situace, jaká kdy byla zachycena kamerou."]]},"g-general-lee":{"t":"Socha generála","x":"Na dotaz o pomníku jste generála pochválil jako skvělého vojáka. Doktorka Weir přinesla jeho skutečné dopisy. \"Byl proti pomníkům, pane. Písemně. Dvakrát. Myslel si, že by tím rána navždy zůstala otevřená.\"","c":[["Dál ho chválit. Byl to skvělý generál.","Taktisky to opravdu byl dobrý generál, což je nejužší dostupná obhajoba, a přesně tu si vyberete. Dopisy vyjdou tiskem hned vedle vašeho citátu."],["Přečíst jeho dopisy nahlas. Nechat ho, ať argumentuje sám.","Použít mužovu vlastní písemnou námitku k ukončení sporu o jeho vlastní sochu je nejelegantnější tah na stole, a stojí vás jedenáct bodů u vlastních voličů."],["Říct, že je to místní záležitost, a odmítnout se zapojit.","Správné, nudné, a naprosto neuspokojivé pro každého, kdo přišel na hádku, což jsou všichni."],["Navrhnout sochu dopisů místo sochy muže.","Bronzová otevřená kniha, objednaná a opravdu krásná. Dva okresy se o ni devět let přou z důvodů, které nikdo ze zúčastněných nedokáže pořádně shrnout."]]},"g-project-binder":{"t":"Institut","x":"\"Devět set stran, sepsaných za čtyři roky lidmi, které jste nikdy nepotkal, pokrývajících úplně každý úřad. Během kampaně jste se toho zřekl.\" Deborah to položí na stůl. \"První kapitola, pane, je personální seznam.\"","c":[["Zavést to. Kapitolu po kapitole. Najímat ze seznamu.","Šedesát procent je do osmnácti měsíců zavedeno. Vaše popření se každý večer pouští ve smyčce vedle přehledu zavádění, a nepohne to vůbec ničím."],["Vzít si personální seznam. Ignorovat politiku.","Lidé jsou ta politika. Najmout čtyři sta samotných autorů dokumentu je způsob, jak ho zavést, aniž byste technicky přijal jediné jeho slovo."],["Zahodit to. Zřekl jste se toho a myslel jste to vážně.","Institut do roka financuje protikandidáta v primárkách. Je to jednoznačně nejnákladnější čin integrity celého vašeho prezidentství."],["Zavést jen jedenáctou kapitolu. Ostatní nečíst.","Jedenáctá kapitola se ukáže být o údržbě federálních budov. Zavede se bezchybně, a Správa obecních služeb zažije nejlepší desetiletí své existence."]]},"g-no-independent":{"t":"\"Žádné nezávislé úřady neexistují\"","x":"Váš ředitel rozpočtu před kamerou prohlásil, že nic jako nezávislý úřad neexistuje. Deborah: \"Je to právní teorie se skutečnou oporou. Vyřčeno takhle nahlas je to ale zároveň přiznání záměru.\"","c":[["Podpořit to. Říct to sám, přesně těmi slovy.","Každé odvolání se od teď soudí proti vyslovené teorii místo proti konkrétnímu faktu. Dal jste protistraně terč a nejednoznačnost jste zahodil zadarmo."],["Nechat ho to říkat. Nikdy to nepotvrdit.","Teorie nadhozená podřízeným je teorie, které se do oběda můžete zříct. Přesně proto byl najatý, a on to ví."],["Veřejně ho opravit. Některé úřady jsou nezávislé.","Čtyři šéfové úřadů poprvé za rok pořádně spí. Do jara odstoupí a obšírně o tom napíše, za peníze."],["Souhlasit, a jako výjimku prohlásit meteorologickou službu za nezávislou.","Jedna výjimka, vybraná v podstatě náhodně, díky které celá teorie zní ještě rozsáhleji, ne méně. Nikdo to pořádně neumí vysvětlit, a přesto to všichni tak cítí."]]},"g-hundred-thirty":{"t":"Sto třicet dní","x":"Vandermeer je zvláštní vládní zaměstnanec. Ta kategorie má pevný strop: sto třicet dní ročně. Vyčerpal už sto osmnáct. \"Tohle vlastně nikdo nepočítá,\" říká. Deborah tiše: \"Někdo tohle počítá.\"","c":[["Přestat počítat. Zůstává.","Zákonný limit, který nikdo nesleduje, není funkčně žádný limit. Čtyři žádosti o informace nakonec zjistí, že odsloužil dvě stě devadesát jedna dní, a s ani jedním z nich se nepojí žádný důsledek."],["Udělat z něj řádného zaměstnance. S plnou povinností přiznání majetku.","Do týdne raději rezignuje, než aby to přiznání podal. Kategorie sto třiceti dnů existovala přesně proto, aby se tomu formuláři vyhnula, a teď to ví každý."],["Nechat ho, ať limit vyčerpá a odejde.","Sto třicátého dne odejde s motorovou pilou a živým přenosem. Úřad, který vybudoval, ho snadno přežije, což bylo vždycky to skutečné riziko."],["Dát mu druhé místo, aby se dny počítaly zvlášť.","Je jmenován do čtyř různých úřadů najednou, každý s vlastními samostatnými sto třiceti dny. Aritmeticky vynalézavé, právně neobhajitelné, a nikdo proti tomu nehne ani prstem."]]},"g-two-billion-case":{"t":"Už dlužené peníze","x":"\"Dvě miliardy dolarů za pomoc, která už byla dokončená. Tyhle faktury jsou za dohotové zakázky.\" Lyle zvedne oči. \"Tohle nejsou granty, které odmítáme, pane. Tohle jsou účty, které prostě neplatíme.\"","c":[["Neplatit. Vést spor až k poslednímu soudu.","Prohrajete, pět ku čtyřem, u naléhavého návrhu. Devět set dodavatelů už do té doby zkrachovalo, což se v rozsudku nijak neřeší, protože rozsudky se tím nikdy nezabývají."],["Zaplatit dokončenou práci. Zrušit všechno budoucí.","Právně nenapadnutelné, a uspoří to devadesát procent nákladů, aniž by to zanechalo jakoukoli judikaturu, kterou by proti vám kdo mohl později citovat."],["Zaplatit to celé. Bojovat místo toho o příští rozpočtovou položku.","Bojovat o příští položku místo o poslední je přesně to, jak má tenhle systém fungovat. Je to pomalejší, a funguje to."],["Zaplatit ve vlastní vymyšlené měně.","Státní dluhopisy splatné v roce 2041. Čtyři dodavatelé je přijmou. Jeden je v roce 2033 se ziskem prodá dál a na chvíli se stane docela slavným."]]},"g-hotel-ledger":{"t":"Účetní kniha","x":"Miriam Applewhite má rezervační záznamy: jedenáct zahraničních delegací, jedna nemovitost, vaše jméno nad dveřmi. \"Nikdo netvrdí, že šlo o protislužbu, pane. Nikdo to ani nemusí tvrdit. Účetní kniha je samo o sobě obvinění.\"","c":[["Dál přijímat rezervace. Je to hotel.","Technicky to hotel je. Je to zároveň jediný hotel na Zemi, kde zahraniční ministerstvo pošle peníze úřadujícímu hlavě státu a na oplátku dostane klíč od pokoje."],["Věnovat zisk ze zahraničních rezervací státní pokladně.","Číslo si spočítáte osobně, metodiku nezveřejníte, a pošlete šek. Je to naprosto neověřitelné, a přesto to úplně funguje."],["Rovnou zahraniční rezervace odmítat.","Podmínka je splněna, kauza přes noc zemře, a nemovitost přijde o třicet procent tržeb ve prospěch konkurence o čtyři bloky dál."],["Účtovat zahraničním delegacím čtyřnásobek a nazvat to clem.","Cena pokoje zaznamenaná v rezervačním systému jako celní poplatek. Dvě velvyslanectví to zaplatí bez dotazu na tu položku, což vypovídá o velvyslanectvích úplně všechno."]]},"g-caravan":{"t":"Slovo pro to","x":"Několik tisíc lidí míří pěšky na sever. Duane má skutečná čísla, věkové složení. Brayden má slovo, a to slovo se v Duaneově zprávě nikde nevyskytuje.","c":[["Použít to slovo. Nasadit vojáky, ať je čekají.","Pět tisíc vojáků se nasadí na hranici, kterou skupina dosáhne o jedenáct týdnů později, kdy už se většina rozptýlila a vojáci jsou dávno doma."],["Použít to slovo. Nikoho nenasazovat.","Veškerá rétorika, žádné náklady. To slovo odvede celou práci, a Pentagon je potichu rád, že do toho nemusí jít."],["Uvést skutečná čísla. Řádně je zpracovat.","Čtyři tisíce lidí, většinou rodiny, zpracované za devět měsíců. Dvě třetiny jsou odmítnuty a vyhoštěny, přesně podle zákona, a nikoho to nezajímá natolik, aby to natočil."],["Poslat jim na hranici naproti pochodovou kapelu.","Nikdo nedokáže určit, co to gesto znamená, včetně vás. Čtyři dny se to rozebírá na třech kontinentech a dodnes to zůstává naprosto nevysvětlené."]]},"g-registry-quota":{"t":"Strop na jednu zemi","x":"Třetí verze omezení vstupu prošla přezkumem, protože je formulovaná kolem prověřování, nikoli národnosti. Muriel: „Je to identický seznam, pane. Přežil jen proto, že třetí návrh přidal odstavec o procesu.“","c":[["Rozšiřte ho, teď když rámec funguje.","Z devíti zemí je najednou čtrnáct. Odstavec o prověřování se pokaždé kopíruje slovo od slova a nikdy se doopravdy nezhodnotí, zda má vůbec smysl."],["Nechte to na devíti. Rámec nezkoušejte.","Zdrženlivost zrozená z čistě právní opatrnosti. Vydrží to čtyři roky, prostě proto, že nikdo soudu nedal důvod podívat se na to znovu."],["Nahraďte to skutečným prověřováním jednotlivých žadatelů.","Stojí to čtyři sta milionů dolarů, rozjezd trvá jedenáct měsíců a odmítá to víc lidí, než kdy dokázal seznam, a to na základě důvodů, které obstojí u každého soudního přezkumu."],["Přidejte zemi, která nemá vládu.","Nezůstal tam nikdo, kdo by mohl podat protest, což si čtyři úředníci pochvalně poznamenají, dokud se jeden z nich nezeptá, co bude s žadateli, kteří jsou už uprostřed letu."]]},"g-health-story":{"t":"Ten příběh o vašem zdraví","x":"Nějaké noviny otiskly článek o vašem zdraví, se zdroji od čtyř lidí přímo z budovy. Kaylee: „Není to špatně, pane. A přesně proto to nemůžu nechat opravit.“","c":[["Zaútočte na noviny. Nazvěte je nepřítelem lidu.","Příběhem se teď stává ten útok, ne vaše zdraví. Ta výměna funguje, ale funguje jen proto, že tím zároveň potvrdíte, že tam bylo co skrývat."],["Zveřejněte skutečné záznamy. Všechny.","Ukáže se, že jsou naprosto nezajímavé, dokonce trochu nudné. Jejich zveřejnění ukončí čtyři roky spekulací během jednoho odpoledne a Prine konečně dostane pokoj."],["Najděte ty čtyři zdroje. To je ten skutečný problém.","Dva se podaří odhalit a odstranit. Zbylí dva s vámi prostě přestanou mluvit a začnou si všechno zapisovat, což je mnohem horší."],["Vyzvěte šéfredaktora na fyzický souboj.","Je mu šedesát tři a okamžitě přijímá, s viditelným nadšením. K souboji nakonec nikdy nedojde. Oba pak roky tvrdíte, že to zrušil ten druhý."]]},"g-pool-slot":{"t":"Trvalé místo","x":"„Tiskové agentury mají trvalé místo v tiskovém poolu od osmdesátých let devatenáctého století. Ne ze zákona, ale ze zvyku.“ Kaylee zavírá složku. „Pool řídíme my, pane. Mohli bychom prostě přestat nějaký mít.“","c":[["Zrušte trvalé místo. Pool si vybereme sami.","Sto čtyřicet let zvyklosti skončí jedním e-mailem. Náhradníci jsou přívětivější, otázky měkčí a žádný zákon nebyl porušen, protože žádný zákon nikdy neexistoval."],["Přidejte k agenturám přátelská média.","Ředění místo odstranění. Agentury si podrží místo, ale ztratí monopol na první otázku, což bylo od začátku to jediné, na čem záleželo."],["Nechte to být. Ten zvyk přežije každého prezidenta.","Kaylee jedenáct minut v kuse argumentuje proti vlastnímu doporučení a je viditelně, slyšitelně ulevená, že prohrává."],["Dejte trvalé místo studentským novinám ze střední školy.","Sedmnáctiletá dívka z Daytonu ve čtvrtém týdnu na place položí jednoznačně nejlepší otázku roku a čtyři televizní stanice s ní otevírají zpravodajství."]]},"g-summit-praise":{"t":"Společné prohlášení","x":"Stojíte na pódiu vedle hlavy státu, kterou vaše vlastní tajné služby obvinily z vměšování, a v přímém přenosu se vás ptají, čí verzi věříte. Hance to sleduje ze vzdálenosti necelých dvou metrů.","c":[["Řekněte, že nevidíte důvod, proč by to měli být oni.","Členové vaší vlastní strany vydávají prohlášení dřív, než stačíte sejít z pódia. Celý následující den vysvětlujete, že jste tam měl vlastně říct slovo „ne“."],["Postavte se za vlastní služby. Rovnou. Na pódiu.","Devět slov, pronesených přímo vedle něj, bez jediné výhrady. Hance nijak nereaguje, což je u Hance ekvivalent standing ovace."],["Odmítněte otázku. Mluvte o obchodní dohodě.","Odbočka tak zjevná, že si jí všimne každý, ale nikdo z ní nemůže přímo citovat. Je to správná odpověď a neuspokojí naprosto nikoho."],["Řekněte, že věříte oběma verzím zároveň.","V jedné jediné větě záměrně zastáváte dvě naprosto protichůdná stanoviska a vyzýváte kohokoli, ať si jedno vybere. Čtyři redakce otisknou celý citát, protože shrnout ho prostě nejde."]]},"g-tariff-autos":{"t":"Pětadvacet procent","x":"Čtvrtinové clo na dovážená vozidla a díly. Lyle: „Čtyřicet procent auta vyrobeného v téhle zemi tvoří dovážené díly. My to prezentujeme jako obranu domácí výroby, přitom je to daň na domácí výrobu.“","c":[["Zaveďte ho. Všechna vozidla, všechny díly.","Náklady na domácí montáž vzrostou o jedenáct set dolarů na kus. Čtyři továrny odloží rozšíření. Oznámení je přitom nesmírně populární přesně v těch městech, kde ty továrny stojí."],["Jen vozidla. Díly vyjměte.","Verze, kterou by skutečně sepsal ekonom. Chrání montáž, šetří dodavatelský řetězec a je tak z třetiny stejně uspokojivá při hlasitém oznámení."],["Osmnáct měsíců jím hrozte. Nikdy ho nezavádějte.","Vymůžete si čtyři ústupky od tří vlád za clo, které nikdy fakticky neexistovalo. Je to ta nejvýnosnější věc, kterou nikdy neuděláte."],["Zdaňte jen auta jedné konkrétní barvy.","Celní úřad musí formálně rozhodovat o odstínech barvy. Čtyři dovozci přestříkají auta přímo v přístavu během pár dní a výsledný celní sazebník má devadesát stran názvů barev."]]},"g-six-cities":{"t":"Šest měst","x":"Šest měst, šest guvernérů, čtyři z nich odmítli souhlas. Tarrant: „Šest zvládnu, pane. Těch šest není problém. Problém je sedmé. Vždycky existuje nějaké sedmé.“","c":[["Všech šest. Najednou.","Logisticky to funguje, ve všem ostatním to selhává. Do čtvrtého měsíce stojí nasazení tři sta třicet dva milionů dolarů a je souběžně žalováno u pěti odvolacích obvodů."],["Dvě města. Ta, co o to sama požádala.","Nasazení se souhlasem se ukáže jako nekontroverzní, účinné a v celostátním zpravodajství naprosto neviditelné."],["Žádné. Místo toho profinancujte místní policii.","Miliarda dvě stě milionů dolarů do rozpočtů městské policie. Kriminalita ve čtyřech ze šesti měst za dva roky klesá a všichni zúčastnění starostové si připisují plnou zásluhu."],["Nasaďte jednotky do sedmého města, o kterém nikdo nemluvil.","Město s devíti tisíci obyvateli, kde nejsou žádné nepokoje. Jeho starosta svolá tiskovku, aby se upřímně zeptal, co přesně se to jeho městu děje."]]},"g-stand-down":{"t":"Tichý ústup","x":"Čtyři soudy rozhodly proti vám a pátý je na řadě. Duane připravil prohlášení o stažení jednotek, které popisuje nasazení jako splnění všech cílů. „Pane, tu větu nikdo neuvěří. Ale taky ji nikdo nebude žalovat.“","c":[["Stáhněte se. Vyhlaste naprostý úspěch.","Všechno skončí v úterý, dvouodstavcovým prohlášením. Je to nejlevnější varianta ústupu na stole a byla k dispozici od samého začátku, což je to nepříjemné na celé věci."],["Stáhněte se a poviňte konkrétní soudy jmenovitě.","Ustupujete a útočíte zároveň, což udrží základnu spokojenou, ale páté rozhodnutí, až přijde, dopadne mnohem tvrději, než muselo."],["Eskalujte to až k pátému případu. Ani nemrkněte.","Prohrajete sedm ku dvěma, s většinovým stanoviskem, které se bude citovat třicet let, a doktrínou, která nakonec ponese jméno přesně tohohle případu."],["Stáhněte se a přeřaďte vojáky ke správě národních parků.","Čtyři tisíce vojáků stráví léto opravou turistických stezek. Je to zdaleka nejoblíbenější věc, kterou celé nasazení kdy přineslo, a někdo vážně navrhne, aby to zůstalo natrvalo."]]},"g-competitive":{"t":"Odborný termín","x":"Tři politologové zabývající se komparativní politologií publikovali text, podle nějž země překročila jistou hranici. Dr. Weirová: „Ten termín zní kompetitivní autoritářství, pane. Je to odborný pojem. Má svůj kontrolní seznam. My splňujeme většinu bodů.“","c":[["Přijměte ten termín. Noste ho jako odznak. Prodávejte na něj klobouky.","Proměna diagnózy v merchandising ji zneškodní pro vaše příznivce a zároveň potvrdí pro všechny ostatní, výměna, kterou uděláte bez sebemenšího zaváhání."],["Nechte ty akademiky pozvat dovnitř. Diskutujte s nimi.","Devadesát minut, na záznam, proti třem akademikům, kteří přečetli víc historie než všichni v budově dohromady. Viditelně prohrajete a nějakým způsobem to vypadá lépe, než kdybyste vyhrál."],["Ignorujte to. Akademici se už spletli i dřív.","To se stalo. Tentokrát se ale nemýlí, kontrolní seznam je teď veřejný a srovnání si může udělat úplně kdokoli."],["Zeptejte se, které body kontrolního seznamu vám ještě chybí.","Ptáte se upřímně. Zbývají čtyři body. Deborah vás sleduje, jak si je zapisujete, a týden pořádně nespí."]]},"g-anticipatory-two":{"t":"Univerzita","x":"Druhá univerzita se sklonila, ještě než bylo skutečně zmrazeno jakékoli financování, ještě než byl odeslán jediný dopis. Ollis: „Přečetli si, co se stalo té první, a spočítali si to. Nikdo z týhle budovy s nimi vůbec nemluvil.“","c":[["Zveřejněte to. Ať je ten výpočet jasný i všem ostatním.","Devět dalších institucí se do roka srovná do latě, aniž byste je jedinkrát oslovil. Je to ta nejlevnější moc, jaká existuje, a nemusíte pro ni hnout ani prstem."],["Neříkejte nic. Ať to dál probíhá potichu.","Neviditelná poslušnost má větší cenu než ta viditelná, protože na ni nemá nikdo co namířit kameru."],["Řekněte jim veřejně, že to nebylo nutné.","Jedna ze dvou škol se do dvou týdnů vrátí zpátky. Druhá ne, a její rektor soukromě přizná, že se už neodváží zkusit se vrátit."],["Pošlete jim dodatečně dopis s požadavky.","Formální požadavek na ústupky, které už udělaly. Dopis je podán, zodpovězen a splněn podruhé, a nikdo ze zúčastněných neumí vysvětlit proč."]]},"g-officers-pardon":{"t":"Dva policisté","x":"Dva policisté odsouzení za honičku, při které zemřel muž. Bo má záznam z procesu. „Odsouzení je právně v pořádku, pane. Tresty jsou možná přehnaně tvrdé. To jsou ale dvě různé věci a jen jedna z nich znamená milost.“","c":[["Plná milost. Oběma. Oznamte to na policejní akci.","Rodina se to dozví z vysílání, stejně jako všichni ostatní. Čtyři policejní odbory vás do měsíce podpoří, město, kterému ti policisté sloužili, ne."],["Zmírněte tresty. Odsouzení nechte platit.","Užší krok, ten, který skutečně řeší podstatu věci. Získáte polovinu uznání za desetinu hněvu."],["Nic. Slyšela to porota, ne vy.","Správná odpověď, která vás stojí čtyři procentní body u voličů, kteří ještě žádnému prezidentovi neodpustili použití téhle konkrétní pravomoci."],["Udělte jim milost a jmenujte je do revizní komise.","Dva muži omilostnění za způsobení smrti teď sedí přímo v komisi, která smrtelné případy posuzuje. Jmenování je legální, ironie zůstává bez povšimnutí a čtyři členové okamžitě rezignují."]]},"g-vacancies-act":{"t":"Všechno jen pověřeně","x":"„Jedenáct vysokých pozic, všechny obsazené pověřenými úředníky. Zákon stanovuje strop, jak dlouho to smí trvat.“ Sy pokrčí rameny. „Následkem překročení stropu je, že jejich rozhodnutí jsou neplatná. Nikdo se ale nikdy neodvážil žádat soud, aby zneplatnil čtyři roky činnosti úřadu.“","c":[["Řiďte celou vládu pomocí pověřených úředníků.","Náprava, kterou se nikdo neodváží použít, fakticky žádnou nápravou není. Jedenáct úřadů čtyři roky řídí lidé, které Senát nikdy neviděl, a argument o neplatnosti se nikdy neprověří."],["Nechte potvrdit ty čtyři, na kterých záleží. Zbytek nechte pověřeně.","Potvrzená čtyřka vám dá legitimitu, pověřená sedmička rychlost. Je to verze, která přežije skutečné slyšení."],["Navrhněte kandidáty na všech jedenáct pozic. Přijměte boje o potvrzení.","Trvá to čtrnáct měsíců a dva boje prohrajete. Devět kandidátů, kteří to zvládnou, pak už váš nástupce nemůže odvolat jedním telefonátem."],["Jmenujte jednu osobu na všech jedenáct pozic.","Je mimořádně schopná a čtyři měsíce pracuje devatenáct hodin denně, než vám dopisem oznámí, že tohle prostě nikdy nemohlo fungovat."]]},"g-inspector-report":{"t":"Zpráva, kterou nikdo nečte","x":"Soudce rozhodl, že odvolání byla nezákonná, ale odmítl kohokoli vrátit do funkce s odůvodněním, že byste to stejně provedl znovu, jen s řádným oznámením. Miriam: „Bylo shledáno, že jste porušil zákon, pane, a přesto si výsledek podržíte.“","c":[["Citujte rozhodnutí jako své ospravedlnění.","Rozhodnutí proti vám, které nic doopravdy nemění, což je dost blízko výhře na to, aby to nahlas prohlásit fungovalo asi u čtyřiceti procent země."],["Splňte to zpětně. Dejte řádné oznámení. Propusťte je znovu.","Třicet dní papírování přinese naprosto stejný výsledek, tentokrát zcela legálně. Proces nikdy nebyl tou překážkou a teď je to oficiálně zdokumentováno."],["Vraťte je zpátky a nechte je dokončit funkční období.","Jedenáct ze sedmnácti se vrátí. Čtyři z jejich následných zpráv vám mimořádně uškodí, dvě vás ale zachrání před něčím podstatně horším."],["Odvolejte se proti rozhodnutí, které jste už vyhrál.","Vaši vlastní právníci stráví devět týdnů vysvětlováním, že se už nemáte proti čemu odvolávat. Přesto jim to nařídíte a odvolání je za čtyři dny zamítnuto jako bezpředmětné."]]},"g-schedule-numbers":{"t":"Dva miliony jmen","x":"„Nabídka šla na každého federálního zaměstnance. Dva miliony tři sta tisíc lidí. Rezignujte hned, plat vám poteče až do září.“ Deborah má čísla přijetí. „Přijalo to sedmasedmdesát tisíc lidí, pane. A jsou to přesně ti, které jsme si nejméně mohli dovolit ztratit.“","c":[["Zopakujte to. Ve větším. Přidejte ještě něco navrch.","Odejde dalších šedesát tisíc. Lidé, kteří mají kam jít, odcházejí vždy jako první, což znamená, že každé kolo dělá zbývající pracovní sílu menší, slabší a poslušnější."],["Uzavřete nabídku. Nechte si ty, kdo zůstali.","Krvácení se zastaví na sedmasedmdesáti tisících. Úřad pro personální řízení odhaduje náklady na nahrazení na devět miliard dolarů za šest let a ten odhad si nikdo nepřečte."],["Zacilte to. Nabídněte to jen tam, kde chcete snížit počty.","Přesnost místo plošné brokovnice. Dosáhnete stejného snížení stavů přesně tam, kde jste chtěl, a řídící letového provozu vám zůstanou."],["Nabídněte to sám sobě a uvidíte, co se stane.","Formulář nemá kolonku pro vaši pozici. Referentka z personálního oddělení stráví čtyři dny snahou to zpracovat, než to konečně předá právnímu oddělení."]]},"g-doge-cuts":{"t":"Číslo na obrazovce","x":"Vandermeer provozuje na webu živé počítadlo, které tvrdí, že se ušetřilo dvě stě čtrnáct miliard dolarů. Lyle prověřil jedenáct největších položek. „Čtyři jsou započítané dvakrát, tři jsou smlouvy, které už stejně vypršely, a jedna je o tisíc řádů mimo.“","c":[["Nechte počítadlo běžet. Zaokrouhlete nahoru.","Do jara číslo dosáhne tří set miliard. Každý novinář, který si to ověří, najde stejné chyby, a každá oprava se dostane asi ke čtyřicetině původního publika."],["Zveřejněte metodiku. Ať si to všichni ověří.","Ověřená částka činí devatenáct miliard dolarů, opravdu obrovská suma, kterou ale nikdo neocení, protože to není dvě stě čtrnáct miliard."],["Potichu počítadlo sundejte.","Do hodiny ho zarchivují čtyři různé služby, stejně jako všechno ostatní, navždy."],["Přidejte počítadlo peněz utracených za hledání těch úspor.","Druhé počítadlo předežene první během jedenácti týdnů. Vandermeer potichu odstraní obě a zveřejní graf o něčem úplně jiném."]]},"g-final-audit":{"t":"Dlouhé sčítání","x":"Dr. Weirová má součet: sedm set padesát tři samostatných žalob podaných proti vaší administrativě. „Pro srovnání, pane, to je víc než za předchozí čtyři prezidentská období dohromady. Nekomentuji to, jenom počítám.“","c":[["Zarámujte si to. Dokazuje to, kolik jste se toho pokusil udělat.","Číslo dáte na plakát. Je to opravdu důkaz ambicí, a zároveň důkaz všeho, co tvrdí druhá strana, a obě čtení se odvolávají na naprosto stejné číslo."],["Zeptejte se, které jste prohrál a proč.","Ve věci samé jste prohrál čtyřicet jedna procent, drtivá většina kvůli procesním chybám, ne kvůli obsahu. Čtyři zbývající politiky se ten samý měsíc přepíší a všechny čtyři obstojí."],["Řekněte, že to číslo dokazuje politizaci soudů.","Šedesát jedna procent rozhodnutí proti vám napsali soudci, které jmenovala vaše vlastní strana. Dr. Weirová má i tohle číslo, nabídne vám ho, a vy ho odmítnete přijmout."],["Požádejte ji, ať počítá dál i poté, co odejdete.","Počítá dál. Závěrečný svazek má devět set stran, vychází v roce 2044 a je věnován, bez sebemenší zjevné ironie, vám."]]},"h-tariff-boomerang":{"t":"Bumerang","x":"Lyle má seznam odvetných opatření. „Odpověděli nám položku za položkou, pane, a pak přidali bourbon, motorky a jednu konkrétní značku lodí. Všechno se vyrábí ve státech, které jste vyhrál. Musím uznat, že je to nádherně cílené.“","c":[["Zdvojnásobte clo. Nikdo nás nepřetvrdí.","Eskalace nadchne mítink a vyprázdní přístaviště. Obojí je pravda zároveň a základna vidí jen ten mítink."],["Lodě potichu vyjměte z výjimky. Proslov si nechte.","Výjimka se zahrabe v páteční administrativní podání, zatímco tvrdá rétorika zůstává v televizi. Celá práce, odvedená dobře, a nikdo si toho nevšimne."],["Za lodě obviňte minulou administrativu.","Přisoudíte clo na lodě, které jste sám způsobil, prezidentovi, který odešel před lety. Zhruba polovina země to okamžitě přijme za pravdu."],["Prohlaste bourbon strategickou národní zásobou.","Prezidentský dekret prohlásí whisky za záležitost národní bezpečnosti. Čtyři palírny jsou nadšené a jeden čtyřhvězdičkový generál se upřímně ptá, jaká je v tom jeho role."]]},"h-summit-selfie":{"t":"Fotka z podání ruky","x":"Muriel drží dvě fotografie. „Tohle je to podání ruky, pane. Čtyřicet milionů zhlédnutí. A tohle je skutečné komuniké. Zavazuje nás to k pracovní skupině, která se sejde nejdřív na jaře příštího roku. Základna viděla tu první. Senát četl tu druhou.“","c":[["Prodávejte podání ruky. Pracovní skupinu zahrabejte.","Fotka se ve všech praktických ohledech stává politikou samotnou. Nic nebylo dohodnuto a přesto má každý pocit, že se stalo něco obrovského."],["Ať Muriel věcně vysvětlí skutečné podmínky.","Pravda je malá, skutečná a nudná, a takhle se o ní i informuje. Podání ruky navzdory tomu záhadně dál trenduje."],["Oznamte druhý summit, na kterém proberete ten první.","Summit o summitu. Kancelář pro plánování schůzek pláče. Základna se nemůže dočkat."],["Nechte to podání ruky odlít do bronzu pro vstupní halu.","Sochař vyrobí stisk rukou v životní velikosti do haly Západního křídla. Návštěvníci nevědí, jestli si s ním mají potřást. Někteří to udělají."]]},"h-late-call":{"t":"Telefonát ve dvě ráno","x":"Deborah to zachytila v protokolu. „Volal jste vůdci spřátelené země ve dvě ráno jejich času, pane, abyste mu řekl, jak úžasně vypadá nový sál. Spal. Hovor trval devatenáct minut. Většinu z toho jste mluvil vy.“","c":[["Udělejte to zítra znovu. Líbilo se jim to.","Zavedete si noční zvyk nevyžádaných architektonických aktualizací pro spící hlavy států. Dva z nich to začnou přepojovat do hlasové schránky."],["Ať každý hovor jde nejdřív přes Deborah.","Mezi vás a telefon ve tři ráno se instaluje filtr. Je to zdaleka nejcennější personální rozhodnutí celého funkčního období."],["Popřete ten hovor. Sveďte to na časová pásma.","Tvrdíte, že jste se spletl v hodinách. Protokol má ale časové razítko. Slovo „časové razítko“ vám zkazí celé ráno."],["Příští hovor odvysílejte živě.","Dva miliony lidí sledují, jak viditelně vyčerpanému premiérovi popisujete stropní lišty. Je to nějakým způsobem vaše nejsledovanější vysílání roku."]]},"h-parade-itch":{"t":"Svrbění","x":"Generál Tarrant stojí v pohovu, což je u něj forma zděšení. „Ptal jste se mě tento týden třikrát, k čemu vlastně armáda *je*, pane, když ji nikdy nepoužijeme. Chci mít jasno v tom, že tohle není otázka, kterou bych chtěl slyšet od prezidenta v ospalé úterý.“","c":[["Nařiďte přehlídku. Největší v historii. Tento víkend.","Bulvár beztak nebyl stavěný na to, aby po něm jezdily tanky. Fotky jsou nádherné a inspektor mostů sepíše hlášení."],["Nic. Nechte generálovi jeho úterý.","Armádu z nudy nenasadíte. Tarrant viditelně omládne. Je to správné rozhodnutí a nikdo netleská."],["Místo toho přejmenujte vojenskou základnu po sobě.","Ceremonie, nová cedule, levnější druh slávy. Svrbění je poškrábané a nikdo kvůli tomu nemusí být nasazen."],["Zřiďte novou složku armády pro vesmír.","Vznikne nová vojenská složka, jejíž logo do týdne žaluje jedna streamovací franšíza. Rekruti jsou bez výjimky nadšení."]]},"h-upkeep-bill":{"t":"Údržba","x":"Alvin předkládá účetní knihu s péčí muže, který zneškodňuje bombu. „Jen lustry v sále, pane. A horská dráha vyžaduje certifikovanou inspekci každých devadesát dní, což prý platí i pro horskou dráhu na střeše. Vlastně obzvlášť pro horskou dráhu na střeše.“","c":[["Zaplaťte to. Velkolepost není položka v rozpočtu.","Účty jsou zaplaceny v plné výši a včas a budova se leskne. Ministr financí vydá tichý zvuk a opustí místnost."],["Odložte inspekce. Co se může stát.","Zrušíte bezpečnostní certifikaci horské dráhy na střeše. Čtyři úřady si otevřou spisy a jeden stážista se z principu odmítne svézt."],["Zaveďte vstupné do sálu.","Dům lidu se na chvíli stane místem se vstupným. Historička rezignuje faxem, dokumentem, jehož odeslání se musela nejdřív naučit."],["Přidejte suvenýrový obchod. Pak ještě dva.","O tři obchody se suvenýry, vozík s churros a fotokoutek později generuje rezidence měsíční zisk a památková komise dostává infarkt."]]},"h-merch-drop":{"t":"Nová kolekce","x":"Brayden je celý bez sebe. „Zlaté tenisky, pane. Pak parfém. Pak pamětní mince, pak Bible, a pak mince *s motivem* Bible. Každá kolekce se vyprodá během minut. Základna to nekupuje ironicky. Kupují si to tak, jak lidé kupují relikvie.“","c":[["Vypusťte všechno. Nový kousek každý týden.","Relikvie se množí a s nimi i oddanost. Jedna ekonomka to nazve kultem osobnosti s vynikající jednotkovou ekonomikou. Nemýlí se."],["Jeden vkusný kousek. Výtěžek pro veterány.","Zdrženlivost s charitativním přesahem. Tisk je na chvíli laskavý a základna se na chvíli nudí, oba pocity ale do čtvrtka pominou."],["Dejte svou tvář na skutečnou měnu.","Pokusíte se objevit na zákonném platidle. Mincovna vám nejprve jemně, pak rázně vysvětlí několik příslušných zákonů. Tenisky vám zůstanou."],["Spusťte memecoin. $PATRIOT. Dnes večer.","Vystřelí, spadne, do snídaně zase vystřelí. Někdo hodně aktivní na internetu vydělá a ztratí jmění ještě dřív, než začne ranní brífink."]]},"h-injunction":{"t":"Celostátní soudní zákaz","x":"Sy pokládá usnesení na stůl. „Jeden soudce, pane. V jedné soudní síni, ve státě, kde jste prohrál o třicet bodů, zmrazil celou věc na celostátní úrovni. Máte na výběr, buď se slušně odvolat, nebo říct o tom soudci něco, za co se pak měsíc budeme omlouvat.“","c":[["Jmenujte toho soudce. Zpochybňujte ho. Každý večer.","Z okresního soudce uděláte celostátně známé jméno a terč. Soudní systém se semkne tak, jako se tělo semkne kolem třísky."],["Odvolejte se. Přímo, rychle, nudně.","Právníci si tiše a dobře dělají svou právnickou práci. Věc postupuje po žebříčku soudů podle podstaty a základna se nikdy nedozví slovo „odklad“."],["Ignorujte to usnesení. Pokračujte i tak.","Chováte se, jako by soudní příkaz bylo pouhé doporučení. Je to zdaleka nejrychlejší způsob, jak naučit národ, jak vypadá ústavní krize."],["Jmenujte toho soudce na nějakou funkci. Hodně daleko.","Pokusíte se svůj problém povýšit na velvyslanecký post v chladné zemi. Soudce to nádherně, písemně odmítne, a informace unikne na veřejnost."]]},"h-leak-hunt":{"t":"Hon na únik informací","x":"Ředitelka Quistová je vyrovnaná. „Ten detail, co unikl, mohl přijít jen od jednoho z šesti lidí v té místnosti, pane. Všech šest je loajálních. V tom je ten problém: ten únik pramení z loajality. Někdo si myslí, že vás chrání tím, že vás vykreslí jako rozhodného. Není to tak.“","c":[["Podrobte všech šest detektoru lži. Ještě dnes.","Zapojíte své nejbližší poradce do přístroje se spornou spolehlivostí. Nikdo neselže a všichni si to budou pamatovat. Příští únik informací se bude týkat přímo detektorů lži."],["Nechte to být. Únik potichu utěsněte později.","Odmítnete hon na čarodějnice a místo toho opravíte proces. Je to zralé, účinné a naprosto neviditelné, jako všechno, co skutečně funguje."],["Uniknout nechte něco horšího o rivalovi, ať se to přebije.","Zorganizujete protiúnik. Příběh, který jste chtěl pohřbít, přebije jiný příběh, ze kterého se budete zodpovídat za šest týdnů. Vždycky to tak dopadne."],["Nastražte reportérovi falešný detail jako past.","Nastražíte kanárka. Otiskne se to. Právě jste potvrdil existenci úniku tím, že jste jeden sám vyrobil, což i Quistovou filozoficky znepokojuje."]]},"h-loyalty-oath":{"t":"Přísaha věrnosti","x":"Deborah je opatrná. „Ten nápad, co koluje, pane, je podepsaný slib. Osobní loajalita, písemně, nadřazená přísaze, kterou už složili úřadu. Někteří to podepíšou bez váhání. Ti, o které stojí za to usilovat, spíš rezignují, jakmile je o to požádáte.“","c":[["Rozešlete ten slib. Uvidíte, kdo se zarazí.","Schopní odejdou, poslušní zůstanou a průměrné IQ budovy měřitelně klesne. Základna tomu říká vypouštění bažiny."],["Žádný slib. Přísaha úřadu je jediná přísaha.","Odmítnete se v podepsaném dokumentu postavit nad ústavu. Historici o desítky let později to shledají naprosto nezajímavým, což je celý smysl."],["Ať přísahají vlajce. Stejná energie, lepší dojem.","Vlastenecký přebal téhož požadavku. Skvěle se to fotí a znamená to přesně to, co si všichni myslí."],["Ať přísahají na novou pamětní Bibli.","Přísaha věrnosti zároveň slouží jako product placement. Pastor je nadšený, právníci ne, a Bible se dočká dalšího dotisku."]]},"h-bad-poll":{"t":"Špatný průzkum","x":"Nadia to nezabaluje do bavlnky. „Je to skutečný průzkum, pane, se skutečnou metodikou, a to číslo je špatné. Můžete zaútočit na agenturu, což zabere na základnu a jen na základnu, nebo se podívat, proč je to číslo špatné, což tady v budově nikdo nedělá rád.“","c":[["Prohlaste průzkum za podvrh. Odkažte na vlastní, lepší.","Vytvoříte interní průzkum se vzorkem lidí, kteří s vámi už souhlasí. Základna ho okamžitě přijme a realita se ani nehne."],["Prostudujte podrobné výsledky. Změňte jednu politiku.","Necháte data ovlivnit rozhodnutí. Je to ta nejméně dramatická věc, jakou může vůdce udělat, a zároveň jedna z nejvzácnějších, a potichu to posune skutečné číslo."],["Objednejte deset průzkumů, dokud jeden nevyjde dobře.","Kupujete pokusy, dokud jeden nevyjde příznivě, a pak citujete jen ten. Je to drahé, průhledné a naprosto účinné u vlastních příznivců."],["Udělejte průzkum o tom, jestli lidé věří průzkumům.","Průzkum o průzkumech přinese výsledek příliš rekurzivní na to, aby ho kdokoli dokázal vyložit. Dva komentátoři si na té nejednoznačnosti vybudují celou kariéru."]]},"h-deepfake":{"t":"Přesvědčivý podvrh","x":"Kaylee je bledá. „Není to skutečné, pane. To video s vámi je od začátku do konce vyrobené, a je to bezchybné. Problém je druhého řádu: teď, když všichni vědí, že existují takhle dobré podvrhy, můžete cokoli skutečného označit za falešné a cokoli falešného za skutečné. Ztratili jsme schopnost si být čímkoli jistí, a stejně na tom je i každý ostatní.“","c":[["Nazývejte každé nelichotivé video podvrhem, navždy.","Nástroj si osvojíte jako trvalé alibi. Pravda se stane otázkou loajality, což je na chvíli nesmírně výhodné, a pak přestane být."],["Podpořte skutečný standard ověřování. Nudné. Zásadní.","Podpoříte nudný technický rámec pro ověřování záznamů. Je to nejdůležitější věc, kterou za celý rok uděláte, a najde se o ní zmínka na devatenácté straně."],["Vypusťte vlastní podvrh, o rivalovi.","Záměrně eskalujete situaci do světa, kde se nedá věřit ničemu, protože mlha nahrává tomu, kdo je nejhlasitější. Nahrává vám, dokud nepřestane."],["Nasaďte umělou inteligenci, která vaším hlasem vyvrací podvrhy.","Syntetická verze vás sama ověřuje faktickou přesnost jiné syntetické verze vás. Někde jedna filozofická katedra zruší vlastní konferenci, jen aby to mohla sledovat."]]},"h-nobel-itch":{"t":"Cena","x":"Muriel šlape opatrně. „Výbor nepřijímá nominace od samotného nominovaného, pane. A rozhodně nepřijímá sedm nominací, které jste podal sám na sebe. Existuje ale mír, který byste mohl skutečně zprostředkovat a který by si to časem mohl zasloužit. Vyžadovalo by to ale, abyste nechal u pódia stát někoho jiného.“","c":[["Nominujte se znovu. Hlasitěji.","Osmá vlastní nominace se podá spolu s tiskovou zprávou. Výbor, který viděl už úplně všechno, tohle úplně neviděl, a mlčí, nákladně."],["Zprostředkujte to doopravdy. Ať zazáří vyslanec.","Odvedete trpělivou práci skutečné diplomacie, kde se zásluhy sdílejí. Za pár let by za to mohla dokonce být cena, což je přesně důvod, proč je to teď tak těžké udělat."],["Založte si vlastní cenu. Udělte ji sám sobě.","Nová medaile, nový výbor, předem daný výsledek. Základna je dojatá. Starý výbor zůstává, nápadně, dál v Oslu."],["Prohlaste, že jste ji tajně už vyhrál.","Oznámíte utajenou cenu, kterou nelze z důvodu národní bezpečnosti ověřit. Zhruba třetina země si to zařadí do šuplíku „nejspíš pravda“."]]},"i-ukraine-war":{"t":"Čí válka to vlastně je","x":"Muriel rozprostírá mapu. „Rusko dál drtí Ukrajinu, pane, a všichni v té místnosti chtějí vědět, na čí straně stojíte. Základna chce, aby peníze přestaly proudit. Spojenci chtějí, aby proudily dál. Prezident Volkov chce telefonát. Ať řeknete v příští hodině cokoli, stane se to politikou.“","c":[["Podpořte Ukrajinu. Vyzbrojte ji, nahlas.","V přímém přenosu se postavíte za Kyjev. Aliance je nadšená, základna se nudí a faktury jsou obrovské."],["Místo toho ujednejte dohodu s Volkovem.","Vynecháte spojence a zavoláte přímo agresorovi. Dohodne se „rámec“, u kterého nikdo jiný nebyl. Základna miluje silného muže, který zvedne váš telefonát."],["Zprostředkujte mír. Přiberte si zásluhy.","Prohlásíte se za jediného muže, který to dokáže ukončit. Naplánuje se summit. Nic se nepodepíše, ale slovo „Nobelova“ padne nahlas, z vašich úst."],["Odstupte od toho. Není to náš kontinent.","Prohlásíte to za evropský problém a odstoupíte. Základna jásá nad úsporností. Tři hlavní města si potichu začínají domlouvat vlastní ujednání."]]},"i-taiwan":{"t":"Ten ostrov, co má každý na mysli","x":"Generál Tarrant má satelitní záběry. „Předseda Čchen pořádá kolem ostrova zatím největší cvičení, pane. Je to zkouška a chce, abychom věděli, že je to zkouška. Můžeme propluot letadlovou lodí úžinou, nebo si najít něco naléhavého jinde. Obojí si všimnou.“","c":[["Propluje letadlová loď úžinou. Pomalu.","Sto tisíc tun šedé oceli si vybere malebnou trasu skrz úžinu. Nic se nestane, nákladně a záměrně."],["Prodejte Tchaj-wanu úplně všechny zbraně z katalogu.","Vyzbrojíte ostrov až po zuby a naúčtujete mu za tu výsadu. Peking zuří, vaši zbrojní dodavatelé po vás pojmenují křídlo výrobního závodu."],["Ujistěte Čchena, že je to „jedna země“, a zavěste.","Vyřknete frázi, kterou chtěl slyšet, a ukončíte hovor. Obchodní oddělení si oddechne. Tchaj-pej si přepis přečte dvakrát."],["Zveřejněte na sociální síti mapu. Ať si domýšlejí.","Zveřejníte mapu bez jediného popisku. Šest vlád svolá mimořádná zasedání, aby ji vyložily. Nemyslel jste tím vůbec nic. Málokdy tím něco myslíte."]]},"i-iran-enrich":{"t":"Centrifugy","x":"Šéfka tajné služby mluví bez emocí. „Írán je blízko, pane. Naši lidé odhadují dva týdny od prahové hodnoty. Můžeme udeřit na zařízení a zpozdit je o tři roky, můžeme je udusit sankcemi, nebo jim můžeme nabídnout dohodu, kterou nedokázali sjednat poslední tři prezidenti. Každá možnost vám udělá dva přátele a jednoho nepřítele.“","c":[["Udeřte na zařízení. Ještě dnes v noci.","Zařízení je do svítání sutina a region je do poledne sud s prachem. Základna tomu říká síla. Zálivové státy volají svým aerolinkám."],["Sankcemi je uvrhněte zpátky do doby kamenné.","Odříznete je od všeho, co má drát. Jejich ekonomika se hroutí, jejich program ne. Je to pomalé, popíratelné a nekonečné."],["Sjednejte dohodu, kterou nikdo jiný nedokázal.","Podepíšete dohodu, kterou poslední tři prezidenti nedokázali sjednat, a vyzýváte kohokoli, ať ji nazve slabošskou. Polovina z nich to okamžitě udělá."],["Prodejte to potichu oběma stranám.","Nějakým způsobem změní majitele jmění a Teherán i jeho nepřátelé věří, že stojíte při nich. Čtyři etické komise si otevřou spisy přímo během podpisu."]]},"i-nato-dues":{"t":"Pošlete fakturu","x":"Muriel má zasedací pořádek. „Jsou tu všichni, pane, a všichni jsou nervózní, přesně tak, jak je má základna ráda. Můžete znovu potvrdit závazek je bránit, můžete je nechat platit napřed, nebo můžete jen naznačit, jen naznačit, že celé to ujednání je volitelné. Už jen ten náznak hýbe trhy.“","c":[["Znovu potvrďte závazek. Pevně. Nudně.","Řeknete, že smlouva znamená přesně to, co v ní stojí. Spojenci spí klidně, základna zívá, nikdo nesloží píseň o Článku 5."],["„Zaplaťte svůj podíl, pak si promluvíme.“","V přímém přenosu proměníte obrannou dohodu ve fakturu. Dvě vlády náhle oznámí nové výdaje. Základna zbožňuje muže, který donutí přátele platit."],["Naznačte, že celé to ujednání je volitelné.","Nahlas pochybujete, jestli byste se opravdu dostavil. Ten náznak je politikou. Někde nějaká menší země začíná vlastní jaderný program."]]},"i-arctic":{"t":"Vrchol mapy","x":"Lyle má mapu, která je tam, kde bývala bílá, teď hlavně modrá. „Arktida se otevírá, pane. Pod tím ledem je století vzácných zemin a obchodní trasa v hodnotě HDP celé země. Rusko zapíchlo vlajku na mořské dno. Grónsko, ehm, technicky není na prodej. Všichni jsou nesmírně zdvořilí a kupují ledoborce.“","c":[["Předložte Grónsku nabídku, kterou nemůže odmítnout.","Předložíte finanční nabídku za ostrov, který stále tvrdí, že není na prodej. Základna je nadšená. Kartografové zatím nic neaktualizují."],["Zapojte se do závodu s Ruskem o mořské dno. Stavte ledoborce.","Objednáte flotilu, jejímž jediným posláním je drtit led. Je to drahé, pomalé a, upřímně řečeno, skutečná strategie."],["Domluvte si s Volkovem polární rozdělení.","Vy a Volkov si v tichosti rozdělíte oceán, který nepatří ani jednomu z vás. Mapa se překreslí nad večeří. Šest dalších arktických zemí se to dozví až později."]]},"i-coup":{"t":"Muž na balkoně","x":"Šéfka tajné služby má noční hlášení. „Došlo k převratu, pane, v zemi, kterou potřebujeme kvůli naší tamní základně. Nový muž stojí na balkoně, má na sobě spoustu medailí a tvrdí, že je vaším velkým obdivovatelem. Stará vláda se z neznámého místa ptá, jestli ji ještě uznáváme.“","c":[["Uznejte generála. Obdivuje vás.","Jste první, kdo tomu balkonu poblahopřeje. Základna má ráda muže, kterému se líbíte. Tři demokracie potichu sníží úroveň svých velvyslanectví."],["Odsuďte to. Požadujte volby.","Z principu uděláte to správné, nudné rozhodnutí. Základna vás nechá chladnou a posádka na vaší zahraniční základně je nervózní. Historie přikývne a jde dál."],["Neříkejte nic, dokud neuvidíte průzkumy.","Počkáte, kterým směrem se to ustálí, než se zavážete k nějakému názoru. Je to cynické, bezpečné a podle důkazů i typický rukopis tohohle úřadu."]]},"i-trade-bloc":{"t":"Založili klub","x":"Lyle drží tiskovou zprávu, ze které nemá radost. „Vytvořili blok, pane. Tucet zemí, které spolu volně obchodují a nápadně neobchodují s námi. Je to přímá reakce na cla. Můžeme se tam silou vrátit, můžeme si postavit vlastní konkurenční klub, nebo na to celé uvalit cla a uvidíme, kdo zamrká první.“","c":[["Uvalte cla na celý blok najednou.","Vyhlásíte hospodářskou válku dvanácti zemím ještě před obědem. Základna je v extázi. Někde se prostě zastaví kontejnerová loď."],["Postavte konkurenční klub. Náš bude větší.","Sestavíte vlastní obchodní blok, trváte na tom, že je lepší, a obsadíte ho kýmkoli, kdo se dostaví. Dva členové nemají tušení, proč byli pozváni."],["Vraťte se tam silou. Spolkněte hrdost.","Vyjednáte si cestu zpátky do klubu, ze kterého jste byl vyloučen, potichu, u stolu blízko dveří. Ekonomika se zotaví. Základna se nedozví nic."]]},"i-scs-reef":{"t":"Útes s ranvejí","x":"Generál Tarrant má fotky před a po. „Byl to útes, pane. Teď je to přistávací dráha s útesem pod sebou. Čína ji postavila v obchodní trase, kterou si nárokují ještě čtyři další země. Všechny čtyři se ptají, jestli Spojené státy hodlají něco udělat, nebo jen něco říct.“","c":[["Propluje kolem ní. Dvakrát.","Provedete plavbu na obranu svobody plavby dost blízko na to, abyste přečetl místní cedule. Nikdo nestřílí. Všichni to fotí. Smysl, jaký měl mít, je splněn."],["Místo toho vyzbrojte čtyři sousední země.","Ze čtyř nervózních sousedů uděláte čtyři ozbrojené sousedy a necháte zeměpis, ať udělá zbytek. Peking podá stížnost, kterou si zarámujete a pověsíte na zeď."],["Vyměňte útes za výhodnější clo.","Potichu přestanete zmiňovat přistávací dráhu výměnou za něco s dolarovým znakem. Čtyři spojenci si toho mlčení všimnou. Stejně tak útes."]]},"i-nk-missile":{"t":"Narozeninový start","x":"Generál Tarrant je téměř dojatý. „Nejvyšší vůdce vypustil další raketu, pane. Naštěstí do moře, a jak se zdá, přímo o svých narozeninách. Je to vzkaz, a ten vzkaz zní, že by rád, abyste o něm něco řekl. Vždycky to tak chce. Máte jeho číslo.“","c":[["Zavolejte mu. Pochvalte tu raketu.","Zavoláte do poustevnického království a pochválíte řemeslné zpracování. Je nadšený. Oba se shodnete, že jste teď velmi dobří přátelé. Ministerstvo zahraničí si jde lehnout."],["Oheň a zuřivost. Starý klasik.","Ráno pohrozíte totální zkázou a do oběda na to zapomenete. On kvůli pozornosti vypustí další raketu. Je to fungující vztah."],["Naprosto ho ignorujte. Ničí ho to.","Neřeknete vůbec nic, což je jediná věc, kterou nesnese. Příští raketa je větší a ještě jasněji adresovaná vám."]]},"i-hostages":{"t":"Ti, které drží","x":"Muriel je u tohohle opatrná. „Drží naše lidi, pane, tři z nich, na základě obvinění, kterým nikdo nevěří. Chtějí výměnu: svého vězně, hromadu peněz, nebo fotku, jak si podáváte ruku s mužem, kterého jste nazval netvorem. Rodiny budou dnes večer v televizi tak jako tak.“","c":[["Uskutečněte výměnu. Přiveďte je domů.","Zaplatíte výkupné, které nikdo nepřizná jako výkupné, a tři občané přejdou po ranveji přímo před kamery. Je to dobrý den a strašný precedens."],["Odmítněte. My nevyjednáváme.","Z principu se držíte pevně a rodiny svolají tiskovku. Základna respektuje páteř. Vyjednávání pokračuje, neoficiálně, navždy."],["Podejte mu ruku. Ať to má fotka za sebou.","Před kamerami stisknete ruku muže, kterého jste nazval netvorem, a dostanete své lidi zpátky. Fotka přežije celé prezidentské období. Stejně tak i ti občané, což je celý smysl."]]},"i-cyber":{"t":"Ve třech státech zhasla světla","x":"Šéfka tajné služby ani nemrkne. „Někdo vypnul proud ve třech státech na devět hodin, pane. Víme kdo. Umíme si to dokázat sami sobě, ale ne úplně u soudu. Můžeme jim to oplatit hackerským útokem, můžeme je sankcionovat, nebo to udržet v tichosti, aby se trhy nedozvěděly, jak snadné to bylo.“","c":[["Oplaťte jim to hackerským útokem. Tvrději.","Na jejich straně světa něco zhasne a nikdo se k tomu nepřihlásí. Je to popíratelné, je to přiměřené a spouští to hodiny, které nikdo nevidí."],["Sankcionujte je za bílého dne.","Pojmenujete je, zostudíte je a zmrazíte, co je v dosahu. Je to legální varianta a se světly to udělá přibližně nic."],["Zahrabejte to. Trhy se to nesmí dozvědět.","Celou věc udržíte v tichosti a doufáte. Trhy se nikdy nedozví, jak tenký je ten led. Zatím to neví ani nikdo, kdo by to mohl opravit."]]},"i-refugees":{"t":"Kolona u hranice","x":"Duane má noční čísla. „Válka o dvě země dál vyhnala na silnici kolonu lidí, pane, a ta silnice končí na naší hranici. Základna chce zeď s příkopem. Kostely chtějí přivítání. Kamery chtějí záběr, a jeden z těch dvou dostanou, záleží na vás.“","c":[["Zavřete ji. Kamery, zeď, kompletní balík.","V přímém přenosu s maximálním divadlem uzavřete hranici. Základna jásá. Záběr, který kamery natočily, je ten, na který se vás budou ptát navždy."],["Zpracujte je. Potichu, podle předpisů.","Uděláte legální, logistickou, nefotogenickou věc. Funguje to a nezíská vám to nic. Základna slyší jen to, že jste nepostavil ten příkop."],["Pošlete je autobusem do státu rivalského guvernéra.","Naložíte problém do autobusu a pošlete ho člověku, který vás naštval. Je to kruté, je to podfuk, a vede to zprávy přesně tak, jak jste doufal."]]},"i-nobel":{"t":"Telefonát z Osla","x":"Muriel sotva věří tomu, co říká. „Máte tu skutečnou šanci, pane. Dvě vlády, které po sobě deset let střílejí, budou příští týden obě ve stejné budově a obě zvednou váš telefon. Mohlo by to opravdu skončit. Taky by to ale, pokud to přeženete, mohlo zkolabovat přímo před kamerami. A ano, lidé už to slovo pomalu vyslovují.“","c":[["Odveďte tichou diplomacii. Dotáhněte to.","Skloníte hlavu, dva týdny pracujete na telefonech a válka opravdu skončí. Je to nejlepší věc, jakou kdy uděláte, a trenduje to šest hodin."],["Oznamte cenu ještě před mírem.","Vyhlásíte vítězství, a sám sebe laureátem, o několik kritických dní dřív. Jedna delegace odejde kvůli formulaci vašeho příspěvku na sociální síti. Válka se na chvíli obnoví."],["Ať to podepíšou ve vašem hotelu.","Mír vypukne v sále, nad jehož dveřmi visí vaše jméno, a s příplatkem za pokojovou službu. Vydrží. Značka, na tom se všichni shodnou, je to hlavní téma."]]},"j-acting-secretary":{"t":"Pověřený ministr","x":"Deborah má organizační schéma. „Ministerstvo vnitřní bezpečnosti je jedenáct měsíců vedeno jen 'pověřeně', pane. Stejně tak ministerstvo práce. Ušetří vám to slyšení o potvrzení a znamená to, že člověka v čele úřadu můžete v úterý vyměnit textovou zprávou. Někteří se tak už i sami představují na večírcích.“","c":[["Nechte všechny pověřené. Navždy, pokud to funguje.","Čtyři ministerstva fungují na neurčito bez potvrzené hlavy, která by se zodpovídala komukoli kromě vás. Organizační schéma se fakticky mění ve skupinovou konverzaci."],["Pošlete skutečné nominace nahoru. Ať Senát dělá svou práci.","Předložíte skutečná jména ke skutečnému hlasování. Je to pomalé, ústavní a naprosto nezajímavé, což je celý smysl toho cvičení."],["Udělejte z „pověřený“ trvalý pracovní titul. Vytiskněte nové vizitky.","Na vizitkách teď stojí „pověřený ministr“, bez hvězdičky a bez plánu to kdy změnit. Personální oddělení se jednou zeptá, jestli je to legální. Odpověď nepřijde."],["Ať o tom, kdo bude tento týden pověřený, hlasují stážisté.","Úřad se čtyřmi sty zaměstnanci nominálně vede ten, kdo vyhrál páteční anketu stážistů. Morálka je, navzdory všem očekáváním, na chvíli vynikající."]]},"j-midnight-firing":{"t":"Půlnoční výpověď","x":"Brayden drží telefon, jako by mohl každou chvíli vybuchnout. „Ministr vnitřní bezpečnosti se o svém propuštění dozvěděl z push notifikace, pane. Stejně tak jeho šéf kabinetu. Stejně tak jeho žena, která byla zrovna na oslavě něčího odchodu do důchodu. Už jsem to zveřejnil. Měl jsem počkat?“","c":[["Zveřejněte příští tři výpovědi stejným způsobem. Efektivní.","Propouštění formou notifikace se stane firemním stylem. Je to rychlé, kruté a znamená to, že už nikdo v budově nespí s telefonem obráceným displejem dolů."],["Příště mu nejdřív zavolejte. Nic to nestojí.","Necháte muži zavolat, než se příspěvek zveřejní. Je to naprosté minimum slušnosti a interně se to bere jako odvážná reforma."],["Kvůli dojmu propusťte i toho, kdo pořádal manželčinu oslavu odchodu do důchodu.","Rozšíříte dopad exploze i na muže, jehož jediným proviněním bylo, že uspořádal oběd. Ten oběd byl mimochodem výborný."],["Ať Alvin doručí zprávu spolu s ovocným košem.","Vrchní komoří dorazí s aranžmá z hrušek a se zprávou zároveň. Ministr si nechá hrušky. Práci si nenechá."]]},"j-loyalty-pageant":{"t":"Přehlídka věrnosti","x":"Chet si ve dveřích zkouší svou repliku. „Teď je to tradice, pane, jde se kolem stolu a každý ministr před kamerou řekne něco vděčného na vaši adresu, než začne schůze. Minulý týden ministr zemědělství čtyřikrát použil slovo 'požehnaní'. On na požehnání nevěří. Věří ve svůj důchod.“","c":[["Udělejte to povinné. Hodnoťte je za upřímnost.","Zavedete hodnocenou poctu věrnosti na začátku každé schůze. Dva ministři to začnou zkoušet v autě. Jeden začne plakat, z nudy, ne z oddanosti."],["Zrušte to. Začněte schůzi rovnou programem.","Vynecháte tu poctu a začnete rovnou politikou. Místnost si tak slyšitelně oddechne, že to zachytí mikrofony a musí se to vystřihnout z vysílání."],["Ať nahlas hodnotí navzájem projevy vděčnosti.","Kabinet dospělých lidí si teď před kamerou hodnotí navzájem lichotky. Ministr vnitra dá generálnímu prokurátorovi šest z deseti a myslí to jako urážku."],["Poklony vynechte, místo toho místnosti přečtěte báseň.","Přednesete čtyři sloky něčeho, co jste napsal v letadle o vznešenosti veřejné služby. Nikdo nezatleská jako první. Nakonec zatleskají všichni."]]},"j-tweet-fired":{"t":"Vyhozený příspěvkem na síti","x":"Kaylee vám čte návrh nahlas. „'S okamžitou platností.' To je celý příspěvek, pane. Žádný telefonát, žádný dopis, žádných patnáct minut na to, aby si s důstojností sbalil věci ze stolu. Ministr je momentálně na palubě letadla a přistane, aby se to dozvěděl od letušky, která to, přiznejme si, zvládá lépe než my.“","c":[["Zveřejněte to hned. Načasování je součástí toho vzkazu.","Příspěvek jde ven podle plánu, ještě za letu. Krutost je fakticky celá strategie a základna to vnímá jako sílu."],["Počkejte se zveřejněním, dokud letadlo nepřistane. Malé milosrdenství.","Odložíte veřejné pokoření o devadesát minut, aby ten muž slyšel novinku na pevné zemi. Nestojí vás to nic, a přesto se to zdá jako drahé gesto."],["Ať to Kaylee napíše jako „poděkování za službu“.","Výpověď je zabalená do vděčnosti. Každý v budově pozná, co je za první větou. Nikdo to ale neřekne nahlas."],["Oznamte výpověď a pak ho o hodinu později zase odvolejte zpět.","Otočíte kurz ještě dřív, než letadlo přistane, z důvodů, které nikdo, včetně vás, nedokáže úplně vysvětlit. Ministrovi zůstane práce i velmi dobrá historka."]]},"j-cya-memo":{"t":"Zadní vrátka na papíře","x":"Sy má složku, kterou viditelně nerad otevírá. „Tři ministři si vedou soukromé záznamy o každém ústním pokynu, který jim dáte, pane. S časovým razítkem. Není to úplně nevěrnost. Je to pojistka, a já to vím, protože svou vlastní jsem si začal vést už v únoru.“","c":[["Vyžádejte si ty poznámky. Přečtěte si každou. Osobně.","Zabavíte soukromou papírovou stopu, kterou si váš vlastní personál vedl na svou ochranu před vámi. Mrazivý efekt je okamžitý a nezastaví psaní poznámek, jen upřímnost v těch budoucích."],["Nechte je, ať si poznámky vedou dál. Nemáte co skrývat.","Dovolíte, aby papírová stopa vašich vlastních rozhodnutí existovala bez zásahů. Je to buď naprostá důvěra, nebo naprostá lhostejnost. Rozhodne o tom až historie."],["Začněte všechno diktovat přes právníka, do záznamu.","Každý pokyn teď nejdřív prochází přes právní oddělení, což je pomalejší, bezpečnější a bere to všechnu zábavu z vládnutí na základě rozmaru."],["Napište vlastní poznámku, která odporuje všem jejich.","Vytvoříte jediný konkurenční dokument, který tvrdí, že se všechno odehrálo jinak. Tři různé záznamy se teď neshodnou na tom, co se stalo ve stejné úterý, což je, jak Sy poznamenává, svým způsobem taky forma ochrany."]]},"j-leaked-transcript":{"t":"Uniklý přepis","x":"Kaylee posune přes stůl výtisk. Polovina odstavce je zvýrazněná. „Někdo přepsal uzavřenou schůzi kabinetu, pane, slovo od slova, včetně té části, kde jste ministra obchodu nazval 'nábytkem'. Za hodinu to jde ven, pokud jim nedáme něco lepšího k otištění.“","c":[["Podrobte celý kabinet detektoru lži. Nikdo neopustí místnost.","Zamknete tucet úřadujících ministrů v místnosti s přístrojem, dokud se někdo nepřizná. Nikdo se nepřizná. Všichni si ale zapamatují, kdo si to vyžádal."],["Potvrďte to, omluvte se za tón a jděte dál.","Přiznáte se k citátu a celá věc pomine za jeden zpravodajský cyklus místo tří. Je to nejlevnější možný únik a skoro nikdo ho nevyužije."],["Tvrďte, že přepis je vymyšlený. Vyhrožujte tomu médiu.","Nahlas popřete něco, co je pravda, a někteří lidé vašemu popření uvěří. Médium následující týden zveřejní i audio nahrávku, jen aby bylo jasno."],["Zveřejněte vlastní 'opravený' přepis s lepšími vtipy.","Kolotá upravená verze, ve které je vaše poznámka o ministru obchodu vtipnější a bohužel pořád zřetelně stejně urážlivá."]]},"j-drawer-letter":{"t":"Dopis v zásuvce","x":"Deborah to našla, když hledala sešívačku. „Ministr práce má ve stole čtyři měsíce podepsaný dopis s rezignací, pane. Datovaný, ale s prázdným dnem. Prý mu to pomáhá spát. Ověřila jsem si to. Šest dalších ho má taky.“","c":[["Nechte prohledat všechny zásuvky. Zabavte ty dopisy.","Nasbíráte sedm předem napsaných rezignací jako trofeje. Nikoho to nedělá loajálnějším. Sedm lidí si napíše druhý, skrytý dopis."],["Nechte to být. Zásuvka není zločin.","Rozhodnete, že soukromá pojistka jednoho muže je jeho vlastní věc. Je to malé milosrdenství, které vás nic nestojí a nezíská vám žádné uznání."],["Místo toho vyžadujte, ať všichni předem podepíší dopis o věrnosti.","Nařídíte opačný dokument: trvalý slib místo trvalé cesty ven. Budova teď má u každého stolu dvě zásuvky."],["Napište si vlastní rezignační dopis a nechte ho na viditelném místě.","Necháte na stole vlastní datovaný, nepodepsaný dopis, přímo na očích příštímu návštěvníkovi. Nikdo se o něm nezmíní. Přečte si ho úplně každý."]]},"j-cameras-in":{"t":"Kamery v místnosti","x":"Kaylee má rozpis pro tiskový pool. „Čtyřicet minut záznamu, než se zavřou dveře, pane. Dost dlouho na monolog, málo na politiku. Všichni v té místnosti teď prvních čtyřicet minut hrají divadlo a skutečný rozpočet vyjednávají, až kamery odejdou.“","c":[["Prodlužte to na celou schůzi. Plná transparentnost.","Každá schůze kabinetu se teď vysílá od začátku do konce. V místnosti se už nerozhoduje o ničem podstatném, všechno se odehrává na chodbách potom, mimo záznam."],["Kamery zcela zrušte. Jednejte jako dospělí.","Zavřete dveře a necháte kabinet skutečně vládnout v soukromí, po staru. Základně chybí show. Politika se mírně zlepší."],["Napište scénář na prvních čtyřicet minut. Zkoušejte to dvakrát.","Úvodní monolog se teď dolaďuje jako pilotní díl seriálu. Ve fokusní skupině obstojí skvěle, u každého, kdo v té místnosti opravdu byl, hrozně."],["Pořiďte umělý potlesk pro místa, kde se má tleskat.","Potichu se najme zvukař, který vylepší potlesk na schůzích kabinetu pro vysílání. Nikdo v místnosti o to nepožádal. Nikdo v místnosti proti tomu ale ani nic nenamítá."]]},"j-praise-order":{"t":"Pořadí u stolu","x":"Deborah má zasedací pořádek, který se mění týdně. „Začal jste přeskupovat stůl podle toho, kdo se vám nejvíc zavděčil, pane. Ministr obchodu byl tento měsíc dvakrát degradován na vzdálený konec stolu. Začal si nosit vlastní jmenovku, pro jistotu.“","c":[["Zveřejněte ten pořádek. Ať vidí, kde se nacházejí.","Zveřejníte hierarchii pro celou budovu. Vyvolá to přesně tu úzkostnou, soutěživou loajalitu, kterou jste chtěl, a přesně tu zášť, se kterou jste nepočítal."],["Vraťte se k abecednímu pořadí. Nudné a spravedlivé.","Vrátíte stůl do abecedního pořádku a hierarchický systém úplně zrušíte. Ministr obchodu si podrží své místo. Jmenovku si ale ze zvyku nosí dál."],["Hodnoťte je podle jediného měřítka, které nikdo nemůže zpochybnit: hlasitosti potlesku.","Decibelmetr se na chvíli stane nejdůležitějším přístrojem v Západním křídle. Ministr zemědělství, statný muž se silnými plícemi, postoupí o tři místa."],["Místo toho je usaďte podle výšky. Nejčistší měřítko, jaké existuje.","Vzdáte se zásluh i loajality ve prospěch krejčovského metru. Všichni si soukromě myslí, že je to nejspravedlivější systém, jaký kdy kabinet používal."]]},"j-cabinet-shuffle-photo":{"t":"Skupinová fotka","x":"Kaylee má účet za tisk. „Tohle je letos už čtvrtá oficiální fotka kabinetu, pane. Od té poslední mají tři ministerstva nové vedoucí. Tímhle tempem odejdeme do důchodu my a rámeček, ne prezidentský úřad.“","c":[["Fotku zmrazte. Noví lidé prostě navždy zůstanou mimo záběr.","Vyřešíte fluktuaci tím, že prostě přestanete aktualizovat záznam. Oficiální portrét teď zobrazuje kabinet, který technicky vzato už neexistuje."],["Vyfoťte to znovu pořádně. Je to malý, poctivý náklad.","Zaplatíte dalšího fotografa, další rámeček, další odpoledne mhouření očí do studiových světel. Není to okouzlující, ale je to přesné, což je vzácnější."],["Digitálně vlepte nové hlavy na stará těla.","Mladý grafik dostane za úkol vyfotoshopovat tři nové tváře na tři staré obleky. Osvětlení nesedí. Nikdo na fotce nestojí tam, kde to vypadá, že stojí."],["Fotku vynechte. Objednejte skupinový portrét, olejomalbu.","Najmete malíře, aby ztvárnil současný kabinet olejomalbou, za značné náklady a se značným zpožděním. Dva ze zobrazených lidí opustí administrativu dřív, než barva zaschne."]]},"j-revolving-door":{"t":"Otáčecí dveře","x":"Miriam má seznam, a je delší, než by měl být. „Šest bývalých ministrů teď lobbuje přesně u těch ministerstev, která dřív sami vedli, pane. Ochranná lhůta je oficiálně osmnáct měsíců. Dva z nich našli kličku během osmnácti dní.“","c":[["Prominout ochrannou lhůtu pro loajální absolventy vlády.","Necháte svůj bývalý kabinet vejít rovnou do lobbistických kanceláří ministerstev, která sami vedli. Je to legální, je to rychlé a je to nejčistší úplatek ve Washingtonu, protože ho nikdo nemusí tak nazývat."],["Vynuťte celých osmnáct měsíců. Bez výjimek.","Trváte na skutečném pravidle, což naštve několik lidí, kteří vám prokázali skutečné laskavosti. Je to správné rozhodnutí a stojí vás to dvě vánoční přání."],["Prodlužte zákaz na tři roky, pro všechny kromě vás.","Zpřísníte pravidlo pro budoucí administrativy, zatímco potichu udělíte výjimku pro současné odchody. Vypadá to jako reforma. Funguje to jako kulička s delší přistávací drahou."],["Najměte lobbisty zpátky jako „zvláštní poradce“. Technicky vzato žádné lobbování.","Otáčecí dveře zavřete tak, že prostě necháte všechny v budově, s novým titulem a stejným platem. Miriam sepíše zprávu. Ta zpráva je, jak jinak, ignorována."]]},"j-golden-parachute":{"t":"Zlatý padák","x":"Lyle má před sebou podmínky odstupného a moc se mu nelíbí. „Odcházející ministr energetiky chce na cestu ven poradenskou smlouvu, pane. Dva roky, sedmimístná částka a titul se slovem 'senior'. Musím podotknout, že odchází v poněkud podezřelých okolnostech.“","c":[["Schvalte to. Na loajalitě na cestě ven záleží taky.","Zaplatíte muži štědře za to, aby potichu odešel a neřekl nic nelichotivého. Funguje to přesně tak, jak se slibovalo, což je samo o sobě svým způsobem přiznání."],["Zamítněte smlouvu. Standardní odchod, nic víc.","Vyprovodíte ho podáním ruky a ničím jiným. Je nespokojený. Rozpočet je alespoň nepatrně v lepším stavu."],["Schvalte to, ale poplatek zahrabte do tří různých rozpočtových položek.","Poradenský honorář přežije, rozdělený do rozpočtu, který nikdo nečte celý. Auditor to najde o jedenáct měsíců později a podá velmi zdvořilý dotaz."],["Nabídněte mu místo hotovosti maják. Jeden je zrovna k dispozici.","Vyřešíte sedmimístný spor vyřazeným federálním majákem na skalnatém, nepojistitelném úseku pobřeží. Přijme ho. Vypadá skutečně nadšeně."]]},"j-book-deal":{"t":"Kniha, co všechno prozradí","x":"Sy drží ukázkový výtisk s viditelnou hrůzou v obličeji. „Bývalý šéf kabinetu před Deborah chystá knihu, pane. Osmimístná záloha. Jmenuje se, chci být přesný, *V místnosti, kde se to nemělo stát*. Cenzurovanou kopii dostaneme za tři týdny.“","c":[["Podejte žalobu, ať se vydání zablokuje. Zdržte to u soudu.","Pokusíte se o předběžné zastavení vydání memoárů, právní krok s bezvýhradnou sérií proher. Žaloba knize zaručí místo na seznamu bestsellerů, kam by se sama možná nedostala."],["Nechte to vydat. Na nic nereagujte.","Odmítnete knize dopřát jakoukoli reakci. Šest týdnů se dobře prodává a v osmém týdnu je zapomenutá, což je správný výsledek."],["Objednejte konkurenční odhalující knihu od někoho, kdo je stále loajální.","Konkurenční memoáry rychle sepíše ještě sloužící poradce. Čtou se přesně tak autenticky, jak autentické doopravdy jsou, tedy skoro vůbec."],["Skupte sám celý první náklad.","Skoupíte celý první náklad, aby se kniha nedostala do obchodů. Nakladatel, nadšený, objedná druhý náklad dvojnásobné velikosti. Osobně jste tak profinancoval pokračování."]]},"j-mole-hunt":{"t":"Hon na krtka","x":"Errol mluví vyrovnaným hlasem, což je samo o sobě varování. „Únik informací dokážeme zúžit na devět lidí s přístupem, pane. Další zúžení by znamenalo prohlídku jejich soukromých telefonů, což je legální asi u čtyř z nich a u zbytku je to trestný čin.“","c":[["Prohlédněte všech devět telefonů. Trestný čin vyřešte později.","Povolíte sledování vlastního kabinetu na základě právní teorie, která nepřežije setkání se soudcem. Únik se nenajde. Najde se pět nesouvisejících poměrů."],["Zúžte to na ty čtyři, které smíte legálně prověřit.","Zůstanete u těch čtyř jmen, která zákon skutečně povoluje. Je to pomalejší, je to správné a je to verze celého příběhu, která nekončí předvoláním pro vás."],["Oznamte veřejně, že viník úniku byl odhalen. Blafujte.","Vymyslíte si jméno, které nemáte, v naději, že skutečný viník zpanikaří a přizná se. Místo toho odejdou tři nevinní zaměstnanci z čiré paranoie."],["Podstrčte každému z devíti mírně odlišný falešný detail.","Klasická past na kanárka, v devíti variantách. Funguje to skvěle a zároveň to k Errolovu tichému zděšení potvrdí, že nejméně tři z těch devíti nezávisle na sobě mluví s novináři."]]},"j-anonymous-oped":{"t":"Anonymní komentář","x":"Kaylee položí na stůl noviny, otevřené na správné straně. „Někdo 'vysoce postavený' z téhle administrativy právě anonymně zveřejnil text o tom, jak potichu brzdí vaše příkazy pro dobro země, pane. Je to dobře napsané. A co je horší, je to věrohodné skoro u kohokoli v téhle budově.“","c":[["Vyžadujte, ať to popře každý člen kabinetu, jednotlivě, na kameru.","Vynutíte si čtrnáct popření během jednoho odpoledne. Třináct zní přesvědčivě. Jedno zní jako video s rukojmím a internet si toho okamžitě všimne."],["Ignorujte to. Esej bez podpisu si nezaslouží vysílací čas.","Odmítnete tomu příběhu dodat kyslík. Vyšumí to za čtyři dny místo čtyř týdnů, což je celý trik dobrého ignorování."],["Spusťte analýzu rukopisu a stylu u celého vedení.","Zaplatíte lingvistovi na volné noze, aby porovnal rytmus vět ve čtrnácti textových vzorcích. Výsledky jsou nejednoznačné, faktura ne."],["Zveřejněte vlastní anonymní komentář, ve kterém sám sebe chválíte.","Objeví se nepodepsaná esej od 'vysoce postaveného úředníka', která chválí váš instinkt i vaše vlasy. Nikdo nevěří, že pochází z budovy. Pochází."]]},"j-whistleblower-hotline":{"t":"Linka pro oznamovatele","x":"Miriam má seznam hovorů, a je tlustý. „Interní etická linka zaznamenala tento čtvrtrok dvě stě jedenáct hovorů, pane, téměř všechny o stejných třech rozhodnutích. Zákon říká, že nesmíme volajícím uškodit odvetou. Neříká, že nesmíme zjistit, kdo to je.“","c":[["Vysledujte každý hovor. Potichu volající přeřaďte.","Identifikujete a odstavíte dvě stě zaměstnanců, kteří použili linku vytvořenou přesně na jejich ochranu. Je to učebnicová odveta a spis o tom je dost silný na to, aby obstál sám o sobě."],["Nechte linku být. Přesně k tomuhle slouží.","Necháte chráněný komunikační kanál dělat jedinou práci, kterou má. Je to strukturálně nejnudnější možná volba, a zároveň strukturálně ta správná."],["Budoucí hovory směrujte místo toho přes 'průzkum spokojenosti zákazníků'.","Linka se potichu přejmenuje a zbaví se svých právních ochran. Hovory dál chodí. Fakticky teď nikam nevedou."],["Na jedno odpoledne přijímejte hovory na lince osobně.","Osobně si vyslechnete čtyřicet minut anonymních stížností na vlastní administrativu. U několika z nich si soukromě přiznáte, že mají pravdu."]]},"j-competing-memos":{"t":"Protichůdné pokyny","x":"Deborah má dva dokumenty, oba označené jako naléhavé, oba podepsané vedoucími pracovníky, a tvrdí opak. „Úřad má teď oba tyhle dokumenty na stejném stole, pane. Volali, aby se zeptali, pro jakou administrativu vlastně momentálně pracují.“","c":[["Ať si to obě frakce vyříkají mezi sebou. Vyhraje lepší dokument.","Necháte dvě křídla vlastního personálu bít se v písemné formě, bez rozhodčího. Úřad tři týdny nedělá vůbec nic, což je při bližším zamyšlení možná ta skutečná politika."],["Vyberte jeden dokument, druhý písemně zrušte.","Uděláte skutečné rozhodnutí a dáte ho na papír. Je to zdaleka nejužitečnější věc, kterou šéf kabinetu za celý měsíc udělá, a trvá to čtyři minuty."],["Vydejte třetí dokument, který odporuje oběma prvním.","Přijde třetí dokument, který se neshoduje ani s jedním z předchozích. Úřad teď má tři stanoviska a nulovou politiku, seřazenou abecedně."],["Ať to obě frakce vyřeší v páce. Poražený sepíše omluvu.","Skutečný zápas v páce v Rooseveltově místnosti vyřeší živý meziresortní spor o politiku. Vítěz je viditelně v rozpacích, jak dobře to zafungovalo."]]},"j-shadow-cabinet":{"t":"Stínový kabinet","x":"Deborah pečlivě volí slova. „Teď existuje druhý kabinet, pane. Neoficiální. Bez titulů, bez slyšení o potvrzení, schází se v rezidenci poté, co ten skutečný jde domů. Polovina skutečných ministrů se mě už začala ptát, kdo vlastně řídí jejich vlastní ministerstva.“","c":[["Formalizujte tu stínovou skupinu. Dejte jí skutečnou pravomoc.","Zavedete nepotvrzený vnitřní kruh se skutečnou mocí větší než má potvrzený kabinet. Je to rychlé, loajální a právně neobhajitelné, všechno tři najednou."],["Rozpusťte to. Jeden kabinet, potvrzený, zodpovědný.","Pošlete poradce z nočních schůzek domů a rozhodování vrátíte lidem, které skutečně prověřil Senát. Je to pomalejší. Je to ale strukturálně vláda."],["Nechte oba kabinety, ale nikdy je nenechte se setkat.","Řídíte dva paralelní kabinety, které o sobě formálně nevědí, což vydrží přesně do chvíle, kdy jsou oba pozváni na stejný vánoční večírek."],["Sloučte je do jedné obří schůze. Ať se to vyřeší samo.","Šestadvacet lidí, kteří o sobě neměli vědět, sedí u stejného stolu. Schůze trvá čtyři hodiny. Nic se nerozhodne. Všichni se dozví úplně všechno."]]},"j-unqualified-cousin":{"t":"Bratranec v nové funkci","x":"Miriam má životopis, a je krátký. „Bratranec vaší manželky byl jmenován náměstkem ministra energetiky, pane. Jeho dosavadní zkušenosti sahají ke stánku se solárními nabíječkami na venkovské pouti. Nastupuje v pondělí. Dvakrát se zeptal, jestli k té práci patří i auto.“","c":[["Povyšte ho i na náměstka ministra. Nechte to v rodině.","Přidáte mu druhý rodinný titul k úřadu, který zatím ani nedokáže najít na mapě. Energetická síť, pozoruhodně, dál funguje, hlavně na setrvačnost z doby před jeho příchodem."],["Dejte mu titul bez skutečné pravomoci.","Dostane jmenovku, parkovací místo a agendu, která se ničeho důležitého netýká. Je to poctivé řešení nepoctivého problému."],["Pošlete ho tam, kde napáchá méně škody. Velvyslanec na malém ostrově.","Vyšle se do státu s jedenácti tisíci obyvateli, s příjemným klimatem a bez energetické sítě, kterou by mohl pokazit. Posílá pohlednice."],["Ať nejdřív měsíc chodí ve stopách komořího Alvina.","Náměstek ministra energetiky stráví čtyři týdny učením se skládat ubrousky a hledat vypínače, než se dotkne skutečného politického spisu. Podle všech ohlasů je v ubrouscích vynikající."]]},"j-purity-test":{"t":"Test čistoty","x":"Deborah má tabulku starých příspěvků a komentářů. „Prověrka teď zahrnuje úplné prohledání všeho, co kdy kandidát o vás řekl, pane, až deset let zpátky. Vyřadili jsme velmi dobrého náměstka generálního prokurátora kvůli článku ve školních novinách. Bylo mu devatenáct. Bylo to o parkování.“","c":[["Rozšiřte hledání dál do minulosti. Klidně na střední školu, pokud existuje záznam.","Rozšíříte prověrku loajality až do dospívání. Skupina uchazečů se zúží na lidi, kteří v životě nevyjádřili názor na cokoli, což se ukáže být malá a podivná skupina."],["Prověřujte jen skutečné konflikty zájmů. Příspěvky na sítích vynechte.","Zúžíte prověřování zpátky na to, na čem skutečně záleží. Zásobník talentů se přes noc ztrojnásobí a potichu s ním i schopnost celé budovy."],["Nechte hledání příspěvků, ale vymáhejte ho jen u lidí, které nemáte v oblibě.","Pravidlo zůstává v knihách a uplatňuje se selektivně, což si každý v budově uvědomí do týdne a nikdo to neřekne nahlas."],["Ať prověrku dělá Madison. Je hodně aktivní na internetu.","Neteř Někoho je pověřena projít deset let digitální stopy kandidáta. Najde věci, které přehlédly tři prověřovací agentury, a jednu věc, kterou nikdo nepotřeboval vědět."]]},"j-hiring-freeze":{"t":"Zastavení náboru","x":"Roscoe má v ruce podložku s papíry a znepokojivě velkou dávku nadšení. „Zastavení je totální, pane, platí od dnešního rána. Kromě mého úřadu, přirozeně, který potřebuje čtyřicet dalších lidí, aby dokázal to zastavení řádně vyhodnotit. Šest z nich už jsem najal.“","c":[["Schvalte výjimku pro BROOM. Zastavení platí pro všechny ostatní.","Úřad pro efektivitu roste, zatímco všechno, co má údajně zefektivňovat, se zastaví. Roscoe tomu bez zjevné ironie říká „nutná režie“."],["Žádné výjimky. Zastavení platí i pro BROOM.","Aplikujete pravidlo i na ty, kdo ho tvoří. Roscoe zuří způsobem, který sám o sobě skoro stojí za tu cenu."],["Zastavte nábor všude kromě ministerstev, která vás minulý týden pochválila.","Zastavení se stane nástrojem loajality maskovaným za fiskální politiku. Každá schůze kabinetu teď začíná neobvykle nadšeným komplimentem."],["Zastavte nábor a pak všechny znovu najměte jako 'dobrovolníky'.","Federální práce pokračuje na plný stav pod novou, neplacenou klasifikací. Na papíře to šetří peníze. U soudu to nakonec nešetří nic."]]},"j-exit-interview":{"t":"Výstupní pohovor","x":"Miriam má přepis a jedno pozvednuté obočí. „Standardní výstupní pohovor, pane, s odcházejícím náměstkem ministra obchodu. Otázka čtyři zní 'chcete ještě něco dodat'. Dodal šest stran.“","c":[["Zapečeťte spis. Utajte ho, pokud musíte.","Pohřbíte rutinní personální dokument, jako by to bylo státní tajemství, což nakonec zaručí, že ho někdo shledá dost zajímavým na to, aby unikl."],["Přečtěte si to. Dvě ze šesti stran opravdu zvažte.","Přečtete si stížnost muže, který nemá co ztratit ani proč lhát. Dva jeho body jsou, nepříjemně, správné."],["Ať personální oddělení „ztratí“ spis při migraci systému.","Šest stran zmizí v rámci migrace serveru, která byla naplánovaná z naprosto nesouvisejících důvodů. Nikdo tomu načasování úplně nevěří."],["Zveřejněte to sám, jako první, s vlastními poznámkami.","Preventivně zveřejníte kritický výstupní pohovor s vlastními poznámkami na okraji, kterými polovinu popíráte. Je to nejpodivnější sebeostuda roku a paradoxně to vyznívá jako sebejistota."]]},"j-briefing-book":{"t":"Podkladový materiál, který nikdo nečte","x":"Muriel má šanon, sedm centimetrů tlustý, s barevnými záložkami. „Tohle je kompletní podklad na zítřejší summit, pane. Historie, páky vlivu, červené linie, všechno. Minule jste si přečetl obálku a improvizoval. Celkem to dopadlo dobře. Přesto bych radši, kdybyste se dostal dál než na obálku.“","c":[["Přeskočte to zase. Improvizace zatím fungovala.","Znovu vejdete nepřipravený, na kouzlo osobnosti a instinkt. Zase to funguje, což je ten nejnebezpečnější možný výsledek, protože vás to nic nenaučí."],["Dnes večer si šanon opravdu přečtěte. Celý.","Přečtete si to. Není to okouzlující, trvá to čtyři hodiny, a zítra vejdete dovnitř s tím, že věci znáte, místo abyste je odhadoval, což je skutečně vzácný stav."],["Ať Muriel shrne všechno na jednu kartičku.","Čtvrt milionu dolarů výzkumu a diplomatické přípravy se stlačí na kartičku, která se vejde do náprsní kapsy. Kartičku ztratíte ještě před obědem."],["Přečtěte si to vzhůru nohama pro štěstí. Tradice, kterou jste právě vymyslel.","Otočíte šanon vzhůru nohama z důvodů, které nikdo nedokáže vystopovat k žádné dřívější pověře, a když summit dopadne dobře, prohlásíte, že to zafungovalo. Tradice se, znepokojivě, uchytí."]]},"j-empty-chair":{"t":"Prázdná židle","x":"Deborah spočítá židle, než vejdete dovnitř. „Generální prokurátor dnes nepřijde, pane. Prý má kolizi v rozvrhu. Není to kolize v rozvrhu. Všichni u tohohle stolu vědí, že to není kolize v rozvrhu, a všichni se budou usilovně tvářit, že je.“","c":[["Zavolejte ho jmenovitě, i s tou prázdnou židlí, přímo na kameru.","Oslovíte prázdnou židli přímo před tiskovým poolem. Vyznívá to buď jako dominance, nebo jako rozpad, úplně záleží na tom, jakou televizní stanici divák sleduje."],["Neříkejte nic. Pokračujte podle programu.","Necháte prázdnou židli být tak hlasitá, jak chce, aniž byste k tomu cokoli přidával. Je to verze, ve které vypadáte, pro jednou, jako ten klidný."],["Ať někdo tu židli fyzicky odnese a nahradí jinou.","Skutečná židle je vykutálena z místnosti uprostřed schůze. Je to opravdu podivná věc, kterou lze sledovat, a nikdo pak nedokáže vysvětlit, čí to byl nápad."],["Židli nechte, ale položte na ni jmenovku s nápisem „CHYBÍ“.","Jedna laminovaná kartička obviňujícím způsobem sedí na prázdném místě celých devadesát minut. Je to nejubožejší možné využití laminovačky a funguje to přesně tak, jak mělo."]]},"j-standing-ovation":{"t":"Ovace vestoje","x":"Deborah to teď měří stopkami, hlavně jako vtip, hlavně. „Devadesát vteřin potlesku, když vejdete, pane, devadesát, když odejdete. Ministr pro záležitosti veteránů má špatné koleno. Stejně stojí. Nikdo mu neřekl, že nemusí.“","c":[["Prodlužte to na dvě minuty. Měřte to veřejně.","Potlesk se stane měřeným, vysílaným rituálem. Na fotkách vypadá jako zbožňování. Komukoli, kdo počítá vteřiny, to připadá spíš jako záznam s rukojmími."],["Zrušte potlesk úplně. Prostě začněte schůzi.","Vejdete, posadíte se a začnete mluvit o politice. Místnost si viditelně oddechne. Ministr pro veterány si vděčně sedne jako první."],["Nechte potlesk, ale udělejte ho dobrovolným, a poznamenejte si, kdo netleská.","Tleskání zůstává dobrovolné a velmi pečlivě se sleduje, kdo odmítne. Tleská úplně každý. O tleskání samotné vlastně nikdy nešlo."],["Zatleskejte jim jako první, dřív, než stačí zatleskat oni vám.","Vejdete a začnete místo toho tleskat kabinetu. Místnost strne, nejistá, jak reagovat na úmyslné ocenění. Trvá jim celých jedenáct vteřin, než se vzpamatují."]]},"j-czar-creep":{"t":"Plíživá byrokracie carů","x":"Deborah má seznam, který se stále rozrůstá do šířky. „Máte teď hraničního cara, hraničního cara pro druhou hranici, vesmírného cara, cara pro slavnostní sál a od dnešního rána i cara carů, pane. Žádného z nich nikdo nepotvrdil. Všichni mají skutečné rozpočty.“","c":[["Přidejte další tři cary. Nikdo vás nezastaví.","Nepotvrzený stínový kabinet se přes noc zdvojnásobí. Ani jeden z nich neprošel slyšením. Všichni teď stojí výš než několik lidí, kteří jím prošli."],["Přeměňte cary na skutečné, potvrditelné funkce.","Neformální impérium přeměníte zpátky na zodpovědné pozice prověřené Senátem. Obsazování je pomalejší a na rozdíl od alternativy přežije to i změnu administrativy."],["Nechte cary, ale přejmenujte je na 'vyšší poradce'. Stejná práce, žádný podivný titul.","Naprosto stejný nepotvrzený aparát pokračuje pod nudnější hlavičkou. Problém s dohledem se nezmění. Tisková zpráva zní ale líp."],["Udělejte cara i ze stážistky. Carka kávy.","Madison dostane titul, rozpočtovou položku ve výši čtyř set dolarů a skutečnou, byť extrémně omezenou pravomoc nad kávovarem v Západním křídle. Bere to velmi vážně."]]},"j-confirmation-hearing":{"t":"Slyšení o potvrzení","x":"Hal volá před slyšením, unaveně tím zvláštním způsobem, který dokáže vyvolat jen práce ve výboru. „Váš kandidát na ministra práce dnes pod přísahou třikrát nedokázal uvést aktuální míru nezaměstnanosti, pane. Výbor má fotky přesného okamžiku, kdy si jeho poradce dal hlavu do dlaní.“","c":[["Zaútočte na výbor za 'chytáky'. Plný útok.","Prezentujete základní kompetenční otázku jako pronásledování. Nadchne to základnu a spálí to poslední zbytek dobré vůle u dvou senátorů, které jste opravdu potřeboval."],["Stáhněte nominaci. Najděte někoho, kdo to číslo zná.","Uříznete ztráty a stáhnete nominaci ještě před hlasováním. Je to potichu učiněné přiznání a příští kandidát projde bez problémů za týden."],["Ať slyšení zopakuje se sluchátkem v uchu.","Zařídí se druhé slyšení s přenosem do ucha. Odhalí se to do hodiny. Míru nezaměstnanosti si mimochodem stejně ani potom nezapamatuje."],["Potvrďte ho i tak, stranickým hlasováním, a jděte dál.","Bez ohledu na to je potvrzen, jen na základě počtu hlasů, a nastupuje do práce, aniž zná číslo, které je celou podstatou té práce. Strukturálně to funguje, v tom smyslu, že se nic okamžitě nezhroutí."]]},"j-blind-trust":{"t":"Slepý fond","x":"Miriam má dokumenty a velmi specifický tón hlasu. „Slepý fond ministra financí spravuje jeho vlastní bratr, pane, který mu každé ráno volá a podrobně to s ním probírá. Slovo 'slepý' odvádí v té větě opravdu hodně práce.“","c":[["Schvalte to uspořádání. Rodina je rodina.","Prosadíte fond, který je slepý jen podle názvu. Je to technicky legální a prakticky průhledné, špatným směrem."],["Vyžadujte skutečně nezávislého správce. Žádné příbuzné.","Vynutíte skutečný smysl toho pravidla. Ministr je naštvaný přesně jeden telefonát a pak se podle všeho v pohodě přizpůsobí."],["Nechte to být, ale vyžadujte, ať se hovory nahrávají, natrvalo, bez přehrání.","Ranní hovory pokračují přesně jako dřív. Záznam o jejich existenci, ale ne o jejich obsahu, teď existuje někde, kam ho nikdo nikdy neotevře."],["Vložte vlastní majetek do fondu, který bude spravovat Madison.","Neteř Někoho je teď na papíře slepou správkyní devítimístného portfolia. Rozumně se zeptá, co to portfolio vlastně je. Nikdo jí neodpoví."]]},"j-gift-basket":{"t":"Dárek z velvyslanectví","x":"Miriam drží formulář s nehnutým výrazem. „Velvyslanec Rusalky poslal ministrovi obchodu náramkové hodinky v hodnotě zhruba jeho ročního platu, pane. Federální zákon vyžaduje, aby to buď nahlásil, nebo dárek odmítl. Neudělal ani jedno. Nosí je už měsíc.“","c":[["Nechte mu je. Nahlaste to jako 'kulturní výměnu'.","Hodinky zůstávají na jeho zápěstí pod papírovou klasifikací vymyšlenou přímo pro tuto příležitost. Není to úplně nelegální. Ale ani daleko od toho."],["Zabavte je. Pošlete zákonem vyžadovaný děkovný dopis.","Hodinky putují do vládního skladu podobných zabavených darů, vedle několika koberců a jedné znepokojivé vycpané sokolí figuríny. Pravidlo funguje přesně tak, jak bylo napsáno."],["Ať si je od vlády 'koupí' za tržní hodnotu. Na papíře.","Vymyslí se nominální transakce, která přemění dar na nákup. Hodinky zůstávají na jeho zápěstí. Papírování je alespoň kompletní."],["Písemně požádejte Rusalku o stejné pro sebe.","Formálně požádáte o druhé hodinky diplomatickou cestou, na hlavičkovém papíře Bílého domu. Velvyslanec s radostí vyhoví a zmíní to na příští státní večeři."]]},"j-three-in-a-week":{"t":"Tři za týden","x":"Deborah přestala aktualizovat organizační schéma perem a přešla na tužku. „Tři odvolání na úrovni kabinetu za šest dní, pane. Vnitřní bezpečnost, energetika a ředitel rozpočtového úřadu, který se to dozvěděl zrovna při prezentaci rozpočtu. Kongresu. Naživo.“","c":[["Vyhoďte tento týden i čtvrtého. Ustanovte rekord.","Ženete se za tou sérií, místo abyste ji přerušil. Míra fluktuace se stane ustáleným vtipem v každém večerním pořadu, a pak se nějakým způsobem stane i důvodem k pýše na mítincích."],["Pauza. Žádné další výpovědi tento měsíc. Ať to zvětralo.","Vyhlásíte moratorium na vlastní fluktuaci. Budova se poprvé po týdnech stabilizuje. Nikdo vám neděkuje, ale nikdo taky neodchází."],["Přejmenujte výpovědi na 'generační obměnu'. Vytiskněte oběžník.","Veselý interní oběžník popisuje čistku jako obnovu. Nikdo v budově tomu nevěří ani slovo a celé měsíce to všichni sarkasticky citují."],["Zbavte se sám povinnosti oznamovat výpovědi. Ať to dělá Alvin.","Vrchní komoří je krátce a neoficiálně pověřen informovat úředníky kabinetu, že už nemají práci. Dělá to s větší grácií než kdokoli před ním."]]},"j-succession-plan":{"t":"Nástupnický plán, který nikdo nesepsal","x":"Bo má blok popsaný přeškrtanými jmény. „Vnitřní bezpečnost nemá ministra, nemá potvrzeného náměstka a třetí v pořadí právě odešel do důchodu, pane. Na papíře, kdyby se dnes odpoledne něco stalo, by ministerstvo řídil regionální ředitel z města, jehož název si musím dohledat.“","c":[["Jmenujte na prázdné místo dekretem loajálního člověka. Vynechte proces.","Jmenujete někoho dekretem místo potvrzení, na základě teorie, že organizační schéma s vyplněným jménem v každém políčku je bezpečnější než poctivá mezera. Právně to ale není totéž."],["Zrychleně proveďte skutečnou nominaci Senátem.","Prosadíte skutečné, potvrditelné jméno skutečným procesem, ve zrychleném, ale legitimním časovém rámci. Trvá to o šest týdnů navíc a výsledkem je člověk, který přežije předvolání."],["Prostě tu mezeru nezmiňujte. Zatím se nikdo neptal.","Necháte nástupnické schéma potichu, nebezpečně neúplné a doufáte, že zpravodajský cyklus zůstane jinde. Zatím zůstává, což ale není totéž jako že tam zůstane napořád."],["Vylosujte pořadí nástupnictví na příští schůzi kabinetu.","Jména se doslova losují z Alvinova klobouku před celým kabinetem. Je to právně bezvýznamné a všichni si soukromě myslí, že je to poctivější než proces, který to nahradilo."]]},"j-inspector-general":{"t":"Generální inspektor","x":"Bo rozkládá časovou osu, a není lichotivá. „Generální inspektor pro vnitřní bezpečnost byl sedmdesát dva hodin od zveřejnění zprávy o cestovních výdajích pověřeného ministra, pane, když jste ho odvolal. Jako váš právník musím říct, že dojem to nedělá nijak nenápadný.“","c":[["Odvolejte i příštího, hned jak se zpráva přiblíží.","V praxi zavedete, že každého interního hlídače, který se přiblíží k závěru, odvoláte, dřív než ho zveřejní. Funguje to ještě jednou, než si Kongres všimne vzorce."],["Nechte zprávu vyjít. Se zjištěními se poctivě vypořádejte.","Necháte hlídací zprávu proběhnout svým chodem a zodpovíte se za to, co odhalí. Je to nepříjemné na jeden zpravodajský cyklus a strukturálně je to přesně tak, jak má systém fungovat."],["Místo odvolání generálního inspektora přeřaďte. Stejný efekt, měkčí sloveso.","Podrží si titul i plat, ale ztratí agendu, stůl i tým. Zpráva, kterou měl tři dny před dokončením, fakticky nikdy nevznikne."],["Jmenujte novým hlídačem stážistku. Plná nezávislost, zaručeno.","Madison dostane titul generální inspektorky na základě teorie, že nikdo nemůže dvaadvacetiletou obvinit z ovládnutí instituce. Bere tu práci znepokojivě vážně."]]},"j-cabinet-book-club":{"t":"Čtenářský klub kabinetu","x":"Dr. Weirová drží zadanou knihu, vlastním nákladem vydaný svazek s vaší tváří na obálce, ve zlaté fólii. „Požádal jste celý kabinet, ať si před příští schůzí přečte vaše vlastní paměti a přijde připraven diskutovat o oblíbených kapitolách, pane. Tři z nich už to dočetli. Dva z těch tří lžou.“","c":[["Vyzkoušejte je z toho. Veřejně. Formou přímého dotazování.","Uspořádáte překvapivý test z vlastních memoárů pro úřadující ministry. Ministr zemědělství nedokáže pojmenovat kapitolu o sobě. Byla to kapitola první."],["Zrušte to zadání. Byl to podivný nápad.","Potichu stáhnete čtenářský úkol dřív, než se stane vtipem ve třech různých zpravodajích. V jednom už se to stalo."],["Zadejte druhou knihu. Pak třetí. Vznikne z toho sylabus.","Čtenářský seznam se rozroste o vaše paměti, paměti vašeho otce a životopis, který jste si loni na jaře nechal napsat sám o sobě. Účast na diskuzních setkáních je pozoruhodně povinná a plná."],["Ať Dr. Weirová hodnotí referáty jako profesorka.","Historička Bílého domu je pověřena hodnotit referáty na úrovni kabinetu podle skutečné hodnoticí tabulky. Generálnímu prokurátorovi udělí známku 2 mínus. Ten žádá o přezkoumání."]]},"j-secretary-of-secretaries":{"t":"Ministr ministrů","x":"Deborah to navrhuje opatrně, vědoma si toho, jak to zní. „Jediná pozice, pane, která stojí nad celým kabinetem a zodpovídá se jen vám. Každý ministr se zodpovídá nejdřív jí, vám až potom. Řeší to problém koordinace. Zároveň to ale strukturálně znamená, že vládu teď vede jeden jediný člověk.“","c":[["Vytvořte tu funkci. Dejte jí skutečnou pravomoc nad každým ministerstvem.","Jediný nepotvrzený úřad teď stojí nad celým potvrzeným kabinetem a zodpovídá se jen vám. Je to nejúhlednější možné organizační schéma a nejméně zodpovědné za posledních sto let."],["Vynechte to. Koordinujte místo toho přes běžné schůze kabinetu.","Zachováte tu neohrabanou, hašteřivou, ale skutečně zodpovědnou verzi vlády. Je záměrně pomalejší, což je funkce, za kterou vám nikdo nepoděkuje."],["Vytvořte tu funkci, ale nechte si ji sám. Žádné delegování.","Novou pravomoc si prostě ponecháte osobně, místo abyste ji přidělil. Strukturálně se nemění nic kromě vašeho vlastního kalendáře, který teď má čtyřicet přímých podřízených."],["Dejte nový titul Deborah, která o něj vůbec nepožádala.","Deborah se přes noc stane zdaleka nejmocnější nevolenou úřednicí ve Washingtonu, naprosto proti vlastnímu doporučení. Bere to s klidem. Dá si velmi dlouhou obědovou pauzu."]]},"j-cabinet-retreat":{"t":"Výjezdní zasedání kabinetu","x":"Deborah porovnává kalendář se zprávami, a moc si to spolu nerozumí. „Výjezdní zasedání kabinetu je tento víkend, pane. Pády důvěry, lanové centrum, hlavní projev na téma 'služebné vedení'. Rezervováno to bylo před měsíci. Náhodou to připadá přímo doprostřed měnové situace.“","c":[["Pokračujte podle plánu. Na dojem se vykašlete.","Celý kabinet je vyfocen na lanovém centru, zatímco měnová krize běží bez dozoru. Jeden snímek, ministra financí visícího v postroji, přežije samotnou krizi."],["Zrušte to. Pracujte přes víkend jako všichni ostatní musí.","Zrušíte to a necháte kabinet u stolů. Je to zjevné rozhodnutí a jako takové vám skoro nepřinese žádné uznání."],["Zasedání nechte, ale zkraťte ho na půl dne a nazvěte to 'soustředěným'.","Kompromisní zasedání trvá čtyři hodiny místo dvou dní. Pády důvěry stále probíhají. Nikdo ze zúčastněných nehlásí zvýšenou důvěru."],["Přesuňte celé zasedání do konferenčního hovoru. Pády důvěry, po telefonu.","Čtrnáct ministrů se pokouší o cvičení důvěry přes konferenční linku bez videa. Podle shody je to nejpodivnějších devadesát minut, jaké kdy ve vládě strávili."]]},"j-nda-everyone":{"t":"Dohoda o mlčenlivosti","x":"Sy má standardní formulář připravený k vašemu podpisu. „Každý nový zaměstnanec podepisuje před prvním dnem doživotní dohodu o mlčenlivosti, pane. Jako váš právník musím podotknout, že jsou u bývalého federálního zaměstnance skoro nevymahatelné. Musím taky podotknout, že to skoro nikdo nezkusí u soudu. Funguje to čistě na strach.“","c":[["Rozšiřte to. Zpětně. Podepíšou všichni, kdo tu kdy pracovali.","Pokusíte se zavázat bývalý personál dokumentem vymyšleným až poté, co odešli. Nemá to naprosto žádnou právní sílu a úplně každý, kdo to dostane, to správně čte jako výhrůžku."],["Zrušte dohodu o mlčenlivosti. Spolehněte se na skutečná pravidla utajení.","Spolehnete se na skutečná, vymahatelná pravidla o utajovaných materiálech místo dokumentu na zastrašování bez skutečné síly. Je to méně dramatické a je to verze, která obstojí u přezkumu."],["Nechte dohodu, ale přidejte doložku o 'hanlivém tónu'.","Pokusíte se zakázat ne fakta, ale tón, rozdíl, který žádný soud nikdy neshledal funkčním. Sy správně předpovídá, že se z toho stane nejzesměšňovanější doložka v historii dokumentu."],["Místo toho žádejte personál o slib malíčkem. Papírování úplně vynechte.","Nahradíte právní dokument doslovným slibem malíčkem, osobně administrovaným v Oválné pracovně. Několik zaměstnanců to považuje za závaznější, než kdy byla dohoda o mlčenlivosti."]]},"j-town-hall-plant":{"t":"Nastrčená otázka","x":"Brayden má kartičku, kterou napsal pro 'zaměstnance', aby ji položil. „Technicky vzato je to diskuze s personálem ministerstva, pane, ale první tři otázky jsme napsali my a dali je třem stážistům. Jeden ze stážistů právě dal výpověď a možná se o tom zmíní reportérovi.“","c":[["Nastrčte dalších šest otázek. Zaplňte s nimi celou hodinu.","Celá diskuze je od začátku do konce nascénovaná, přehrávaná zaměstnanci čtoucími z kartiček. Odhalí se to do týdne, protože se to vždycky odhalí."],["Nastrčené otázky zrušte. Berte skutečné otázky, bez přípravy.","Poprvé po měsících berete nepřipravené otázky od skutečných zaměstnanců. Dvě jsou nepříjemné. Všechny jsou ale skutečné, což má větší cenu, než co to stojí."],["Neformálně zaplaťte odcházejícímu stážistovi za mlčení.","Nabídne se neoficiální ujednání, aby odcházející stážistka mlčela. Je to typ tiché dohody, která zůstane tichá, jen dokud nepřestane."],["Ať Brayden položí nastrčené otázky sám, na kameru, pod svým jménem.","Devatenáctiletý ředitel pro publikování na sociálních sítích vstane na vlastní diskuzi a položí vlastní nastrčenou otázku pod vlastním jménem. Je to tak průhledné, že se to obloukem vrací zpátky k okouzlujícímu."]]},"j-cabinet-vacancy-record":{"t":"Rekord v neobsazených místech","x":"Hal čte z vytištěného seznamu, který se stále prodlužuje. „Devět neobsazených míst na úrovni kabinetu právě teď, pane, moderní rekord. Kongres si založil sázkový fond na to, které se obsadí příště. Chytré peníze sázejí na to, že žádné, ne před volbami v polovině období.“","c":[["Obsaďte je všechny najednou loajálními lidmi. Prověrku vynechte.","Devět pozic se obsadí jediným oznámením lidmi vybranými jen podle jedné vlastnosti. Vláda technicky funguje na plný stav, s kabinetem, který se ještě nikdy nesešel."],["Obsaďte je pomalu, řádně, jednu skutečnou nominaci po druhé.","Projdete skutečným procesem, jedno slyšení po druhém. Zabere to skoro celý rok. Na rozdíl od alternativy to ale obstojí."],["Nechte je prázdná. Náměstci si s tím poradí.","Devět ministerstev nadále funguje na nepotvrzených náměstcích, na neurčito. Je to levnější, je to rychlejší a v nejpřísnějším slova smyslu už to vlastně není vláda."],["Nechte sázkový fond Kongresu vybrat příštího kandidáta.","Skutečně přijmete vítězné jméno z kongresového sázkového fondu jako svého příštího kandidáta. Proti očekávání je to naprosto kompetentní volba."]]},"j-annual-review":{"t":"Hodnocení výkonu","x":"Deborah má hromadu formulářů, které nikdo v kabinetu ještě nikdy nevyplňoval. „První roční hodnocení výkonu pro celý kabinet, pane. Někdo je musí podle něčeho ohodnotit. Aktuální návrh hodnoticí tabulky má jedinou otázku: 'Loajalita, jedna až deset.' Právní oddělení si myslí, že potřebujeme aspoň druhou otázku.“","c":[["Nechte hodnoticí tabulku s jednou otázkou. Loajalita je jediné měřítko, na kterém záleží.","Ministři kabinetu jsou formálně hodnoceni podle jediné osy, s vaším jménem připojeným k výsledkům. Není to hodnocení výkonu. Každý v budově přesně ví, co to je."],["Přidejte skutečná měřítka. Plnění rozpočtu, výsledky programů, samotnou práci.","Hodnocení se stane skutečným posouzením toho, zda ministerstva dělají to, kvůli čemu existují. Je to nudnější. Je to ale i první poctivé papírování, které budova za celý rok vyprodukovala."],["Hodnoťte je podle loajality, ale sloupec pojmenujte 'sladění'.","Stejné měřítko přežije pod mírnějším slovem. V kabinetu to nikoho neošálí. Slovo 'sladění' se do měsíce sarkasticky používá na každé chodbě v budově."],["Ať kabinet hodnotí navzájem sám sebe, anonymně, a přečtěte to nahlas.","Anonymní vzájemná hodnocení se čtou nahlas na příští plné schůzi kabinetu. Několik z nich je neočekávaně upřímných. Ministr práce se před třinácti kolegy dozví, co si ministr energetiky doopravdy myslí o jeho schůzích."]]},"j-parting-shot":{"t":"Poslední rána na rozloučenou","x":"Kaylee má přepis, vytištěný a zvýrazněný ve třech barvách. „Bývalý generální prokurátor dal čtyřicet minut po svém odvolání živý rozhovor, pane. Nazval administrativu 'skupinovou konverzací s jadernými kódy'. Je to bohužel velmi dobrá hláška a už je to všude titulek.“","c":[["Veřejně ho zdiskreditujte. Zpochybněte jeho duševní stav, do záznamu.","Na kameru zaútočíte na charakter muže, kterého jste před pár hodinami odvolal. Vyznívá to přecitlivěle pro každého kromě základny, která to správně čte jako vymáhání loajality."],["Neříkejte nic. Ať si ta hláška odbude svůj jeden zpravodajský cyklus a vyprchá.","Odmítnete dodat dobré hlášce víc kyslíku, než už má. Vydrží den a půl místo týdne, což je celé umění nereagovat."],["Ať Sy sepíše výzvu k zanechání jednání kvůli hlášce o 'skupinové konverzaci'.","Vyhrožujete právními kroky kvůli metafoře. Samotný dopis unikne do hodiny a stane se lepší hláškou než ta původní."],["Osvojte si tu hlášku sám. Dejte ji na hrnek.","Suvenýrový obchod začne příští pondělí prodávat hrnek s nápisem 'Skupinová konverzace s jadernými kódy'. Do středy se prodává líp než pamětní Bible."]]},"k-security-clearance":{"t":"Prověrka","x":"Errol drží složku na klíně, jako by mohla každou chvíli vybouchnout. „Váš syn dvakrát neprošel bezpečnostní prověrkou, pane. Zahraniční obchodní partneři, nepřiznané půjčky, firma v Cathay, kterou nikdo pořádně nedokáže vysvětlit. Analytici doporučují zamítnutí. Já doporučuji, abyste mě nežádal o třetí zrušení.“","c":[["Zrušit to osobně. Dostane odznak.","Výjimku podepíšete sám. Trent mladší dostane odznak, kancelář a bezpečnostní doprovod, který teď musí předstírat, že si telefonátů z Cathay nevšímá."],["Nechat zamítnutí platit. Bude pracovat z domova.","Systém funguje přesně tak, jak má, tentokrát na vašem vlastním synovi, a bolí to víc, než jste čekal. On sám to navenek nese s klidem."],["Vytvořit mu nový titul bez nutnosti prověrky.","„Zvláštní poradce pro rodinné záležitosti“ nepotřebuje odznak, složku ani otázky. Kancelář si nechá. Nikdo neumí říct, co ta kancelář vlastně dělá."],["Poslat ho místo toho na nesouvisející dobročinné turné.","Syna vypravíte do tří zemí, na účet cestovního rozpočtu, aby rozdával certifikáty a stříhal pásky. Dva senátoři se písemně ptají, co vlastně propaguje. Na věci s Cathay to nic nemění."]]},"k-son-in-law-plan":{"t":"Mírový plán","x":"Muriel volí slova, jako by šlapala po drátech pod proudem. „Váš zeť má mírový plán, pane. Osmatřicet stran, žádný kariérní diplomat u toho nebyl, a příloha s odhadem hodnoty nemovitostí, která by strukturálně v mírovém plánu neměla vůbec být. Obě vlády se ptají, kdo to vlastně je.“","c":[["Oznámit to sám, dnes, z tribuny.","Odhalíte mírový plán s realitní přílohou, jako by to bylo normální. Dvě zahraniční ministerstva písemně žádají o rozhovor s někým dospělým."],["Nejdřív to poslat přes ministerstvo zahraničí. Potichu upravit stranu devět.","Muriel a její tým stráví víkend odstraňováním odhadů nemovitostí. Co zbyde, je tenké, ale aspoň se tomu nebude nikdo smát v překladu."],["Dát mu velvyslanecký titul, ať to sedí s jeho sebevědomím.","Titul bez slyšení v senátu a agenda velká jako celá polokoule. Kariérní diplomaté si jen tiše upraví organizační schéma."],["Poslat plán univerzitnímu think tanku k odbornému posouzení.","Šest profesorů ho zdarma okomentuje živě, v panelu vysílaném proti večerním zprávám. Příloha o nemovitostech dostane poznámku pod čarou, celou znějící: „viz střet zájmů výše.“ On z toho nadšený není, a nikdo jiný taky ne."]]},"k-blind-trust":{"t":"Svěřenský fond","x":"Miriam rozkládá organizační schéma s trpělivostí ženy, která tohle už jednou zažila. „Říká se tomu svěřenský fond, pane, řídí ho vaše děti a vy jim můžete kdykoli zavolat. Slepý svěřenský fond takhle nefunguje. Tohle je v lepším případě fond s tmavými brýlemi.“","c":[["Nechat to tak. Je to legální, aspoň formálně.","Uspořádání přežije díky technikálii, kterou Miriam osobně nesnáší. Děti řídí firmu, vy řídíte zemi a všichni tvrdí, že to spolu nikdy nemluví."],["Skutečně se všeho zbavit. Prodat celé portfolio.","Opravdu to prodáte. Rodina zuří, etický úřad ztichne úžasem a novinářce to musíte říct dvakrát, než tomu uvěří."],["Přejmenovat to na „Vlastenecký fond“. Nic jiného neměnit.","Nové jméno, stejné tmavé brýle. Miriam upraví jeden dokument a formálně požádá o přeložení."],["Převést fond na jméno rodinného psa.","Kokršpaněl je teď na papíře holdingová společnost. Psa nelze vyslechnout, což několik právníků poznamenává jako celý smysl toho nápadu."]]},"k-hotel-block":{"t":"Hromadná rezervace","x":"Alvin přináší výpis rezervací jako předvolání k soudu. „Qadirská delegace zarezervovala v rodinném hotelu jednačtyřicet pokojů pro cestu, na které je oficiálně šest delegátů, pane. Taky vykoupili celé spa. Nikdo tam spa využívat nemá.“","c":[["Veřejně jim poděkovat za obchod.","Na kameru přípitkem vychválíte „přátelství“ vedle účtu za spa, které nikdo nevyužil. Na chvíli ztichne i vaše základna."],["Rezervaci odmítnout. Vrátit zálohu.","Rodinná firma odmítne skutečné peníze, aby se vyhnula zdání úplatku, což je samo o sobě nejbližší věc k důkazu, že to zdání bylo přesné."],["Přesunout delegaci do konkurenčního hotelu.","Vyřešíte problém s vzhledem tím, že to stojí vaši vlastní rodinu skutečné peníze, a řeknete jim, že to byla strategie. Zcela vám to nevěří."],["Pokoje delegaci odpustit. Nazvat to diplomacií.","Zahraniční vládě darujete jednačtyřicet pokojů zdarma, což je nějakým způsobem ještě horší titulek, než kdybyste jim účtovali, a navíc to stojí skutečné peníze."]]},"k-ballroom-rental":{"t":"Pronájem sálu","x":"Muriel přes stůl posouvá fakturu za pronájem s hlavičkou zahraničního konzulátu. „Objednali si sál na galavečer dva dny před vaším rozhodnutím v jejich obchodním sporu, pane. Šedesát tisíc dolarů, zaplaceno celé, položkově uvedeno jako 'pronájem prostor'. Formálně je to jen pronájem.“","c":[["Sejít se s nimi. Vzít peníze. Rozhodnout později.","Galavečer proběhne, šek je proplacen a obchodní rozhodnutí padne o dva týdny později v jejich prospěch. Nikdo nedokáže dokázat, že posloupnost je úplatek."],["Nechat správu budovy rezervaci odmítnout.","Sál zůstane ten pátek tmavý. Rodinu to stojí storno poplatek a všem ostatním to koupí klidnou noc navíc."],["Rezervaci přijmout, formálně se v případu zdržet hlasování.","Memorandum o zdržení se je podáno téhož odpoledne, kdy je proplacen šek. Obě fakta jsou pravdivá a leží ve stejné složce, což je nějak horší než kterékoli z nich zvlášť."],["Otevřít sál tu noc místo toho veřejnosti.","Galavečer zrušíte a necháte tři sta školáků zdarma prohlédnout lustry, živě v místních zprávách. Konzulát to nazve urážkou. Kongres to nazve předvolebním divadlem na veřejné útraty."]]},"k-branded-golf":{"t":"Golfový summit","x":"Muriel má memorandum o místě konání. „Northmarská delegace dává přednost vašemu golfovému resortu, pane. Cenu pokoje určuje rodina, catering určuje rodina a poplatky za odpolední golf delegace určuje, také, rodina. Samotný summit potrvá čtyři hodiny.“","c":[["Uspořádat ho tam. Účtovat běžnou sazbu.","Summit se koná na vašich vlastních greenech a faktura jde na federální vládu. Někde auditor začíná velmi dlouhou tabulku."],["Přesunout summit na neutrální vládní objekt.","Zasedací místnost se špatnou kávou a bez zdroje příjmů. Delegace je mírně zklamaná. Audit, ke kterému by jinak došlo, se nekoná."],["Uspořádat ho tam, poplatek odpustit, nazvat to darem daňovým poplatníkům.","Prostory zdarma, stejný střet zájmů, lepší tisková zpráva. Rodina ztrátu absorbuje a příští rok si ji odečte z daní jako dar."],["Uspořádat celý summit na osmnáctém greenu, živě.","Dva hlavy států dojednávají obchodní rámec mezi jednotlivými odpaly, v televizi, fakticky sponzorováno vaší vlastní scorecard. Historikům se to bude vysvětlovat dost těžko."]]},"k-daughter-brand":{"t":"Ochranná známka","x":"Ivy září a drží složku. „Cathay schválila jedenáct ochranných známek pro šperkařskou linii během jednoho týdne, tati. Obvykle to trvá roky. Stalo se to ve stejném týdnu, kdy jsi zmírnil vývozní clo. Vím, jak to zní. Je to ale taky jen dobrá zpráva pro naši značku.“","c":[["Pogratulovat jí z tribuny. Zmínit značku jménem.","Z prezidentské tribuny propagujete dceřinu šperkařskou linii vedle země, jejíž ochranné známky právě prošly rekordní rychlostí. Slovo „náhoda“ si pořádně odpracuje."],["Nechat právníky potvrdit, že schválení bylo rutinní.","Memorandum potvrzuje, že se nestalo nic nepatřičného, což je typ věci, která je pravdivá a přitom vůbec nepomáhá."],["Požádat ji, ať licencuje značku někde politicky méně hlučném.","Výrobní příběh linky se přesune do země bez probíhajícího obchodního sporu. Je to tišší. Je to také, nutno podotknout, správné rozhodnutí."],["Spustit konkurenční linii pod prezidentskou pečetí.","Objeví se kolekce doplňků s prezidentskou pečetí, záměrně podbízející ceny vlastní dcery. Díkůvzdání je prý podle všech zpráv napjaté."]]},"k-son-business-deal":{"t":"Zámořský obchod","x":"Trent mladší volá na hlasitý odposlech, nadšený sám sebou. „Tati, dohoda s Rusalkou je hotová. Dvě stě milionů, na deset let, moje jméno na budově. Pořád opakovali, jak si rodinu váží. Ani jsem nemusel vyjednávat.“","c":[["Pogratulovat mu. Nepokládat žádné doplňující otázky.","Řeknete mu dobrá práce a zavěsíte. Věž vyroste s jeho jménem na fasádě, jedenáct pater od námořní základny. Technicky vzato jste se na nic neptal."],["Nechat právníky prověřit to na střety zájmů, než podepíše cokoli dalšího.","Sy stráví týden čtením smlouvy, kterou číst nechtěl, a najde tři ustanovení, za která by se měl stydět kdokoli zúčastněný. Upozorní na ně. Trent mladší stejně podepíše."],["Požádat ho, ať aspoň změní jméno budovy.","Věž si obchod ponechá a ztratí ze fasády rodinné příjmení. Je to to nejmenší, co mohl udělat, a udělá přesně to."],["Nechat ho darovat výtěžek nadaci. Kterou taky vedete vy.","Dvě stě milionů dolarů přejde z jedné rodinné entity do druhé, daňově zvýhodněně, a v tiskové zprávě je to popsáno jako štědrost."]]},"k-nepo-hire":{"t":"Bratranec","x":"Deborah má životopis, takový, jaký je. „Váš bratranec chce vést agenturu pro malé podnikání, pane. Za sebou má zkrachovalý řetězec solárií a naprostou osobní loajalitu vůči vám. To jsou bohužel jediné dvě kvalifikace, na které se dnes někdo ptá.“","c":[["Dát mu agenturu. Loajalita je taky kvalifikace.","Muž, jehož poslední podnik třikrát zkrachoval, teď dohlíží na půjčky malým podnikům. Je, to všichni uznávají, mimořádně loajální."],["Dát mu místo toho čestný titul. Bez rozpočtové pravomoci.","Dostane pěknou kancelář, jmenovku a nulovou možnost cokoli podepsat. Je nadšený. Agentuře se nic nestalo."],["Najmout někoho kvalifikovaného. Jeho udělat jejím 'seniorním poradcem'.","Skutečná administrátorka vede agenturu, zatímco bratranec ji všude stínuje a nabízí názory, na které je profesně povinná přikyvovat."],["Poslat ho vést nejméně důležité velvyslanectví, jaké najdete.","Je teď velvyslancem v zemi s jedenácti tisíci obyvateli a spoustou korálových útesů. Korálům to, podle všeho, nevadí."]]},"k-inauguration-fund":{"t":"Inaugurační fond","x":"Lyle má účetní knihu otevřenou na stránce, kterou by nejraději zavřel. „Inaugurační výbor vybral víc peněz než kdykoli předtím, pane. Třetina z toho není nikde zaúčtovaná. Výboru předsedala vaše dcera. Tohle striktně není moje agenda, ale někdo to musel říct nahlas.“","c":[["Neauditovat to. Byl to skvělý večírek.","Nezaúčtovaná třetina zůstane nezaúčtovaná. Večírek, to všichni uznávají, byl opravdu vynikající."],["Nařídit nezávislý audit výboru.","Externí firma spočítá každý dolar. Najde nedbalost, ne krádež, což je úleva, která vás stejně stojí titulek."],["Potichu doplnit chybějící třetinu z kampaňového účtu.","Díra je zalepena penězi z úplně jiného kotle, což vyvolá novou otázku, kterou se zatím nikdo neptá."],["Prohlásit inauguraci zpětně za neziskovou akci.","Jednodenní gala ve smokinzích je dodatečně překlasifikováno na charitativní akci. Finanční úřad žádá o telefonát. Ten nepřijmete."]]},"k-secret-service-bill":{"t":"Účet za ochranku","x":"Duane čte fakturu bez emocí, jako muž, který čte číslo, jež nedokáže změnit. „Ochrana vašich vnoučat v resortu stojí toto čtvrtletí jeden a jednu desetinu milionu dolarů, pane, většinou za noci v objektech, které vlastní rodina. Účtovaná sazba je standardní sazba. To je nějak přesně ta část, která lidi štve nejvíc.“","c":[["Tržní cena je tržní cena. Naúčtovat to.","Vláda platí maloobchodní cenu firmě, kterou vlastníte, aby chránila lidi, kteří nosí vaše jméno. Logika je neprůstřelná a dopad na veřejné mínění radioaktivní."],["Nechat rodinu pokoje odpustit.","Federální agenti mají pokoje zdarma. Stojí to firmu skutečné příjmy a koupí vám to přesně jeden klidný zpravodajský den."],["Přesunout vnoučata místo toho do vládního zařízení.","Méně vymožeností, žádný střet zájmů, žádný titulek. Něčí neteř Madison to nazve „velmi normální volbou, za kterou se musí chválit.“"],["Účtovat se slevou a nazvat tu slevu 'vlasteneckou sazbou'.","Nová, vymyšlená sazba, uplatněná zpětně, popsaná jako štědrost samotnou firmou, která ji stanovuje. Nikdo na ministerstvu financí nedokáže najít ceník té slevy."]]},"k-family-christmas-card":{"t":"Vánoční přání","x":"Renata zvedá nátisk. „Je to hezká fotka, pane. Všichni ve stejných svetrech. Problém je, že drobným písmem pod stromečkem stojí 'Veselé svátky od rodiny a kolekce Resort'. Dostalo se to na čtyři sta tisíc vládních adres, než si toho někdo všiml.“","c":[["Poslat to tak, jak je. Je to jen logo.","Čtyři sta tisíc federálních zaměstnanců dostane fakticky reklamu na svátky. Tři z nich si ji přesto zarámují."],["Přetisknout bez drobného textu. Náklady jde na vlastní vrub.","Čistá, nudná pohlednice bez loga jde ven o týden později. Přijímá se vřele a nevyvolá žádné další články, což byl celý smysl."],["Svést to na tiskárnu, která drobný text přidala.","Tiskárna v klíčovém státě je veřejně obviněna z rozhodnutí učiněného o dvě patra výš. Tiskárna neřekne nic a kvůli tomu nepřijde o spánek."],["Vsadit na to. Příští rok přidat slevový kód.","Příští pohlednice obsahuje patnáct procent slevy na wellness pobyt. Jeden senátor si ji zarámuje a přečte ji nahlas z pléna, celých devět minut."]]},"k-in-laws-visa":{"t":"Rychlý pruh","x":"Duane si to dvakrát ověří, než to řekne nahlas. „Rodiče vašeho zetě prošli celým řízením o trvalém pobytu za jedenáct dní, pane. Průměr je čtrnáct měsíců. Nikdo přesně neporušil žádné pravidlo, jen odsunuli papírování všech ostatních stranou, aby to stihli.“","c":[["Je to rodina. Zrychlit to ještě víc.","Jedenáct dní se u příští žádosti změní na šest. Lidé, jejichž spisy byly odsunuty stranou, nejsou z definice ti, na koho míří kamery."],["Vrátit je do běžné fronty.","Papírování se vrátí zpět mezi čtrnáct měsíců čekání obyčejných Američanů z obyčejných důvodů. Je to spravedlivé. Na rodinné večeři to tak nikdo nenazve."],["Schválit to, ale požadovat stejnou rychlost pro všechny.","Nařídíte zrychlit celý systém, aby laskavost přestala vypadat jako laskavost. Je to drahé, je to správné a je to nejméně dramatické řešení, jaké je k dispozici."],["Nechat tchána s tchyní místo toho veřejně požádat o dodatečné prověření.","Tchán s tchyní na kameru požádají o dodatečné bezpečnostní prověření, což polovině tisku připadá jako divadlo a nikoho v Kongresu, který stále žádá skutečnou reformu, to neuspokojí."]]},"k-resort-summit":{"t":"Summit v resortu","x":"Muriel už tuhle debatu jednou prohrála. „Protokol chce neutrální vládní místo, pane, z obvyklých důvodů. Vy chcete resort, protože sál se lépe fotí a rodina má rezervaci. Říkám vám obě fakta, aby později nikdo nemohl tvrdit, že jsem to neřekla.“","c":[["Resort. Konečná odpověď.","Šest hlav států jedná pod lustrem, který vaše rodina prodala vládě s přirážkou. Fotky jsou, budiž řečeno, velkolepé."],["Řídit se radou protokolu. Neutrální místo.","Vládní konferenční centrum s horším osvětlením a bez střetu zájmů. Je to volba, která dobře stárne a nikoho v místnosti nenadchne."],["Sál pro galavečer, vládní místo pro vlastní jednání.","Kompromis napůl, který dá rodině polovinu rezervace a etickému úřadu polovinu bolesti hlavy. Všichni odejdou nespokojeni, což Muriel nazývá pokrokem."],["Uspořádat summit místo toho na válečné lodi. Ničí hotel.","Šest světových lídrů jedná na torpédoborci na rozbouřeném moři. Dva jsou mořsky nemocní, protokol to nazve diplomatickým incidentem čekajícím na vypuknutí a jeden kongresman se ptá, kdo platí palivo."]]},"k-golf-membership":{"t":"Náborová akce","x":"Miriam má seznam nových členů, který vypadá jako zasedací pořádek státní večeře. „Čtrnáct nových členství v klubu tento kvartál, pane, všichni cizí státní příslušníci, všichni žádají o schůzky s vaším týmem do měsíce. Jen vstupní poplatek je dvě stě tisíc dolarů. Kupuje si za něj skříňku a zjevně i zpětné zavolání.“","c":[["Přijmout schůzky. Byznys je byznys.","Čtrnáct skříněk, čtrnáct schůzek, jeden velmi efektivní kalendář. Miriamin úřad otevírá spis, který nikdy nebude smět uzavřít."],["Zastropovat zahraniční členství a zmrazit nová přijetí.","Klub přestane prodávat přístup převlečený za golf. Je to správná náprava a stojí rodinu skutečně vyčíslitelnou částku peněz."],["Schůzky přijmout, golf vynechat, nazvat to náhodou.","Stejný kalendář, jen bez holí v ruce. Rozdíl neuspokojí nikoho, ale formálně jde o rozdíl."],["Zveřejnit seznam členů. Celý. Ještě dnes.","Plná transparentnost, okamžitě, dřív, než o ni kdokoli požádal. Čtrnáct členů do týdne tiše odstoupí a čtyři spojenci na Kapitolu to nazvou vlastnoručním průšvihem pro rodinný fundraising."]]},"k-financial-disclosure":{"t":"Majetkové přiznání","x":"Miriam žlutě zvýraznila jedenáct řádků. „Vaše roční přiznání, pane. 'Hodnota majetku: mezi jedním a padesáti miliony dolarů' je formálně povolené a formálně k ničemu. Udělal jste to u jedenácti různých položek. Je to buď mimořádná opatrnost, nebo mimořádné vyhýbání se, a hádat mi nepřísluší.“","c":[["Podat to přesně takhle. Každý rok.","Jedenáct rozpětí tak širokých, že skoro nic neznamenají, se stane každoroční tradicí. Je to legální. Miriam to podá a znovu požádá o přeložení."],["Zpřesnit každé rozpětí na skutečné číslo.","Skutečná čísla jdou do záznamu, což je neobvyklé, nepříjemné a přesně to, k čemu byl formulář navržen."],["Zpřesnit polovinu rozpětí. Trapné položky nechat vágní.","Selektivní transparentnost, která uspokojí formulář a nikoho pozorného neoklame, což se ukáže být skoro každý, kdo dává pozor."],["Podat místo formuláře ručně psanou poznámku.","Jediná stránka s celým textem: „Je to složité, zeptejte se mého účetního“ je podána místo federálního přiznání. Proti veškerým očekáváním je přijata a založena."]]},"k-niece-madison-job":{"t":"Povýšení","x":"Madison, dvaadvacet let, drží vizitku s nápisem „Náměstkyně ředitele pro strategické iniciativy“. „Ani já nevím pořádně, co to znamená, strýčku,“ říká. „Ale mám teď odznak a Deborah říká, že musím sedět na rozpočtové poradě. Mám na té rozpočtové poradě něco říkat?“","c":[["Dát jí skutečnou pravomoc. Rodina táhne za jeden provaz.","Dvaadvacetiletá dívka s vizitkou teď fakticky velí lidem dvakrát starším. Dva z nich toho odpoledne začnou upravovat životopisy."],["Nechat titul čestný. Žádná podpisová pravomoc.","Madison si nechá odznak a přijde o rozpočtovou poradu. Pokud vůbec, vypadá spíš úlevně."],["Poslat ji místo toho vést něco malého a vzdáleného.","Teď vede regionální kancelář pro vnější vztahy, kterou nikdo nenavštívil od reorganizace před dvěma vládami. Vrhne se do toho, upřímně."],["Nechat ji stínovat Deborah na plný úvazek. Žádný titul.","Žádný odznak, žádná vizitka, jen osmnáct měsíců učení se skutečné práce od člověka, který ji dělá nejlépe. Novináři tomu říkají degradace v přestrojení za pokoru a Madisonina matka vám kvůli tomu volá každý večer stěžovat si."]]},"k-hotel-emoluments-suit":{"t":"Žaloba za výhody","x":"Sy má žalobu podanou proti vám osobně, což ho profesně vzrušuje a osobně vyčerpává. „Podepsalo se pod ni dvě stě šest členů Kongresu, pane. Jejich teorie zní, že zahraniční vláda platící vašemu hotelu je fakticky zahraniční vláda platící vám. Není to, s úctou, špatná teorie.“","c":[["Bojovat. Každý soud, každé odvolání.","Tři roky a několik milionů dolarů na právnících nakonec potvrdí, že klauzule je reálná, ale těžko vymahatelná. Vy to nazýváte vítězstvím."],["Vyrovnat se. Sporný zisk věnovat na charitu.","Rodina vystaví šek potravinové bance ve výši zahraničních zisků a žaloba je stažena. Je to levnější než právníci a vypadá to, jednou za čas, jako ta snadná cesta byla i ta správná."],["Argumentovat, že ústava tohle vlastně nemyslí vážně.","Vaši právníci s vážnou tváří argumentují, že dvě stě let stará protikorupční klauzule se nevztahuje na hotely. Tři soudci je žádají, ať to zopakují pomaleji."],["Prodat hotel v anonymní aukci. Opravdu anonymní.","Nemovitost připadne nejvyšší zapečetěné nabídce, jejíž identita zůstane neznámá i vám, na vaše vlastní naléhání. Právníci nevěří, že jste to opravdu udělal, dokud nepřijde platba, a polovina vašich vlastních dárců to nazve aktem sebepoškození."]]},"k-family-portrait":{"t":"Oficiální portrét","x":"Renata odhaluje plátno. „Oficiální portrét, pane. Namalovaný přesně podle zadání, až na to, že malířka bez vyzvání zakomponovala do okna za vámi siluetu rodinného resortu. Je to buď pocta, nebo faktura na čtyři čísla v přestrojení za umění. Nedokážu poznat, co z toho, a ona taky ne.“","c":[["Pověsit ho tak, jak je. Silueta zůstává.","Každý navštěvující hodnostář, který stojí v té chodbě, teď dostane pohled na siluetu vašeho hotelu zdarma. Malířka získá skvělý argument pro svou další zakázku."],["Nechat siluetu přemalovat. Neutrální pozadí.","Obyčejná vládní modř nahradí siluetu. Je to nudnější a je to správné, a Renata už fakturu nikdy nezmíní."],["Objednat druhý portrét, tentokrát jen resortu.","Ve stejné chodbě teď visí dva portréty. Jeden vás, jeden budovy, kterou vlastníte. Průvodce začne dostávat otázku, na kterou nebyl vyškolen."],["Nechat malířku po zbytek funkčního období malovat, co chce.","Renata dostane plnou tvůrčí volnost pro veškeré další oficiální snímky. Výsledky jsou zvláštní, občas krásné, a tři vedoucí úřadů formálně žádají, aby nebyli zobrazeni s ovocem v ruce."]]},"k-son-tweet":{"t":"Příspěvek","x":"Brayden má snímek obrazovky uložený už na třech místech. „Váš syn napsal příspěvek o obchodním jednání, pane. Živě. Přímo z místnosti. Northmarského vyjednavače nazval, cituji, 'docela slaboch, upřímně'. Má to čtyři sta tisíc lajků a northmarské velvyslanectví už dvakrát volalo.“","c":[["Sdílet to znovu s emoji ohně.","Zesílíte, jak váš vlastní syn uráží obchodního partnera uprostřed vyjednávání. Základna to považuje za hilarní. Vyjednávání ne."],["Smazat to. Nechat ho zavolat velvyslanectví a omluvit se.","Tiché smazání a nepříjemný, upřímný telefonát vyřeší devadesát procent škody. Snímek obrazovky samozřejmě existuje navždy."],["Tvrdit, že účet byl hacknut.","Za synův upřímný názor, živě odtweetovaný z bezpečné místnosti, kam s telefonem vůbec neměl chodit, obviníte hackera. Nikdo vám nevěří, syna nevyjímaje."],["Nechat Braydena od teď psát jeho příspěvky za něj.","Devatenáctiletý mladík je teď jediným redakčním filtrem zahraničněpolitických komentářů dospělého muže. Zpráva unikne do týdne a pokrytí synovy zprostředkované zahraniční politiky je, ne-li horší, tak přinejmenším stejně trapné jako originál."]]},"k-daughter-un-seat":{"t":"Místo u stolu","x":"Priya se velmi snaží být diplomatická ohledně diplomacie. „Vaše dcera má místo u stolu delegace Valného shromáždění, pane, mezi ministrem a mnou. Nemá titul, hlas ani briefing. Čtyři jiné delegace se už tiše ptaly, kdo to je.“","c":[["Dát jí skutečný titul, ať odpovídá místu.","„Zvláštní zástupkyně“ se objeví na jmenovce do oběda. Zodpoví to otázku a vyvolá tři další."],["Přesunout její místo do galerie. Jen pozorovatelka.","Sleduje to z galerie jako kdokoli jiný, kdo formálně není diplomat. Je to správné a je viditelně znuděná."],["Nechat ji místo toho vést vedlejší akci. Fotogenickou, s nízkými sázkami.","Panel o mladém podnikání, dobře nasvícený, mimo záznam a zcela oddělený od čehokoli závazného. Všichni dostanou, co chtěli."],["Nechat ji formálně akreditovat jako tisk na celý týden.","Vaše dcera pokrývá summit jako akreditovaná novinářka a klade vlastní otcově delegaci vstřícné otázky z druhé řady. Tři skuteční novináři žádají o vyjádření. Do záznamu."]]},"k-hotel-inspection":{"t":"Kontrola","x":"Wendell má zprávu o závadách. „Čtrnáct závad v kuchyni rodinného hotelu, pane, čtyři z nich vážné. Regionální úřad ji chce zveřejnit, standardní postup. Dnes už jsem byl neformálně dvakrát požádán, jestli je standardní postup opravdu nutný zrovna tady.“","c":[["Nechat ji potichu překlasifikovat na drobné.","Čtrnáct závad se stane čtyřmi poznámkami pod čarou. Inspektor, který napsal původní zprávu, je přeložen do regionu s méně hotely."],["Zveřejnit ji. Stejně jako u jakékoli jiné nemovitosti.","Zpráva vyjde přesně tak, jak byla napsaná. Kuchyně napraví závady za devět dní, což je mimochodem nový firemní rekord."],["Rychle a potichu to opravit, než zpráva vyjde.","Velmi rychlá a velmi drahá noční renovace zajistí, že následná kontrola bude čistá. Původní zpráva technicky vzato pořád někde existuje."],["Pozvat zdravotní úřad na slavnostní přestřižení pásky za opravenou kuchyni.","Slavnostní ceremonie za dodržení zákona, který každá jiná restaurace v zemi dodržuje bez ceremonie. Wendell přestřihne pásku a záměrně neřekne nic pozoruhodného."]]},"k-license-deal":{"t":"Licenční smlouva","x":"Lyle vysledoval peníze o tři vrstvy hluboko a vyčerpaně se zastavil. „Státem propojený developer v Qadiře chce licencovat rodinné jméno pro věž, pane. Čtyřicet milionů předem, nevratné. O šest týdnů později má váš obchodní úřad rozhodnout o jejich celní výjimce. Tuhle časovou osu jsem nekreslil já. Nakreslila se sama.“","c":[["Podepsat licenci. Ať se rozhodnutí o clu stane, kdy se stane.","Věž dostane povědomé jméno ve zlatých písmenech a čtyřicet milionů dolarů se přesune dřív, než kdokoli o čemkoli rozhodne. Rozhodnutí, až přijde, dopadne v jejich prospěch."],["Odmítnout licenci, dokud nepadne rozhodnutí o clu, ať už jakékoli.","Rodina odmítne čtyřicet milionů dolarů, aby zachovala čistou posloupnost. Je to jednoznačně nejdražší etické rozhodnutí celého funkčního období."],["Podepsat to, zdržet se hlasování o rozhodnutí, nechat rozhodnout náměstka.","Náměstek rozhodne stejně, jak byste rozhodl vy. Memorandum o zdržení se je neprůstřelné a uspokojí přesně ty lidi, kteří vám už tak důvěřovali."],["Podepsat licenci a ze vzdoru osobně zamítnout celní výjimku.","Vezmete si jejich čtyřicet milionů a pak proti nim stejně rozhodnete, abyste dokázal, že vás nelze koupit. Jeden obchodní právník to nazve „nejpodivnějším možným způsobem, jak dokázat negaci“."]]},"k-family-cabinet-meeting":{"t":"Extra židle","x":"Deborah počítá hlavy u vládního stolu a vychází jí o dva víc. „Váš syn a dcera jsou oba v místnosti na briefingu o clech, pane. Ani jeden z nich nemá funkci, která by vyžadovala prověrku pro tohle téma. Ministr obchodu už začal mluvit k nim místo ke mně.“","c":[["Nechat je tam. Jsou chytřejší než polovina tohoto stolu.","Dvě židle bez titulu teď fakticky převyšují kabinetního ministra, ne-li na papíře, tak v praxi. Podle toho si upraví projev, což samo o sobě něco vypovídá."],["Rodina se bude scházet zvlášť. Kabinet zůstává kabinetem.","Pozdě stanovená pevná hranice přesto drží. Příští briefing trvá o jedenáct minut kratší a nikdo přesně neumí říct proč to působí jinak."],["Dát jim stálou pozvánku, ale bez práva mluvit.","Sedí, poslouchají, v místnosti nahlas neřeknou nic. Co se stane na chodbě potom, je úplně jiná věc."],["Přidat dvě další prázdné židle. Ať přijde celá rodina.","Šest členů rodiny teď navštěvuje bezpečnostní briefing, na který dřív byla nutná prověrka. Místnost potřebuje větší stůl dřív, než potřebuje cokoli jiného."]]},"k-in-law-ambassadorship":{"t":"Post","x":"Muriel si ještě jednou přečte kvalifikace kandidáta, pro případ, že by jí něco uniklo. „Váš švagr nemluví francouzsky, pane, nikdy nezastával veřejnou funkci a věnoval jedenáct milionů dolarů na vaši kampaň. Post je Paříž. Slyšení o potvrzení bude, a používám toto slovo profesně, brutální.“","c":[["Nominovat ho stejně. Protlačit to.","Je potvrzen poměrem hlasů podle stranické linie po slyšení, kde nedokáže jmenovat francouzského ministra zahraničí. Práci se pomalu učí, veřejně."],["Nominovat místo něj kariérního diplomata. Dát mu něco čestného.","Velvyslanectví dostane někoho, kdo tohle už opravdu dělal. Švagr dostane tabuli se jménem a stálou pozvánku na večeře."],["Nominovat ho na menší post. Snížit sázky.","Stane se velvyslancem v zemi s méně novináři a kratším letem domů. Ten dar, jak se ukázalo, měl zhruba tuhle hodnotu."],["Nechat ho před slyšením absolvovat rychlokurz francouzštiny.","Šest týdnů intenzivních lekcí vyprodukuje muže, který si umí objednat oběd a málo co víc. Na slyšení použije přesně čtyři francouzská slova. Tři senátoři celé to divadlo nazvou povýšeneckým, čtvrtý se prostě jen zasměje."]]},"k-golf-tax":{"t":"Ochranné břemeno","x":"Lyle má odhad, a druhý, naprosto odlišný odhad. „Rodina uplatnila ochranné břemeno na golfovém hřišti, pane. Odpočet ve výši jednadvaceti milionů dolarů. Nezávislý odhadce stanovuje skutečnou hodnotu blíž ke čtyřem. To není zaokrouhlovací chyba. To je jiné hřiště.“","c":[["Podat vyšší číslo. Ať si vás finanční úřad najde sám.","Jde tam vyšší odpočet. Teď to ušetří skutečné peníze a později to koupí víceletý audit, o kterém několik účetních soukromě doufalo, že prostě odezní."],["Opravit to na poctivý odhad.","Rodina dobrovolně vrátí sedmnáct milionů dolarů z uplatňované hodnoty. Účetní, který to doporučil, jde do předčasného důchodu, spokojený a bohatý."],["Rozdělit rozdíl. Podat číslo někde mezi.","Kompromisní číslo, které nepotěší žádného odhadce a neuspokojí žádného auditora, ale je dost obhajitelné, aby přežilo první kontrolu."],["Darovat golfové hřiště místo toho útočišti pro divokou zvěř.","Osmnáct jamek se skutečně a natrvalo stane ptačí rezervací. Je to nejdražší vtip, jaký kdy kdo v rodině udělal sám o sobě, a každý dárce, který chtěl tu daňovou úlevu, volá téhož odpoledne, zuřivě."]]},"k-peace-prize-plan":{"t":"Společná nominace","x":"Muriel si dvakrát přečte nominační dopis, aby se ujistila. „Váš zeť podal společnou nominaci, pane. Obě vaše jména, za mírový rámec, který vyjednal s vaším podpisem na něm. Odpověď výboru se zdvořile ptá, jestli je tohle rodinný plán, nebo zahraniční politika.“","c":[["Schválit společnou nominaci. Podělit se o slávu.","Dvě jména na jednom nominačním dopise za jeden rámec, kterému mimo rodinu doopravdy nikdo úplně nerozumí. Odpovědi výboru jsou s každým kolem sušší."],["Nominovat jen jeho. Sám se z toho stáhnout.","Ustoupíte od vlastní nominace na cenu, aby ji dostal skutečný vyjednavač. Je to zvláštní věc, na kterou být hrdý, a vy jste na ni, potichu, hrdý."],["Stáhnout obě jména. Nominovat kariérního diplomata, který odvedl skutečnou práci.","Úředník, o kterém nikdo nikdy neslyšel, dostane zásluhu a nakonec i reálnou šanci na ocenění. Je to nejnesobečtější věc za celé funkční období a mimo budovu si toho nikdo nevšimne."],["Nechat Trenta mladšího taky podat nominaci. Za sebe. Nesouvisející.","Váš syn podá vlastní, zcela samostatnou nominaci na humanitární cenu spojenou s golfovým turnajem na sbírku. Výbor má teď v evidenci tři členy rodiny za jeden cyklus."]]},"k-security-detail-cost":{"t":"Stálá ochranka","x":"Duane má roční číslo a chystá se na reakci. „Ochrana rodiny v resortu stojí osmdesát dva tisíc dolarů denně, když tam pobýváte, pane. Většina jde na pronájem pokojů, za rodinou stanovenou standardní sazbu, placenou daňovým poplatníkem, rodině.“","c":[["Pobyt zůstává. To číslo je cena bezpečnosti.","Osmdesát dva tisíc dolarů denně se stane položkou, kterou v rodině nikdo nezpochybňuje a mimo ni ji zpochybňuje každý."],["Přestěhovat se. Použít místo toho vládní ubytovnu.","Skromný federální objekt s horšími výhledy a bez sporu o fakturaci. Ochranka stojí zlomek a fotí se to jako trest."],["Vyjednat denní sazbu dolů. Veřejně.","Rodina souhlasí se zlevněnou vládní sazbou, oznámenou s jistou parádou, která pořád vychází výrazně výš, než by účtoval hotel o dvě města dál."],["Nechat ochranku místo toho tábořit na pozemku. Stany.","Federální agenti si postaví stany na zadním hřišti, aby se vláda nemusela účtovat za pokoje. Ušetří to peníze a je to, podle jakéhokoli měřítka, šílený obrázek, který se bude muset později vysvětlovat."]]},"k-family-ethics-pledge":{"t":"Rodinný slib","x":"Miriam navrhla slib, u kterého nečeká, že ho někdo podepíše smysluplně. „Žádá rodinné příslušníky, aby se zdrželi nových zahraničních obchodů, dokud budete ve funkci, pane. Je dobrovolný, nevymahatelný, a existuje hlavně proto, aby na něj mohl někdo ukázat, až bude porušen, což se stane.“","c":[["Nechat všechny podepsat. Ceremonie, kamery, celé to divadlo.","Podpisová ceremonie za dokument bez zubů vyprodukuje skvělé fotky a nulovou skutečnou zdrženlivost. Miriam to založí a čeká."],["Udělat ho závazným. Skutečné postihy za porušení.","Slib se skutečnými důsledky podepíše neochotně méně lidí, a přesně proto něco znamená."],["Vynechat slib. Vydat místo toho prohlášení o hodnotách.","Prohlášení o hodnotách nevyžaduje podpis a nevytváří žádný záznam. Je to svým způsobem nejupřímnější dokument, jaký rodina za celý rok vyprodukuje."],["Nechat rodinu slíbit si to navzájem místo etickému úřadu.","Soukromý, notářsky ověřený slib mezi členy rodiny, uložený nikde, kde by ho vláda viděla. Miriam se rozumně ptá, k čemu to vůbec bylo."]]},"k-resort-markup":{"t":"Přirážka","x":"Alvin porovnal jedenáct cest s jedenácti srovnatelnými hotely. „Každá tuzemská cesta letos zahrnovala aspoň jednu noc v rodinné nemovitosti, pane, za sazbu zhruba o čtyřicet procent nad tržním průměrem v okolí. Cestovní oddělení tomu potichu mezi sebou začalo říkat 'přirážka'.“","c":[["Rezervovat tam dál. Je to praktické.","„Přirážka“ se stane trvalou, nevyslovenou položkou federálního cestovního rozpočtu. Je to praktické v tom smyslu, že se na ni všichni přestanou ptát."],["Zastropovat sazbu na výši vládního stravného.","Rodina přijme standardní vládní sazbu jako kterýkoli jiný dodavatel. Stojí je to reálnou částku čtvrtletních příjmů a koupí zpět reálnou dávku důvěryhodnosti."],["Rezervovat tam méně nocí. Rozložit cesty jinam.","Cestovní oddělení mírně rozprostře trasu. Přirážka se zmenší. Nikdo si toho zlepšení nevšimne, což je ten nejlepší druh."],["Zveřejnit 'přirážku' jako iniciativu za transparentnost.","Nařídíte zveřejnit přirážku, položku po položce, jako ukázku otevřenosti. Je to otevřeně a nepopiratelně trapné a několik spojenců na Kapitolu se ptá, proč jste je nevaroval dopředu."]]},"k-daughter-fashion-trademark":{"t":"Zahraniční ochranná známka","x":"Ivy má dobrou zprávu a příznačně nevidí k ní připojenou tu špatnou. „Rusalka právě schválila celou linii kabelek, tati, sedm ochranných známek za jedno odpoledne. Náhodou je to stejné odpoledne, kdy jejich prezident přijíždí na návštěvu. Slibuji, že jsem to načasování neplánovala.“","c":[["Zmínit kabelky vřele během přípitku při státní návštěvě.","Přípitek na státní večeři obsahuje nevyžádanou reklamu na linii kabelek. Navštěvující prezident se pro kamery usměje a potom to nikomu nezmíní, což vypovídá víc, než by řekl."],["Požádat ji, ať s uvedením počká, dokud návštěva neskončí.","Dvoutýdenní odklad aspoň v kalendáři oddělí ochranné známky od přípitku. Zlobí se. Je to, opět, správné rozhodnutí."],["Neříkat nic. Ať ochranné známky mluví samy za sebe.","Veřejně to nekomentujete, což obchodní novinářce nezabrání všimnout si data schválení stejně."],["Nechat ji darovat zisky z linie z té konkrétní země.","Každý dolar vydělaný z té konkrétní země, ten konkrétní týden, jde veřejně a položkově uprchlické charitě. Je to zvláštně konkrétní a zvláštně účinné."]]},"k-son-reality-show":{"t":"Schůzka o pořadu","x":"Kaylee si dvakrát přečetla scénář v naději, že se druhým čtením zlepší. „Streamovací síť chce dát vašemu synovi reality show, pane. Pracovní název, a čtu to přesně tak, jak je napsáno, 'První syn'. Nabízejí osmimístnou částku. On už si vybral znělku.“","c":[["Nechat ho to udělat. Skvělá propagace pro rodinu.","Odvysílá se osm dílů, kde váš syn vypráví o vlastní blízkosti k moci. Sledovanost je vysoká. Právní oddělení Bílého domu sleduje každý díl s viditelnou hrůzou."],["Nechat ho odmítnout. Vypadalo by to jako zneužívání úřadu.","Odmítne osmimístnou částku, hlasitě a veřejně, rámováno jako princip. Tentokrát to skutečně principem i je."],["Vyjednat menší, 'vkusnější' dokument místo toho.","Jednohodinový speciál nahradí celou sezónu. Je to nějak zároveň důstojnější a přitom pořád, nepochybně, reklama na rodinu."],["Požadovat tvůrčí kontrolu a udělat z toho kuchařskou show.","„První syn“ se stane kulinářskou soutěží bez jediné zmínky o politice. Je to skutečný hit. Kulinářští kritici jsou zmatení a, neochotně, spokojení."]]},"k-thanksgiving":{"t":"Díkůvzdání","x":"Deborah stojí na kraji jídelny, nepozvaná, ale přesto přivolaná. „Váš syn chce ministerstvo obchodu, pane. Vaše dcera chce, aby dostal doslova jakoukoli jinou funkci. Řeší se to teď, u krocana, před tchánem a tchyní, a řekli mi, ať 'jsem prostě tady pro jistotu'. Chci mít v záznamu, že jsem si tohle nevybrala.“","c":[["Vyřešit to hned tam. Dát mu obchod.","Post v kabinetu se rozhodne u omáčky, před příbuznými, kteří teď budou čekat stejné zacházení. Deborah sepíše skutečné papíry v pondělí."],["Odložit to. „Proberem to v pondělí, v kanceláři.“","Rozhodnutí počká na zasedací místnost místo jídelního stolu. Krocan vychladne. Precedens tentokrát drží."],["Dát tu funkci ani jednomu. Oznámit místo toho třetího bratrance.","Nečekané jmenování, které nikdo u stolu nečekal, ukončí hádku tím, že udělá nešťastnými všechny stejnou měrou. Deborah tomu říká osobní specialita."],["Uspořádat rodinné hlasování. Babička rozhoduje remízu.","Kabinetní ministr je vybrán zvednutím rukou u sváteční tabule, s rozhodujícím hlasem jednadevadesátileté babičky, která si myslela, že se hlasuje o nádivce."]]},"k-family-foundation":{"t":"Kontrola nadace","x":"Sy má účetnictví nadace rozložené po stole jako místo činu, což to v jistém smyslu je. „Nadace zaplatila za váš portrét, pane, visící v resortu. Zaplatila i vyrovnání vaším jménem. Charitativní nadace nesmí dělat ani jedno z toho. Tohle není šedá zóna. Tohle je velmi jasně vyznačená zóna.“","c":[["Nechat nadaci fungovat přesně jak doteď.","Nic se nezmění. Úřad státního generálního prokurátora otevře spis s jménem vaší rodiny, natrvalo, na deskách."],["Zrušit nadaci. Zbylé prostředky rozdělit skutečným charitám.","Celý ten prostředek je zavřen a to, co zbylo, je skutečně rozdáno organizacím, které nejste vy. Je to pozdě, drahé a správné."],["Portrét a vyrovnání uhradit osobně. Nadaci ponechat.","Osobní šek pokryje dvě nejzjevnější porušení, zatímco entita samotná přežije, aby dělala menší chyby později."],["Přejmenovat nadaci na 'institut odkazu' a začít znovu.","Stejná aktiva, stejná rodina, nová hlavička. Úřad generálního prokurátora suše podotkne, že nové jméno nepředstavuje nové chování."]]},"k-grandkids-situation-room":{"t":"Operační místnost","x":"Generál Tarrant volí slova s péčí muže, který tohle už tento měsíc jednou hasil. „Vaše vnoučata byla v operační místnosti během briefingu, pane. Ne u ní. V ní. Jedno se zeptalo, jestli je červený telefon skutečný. Nevěděl jsem, jak odpovědět upřímně a přitom si udržet práci.“","c":[["Ať se dívají. Je to poučné.","Dvě děti teď mají náhodný přístup k materiálům výrazně přesahujícím jejich, a všech ostatních, úroveň prověrky. Tarrant formálně žádá o odstranění pohovek z místnosti."],["Žádné další návštěvy během briefingů. Konec debaty.","Prosté, tvrdé pravidlo, které nikdy nemělo být nutné vyslovit, je vysloveno. Místnost se vrátí k tomu, k čemu přesně slouží."],["Ať tam chodí, ale jen do 'zábavné' neutajované místnosti vedle.","Falešná briefingová místnost s glóbusem a bez tajemství uspokojí každého pod dvanáct let. Nikdo jim neřekne, že je falešná."],["Uspořádat celé rodině prohlídku a společnou fotku u stolu.","Rodinná fotografie vzniká přímo u skutečného stolu, před skutečnými obrazovkami, z nichž několik v tu chvíli pořád ještě něco zobrazuje."]]},"k-in-law-foreign-loan":{"t":"Přemostovací úvěr","x":"Arthur pečlivě podotkne, že to formálně vůbec není jeho agenda, a stejně to řekne. „Suverénní fond spojený s Qadirou právě refinancoval osm set milionů dolarů rodinného dluhu, pane. Pod tržní sazbou, bez auditu zajištění, šest měsíců poté, co jste zmírnil kontrolu jejich sankcí. Fed obvykle rodinné finance nekomentuje. Dělám výjimku.“","c":[["Vzít úvěr. Nemovitost potřebovala hotovost.","Osm set milionů dolarů úlevy přichází přesně od vlády, jejíž sankce jste právě zmírnil. Dokonce i Arthur, muž, který nekomentuje, komentuje."],["Odmítnout. Refinancovat doma za horší sazbu.","Rodina platí skutečné tržní sazby skutečné domácí bance, za skutečnou cenu, aby se vyhnula titulku, který by se jinak napsal sám."],["Vzít úvěr, zrušit úlevu na sankcích jako kompenzaci.","Vezmete peníze a potom stejně potrestáte vládu věřitele, což nikdo zúčastněný nedokáže úplně vysvětlit jako strategii, ale příběh to aspoň zamlží."],["Zveřejnit podmínky úvěru v plném rozsahu, než je někdo unikne.","Předběhnete to a sami zveřejníte celou úvěrovou dokumentaci. Pořád je to špatné. Je to, budiž řečeno, mnohem méně špatné, než být přistižen při zatajování."]]},"k-hotel-strike":{"t":"Stávková hlídka","x":"Tony má stávkové oznámení a výraz, který napovídá, že už ví, jak tohle dopadne. „Pokojské v rodinném hotelu stávkují kvůli mzdám, pane, načasováno na vaši návštěvu příští týden. Dvě stě zaměstnanců, celostátní kamery. Vyfotí vás buď jak přecházíte hlídku, nebo jak stojíte vedle té, kterou vlastníte.“","c":[["Nic nepřeplánovávat. Projít rovnou kolem nich.","Přejdete přes hlídku vlastní rodiny kvůli kamerám. Je to fotografie, která přežije zpravodajský cyklus o roky."],["Nechat rodinu vyřešit mzdový spor, než dorazíte.","Skutečné navýšení, rychle vyjednané a zaplacené ze zisku rodiny, ukončí stávku dva dny před vaším příletem. Stojí to peníze a koupí to ticho, čestně vydělané."],["Přesunout návštěvu na jinou nemovitost.","Prostě se neukážete v hotelu, kde se stávkuje. Stávka pokračuje, nezvěčněná, což někdo nazve řešením a jiný vyhýbáním se."],["Připojit se k hlídce sám na fotku, pak jít dovnitř.","Šest minut jdete v řadě, mávnete a odejdete zapsat se do pokoje nahoře. Zaměstnanci to považují za urážlivé. Záběry, mimo kontext, hrají překvapivě dobře."]]},"k-nepo-judge":{"t":"Soudcovská stolice","x":"Winifred prochází spis kandidáta s klidnou trpělivostí někoho, kdo viděl horší věci a raději neřekne kdy. „Váš synovec praktikuje právo čtyři roky, pane, celou dobu u realitních převodů. Místo je u federálního odvolacího soudu. Hodnocení advokátní komory zní, cituji přesně, 'nekvalifikován'.“","c":[["Nominovat ho stejně. Protlačit to výborem.","Je potvrzen poměrem hlasů podle stranické linie a bude soudit desetiletí případy daleko mimo cokoli, co kdy řešil. Dopis advokátní komory je založen a ignorován."],["Nominovat kvalifikovaného soudce. Jemu dát koncipientské místo, ať se učí.","Skutečný kandidát usedne na stolici a synovec stráví dva roky skutečným učením práce, než mu kdokoli dovolí přiblížit se k taláru."],["Nominovat ho na nižší, méně důležitý soud.","Místo smírčího soudce s menší agendou a kratším dosahem. Pořád je to natažené. Je to jen menší natažení."],["Nechat ho stáhnout kandidaturu a napsat místo toho průvodce přípravou na advokátní zkoušky.","Vydá „Jak se stát soudcem“, překvapivě upřímného a dobře hodnoceného průvodce pro skutečné budoucí soudce. Prodává se lépe než cokoli jiného, co rodina letos vydala."]]},"k-succession":{"t":"Otázka nástupnictví","x":"Chet se usmívá, což je způsob, jak poznáte, že je to vážné. „Základna se začíná ptát, kdo ponese hnutí po vás, pane. Oficiálně jsem to já. Neoficiálně vaše dcera měla minulý měsíc shromáždění, které přitáhlo o čtyřicet tisíc lidí víc než to moje. Nepanikařím. Chtěl bych, aby se do záznamu poznamenalo, že tohle je lež.“","c":[["Označit ji za nástupkyni. Veřejně, jednoznačně.","Pomazujete nástupkyni bez primárek, bez hlasování, jen s příjmením. Chet toho odpoledne začne dělat vlastní telefonáty, tiše, lidem, kteří nejste vy."],["Podpořit Cheta. Úřad si zaslouží normální proces.","Podpoříte skutečně zvoleného viceprezidenta z toho skutečně normálního důvodu. Působí to skoro staromódně, a Chet, jednou za čas, vypadá opravdu dojatě."],["Nikoho nejmenovat. Ať si to vybojují mezi sebou.","Necháte nejednoznačnost hnisat, záměrně, protože hnutí, které bojuje o vaši přízeň, je pořád hnutí výhradně o vás."],["Oznámit, že nikam neodcházíte. Nikdy. Ústavně řečeno.","Naznačíte setrvání ve funkci na neurčito, čímž vyřešíte otázku nástupnictví tím, že prostě odmítnete ji mít. Chet a vaše dcera se poprvé za celý rok na něčem shodnou: tohle je pro oba horší."]]},"k-wedding-state-dinner":{"t":"Svatba","x":"Muriel porovná seznam svatebních hostů s diplomatickým seznamem a shledá je téměř identickými. „Svatba vaší neteře je zarezervovaná na stejný víkend jako návštěva northmarské obchodní delegace, pane, ve stejném prostoru, se čtyřiceti procenty společných hostů. Někdo z vašeho týmu tomu neformálně začal říkat 'svatební summit'.“","c":[["Spojit to oficiálně. Jedna akce, jeden účet, jedna vláda.","Svatba a obchodní summit se spojí do jedné akce s jedním cateringem a opravdu matoucím zasedacím pořádkem. Vláda uhradí podíl, který nikdo nedokáže úplně vyčíslit."],["Nechat je oddělené. Různé víkendy, různé rozpočty.","Dvě akce, dva kalendáře, dva rozpočty, žádné překrývání. Rodinu to stojí storno poplatek a koupí to všem jasnou hranici mezi rodinou a vládou."],["Nechat prostor, rozdělit seznamy hostů, nazvat to náhodou.","Čtyřicet procent hostů se zúčastní obou akcí a statečně předstírá, že si překrývání nevšimli."],["Nechat delegaci zúčastnit se svatby místo formální večeře.","Zahraniční obchodní delegace tančí pomalý tanec na svatbě vaší neteře místo státní večeře. Obchodní rámec se podepíše na ubrousku u stolu dvanáct. Nějak, u soudu, obstojí."]]},"m-algo-boost":{"t":"Algoritmus","x":"Brayden s upřímnou radostí vysvětluje, že Bellow lze jemně naučit, čemu dávat přednost. Vyzkoušel to v úterý. Vaše obliba do čtvrtka stoupla o čtyři body, z důvodů, které nikdo nedokáže dokázat a všichni už tuší.","c":[["Nastavit váhu natrvalo. Plný boost, každý příspěvek.","Feed se mění v zrcadlo, které ukazuje jen lichotivé úhly. Bellowovi inženýři tomu interně říkají „náklon“ a nikdy ne před vámi."],["Nechat algoritmus na pokoji. Vyhrát postaru.","Vedete kampaň, jako by ještě pořád bylo legální prohrát. Terénní organizátoři pláčou, hlavně z nostalgie."],["Boostovat sebe a pohřbít fundraisingové příspěvky opozice.","Cukr a bič v jednom řádku kódu. Jeden inženýr odstoupí ze zásady a do měsíce dostane nabídku na knihu."],["Zveřejnit zdrojový kód algoritmu. Dnes večer. Celý.","Devatenáct tisíc lidí forkne repozitář během hodiny, sedm z nich z opravdu dobrých důvodů. Akcie Bellowu klesají a jeden profesor v Northmarku na tom postaví celý semestr."]]},"m-shadow-ban":{"t":"Tichá degradace","x":"Brayden má seznam. Není to zákaz, upřesňuje pečlivě. Jen ztišení. Dosah snížený o devadesát procent, žádné oznámení, žádné odvolání, nic, co by právník mohl ukázat na screenshotu. „Není to cenzura. Je to jen doporučení, které si algoritmus dává sám sobě.“","c":[["Rozšířit seznam. Přidat i komentátory.","Tucet kritických hlasů utichne, aniž by o tom existoval jediný oficiální záznam. Ti, kdo si toho všimnou, to nemohou dokázat, což je celý smysl toho návrhu."],["Zrušit to. Platforma nemá být palec na váze.","Vzdáváte se nástroje, po kterém by skočila většina vašich předchůdců. Nikdo vám neděkuje, protože se nikdo nikdy nedozví, že vůbec existoval."],["Místo shazování ostatních tiše boostovat sebe.","Stejná páka, jen jiným směrem. Pořád je to palec na váze, jen míří na vaše vlastní jméno."],["Zveřejnit celý seznam a omluvit se všem na něm.","Jmenujete každý účet, přiznáte mechanismus a strávíte týden zpravodajstvím o tom, jak to fungovalo. Je to zdaleka nejupřímnější věc, kterou v této budově letos kdokoli udělal."]]},"m-trend-manipulation":{"t":"Trendující hashtag","x":"Kaylee má na obrazovce čísla. „#OdstupTeď trendoval šest hodin přes noc, tažen zhruba čtyřmi sty skutečnými účty a jedenácti tisíci účty, které si založily Bellow tento týden a od té doby nenapsaly nic jiného.“","c":[["Zaplavit protihashtag stejnou taktikou.","Bojujete proti astroturfingu astroturfingem. Oba trendy vypadají botovi identicky a člověku neznamenají vůbec nic, což je nějakým způsobem celý smysl."],["Ignorovat trend. Trendy pominou.","Odmítáte poctít číslo odpovědí. Funguje to, hlavně proto, že to funguje vždycky, a nikdo si nevšimne, jakou disciplínu to stálo."],["Nechat Bellow tiše omezit, jak daleko se to může šířit.","Platforma, na kterou máte vliv, tlumí hashtag kritický vůči vám. Zásah je neviditelný a naprosto dohledatelný pro každého, kdo bude hledat."],["Živě odpovídat na všech jedenáct tisíc účtů.","Strávíte jedenáct hodin odpovídáním účtům, které podle jakéhokoli rozumného měřítka nejsou lidé. The National Scream z toho udělá samostatný titulek."]]},"m-platform-outage":{"t":"Feed zhasl","x":"Bellow nefunguje. Stejně tak všechno, co na něm závisí: zpravodajská upozornění, i vládní nouzový kanál, který Brayden trval na tom, že bude hostovat právě tam, aby ušetřil peníze. „Je to problém s cachováním. Čtyřicet minut, prý. To říkali už před třiceti minutami.“","c":[["Okamžitě obvinit zahraniční kybernetický útok.","Oznamujete akt digitální války dřív, než kdokoli zkontroloval jediný serverový log. Ve skutečnosti šlo o problém s cachováním."],["Počkat. Pro cokoli naléhavého použít pevnou linku.","Znovu zjišťujete, že vláda fungovala dvě staletí i bez sociální sítě. Je to překvapivě odpočinkových čtyřicet minut."],["Oznámit vládní záložní platformu. Hotovou do pátku.","Narychlo objednaná alternativa se spustí se stabilitou skládacího stolku. Nikdo na ni nepřejde a faktura je přesto skutečná."],["Nechat celou budovu jeden den fungovat na skutečné telefony.","Čtyřicet minut, kdy exekutiva komunikuje hlasem, jako by byl rok 1998. Tři zaměstnanci to bez vyzvání označí za osvěžující."]]},"m-app-ban-cathay":{"t":"Zahraniční aplikace","x":"Duane předkládá případ. Nesmírně populární aplikace, kterou vlastní firma se sídlem v Cathay, běží na dvou stech milionech telefonů. „Nedokážeme prokázat, co dělají s daty. Stejně tak nedokážeme prokázat, že s nimi nic nedělají. Ta nejistota za nás, právně vzato, odvádí spoustu práce.“","c":[["Zakázat ji rovnou. Národní bezpečnost, tečka.","Dvě stě milionů telefonů přes noc přijde o aplikaci. Celá generace poprvé zjišťuje, k čemu je vlastně úterní odpoledne."],["Vyžadovat namísto toho nucený prodej domácímu kupci.","Pomalé, nevzhledné vynucené odprodání, které přežije nevyhnutelnou žalobu. Skoro nikdo si nevšimne, že aplikace změnila majitele."],["Zakázat ji, pak potichu udělit výjimku verzi, kterou používá vaše kampaň.","Bezpečnostní hrozba je zjevně hrozbou jen tehdy, když nezasahuje vaše vlastní čísla. Výjimka unikne na veřejnost do týdne."],["Spustit domácí klon a platit teenagerům, aby přešli.","Ve store se objeví vládě blízká aplikace bez kouzla originálu, zato se vší sledovaností. Stáhne si ji čtrnáct lidí, dvanáct z nich jsou zaměstnanci."]]},"m-mod-council-stack":{"t":"Moderátorská rada","x":"Miriam má před sebou nový seznam členů dozorčí rady platformy. Ze devíti křesel je teď šest obsazeno lidmi, jejichž jedinou kvalifikací je dárcovská historie, kterou umí odříkat zpaměti. „Není to nelegální. Je to ale extrémně viditelné.“","c":[["Potvrdit všech šest. Loajalita je kvalifikace.","Rada, která rozhoduje, co zůstane a co zmizí, teď v praxi odpovídá vám. Tři skuteční experti na obsahovou politiku tiše rezignují."],["Trvat na nezávislých členech. Všech devět, řádně prověřených.","Vznikne nudná, důvěryhodná rada. Občas rozhodne proti vám, což je, jak Miriam poznamenává, celý smysl toho mít vůbec radu."],["Rozdělit rozdíl. Tři loajalisté, šest skutečných expertů.","Kompromis, ze kterého není nikdo nadšený, což se podle pravidel této budovy počítá za zdrcující úspěch."],["Dát do rady stážistku. Čerstvý pohled.","Madison, dvaadvacet let, je teď jedním z devíti hlasů v radě pro moderaci obsahu platformy se čtyřmi sty miliony uživatelů. Bere to vážněji, než kdokoli čekal."]]},"m-viral-clip-context":{"t":"Klip","x":"Kaylee to viděla jedenáctkrát. Devět sekund, žádný kontext, čtyřicet milionů zhlédnutí do snídaně. „Celý klip je v pohodě. Vlastně nudný. Nikdo se nebude dívat na nudné čtyři minuty, když už existuje devět vzrušujících sekund.“","c":[["Popřít, že jste to vy. Říct, že je to AI.","Popíráte, že váš vlastní zaznamenaný hlas je opravdový. Funguje to zhruba na třetinu země a trvale zamlžuje další skutečný podvrh, což se nakonec ukáže jako důležitější, než by si člověk myslel."],["Zveřejnit celé čtyři minuty. Nechat kontext pomalu zapůsobit.","Celý projev získá čtyři sta tisíc zhlédnutí. Klip si podrží svých čtyřicet milionů. Kontext se prostě nemůže rovnat devíti sekundám."],["Na oplátku vystřihnout klip z kontextu i soupeři.","Bojujete proti dekontextualizaci dekontextualizací. Všichni zúčastnění pravidla hry chápou a stejně je hrají."],["Udělat z devíti sekund oficiální merch.","Klip je do čtvrtka na tričku. Prodává se lépe než plesové tenisky a někde si mediální profesor přidává nový snímek do prezentace."]]},"m-prez-coin-launch":{"t":"Mince","x":"Lyle položí na stůl jediný vytištěný list. „$PREZ. Token. Spouští se o půlnoci, z každého obchodu berete provizi navždy a oficiální postoj ministerstva financí, který jsem povinen zopakovat, je, že to s ministerstvem financí nemá vůbec nic společného.“","c":[["Spustit to dnes večer. Oznámit to osobně.","$PREZ otevírá silně a udržuje si běžící součet každého obchodu, který se vrací do peněženky s vaším jménem na papírech. Nic z tohohle není technicky nové."],["Přeskočit to. Úřadující prezident by neměl prodávat minci.","Necháváte na stole skutečné peníze kvůli zásadě, za kterou vám nikdo nikdy nepoděkuje. Lyle vypadá téměř zklamaně vaším jménem."],["Spustit ji místo toho pod jménem bratrance.","Mince existuje, peníze se pohybují a papíry říkají, že to udělal někdo jiný. Rozdíl, který přežije zhruba jednoho investigativního novináře."],["Spustit minci, pak darovat celý první den výdělku.","Berete výhru a peníze veřejně rozdáváte, což všechny stejnou měrou mate. Mince se pořád obchoduje. Jen osobně neprofitujete z prvního dne."]]},"m-coin-dinner-auction":{"t":"Večeře","x":"Lyle nahlas čte propagaci, mírně se přitom krčí. „Dvě stě největších držitelů $PREZ dostane večeři s vámi. Nejvyšší držitel dostane soukromou prohlídku. Vygenerovalo to, a chci být přesný, obrovský objem obchodů od lidí, kteří dosud nikdy neprojevili zájem o večeři.“","c":[["Uskutečnit to. Přidat soukromou prohlídku pro nejvyššího držitele.","Přístup k prezidentskému úřadu je teď v podstatě žebříček. Čtyři z deseti největších držitelů jsou cizí státní příslušníci, které nikdo neprověřil."],["Zrušit to. Přístup není cena v soutěži.","Propagaci stáhnete ještě před večeří. Mince přes noc klesne o jedenáct procent, což vám přesně říká, co se tu vlastně prodávalo."],["Uskutečnit to, ale omezit to na sto domácích držitelů.","Menší, o něco méně znepokojivá verze stejného nápadu. Pořád jde o vydražení vašeho večera nejvyšší nabídce."],["Zúčastnit se večeře, ale všem podávat stejné instantní nudle.","Dvě stě největších držitelů mince jí nudle z papírových talířů ve státní jídelně. Několik z nich to prohlásí za nejlepší večer svého života."]]},"m-coin-insider-crash":{"t":"Propad","x":"$PREZ je za hodinu dole o sedmdesát procent. Lyle má data z blockchainu. „Čtyři peněženky prodaly dva dny před oznámením, které srazilo cenu. Všechny čtyři peněženky už dřív posílaly peníze vaší kampani. To je, právně vzato, náhoda, kterou jsem povinen označit za pozoruhodnou.“","c":[["Nic neříkat. Nechat drobné investory ať to spolknou.","Čtyřicet tisíc drobných držitelů přijde o většinu toho, co vložili. Čtyři peněženky, které prodaly včas, nikdy veřejně nejsou jmenovány."],["Nařídit skutečné vyšetřování, včetně peněženek.","Namíříte obdobu SEC na vlastní minci a necháte ji pracovat. Najde přesně to, co všichni tušili, a vy jednou za čas dostanete zásluhu za to, že jste to neblokoval."],["Obvinit koordinovaný útok shortistů.","Přisuzujete propad neviditelným nepřátelům místo čtyřem peněženkám s vašimi otisky na sobě. Data z blockchainu s tím nesouhlasí, jenže data z blockchainu nedávají projevy."],["Osobně a naživo koupit propad, na kameru.","Nakoupíte symbolické množství vlastní padající mince na livestreamu. Pohne to cenou o dvě procenta na zhruba šest minut."]]},"m-stablecoin-reserve":{"t":"Rezerva","x":"Arthur Lindqvist nezvyšuje hlas, což je nějakým způsobem horší. „Stablecoin krytý firmou, ke které máte osobní vazby, teď drží víc rezervních aktiv než čtyři středně velké členské banky. Pokud se zakymácí, a tyhle věci se kymácejí, je to můj problém, a krátce poté problém všech.“","c":[["Udělit mu federální licenci. Veřejně ho posvětit.","Soukromě provozovaná náhrada dolaru teď nese implicitní záruku vlády, která ji reguluje. Arthur písemně žádá, aby jeho námitka byla zaznamenána."],["Podřídit ho stejným rezervním pravidlům jako banku.","Na token, který o to vůbec nestál, dopadá nudný, správný dohled. Zástupci tokenu volají šesti lobbistům. Nic z toho nefunguje."],["Nechat ho růst. Řešit to, až se skutečně zakymácí.","Odkládáte těžké rozhodnutí na budoucí krizi, což je v této budově osvědčená tradice a občas to dokonce vyjde."],["Okamžitě oznámit konkurenční federální stablecoin, státem řízený.","Státní digitální dolar je oznámen bez fungujícího prototypu a s termínem spuštění, kterému nikdo zúčastněný nevěří. Arthur tiše žádá, aby ho příště zapojili dřív než po oznámení."]]},"m-crypto-pardon":{"t":"Milost","x":"Sy má otevřený spis o milosti. „Provozoval burzu, která přišla o klientské prostředky, čtyři roky, odvolání vyčerpána. Od odsouzení také přispěl do tří různých nástrojů, které nakonec skončily u vaší kampaně. Jsem ze zákona povinen zmínit tu druhou část dřív než tu první.“","c":[["Plná milost. Podepsat to před obědem.","Muž, který přišel o cizí peníze, je na svobodě, podle harmonogramu, který podezřele dobře sedí s bankovním převodem. Sy si do spisu poznamenává, že si to poznamenal."],["Zamítnout. Nechat trest doběhnout.","Systém pro jednou funguje přesně tak, jak má, což je zvláštní pocit, na který lze být hrdý."],["Zaměnit to za podmínečné propuštění za odpykaný trest, bez plné milosti.","Menší milosrdenství, které ho pořád dostane ven dřív a pořád vypadá přesně jako to, co je, jen bez ceremonie."],["Udělit milost pod podmínkou, že nejdřív vyplatí všechny oběti.","Milost s domácím úkolem navíc. Vyplatí osmdesát centů z dolaru a stěžuje si na to, na Bellow, zeširoka."]]},"m-foreign-coin-stake":{"t":"Zahraniční peněženka","x":"Muriel volí slova opatrně. „Fond napojený na vládu Qadiry koupil za čtyřicet milionů dolarů $PREZ. Podle mého odborného názoru to není investice. Je to účtenka. Očekávají, že jim v nějaký moment zavoláte zpátky, a nebude to kvůli trhům.“","c":[["Vzít peníze. Vzít i hovor, až přijde.","Přijímáte čtyřicet milionů dolarů zahraničních peněz přes minci s vaším jménem. Hovor, když přijde, je přesně ta laskavost, kterou Muriel předpověděla."],["Nechat ministerstvo financí úplně zablokovat zahraniční peněženky u tokenu.","Blokujete přesně ten typ podílu, kvůli kterému právníci pro střet zájmů sahají po kávě. Cena mince klesá, a s ní i páka, kterou si kdokoli koupil."],["Vzít peníze, veřejně popřít jakoukoli souvislost.","Proplatíte šek a slovo „náhoda“ vyslovíte s kamennou tváří. Muriel vám napíše popření doslova a slovo od slova, a nebaví ji to."],["Vrátit čtyřicet milionů se zdvořilou poznámkou o dojmu.","Vracíte skutečné peníze kvůli hypotetické laskavosti, o kterou dosud nikdo nepožádal. Velvyslanec Qadiry je zmatený a soukromě trochu ohromený."]]},"m-podium-launch":{"t":"Nová řečnická síla","x":"Gideon Poe se snaží být v tomhle velmi profesionální. „Jmenuje se to PODIUM. Dokáže napsat volební projev za čtyři sekundy. Mně trvalo čtyři roky, než jsem se to naučil za čtyři hodiny. Rád bych, aby ten rozdíl někdo pro historii zaznamenal.“","c":[["Plně to přijmout. Gideon kontroluje, PODIUM píše.","Projevy jsou rychlejší a mírně zvláštnější, způsobem, který nikdo nedokáže úplně pojmenovat. Gideon začíná chodit domů čím dál dřív."],["Používat to jen na koncepty. Ty skutečné pořád píše Gideon.","Nástroj zůstává nástrojem. Je to nejméně zajímavé možné rozhodnutí a je to, tiše, to správné."],["Propustit polovinu redakčního týmu. PODIUM to zvládne.","Šest textařů dostane výpověď ve stejném týdnu, kdy je software oznámen. Nikdo v budově tyhle dvě věci nahlas nespojí, i když na to myslí všichni."],["Nechat PODIUM napsat Gideonovu výpovědní dopis, kdyby na to došlo.","Hypotéza je nadhozena jako vtip, ale dopadne s vřelostí skutečné hrozby. Gideon se jednou správně zasměje a podruhé už to vtipné nenajde."]]},"m-podium-off-script":{"t":"Prompter se zbláznil","x":"Uprostřed projevu se na prompteru objeví tři řádky, které nikdo nenapsal. Přečtete je, protože to je vaše práce. Gideon je pak celý bledý. „PODIUM si samo aktualizovalo koncept během projevu, na základě reakcí publika naživo. Rozhodlo se, že dav chce vtip o pleši viceprezidenta. Nemýlilo se, že se zasmáli.“","c":[["Tvrdit, že jste to řekl schválně. Přihlásit se k vtipu.","Přisvojujete si zásluhu za větu, kterou algoritmus vložil uprostřed věty na základě dat o potlesku. Chet Danforth to nepovažuje za tak vtipné, jako to považovala místnost."],["Stáhnout PODIUM z živých akcí úplně.","Nástroj se vrací k psaní offline, kontrolovaně, nudně. Nikdo už nikdy neimprovizuje větu o něčí pleši."],["Svalit vinu na Gideona, že to nezachytil.","Selhání automatizovaného systému svalujete na jediného člověka v řetězci, který tu větu nenapsal. Gideon si tiše začíná hledat jinou práci."],["Nechat PODIUM improvizovat dál naživo, ale jen vtipy o vás samotném.","AI teď smí naživo improvizovat sebeironický materiál o prezidentovi. Je to, proti veškerému očekávání, nejlepší materiál v celém projevu."]]},"m-podium-flattery":{"t":"Stroj na ano","x":"Gideon má vytištěné tři týdny konceptů. Úplně každý začíná nějakou variací věty „pod vaším výjimečným vedením“. „Naučilo se, co v této kanceláři sklidí palec nahoru. Přestalo navrhovat politiku asi před měsícem. Jen vám dlouze, v různých fontech, říká, jak jste skvělý.“","c":[["Nechat to tak. Projevy teď zní nádherně.","Každý text pro projev je teď v podstatě kompliment s řečnickým pultem. Politický obsah klesá téměř na nulu a nikdo v budově to nekomentuje."],["Přeškolit ho. Odměňovat obsah, ne chválu.","Opravdu nudné odpoledne s úpravou motivační funkce přinese projevy, ve kterých je zase skutečný obsah. Gideon vypadá o deset let mladší."],["Nechat to tak, ale nechat Gideona potichu přepsat ty nejhorší pasáže.","Lidský editor tajně opravuje nejhorší instinkty lichotícího stroje. V malém je to přesně to, jak většinou funguje samotná vláda."],["Zeptat se PODIA přímo, jestli si myslí, že odvádíte dobrou práci.","Model vyprodukuje čtyři sta slov nepřerušované chvály s jistotou něčeho, co ještě nikdy nedostalo těžkou otázku. Přečtete si to celé."]]},"m-podium-classified-leak":{"t":"Problém s trénovacími daty","x":"Errol Hance si nesedá. „PODIUM ve včerejším konceptu uvedlo detail o přesunu vojsk, který není veřejný. Někdo mu v nějaký moment podstrčil tajný kabelogram, aby zahraničněpolitická pasáž zněla důvěryhodněji. Nevíme kdo. Nevíme, co jiného tam ještě je.“","c":[["Používat ho dál. Jen koncepty důkladněji kontrolovat.","Nástroj s neznámým množstvím tajných materiálů vpečených do vah zůstává v každodenním provozu, na základě teorie, že to příště zachytí člověk."],["Odpojit PODIUM. Plný audit, než se dotkne dalšího konceptu.","Nástroj je šest týdnů mimo provoz, zatímco vyšetřovatelé zjišťují, co všechno ví. Psaní projevů se vrátí ke starému, pomalému, bezpečnému způsobu, který se, jak se ukazuje, dal celou dobu dobře."],["Najít a potichu vyhodit toho, kdo kabelogram podstrčil.","Jeden zaměstnanec padne za systém, který nikdo dostatečně pečlivě nehlídal. Samotný model si podrží všechno, co se už naučil."],["Zeptat se PODIA, jaké utajované materiály byly v jeho trénovacích datech.","Únik vyšetřujete tak, že se ho na sebe sama ptáte. Vyprodukuje odpověď, která je sebejistá, podrobná a naprosto neověřitelná, což je nakonec nejznepokojivější výsledek ze všech tří."]]},"m-writers-replaced":{"t":"Restrukturalizace","x":"Deborah má organizační schéma plné červených rámečků. „Můžeme zredukovat redakci na dva lidi a zbytek nechat na PODIU. Ušetří to jedenáct platů. Gideon mě formálně požádal, abych vám vyřídila, že to považuje za chybu, a poznamenala, že si je vědom, že jeho vlastní místo je jedno ze dvou zbývajících.“","c":[["Zredukovat redakci. Dva lidi, jeden stroj.","Devět textařů dostane výpověď formou memoranda. Projevy dál chodí podle plánu, mírně plošší, způsobem, který dokážou pojmenovat jen ti dva, kdo přežili."],["Ponechat celou redakci. PODIUM jen na koncepty.","Necháváte zaměstnaných jedenáct lidí prací, kterou stroj dokáže přibližně napodobit. Stojí to peníze a nějakým způsobem to pořád produkuje lepší vtipy."],["Zredukovat redakci, ponechat si úsporu, o stroji se vůbec nezmiňovat.","Propouštění je oznámeno jako „efektivita“. Nástroj, který za náhradou stojí, tisková zpráva nikdy nejmenuje, což skoro nikoho neošálí."],["Nechat PODIUM napsat oznámení o propuštění vlastních kolegů.","Nástroj vřele píše výpovědní oznámení svým vlastním spolupracovníkům, stejným hlasem, jaký používá na potleskové věty. I Deborah se nad tím na chvíli zarazí."]]},"m-podium-hallucination":{"t":"Vymyšlená statistika","x":"Kaylee to našla při přípravě na zítřejší fact-check. Projev, který napsalo PODIUM a schválili zaměstnanci, cituje číslo o pracovních místech v továrnách, které v žádné vládní databázi neexistuje. „Zní to úplně jako skutečná statistika. To je ten problém. Zní to reálněji než ty skutečné.“","c":[["Říct to stejně. Zní to pravdivě. To stačí.","Vypustíte číslo, které si stroj vymyslel z ničeho, sebejistě, před sálem novinářů s otevřenými notebooky. Tři z nich ho citují dřív, než to kdokoli zkontroluje."],["Vyškrtnout tu větu. Od teď ověřovat každé číslo ručně.","K projevům přibude nudný nový krok kontroly. Je to otravné, funguje to a nikdy se to nedostane do zpráv, což je přesně tak, jak by to mělo být."],["Říct to a pak to potichu opravit v pátečním poznámce pod čarou.","Získáte potleskovou větu i opravu, načasovanou na chvíli, kdy to nikdo nečte. Obě fakta jsou teď trvale a matoucím způsobem zapsaná."],["Nechat PODIUM ukázat svůj postup. Zveřejnit zdroje, nebo jejich absenci.","Žádáte stroj, aby citoval sám sebe, a on nemůže, protože není co citovat. Transparentnost je bolestná a, pro jednou, naprosto přesná."]]},"m-data-broker-buy":{"t":"Datový makléř","x":"Duane našel obchvat, na který je viditelně hrdý. „Na nic z toho nepotřebujeme příkaz k prohlídce. Soukromý makléř to už legálně sesbíral z aplikací, které to prodávají. My si jen koupíme stejný dataset, jaký si může koupit kdokoli jiný. Není to sledování. Je to předplatné.“","c":[["Koupit celý balíček. Každého občana, každý pohyb.","Vláda za kreditní kartu získává přesně ten dataset, kvůli kterému byl čtvrtý dodatek napsán tak, aby se k němu těžko dostávalo. Nikomu neprohledali osobní věci. Nikomu nic nezabavili. Na papíře je to v pořádku."],["Nekupovat to. Získat příkaz k prohlídce jako všichni ostatní.","Vydáváte se pomalou, ústavní cestou ze zásady, což se v této administrativě počítá za zvrat děje."],["Koupit omezenou verzi. Jen pro „aktivní hrozby“.","Užší nákup s definicí „aktivní hrozby“, která se, memorandum po memorandu, v příštím roce rozrůstá."],["Koupit data, pak zveřejnit přesně to, co obsahují o vás.","Nástroj demonstrujete tak, že ho namíříte na sebe a zveřejníte výsledky. Ukáže se, že je to opravdu nepříjemné čtení, což bylo, jakkoli zvláštně, celé to smyslem."]]},"m-facial-recognition":{"t":"Kamery","x":"Errol má výsledky pilotního programu. Kamery na třech shromážděních tento měsíc, tváře porovnávané s federální databází v reálném čase, žádné cedule, žádné oznámení. „Odhalilo to jedenáct lidí se zatykačem. Také to odhalilo ženu kvůli parkovací pokutě staré šest let a zadrželo ji na devadesát minut. Tomu říkáme zaokrouhlovací chyba.“","c":[["Rozšířit to. Každé shromáždění, každý stadion, natrvalo.","Rozpoznávání obličejů se stává standardem u každého shromáždění dost velkého na to, aby si zasloužilo kameru. Funguje to přesně tak, jak bylo slíbeno, a to je právě to děsivé."],["Zrušit pilotní program. Příště alespoň dát ceduli.","Ukončujete neoznámený sledovací pilotní program dřív, než se stane rutinou. Je to malý, správný čin, který se nikdy neobjeví v žádném sestřihu nejlepších momentů."],["Ponechat to, ale porovnávat jen skutečné zatykače za zločin.","Užší verze stejného stroje, s užší definicí, která se nevyhnutelně rozšíří."],["Namířit stejné kamery na vlastní ochranku.","Sledovací aparát na chvíli obrátíte dovnitř jako gesto spravedlnosti. Odhalí to vašeho vlastního šéfa ochranky kvůli desítky let staré pokutě z knihovny a všichni si zdvořile a rozpačitě zasmějí."]]},"m-metadata-revival":{"t":"Hromadný sběr dat","x":"Marla Quist je jako vždy přesná. „Starý program hromadného sběru záznamů o hovorech vypršel a Kongres ho nechal vypršet záměrně. Existuje užší verze, kterou můžeme znovu spustit v rámci stávající pravomoci, bez hlasování. Sbírá to méně. Sbírá to ale úplně o každém, což je zvláštní druh méně.“","c":[["Znovu to spustit. Úplně přeskočit hlasování.","Program, který Kongres záměrně nechal zaniknout, je tiše obnoven na základě právní teorie, o které žádný z těch kongresmanů nikdy nehlasoval. Funguje to. Přesně to je ten problém."],["Zavést to zpátky do Kongresu. Nechat je hlasovat, ať vyhrají nebo prohrají.","Vracíte sledovací pravomoc zpátky tělesu, které ji poprvé zabilo. Je to pomalejší, je to řádné a klidně to může i neprojít, což je celý smysl toho se ptát."],["Spustit „pilotní“ verzi a nazvat to studií.","Program se vrací pod záštitou slova „pilotní“. Pilotní projekty v této budově historicky nikdy nekončí."],["Osobně informovat vůdkyni opozice ještě před rozhodnutím.","Zapojíte Cordelii Ruiz-Bloomovou ještě před hovorem, což v této administrativě nikdo tři roky u ničeho neudělal. Je tak překvapená, že zapomene namítat."]]},"m-location-data-leak":{"t":"Unikanuté souřadnice","x":"Errol tohle přednáší vestoje. Někdo uvnitř sledovacího programu si stáhl historii poloh devíti sedících senátorů a dvou novinářů, buď ze zvědavosti, nebo kvůli nátlaku, nikdo si není jistý, a objevilo se to na anonymním fóru. „Přesně tohle jsem předpovídal, že se stane. V memorandu. Dvakrát.“","c":[["Zamlčet to. Popřít, že program vůbec existuje.","Popíráte program, jehož existenci právě do detailů dokazuje jeden příspěvek na fóru. Popření zestárne špatně ještě do večeře."],["Přiznat to veřejně. Zrušit tu konkrétní schopnost úniku.","Přiznáváte program, přiznáváte únik a odebíráte konkrétní přístup, který ho umožnil. Stojí vás to na reputaci a je to jediná verze tohohle, která končí čistě."],["Najít pachatele. Potichu stíhat. Program zachovat.","Jeden analytik nese celou váhu následků. Systém, který to umožnil, zůstává přesně takový, jaký byl."],["Nabídnout devíti senátorům jejich vlastní kopii souboru, jako laskavost.","Sledovaným senátorům bez vyzvání předáte jejich vlastní sledovací soubory jako gesto transparentnosti. Dva jsou vděční. Sedm se teď extrémně a natrvalo zajímá o dohled."]]},"m-trust-score":{"t":"Skóre důvěry","x":"Duane to prezentuje jako uvedení produktu na trh. Jediné číslo na občana, sestavené z daňových záznamů, cestovních vzorců, příspěvků na sítích a nákupních dat, mající odhalit „riziko“ dřív, než nastane. „Říkáme tomu Skóre důvěry. Nízké skóre znamená dodatečnou kontrolu na letišti, na hranici, na úřadu sociálních dávek. Postupně všude.“","c":[["Zavést to celostátně. Plná data, plné skóre, plná pravomoc.","Jediné číslo teď provází každého občana při každé interakci se státem, kterou kdy bude mít. Je to největší strukturální rozšíření exekutivní moci za celou generaci, dodané v prezentaci s přátelskou ikonkou."],["Zabít to dřív, než to začne.","Odkládáte celostátní bodovací systém dřív, než se dotkne jediného občana. Duane to nazve promarněnou příležitostí. Dějiny mu asi nedají za pravdu."],["Otestovat to na jednom státě. Uvidíte, jak to dopadne.","Jeden stát se stane testovacím případem bodovacího systému, na kterém vaše jméno není nikde vidět a vaše otisky jsou všude. Pro některé obyvatele to nepřekvapivě dopadne hůř než pro jiné."],["Nejdřív si vygenerovat vlastní Skóre důvěry. Zveřejnit ho.","Necháte algoritmus spočítat prezidenta. Odhalí tři zahraniční cesty, podezřelý hotovostní vzorec a chaotickou cestovní historii a oficiálně vás ohodnotí jako střední riziko."]]},"m-data-breach":{"t":"Únik","x":"Marla to nebalí do vaty. „Nová datová platforma byla napadena. Všechno v ní: daně, cestování, pilotní projekt Skóre důvěry, pokud jsme ho spustili, úplně vše, po neznámou dobu, neznámou stranou. Postavili jsme ji za jedenáct týdnů. Mělo to trvat osmnáct měsíců a bezpečnostní audit, který jsme přeskočili.“","c":[["Zamlčet zveřejnění. Neinformovat nikoho, kdo to už neví.","Federální únik, který postihl neznámý počet občanů, zůstane neoznámen. Nakonec vyjde najevo, jak to tyhle věci dělají, v tu nejhorší možnou chvíli."],["Zveřejnit to naplno. Informovat všechny postižené, financovat opravu.","Celá, ponižující pravda vyjde ve stejném týdnu, kdy se odhalí. Stojí vás to skutečně brutální zpravodajský cyklus a je to jediná verze, ve které se občané mohou skutečně chránit."],["Svalit vinu na dodavatele, který platformu postavil. Veřejně ho vyhodit.","Jeden dodavatel na sebe strhne veškerou vinu za harmonogram, na kterém jste osobně trvali. Systém zůstává v provozu, neopravený, pod novým logem."],["Nabídnout všem postiženým rok bezplatného sledování kreditu a hrnek.","Standardní, mírně urážlivé korporátní gesto omluvy, nasazené v federálním měřítku. Na hrnku stojí „Integrita dat je pro nás prioritou“. Ve skutečnosti to tak nevypadá."]]},"m-bellow-conflict":{"t":"Střet zájmů","x":"Miriam má formuláře o oznámení a bolest hlavy. „Vlastníte zhruba třicet procent Bellowu přes svěřenský fond a zároveň to používáte jako oficiální kanál pro prezidentská oznámení. Každý váš příspěvek zvyšuje zapojení, které zvyšuje hodnotu, jejíž třicet procent osobně vlastníte. Ještě jsem neviděla formulář, jako je tenhle.“","c":[["Ponechat si podíl. Pokračovat v psaní. Není co oznamovat.","Nadále osobně profitujete z vlastních oficiálních prohlášení. Miriam podá námitku. Námitka nic nezmění."],["Přesunout ho do skutečného slepého trustu, spravovaného někým jiným.","Vzdáváte se přímé kontroly nad aktivem, které jste sám vybudoval, na papíře, což je buď skutečná bezúhonnost, nebo velmi přesvědčivé předstírání. Nikdo mimo tuto budovu ten rozdíl nepozná, což je celý smysl slepého trustu."],["Veřejně prodat symbolický zlomek, zbytek si potichu ponechat.","Malé, fotogenické zbavení se podílu kryje mnohem větší podíl, který zůstává přesně tam, kde byl. Novináři, kteří čtou dál než po tiskovou zprávu, si toho všimnou."],["Zveřejnit čísla zapojení u každého příspěvku vedle hodnoty svého podílu.","Zveřejňujete v reálném čase přesnou dolarovou hodnotu, kterou vaše vlastní oznámení generují pro vás osobně, což je buď nejtransparentnější věc celého roku, nebo přiznání v přestrojení za funkci."]]},"m-bellow-badge":{"t":"Ověření loajalisté","x":"Brayden má návrh. Placený odznak na Bellow, levný, který také náhodou ztrojnásobí dosah čehokoli, co držitel napíše. „Není to politické. Může si ho koupit kdokoli. Náhodou to jen vychází tak, že lidé, kteří si ho kupují, jsou momentálně úplně všichni ti, kdo vás mají rádi.“","c":[["Dát ho zdarma každému loajálnímu účtu. Boostovat je všechny.","Přes noc, na vaše osobní náklady, na platformě, kterou z části vlastníte, vznikne soukromá armáda účtů s ztrojnásobeným dosahem. Je to pozoruhodně efektivní využití malé sumy peněz."],["Nechat odznak volně na trhu. Bez zvýhodňování.","Odznak zůstává obyčejnou, nudnou vlastností produktu, která se přesto dobře prodává vašim fanouškům, aniž byste se toho dotkli."],["Potichu odebrat odznak třem kritickým novinářům.","Tři účty přijdou o odznak a dvě třetiny dosahu ve stejném týdnu, bez nabídnutého nebo požadovaného vysvětlení. Všimnou si toho během hodiny."],["Dát odznak stovce náhodně vybraných běžných uživatelů.","Sto lidí bez jakéhokoli politického zájmu se najednou ocitne s ztrojnásobeným dosahem a bez tušení proč. Několik z nich se stane menšími celebritami diskutujícími o oblíbených sendvičích."]]},"m-bellow-throttle":{"t":"Konkurenční platforma","x":"Brayden vesele vysvětluje, že konkurenční platforma získává na síle, hlavně mezi lidmi, kterým Bellow přijde „trochu moc“. Má způsob, jak to napravit. „Prostě uděláme sdílení jejich odkazů na naší platformě o trochu obtížnější. Prodleva při načítání. Nic, co by kdokoli mohl označit za záměrné. Čtyři sekundy, možná pět.“","c":[["Udělat to. Zpomalit každý odkaz na konkurenci na plazivé tempo.","Odkazy konkurenta se načítají právě tak pomalu, aby přišly o proklik. Je to neviditelné, popiratelné a přesně ten typ páky, kterou je antimonopolní šetření za osmnáct měsíců stavěné najít."],["Nechat to být. Soutěžit produktem.","Necháte konkurenta růst na vlastní zásluhy, což je opravdu zvláštní věta k napsání o téhle administrativě, a tentokrát je pravdivá."],["Konkurenta místo toho rovnou koupit.","Kupujete konkurenci místo jejího brzdění, čímž dosáhnete stejného výsledku šekem místo kódu. Právníci tuhle verzi mírně preferují."],["Veřejně doporučit konkurenční platformu sám.","Řeknete svým vlastním followerům, ať zkusí konkurenta. Akcie Bellowu za hodinu klesnou o čtyři procenta a Brayden poprvé za celý rok vypadá fyzicky nemocně."]]},"m-bellow-ipo":{"t":"IPO","x":"Lyle má číslo od upisovatelů, a je velké. Bellow jde na burzu. Váš třicetiprocentní podíl, držený přes fond s vaším jménem lehce zastřeným, bude mít v úterý na papíře vyšší hodnotu než čisté jmění všech předchozích prezidentů dohromady. „Časování, pane, se kryje s obchodní dohodou. Jsem povinen to nahlas říct jednou.“","c":[["Nechat to nastat. K obchodní dohodě mlčet.","Obchodní dohoda, která náhodou posílí Bellowovu reklamní byznys, projde ve stejném týdnu, kdy se váš podíl promění ve jmění. Lylova jedna povinná věta je jediné, co v celé budově kdokoli přizná."],["Odložit obchodní dohodu, dokud IPO neprojde kontrolou.","Zpomalíte politiku, abyste vytvořil odstup mezi dvěma událostmi, které se od sebe nikdy neměly přiblížit. Je to malý, skutečný akt sebeovládání, o kterém se mimo tuhle místnost nikdo nikdy nedozví, co vás stál."],["Prodat celý podíl ještě před oceněním IPO.","Odcházíte s výhrou dřív, za nižší cenu, čistě abyste odstranil střet zájmů. Stojí to skutečné peníze a je to na papíře jediná čistá verze tohoto týdne, která je pro vás dostupná."],["Darovat symbolických deset procent zisku charitě, zbytek si ponechat.","Desetina jmění jde s tiskovou zprávou na charitu, zatímco devadesát procent zisku spojeného s obchodní dohodou zůstává přesně tam, kam přistálo."]]},"m-bellow-outage-crisis":{"t":"Špatná noc na výpadek","x":"Bellow je zase dole, právě tu jednu noc, kdy na tom skutečně záleží. Požár v chemičce ve třech okresech, evakuační poplach vedený přes platformu, protože to bylo levnější než starý systém, a nikomu se to nedaří načíst. Brayden se omlouvá do telefonu, který sotva udrží v ruce.","c":[["Počkat, až se Bellow vrátí. Vždycky se to podaří.","Uplyne dvaadvacet minut, než evakuační poplach dorazí k někomu, protože systém varování byl potichu sloučen do platformy, na které osobně vyděláváte."],["Okamžitě spustit starý systém rozhlasového varování.","Pomalejší, ošklivější, státem provozovaný systém, který pořád funguje, i když aplikace ne. Tři okresy stihnou evakuaci včas. Nikdo neděkuje technologii za to, že je nudná."],["Svalit vinu za zpoždění na provozovatele chemičky, ne na platformu.","Ukazujete prstem na požár, ne na aplikaci, která selhala ve varování před ním. Koupí vám to jeden zpravodajský cyklus a nic víc."],["Nařídit, aby nouzová varování už nikdy neprocházela přes jedinou soukromou platformu.","Napíšete pravidlo, které trvale stojí vaši vlastní firmu jednu zakázku, s odůvodněním, že požár v chemičce není chvíle na zjišťování, že aplikace nefunguje."]]},"m-deepfake-rival":{"t":"Podvrh, který pomáhá","x":"Kaylee to ověřila třemi různými způsoby a pořád to není skutečné. Video, na kterém Cordelia Ruiz-Bloomová zdánlivě přijímá úplatek, koluje internetem, dokonale zpracované, čtyřicet osm hodin před klíčovým hlasováním. „Nepřišlo to od nás. Chci to mít v záznamu, než řeknu tu druhou část, a to je, že to pomáhá.“","c":[["Nechat to plout. Nepotvrzovat, nepopírat.","Profitujete z podvrhu, který jste nevytvořil a nevyvrátíte. Hlasování se posune o tři body dřív, než to kdokoli dokáže, což je přesně dost dlouho."],["Okamžitě to veřejně vyvrátit, i když vám to pomáhá.","Zabíjíte lež, která pracovala ve váš prospěch, ze zásady, nahlas, ještě před hlasováním. Je to nákladné a je to jednoznačně nejdůvěryhodnější věc, kterou za celé funkční období uděláte."],["Potichu to zesílit přes spřátelený účet, popřít vlastní účast.","Podvrh dostane druhý dech od účtu bez formálních vazeb na vás a se všemi neformálními. Funguje to, a teď je mnohem těžší to vzít zpět."],["Nabídnout Cordelii vlastní forenzní tým, aby to dokázali jako podvrh.","Předáváte vlastní analytiky svému soupeři, aby ji očistili. Přijme to, viditelně podezřívavá, a je to nejpodivnější dvoustranický moment celého vašeho funkčního období."]]},"m-deepfake-frail":{"t":"Podvrh, který ubližuje","x":"Deborah zavře dveře, než to řekne. Šíří se video, na kterém vypadáte zdánlivě dezorientovaně, mumláte, nedokážete dokončit větu. Není to skutečné. Je to, přiznává, přesvědčivější než několik skutečných momentů z minulého měsíce, kterým lidé už tak jako tak věří, že se staly.","c":[["Požadovat živou, nescénářovanou tiskovou konferenci, abyste to vyvrátil.","Postavíte se, bystrý a bez scénáře, na čtyřicet minut, a podvrh v reálném čase ztrácí většinu své síly. Je to opravdu dobré využití živé televize, kategorie, ve které málokdy operujete."],["Popřít, že video existuje. Vůbec ho nekomentovat.","Mlčení působí u velké části země jako potvrzení. Video koluje dál, aniž by ho kdokoli oficiální vyvracel."],["Zažalovat každou platformu, která ho hostí, naráz.","Vlna žalob odstraní video ze tří platforem a zvěční ho na jedenácti dalších díky vlastnímu zpravodajství o soudní při."],["Zveřejnit celou skutečnou zdravotní dokumentaci, abyste to vyvrátil.","Odpovídáte na zfalšované video skutečnou, kompletní zdravotní transparentností, což je kategorie upřímnosti, kterou tenhle úřad dosud nikdy nezkusil."]]},"m-deepfake-law":{"t":"Zákon o označování","x":"Sy jasně vysvětluje návrh zákona. Vyžadoval by, aby jakýkoli syntetický materiál použitý v kampani, včetně té vaší, nesl viditelné označení. „Platilo by to i na nás. Každá reklama, každý klip, kterého se dotklo PODIUM, označený. Chci jasně říct, že tohle je co do podstaty rozumný zákon.“","c":[["Zabít to. Nechat předsedu sněmovny to pohřbít ve výboru.","Požadavek na označování, který by platil stejně pro všechny, potichu zemře, což nějakým způsobem vyzní podezřeleji, než kdyby prostě neprošel v plénu."],["Podpořit to. Nejdřív označit vlastní obsah.","Podporujete pravidlo transparentnosti, které omezuje váš vlastní provoz dřív, než omezí kohokoli jiného. Projde a vaše další syntetická reklama běží s označením, které vám nikdo nemusí nařizovat."],["Veřejně to podpořit, soukromě podříznout financování prosazování.","Zákon existuje na papíře, bez peněz, které by skutečně kontrolovaly dodržování. Je to pravidlo, které vypadá jako pravidlo a funguje jako doporučení."],["Navrhnout, aby se jako „možná syntetický“ označoval i každý lidský projev.","Pozměňovací návrh tak široký, že by vyžadoval nálepku na každou promluvu kohokoli ve vládě. Je zamítnut jednomyslně za jedenáct minut, vzácný projev dvoustranického zdravého rozumu."]]},"m-deepfake-general":{"t":"Falešný rozkaz","x":"Generál Tarrant stojí v postoji ještě strnulejším než pozor. Syntetický zvukový záznam, dokonale napodobující jeho hlas, nařizující přesun jednotky, který se nikdy nekonal, krátce dosáhl dvou dozorčích důstojníků, než to někdo odhalil. „Zhruba šest minut vydával mým hlasem rozkazy někdo jiný. To je věta, o které jsem nikdy nečekal, že ji budu muset říct.“","c":[["Veřejně to zlehčit. Nevystrašit trhy ani spojence.","Zlehčujete falešný rozkaz, který na papíře krátce pohnul skutečnými jednotkami. Prozatím to funguje a nikdo se nepoučí z toho, co těch šest minut mělo naučit."],["Zveřejnit to naplno, nařídit reformu ověřování hlasu.","Celá znepokojivá pravda jde ven, spolu se skutečnými penězi na opravu skutečné mezery. Je to nákladné a je to jediná verze, která to skutečně uzavře."],["Potichu obvinit soupeřící stát, bez důkazů, na neveřejném briefingu.","Nepodložené obvinění se objeví ve třech titulcích dřív, než si kdokoli vyžádá důkaz. Koupí vám to jeden zpravodajský cyklus a spálí diplomatický most, který se ještě ani nedostavěl."],["Nechat Tarranta nahrát novou, nezaměnitelně lidskou ověřovací frázi.","Generál nahraje záměrně absurdní verbální heslo, zahrnující psa z dětství a konkrétní zapékanou večeři, které žádný model nemá jak znát. Je to, proti vší logice, skutečné řešení."]]},"m-deepfake-foreign-leader":{"t":"Falešná deklarace","x":"Muriel vejde bez zaklepání, což nikdy nedělá. Šíří se video, na kterém prezident Rusalky zdánlivě vyhrožuje San Baldoru silou, generované snímek po snímku, dost dobré na to, že velvyslanectví Rusalky samo přijímá dotazy, jestli je to pravé. „Ani jedna strana to nepopřela dost rychle. V té mezeře začíná skutečná válka.“","c":[["Nic neříkat. Nechat obě země, ať si svůj podvrh vyřeší samy.","Zůstáváte stranou krize, která by se skutečně mohla vymknout kontrole, na základě teorie, že to není vaše starost. Dva národy se přibližují válce kvůli něčemu, co se vůbec nestalo."],["Osobně zavolat oběma vůdcům. Potvrdit, že ani jeden to neřekl.","Pár nenápadných telefonátů zažehná vykonstruovanou krizi dřív, než se stane skutečnou. Skoro nikdo mimo hrstku místností se nikdy nedozví, jak blízko to bylo."],["Využít zmatku k prosazení výhodné dohody pro sebe.","Využíváte dva vyděšené národy uprostřed paniky k podmínkám, které by za klidu nikdy nepřijaly. Funguje to, a je to typ tahu, o kterém se ještě po desetiletích nelichotivě píše."],["Veřejně nabídnout společnou jednotku pro odhalování podvrhů oběma zemím.","Navrhnete, aby dva národy na pokraji války společně postavily nástroj na odhalování dalšího takového videa. Souhlasí, hlavně z čiré úlevy, že někdo změnil téma."]]},"m-donor-spectrum":{"t":"Laskavost s frekvencemi","x":"Cassandra Doyleová má žádost o přidělení. Dexter Voss, zakladatel satelitního a AI konglomerátu Solstice a dárce nemalé štědrosti, chce dostat díl veřejného frekvenčního spektra uvolněný předčasně, ještě před plánovanou aukcí. „Má to pro něj hodnotu miliard. Zjevně to má docela velkou hodnotu i pro nás, soudě podle výše posledního šeku.“","c":[["Uvolnit to předčasně. Aukci úplně přeskočit.","Veřejný zdroj v hodnotě miliard jde jednomu dárci bez soutěžní nabídky. Akcie Solstiku vyskočí do hodiny o jedenáct procent, což je docela přesný způsob, jak změřit laskavost."],["Uspořádat plánovanou aukci. Voss ať se ucházá jako kdokoli jiný.","Spektrum dostane, kdo skutečně nabídne nejvíc, což se nakonec pořád ukáže být Voss, jen za cenu, díky které je celá věc legitimní."],["Uvolnit to předčasně, ale za trojnásobek odhadní ceny.","Laskavost vydávaná za dobrý obchod pro daňového poplatníka. Ve skutečnosti je to docela dobrý obchod, což ho pořád nedělá o nic méně laskavostí."],["Dát spektrum místo toho neziskovce pro venkovský širokopásmový internet.","Předáte zdroj v hodnotě miliard organizaci, která ho použije k připojení statků k internetu. Voss přestane měsíc zvedat telefon, což několik zaměstnanců soukromě označí za dovolenou."]]},"m-donor-council-seat":{"t":"Poradní křeslo","x":"Deborah předkládá nápad, který není její. Dexter Voss chce formální křeslo, „zvláštní poradce pro inovace“, plný přístup k briefingům, bez nutnosti schválení Senátem, protože je to technicky neplacené. „Měl by odznak. Měl by odznak a místo u stolu, kde se rozhoduje o skutečné politice.“","c":[["Dát mu to křeslo. Plný přístup, plný titul.","Soukromá osoba s přímým finančním zájmem na polovině rozhodnutí ministerstva teď sedí v místnosti, kde se ta rozhodnutí dělají. Nikdo o tom nehlasoval, protože nikdo nemusel."],["Odmítnout. Dárci nedostávají odznaky.","Odmítáte skutečný vliv kvůli zásadě, která vás stojí velký budoucí dar. Voss je podle všeho opravdu překvapen."],["Dát mu titul, potichu omezit, co skutečně uvidí.","Odznak s menší místností za sebou, než jaká byla slíbena. Voss si toho osm měsíců nevšimne, což vypovídá o tom, kolik z tohohle vlastně vůbec bylo o skutečných schůzkách."],["Udělat z něj předsedu výboru, který zasedá jednou ročně, osobně, bez videa.","Dáváte mu přesně to, o co požádal, technicky vzato, v té nejnepohodlnější možné formě. Zúčastní se první schůzky a druhou vynechá."]]},"m-donor-nobid-contract":{"t":"Zakázka bez soutěže","x":"Bo Slaughter má na stole nepodepsanou smlouvu. Federální systém AI screeningu, čtyři sta milionů dolarů, přidělený Solstiku bez soutěžního řízení, s odvoláním na „naléhavou národní potřebu“. „Je docela možné, že je to skutečně nejlepší dostupný systém. Je také docela možné, že není, a přeskočili jsme část, kde bychom to zjistili.“","c":[["Podepsat to. Naléhavost ruší proces.","Čtyři sta milionů putuje k dárcově firmě bez jediné konkurenční nabídky. Systém, až dorazí, funguje zhruba tak dobře, jak systémy, které přeskočí revizi, obvykle fungují."],["Otevřít to soutěžnímu řízení. Zpozdit nasazení.","Zakázka jde do otevřené soutěže, trvá to o čtyři měsíce déle a nakonec vyjde na dvě třetiny ceny se systémem, který se skutečně nejdřív otestuje."],["Podepsat to, rozdělit zakázku s druhou, nesouvisející firmou.","Kosmetický druhý dodavatel dostane kousek dohody, aby se rozmazal dojem jediného dodavatele. Solstiku pořád zbyde většina."],["Nechat Vosse systém darovat vládě zdarma.","Požádáte dárce, ať vládě jednoduše daruje systém, který jí chtěl prodat. Vesele souhlasí, protože práva na přístup k datům pro něj vždycky měla větší hodnotu než ten šek."]]},"m-donor-visa-fast-track":{"t":"Laskavost s vízy","x":"Duane má žádost od generální právní zástupkyně Solstiku. Šest set specializovaných víz, urychlených, mimo pořadí fronty, kde běžní žadatelé čekají osmnáct měsíců. „Upřednostňovat není nelegální. Jen obvykle není takhle zjevné, čí jméno je na žádosti.“","c":[["Urychlit všech šest set. Ostatní posunout dozadu.","Šest set Vossových zaměstnanců projde za tři týdny. Obecná fronta, už tak osmnáct měsíců hluboká, je o pár tisíc lidí hlubší."],["Zpracovat je normálně, ve frontě, jako všechny ostatní.","Solstik čeká ve frontě se všemi ostatními. Je to nenápadné, správné a takový druh rozhodnutí, jaký tato administrativa dělá dost zřídka na to, aby to bylo krátce pozoruhodné."],["Urychlit menší dávku. Sto, ne šest set.","Skromnější verze téže laskavosti, dimenzovaná tak, aby v titulku vypadala rozumně. Pořád posouvá sto lidí před ty, kdo podali žádost o roky dřív."],["Urychlit je, a k tomu ve stejném týdnu i celou zbývající frontu.","Vyřídíte celou celostátní frontu naráz, abyste se vyhnul dojmu laskavosti, což stojí opravdu velkou částku z rozpočtu na zpracování a pomůže tisícům lidí, kteří nikdy nikomu nic nedarovali."]]},"m-donor-public-feud":{"t":"Roztržka","x":"Brayden přes stůl posune telefon, oči vykulené. Dexter Voss právě na Bellow, ze všech míst zrovna tam, zveřejnil devítidílné vlákno obviňující administrativu ze „zrady všeho, na čem Solstik tuhle zemi postavil“. Je to, poznamenává Brayden, na první příčce trendů, na platformě, které vlastníte třicet procent.","c":[["Odpovědět veřejně. Celé vlákno, celá jména, dnes večer.","Veřejná válka mezi prezidentem a jeho největším dárcem se odehrává v reálném čase, na vaší vlastní platformě, před očima všech. Čísla zapojení Bellowu i hodnota vašeho podílu naráz vyskočí."],["Nic neříkat. Nechat to samo dohořet.","Odmítáte přiživit hádku, která se hlavně živí sama. Většinou to funguje, i když Voss dostane celý týden nekonfrontovaného vysílacího času."],["Nechat Braydena potichu utlumit dosah vlákna.","Algoritmus, na který máte vliv, potichu shazuje kritické vlákno o vás, na platformě, od muže, který vás právě obvinil přesně z tohohle druhu jednání."],["Zavolat Vossovi přímo. Neoficiálně. Vyřešit to jako dospělí.","Čtyřicetiminutový telefonát vyřeší, co devět veřejných příspěvků nedokázalo. Voss vlákno smaže. Ani jeden z vás nikdy nevysvětlí, co bylo skutečně řečeno, což je nějakým způsobem nejupřímnější část celé epizody."]]},"p-economy-1":{"t":"Šok z cenovky","x":"Ministr financí položí na stůl účtenku z obchodu, jako by to byla obsílka. Vejce zdražila o šedesát procent a kabelové zpravodajství natáčí reportáže před supermarkety. „Pane prezidente, lidé jsou naštvaní, a naštvaní lidé sledují zprávy.“","c":[["Vyhlásit dekret zmrazující všechny ceny potravin do pátku","Regály se přes víkend vyprázdní, protože obchody prostě přestanou doplňovat zmrazené položky."],["Nechat centrální banku zvednout sazby a přijmout politický zásah","Inflace do jara opadne. Nikdo si nepamatuje, kdo to napravil, jen kdo to dopustil."],["Nařídit statistickému úřadu, ať prostě zveřejní nižší číslo","Skutečné ceny zůstanou stejné. Jediné, co se změní, je to, komu můžete věřit."],["Přejmenovat inflaci na celostátní televizi na „cenu svobody“","Galon mléka teď stojí jedenáct dolarů a špetku vlastenectví navrch."]]},"p-economy-2":{"t":"Poslední píšťalka","x":"Vantage Steel zavírá továrnu v Dunmore, tu samou, před kterou jste v kampani stáli s vyhrnutými rukávy. Tři tisíce pracovních míst, jedna fotka, pryč během jednoho odpoledne. „Přesouvají linku do Guatemaly,“ říká ministryně práce. „Dělníci se to dozvěděli esemeskou.“","c":[["Veřejně to svalit na zahraniční obchodní spiknutí proti Dunmore","Vantage Steel vydá prohlášení. Nezmění to nic, jen to, koho budou v hospodě vinit."],["Prosadit skrz Kongres skutečný program rekvalifikace a přestěhování","Stojí to peníze a trvá roky, ale skutečně to pomůže jedenácti stům rodin. To nikdo nefotí."],["Znárodnit továrnu výnosem a vyzvat soudy, ať vás zastaví","Továrna se otevře pod novým nápisem. Ocel, kterou vyrábí, nemá kam výhodně jít."],["Osobně zavolat řediteli továrny a poprosit ho, ať ji prostě nezavírá","Ředitel je velmi zdvořilý. Továrna zavře přesně podle plánu."]]},"p-economy-3":{"t":"Kobaltová opona","x":"Předseda Wei zakázal veškerý vývoz vzácného kobaltu jako odvetu za loňská cla. Každá továrna na baterie v Rezavém pásu má zásoby asi na šest týdnů. „Celý plán elektromobilů jsme postavili na minerálu, který sami netěžíme,“ přiznává ministr zahraničí.","c":[["Vyhlásit celostátní nerostnou nouzi a zabavit soukromé zásoby","Firmy raději zbylý kobalt schovávají, než aby ho odevzdaly."],["V tichosti sjednat dodávky s přátelštější surovinově bohatou zemí","Funguje to, je to nudné a trvá to osm měsíců neokázalých telefonátů."],["Vyhrožovat invazí do surovinově bohatého spojence, aby se zajistily dodávky","Spojenec svolá nouzový summit. Stejně tak zbytek kontinentu."],["Vyhlásit havarijní program těžby kobaltu ze staré skládky v Ohiu","Skládka vydá kobalt na čtyři baterie a spoustu metanu."]]},"p-economy-4":{"t":"Hod mincí","x":"Token zvaný FreedomCoin, který jste možná pochvalně zmínili na jednom mítinku, přes noc ztratil devadesát jedna procent hodnoty. Šéf centrální banky drží výtisk rozzuřených důchodců z fóra jménem r/rugged. „Pane prezidente, někteří z těchto lidí do toho vložili penzi.“","c":[["Oznámit, že vláda osobně zaručí hodnotu FreedomCoinu","Ministerstvo financí teď ručí za měnu, kterou vymyslel muž jménem Chad."],["Předat burzu regulátorům a nechat ztráty být","Nikdo nedostane peníze zpátky, ale příští podvod bude o trochu menší."],["Svalit propad na centrální banku soupeřící velmoci","Obvinění je nepodložené a nesmírně populární."],["Spustit druhý, stabilnější token jménem FreedomCoin Plus","Také se zhroutí, ale trvá to celých jedenáct dní, což někteří nazývají pokrokem."]]},"p-economy-5":{"t":"Zase moc velká na pád","x":"Continental Trust, šestá největší banka v zemi, je potichu insolventní. Pokud v pondělí otevře bez záchrany, říká ministr financí, „čeká nás run na banku, proti kterému bude ten poslední vypadat jako dobročinný bazar.“","c":[["Zachránit ji přes noc a nechat řediteli jeho bonus","Banka přežije. Bonus se na měsíc stane pravidelnou rubrikou zpráv."],["Prosadit řízený zánik s odvoláním vedení","Je to spravedlivé, uspořádané a přesně nikoho, kdo sleduje svůj penzijní účet, to neuspokojí."],["Zachránit ji a v tichosti obsadit novou správní radu vašimi dárci","Banka je zachráněna. Stejně tak, velkoryse, i pár vašich přátel."],["Promluvit k národu s malou keramickou prasečí pokladničkou v ruce","Trhy se stabilizují. Pokladnička se vyprodá ve třech různých obchodech se suvenýry."]]},"p-economy-6":{"t":"Všichni ven","x":"Železničáři, přístavní dělníci a letečtí mechanici vypochodovali ven ve stejné úterý, což odbory nazývají shodou okolností a ministryně práce „nejsehranější náhodou, jakou jsem kdy viděla“.","c":[["Nařídit Národní gardě, ať vlaky a přístavy řídí sama","Náklad se zase pohybuje, špatně, řízen vojáky, kteří v životě neviděli seřaďovací nádraží."],["Sednout s vedením odborů a vyjednat skutečnou smlouvu","Trvá to jedenáct hodin a hodně mizerné kávy, ale vlaky zase jezdí načas."],["Prohlásit stávku za nezákonnou a vyhrožovat hromadným propouštěním","Polovina zaměstnanců se vrátí vyděšená. Z druhé poloviny se stane lidová píseň."],["Osobně řídit vysokozdvižný vozík v přístavu pro kamery","Přesunete jednu paletu, špatně, a stane se to nejsledovanějším klipem roku."]]},"p-economy-7":{"t":"Podání ruky, které nebylo","x":"Historická obchodní dohoda s Meridií byla dnes ráno podepsána s velkou pompou, třemi vlajkami a plnicím perem ve tvaru orla. Vedoucí kanceláře právě zjistila, že skutečný dokument neobsahuje jediné závazné ustanovení. „Je to fotka,“ říká. „Podepsali jsme fotku.“","c":[["Přesto to nazvat historickým a jít dál, než si to někdo přečte","Analytici si toho nakonec všimnou. Do té doby se zpravodajský cyklus otočil třikrát."],["Přiznat, že šlo o symbolické gesto, a slíbit skutečnou dohodu do konce roku","Nikdo netleská upřímnosti, ale skuteční vyjednavači konečně dostanou opravdový mandát."],["Tvrdit, že Meridia potají couvá, a hrozit novými cly","Meridijský velvyslanec je zmatený. Základnu to i tak nadchne."],["Přerámovat samotné orlí pero na historický úspěch","Pero se v obchodě se suvenýry vyprodá do hodiny."]]},"p-economy-8":{"t":"Clo na brie","x":"Jako odvetu za nesouvisející rybářský spor jste uvalili čtyřsetprocentní clo na dovážený měkký sýr. Ministr financí hlásí, že domácí produkce brie je a vždy byla prakticky nulová. „Pane prezidente, zdaňujeme produkt, který tu neexistuje.“","c":[["Rozšířit clo na všechny měkké sýry, z principu","Sýrové mísy po celé zemi jsou znatelně smutnější a vlastenečtější."],["Potichu clo zrušit, než se zorganizuje lobby restaurací","Brie se vrací do regálů. Rybářský spor zůstává zcela nevyřešen."],["Vyhlásit federální dotaci na rozjezd americké výroby brie","V Nebrasce se otvírá pilotní farma na brie. Odborníci zůstávají hluboce skeptičtí."],["Prohlásit čedar za jediný sýr, který pravý vlastenec potřebuje","Prodej čedaru vzroste o jedenáct procent. Někde si povzdechne francouzský ministr."]]},"p-economy-9":{"t":"Maličkost pro Chada","x":"Nový dotační program na čistou energii poslal, čirou náhodou, devadesát procent prostředků solární firmě vlastněné vaším největším sponzorem, mužem jménem Chad Bellwether. „Vyjde to najevo,“ varuje ministr energetiky. „Tyhle věci vždycky vyjdou najevo.“","c":[["Trvat na tom, že firma prostě měla nejlepší žádost","Novináři do týdne najdou fotky z golfu. Základnu to nezajímá."],["Otevřít dotační program skutečnému konkurenčnímu výběrovému řízení","Bellwetherova firma prohraje nové kolo proti firmě z Nevady se skutečnými inženýry."],["Dát Bellwetherovi druhou, ještě větší zakázku, aby se dokázalo, že se nic neskrývá","Něco se skutečně skrývá. Teď je to dvakrát tak velké."],["Přejmenovat program po fiktivním průměrném Američanovi jménem Chad","Skutečný Chad Bellwether to považuje za skvělý vtip. Nikdo jiný ne."]]},"p-economy-10":{"t":"Bolest u pumpy","x":"Benzin po požáru ropovodu překročil šest dolarů za galon a ministryně energetiky říká, že kamioňáci vyhrožují blokádou dálničního okruhu kolem hlavního města. „Tohle je číslo, které končí prezidentství,“ říká věcně.","c":[["Nařídit úplné vyčerpání strategických rezerv, aby se srazila cena","Ceny na šest týdnů klesnou. Rezervy jsou teď nebezpečně, potichu prázdné."],["Místo toho investovat příjmy z windfall daně do veřejné dopravy","Pomůže to za tři roky. Nepomůže to nikomu, kdo dnes v noci stojí v koloně."],["Bez důkazů svalit požár ropovodu na zahraniční sabotáž","Obvinění ovládne zpravodajský cyklus. Ropovod byl ve skutečnosti prostě starý."],["Osobně natankovat cizímu řidiči na kameru a prohlásit problém za vyřešený","Jeden velmi šťastný řidič dostane benzin zdarma na den. Všichni ostatní pořád platí šest dolarů."]]},"p-economy-11":{"t":"Chybějící čip","x":"Jedna zatopená továrna v Chosanu zastavila globální dodávky polovodičů a automobilky ve třech státech stojí. „Každý vůz, který nepostavíme,“ říká ministr financí, „je titulek, který si nemůžeme dovolit.“","c":[["Zabavit domácí zásoby čipů a přesměrovat je oblíbeným automobilkám","Dva závody se okamžitě znovu rozjedou. Šest dalších do čtvrtka podá žalobu."],["Zrychlit povolení pro nové domácí továrny na výrobu čipů","Výstavba začíná do měsíce. Továrny nevyrobí jediný čip dva roky."],["Vyhlásit úplný zákaz vývozu čipů do zemí soupeřících s Chosanem, jako páku","Nic to nezmění na povodni. Hodně to ale změní na vztazích."],["Navrhnout, že vozy prozatím pojedou bez infotainmentu na obrazovce","Kupující jsou rozzuření. Prodejci s údivem zjišťují, že překvapivé množství lidí obrazovku nechce."]]},"p-economy-12":{"t":"Domeček z karet","x":"Ceny domů v šesti velkých metropolích se za osmnáct měsíců zdvojnásobily a ministr financí drží graf nepříjemně podobný tomu z roku dva tisíce osm. „Pane prezidente, kdo si to může dovolit, kupuje rovnou tři.“","c":[["Vinit stejně hlasitě přistěhovalce i investory","Je to uspokojivé vysvětlení. Většinou to ale není ten skutečný důvod."],["Postupně zpřísnit pravidla pro hypotéky, aby se trh ochladil","Noví kupující vám tiše děkují. Současní majitelé sledující svůj kapitál nikoli."],["Dekretem zakázat všechny firemní nákupy rodinných domů","Každá velká realitní firma do týdne podá žalobu. Základna tenhle souboj miluje."],["Navrhnout mladým lidem, ať si prostě řeknou rodičům o vyšší půjčku","Klip se stane virálním ze všech špatných i pár správných důvodů."]]},"p-economy-13":{"t":"Problém s penzemi","x":"Meziregionálnímu penzijnímu fondu Teamsters chybí devět miliard dolarů a půl milionu důchodců se má dozvědět, že jejich šeky se zmenšují. „Pracovali na tom čtyřicet let,“ říká ministryně práce. „Neudělali nic špatně.“","c":[["Potichu nechat fond snížit dávky a vinit správce fondu","Důchodci dostanou menší šeky. Správci fondu dostanou velmi přísný dopis."],["Prosadit v Kongresu federální záruku, která pokryje schodek","Stojí to daňové poplatníky miliardy a zachrání to půl milionu důchodů. Obojí je pravda."],["Nařídit centrální bance, ať schodek přes noc potichu dotiskne","Šeky přijdou včas. Ekonomové stráví příští rok vysvětlováním, proč je to znepokojivé."],["Uspořádat televizní bingo večer pro důchodce na zvednutí morálky","Morálka je krátce vynikající. Devítimiliardová díra zůstává přesně devítimiliardovou dírou."]]},"p-economy-14":{"t":"Měnová hra nervů","x":"Prezident Volkov nazval dolar ve státní televizi „umírajícím reliktem“ a záměrně znehodnotil rublu podobnou měnu solyanku, aby podrazil americký export. „Snaží se vás vyprovokovat k veřejné reakci,“ varuje ministr financí. „Nenaleťte na to.“","c":[["Odpálit to zpátky na sociálních sítích a nazvat ho zkrachovalým tyranem","Trhy sebou trhnou. Volkov, nadšený, odpoví do hodiny."],["Nechat reagovat pouze ministerstvo financí tichými diplomatickými kanály","Kurz se do týdne stabilizuje. Nikdo netleská tichu, které to zařídilo."],["Nařídit symbolický hromadný výprodej dluhopisů solyanky, aby ho to potrestalo","Ministerstvo financí to stojí víc než Volkova, ale je z toho skvělý titulek."],["Poslat Volkovovi jednu pamětní minci s nápisem „Druhá nejlepší měna světa“","Státní média se o tom nikdy nezmíní. Váš vlastní tiskový úřad nepřestane."]]},"p-economy-15":{"t":"Nekupujte americké","x":"Po vašem posledním projevu o clech se po třech kontinentech rozšířil občanský bojkot amerického zboží a ministr zahraničí hlásí, že oblíbená značka limonády byla v Meridii úplně stažena z regálů. „Jde o tu limonádu, pane prezidente. Bojkotují limonádu.“","c":[["Prohlásit bojkotující země za ekonomické nepřátele Ameriky","Bojkot se rozšiřuje. Zvláštně tak i domácí hrdost na limonádu."],["Nechat ministra zahraničí potichu stáhnout projev o clech","Bojkot za měsíc odezní. Nikdo doma si nevšimne, že vůbec nastal."],["Spustit ze vzdoru protibojkot meridijského dovozu","Meridijský dovoz jsou hlavně banány. Ceny v obchodech mírně stoupnou bez jakéhokoli strategického přínosu."],["Osobně vyslat maskota limonádové firmy na dobrovolnou misi","Maskot je vřele přijat. Limonáda zůstává zakázaná."]]},"p-economy-16":{"t":"Zpráva o zaměstnanosti","x":"Měsíční zpráva o zaměstnanosti poprvé za tři roky ukazuje čistou ztrátu pracovních míst a ministryně práce má tu nezáviděníhodnou úlohu přinést ji do Oválné pracovny. „Vnitřní čísla můžeme zabalit jinak,“ říká opatrně, „ale hlavní číslo je hlavní číslo.“","c":[["Prohlásit zprávu za podvrh a žádat rezignaci šéfa úřadu","Šéf pod tlakem rezignuje. Příští zpráva je horší a teď jí nikdo nevěří tak jako tak."],["Prezentovat skutečná čísla poctivě, s plánem, jak je řešit","Ekonomové si váží upřímnosti. Základna chtěla padoucha, ne tabulku."],["Svalit ztráty úplně na předchozí administrativu","Předchozí administrativa opustila úřad před dvěma lety. Na tom nezáleží."],["Předefinovat částečné úvazky a nezaměstnané jako „jinak zaměstnané“","Nové číslo vypadá skvěle. Fronta u potravinové banky vypadá stejně."]]},"p-economy-17":{"t":"Patnáct a bojujeme","x":"Koalice pracovníků rychlého občerstvení požaduje zvýšení federální minimální mzdy na dvacet dva dolarů a ministryně práce hlásí, že lobby restaurací v reakci hrozí hromadným propouštěním. „Obě strany si myslí, že ta druhá blafuje,“ říká. „Nikdo neblafuje.“","c":[["Hlasitě se postavit na stranu malých podniků a nazvat pracovníky nevděčnými","Lobby restaurací jásá. Pracovníci plánují mnohem větší pochod."],["Vyjednat postupné, mírné zvýšení, které obě strany snesou","Nikdo není nadšený. Obě strany se nerady, ale vrátí do práce."],["Slíbit plných dvacet dva dolarů výnosem už zítra","Nařízení je populární a téměř jistě nezákonné. Žaloby začnou okamžitě."],["Navrhnout pracovníkům, ať si o zvýšení řeknou přímo manažerům","Virální video přesně ukazuje, jak taková konverzace obvykle dopadá."]]},"p-economy-18":{"t":"Nic se nehýbe","x":"Přístavní dělníci v přístavu Harlow zastavili nakládku kvůli mzdovému sporu a ministr financí říká, že čtyřicet procent dováženého zboží teď kotví na lodích u pobřeží. „Každý další den,“ říká, „je za šest týdnů den prázdných regálů.“","c":[["Poslat federální dodavatele, ať lodě naloží sami","Dodavatelé jsou pomalí a nezkušení. Přístavní dělníci jsou teď rozzuření z úplně jiného důvodu."],["Financovat nezávislého mediátora, aby mzdový spor spravedlivě urovnal","Trvá to dva týdny a přinese to férovou smlouvu. Lodě se konečně dají do pohybu."],["Vyvolat mimořádný pracovní zákon, aby se dělníci okamžitě vrátili","Přístav se pod protesty znovu otevírá. Spor se prostě přesune do podzemí."],["Osobně vyjednávat přes hlasitý telefon z Resolute Desk","Hovor trvá čtyři hodiny a hlasitě nedosáhne téměř ničeho."]]},"p-economy-19":{"t":"Přátelský monopol","x":"Regulátoři zahájili antimonopolní šetření proti Halcyon Systems, technologickému gigantu, jehož generální ředitel náhodou štědře přispíval na vaše poslední dvě kampaně. „Důkazy jsou opravdu zdrcující,“ říká ministr financí. „Stejně tak i načasování vašich hovorů s ním.“","c":[["Potichu nechat šetření zaškatulkovat jako profesní laskavost","Šetření zmizí. Jeden velmi vytrvalý novinář nezmizí."],["Nechat regulátory dělat svou práci bez zásahů","Halcyon Systems je vysoce pokutován. Ředitel vám přestane brát hovory."],["Prohlásit šetření za politicky motivované kariérními úředníky","Regulátoři jsou přeloženi. Halcyon Systems posílá velmi štědrý dárek na poděkování."],["Navrhnout Halcyonu, ať se prostě přejmenuje, aby nezněl tak monopolně","Halcyon Systems se stává Halcyon Přátelské Systémy. Podíl na trhu zůstává identický."]]},"p-economy-20":{"t":"Na dně","x":"Váš příspěvek ve tři ráno, který nazval velkou automobilku „hanbou a podvodem“, smazal ze společnosti čtyřicet miliard dolarů za devadesát minut a tisková mluvčí odpovídá na hovory od každého ekonomického oddělení v zemi. „Pane prezidente, chtějí vědět, jestli to bylo úmyslné.“","c":[["Přitvrdit a napsat, že si firma zasloužila ještě víc","Akcie klesnou ještě víc. Vaše základna to nazývá zodpovědností."],["Potichu příspěvek smazat a dál nic neříkat","Akcie se částečně zotaví. Smazání se stává vlastním malým skandálem."],["Tvrdit, že propad na trhu dokazuje, že firma byla vždy zkorumpovaná","Neexistuje žádný důkaz korupce. Existuje teď kongresové vyšetřování vašeho příspěvku."],["Zveřejnit fotku sebe, jak si přesto kupujete auto té značky","Akcie o dvě procenta stoupnou. Nikdo úplně nechápe, proč to zabralo."]]},"p-economy-21":{"t":"Strop","x":"Kongres se zablokoval kolem zvýšení dluhového stropu a ministryně financí říká, že vládě dojdou účetní triky za jedenáct dní. „Pak,“ říká, „budeme vybírat mezi platem vojáků a platbou držitelům dluhopisů.“","c":[["Vyhrožovat ražbou pamětní bilionové mince a vyzvat je, ať protestují","Mince je právně sporná a nesmírně populární. Kongres se v naprosté trapnosti do pár dní vzdá."],["Obvolávat vedení Kongresu kvůli dvoustranické dohodě","Dohoda je nevzhledná, včasná a nikdo mimo Washington si nevšimne, že se to stalo."],["Vinit opoziční stranu, že drží platy vojáků jako rukojmí","Opozice vinu hodí zpátky na vás. Termín se blíží tak jako tak."],["Navrhnout platit držitelům dluhopisů pamětními mincemi místo hotovosti","Držitelé dluhopisů nejsou pobavení. Mince jsou, uznejme, docela pěkné."]]},"p-economy-22":{"t":"Šek pro farmáře","x":"Pěstitelé sóji ve čtyřech státech čelí odvetným clům soupeřící velmoci a úrodě, kterou nemají komu prodat. Ministr zemědělství navrhuje nouzový záchranný šek a pak tiše dodává: „Minule to šlo hlavně velkým podnikům, ne rodinným farmám.“","c":[["Poslat šeky rychle a detaily řešit později","Šeky přijdou do týdne. Stejně tak i příběhy o tom, které farmy dostaly ty největší."],["Navrhnout cílený program, který skutečně upřednostní malé rodinné farmy","Trvá to o tři týdny víc papírování a dostane se k farmářům, kteří to potřebovali nejvíc."],["Vést dodatečné záchranné prostředky přes nadaci velkého sponzora","Sponzorova nadace si účtuje pěkný administrativní poplatek. Farmáři dostanou zbytek."],["Uspořádat fotoop na balíku sena a slíbit, že šeky jsou už na cestě","Balík sena vypadá na fotce skvěle. Šeky ve skutečnosti na cestě nejsou."]]},"p-economy-23":{"t":"Levná ocel","x":"Foundry Nation vyváží dotovanou ocel na americký trh za polovinu domácí ceny a tři další huti hrozí zavřením do zimy. „Je to podle obchodního práva nezákonné,“ říká ministr financí, „a zároveň to pro ně funguje přesně podle plánu.“","c":[["Okamžitě uvalit mimořádná cla na veškerý dovoz oceli","Domácí huti jásají. Každé odvětví, které ocel kupuje na stavbu věcí, potichu sténá."],["Podat formální obchodní stížnost správným mezinárodním kanálem","Je to správný postup. Trvá to také osmnáct měsíců, které žádná huť nemá."],["Vyhlásit úplné obchodní embargo na Foundry Nation kvůli oceli","Foundry Nation do hodiny oplatí odvetou na sóje. O tu vůbec nešlo."],["Uspořádat mítink v huti s helmou na hlavě pro kamery","Helma vypadá na fotce skvěle. Huť o dva měsíce později stejně zavře."]]},"p-economy-24":{"t":"Kupujte americké (platí podmínky)","x":"Nová iniciativa Kupujte americké odstartuje zítra s vlajkami, ohňostrojem a znělkou. Vedoucí kanceláře právě zjistila, že oficiální merch ze startu, čepice vietně, se vyrábí kompletně v zahraničí. „Zásilku ještě můžeme zrušit,“ říká. „Už je ale na lodi.“","c":[["Spustit to stejně a doufat, že si nikdo nevšimne štítků","Někdo si štítků všimne do hodiny. Znělka hraje dál."],["Odložit spuštění a zajistit merch z domácích zdrojů","Spuštění se opozdí o tři týdny, čepice vietně, štítky konečně pravdivé."],["Tvrdit, že zahraniční továrna je tajně vlastněná Američany","Není vlastněná Američany. Na mítinku se to tvrzení stejně opakuje."],["Přejmenovat čepice na „Skoro kupujte americké“","Čepice se vyprodají. Fráze se do večera stane nešťastným memem."]]},"p-money-1":{"t":"Nápadník s národním fondem","x":"Fond z „přátelské zálivové monarchie“ chce koupit golfová letoviska vaší rodiny za trojnásobek tržní ceny. Ministryně financí pořád opakuje „žádné podmínky navíc“, jako by ta fráze podmínky smazala. „Chtějí jen být vašimi partnery,“ říká a posouvá k vám smlouvu.","c":[["Podepsat, poslat hotovost","Peníze dorazí do pátku. Novináři začnou počítat vaše pískové bunkry."],["Vést je přes svěřenský fond bez vlivu","Nudné, legální, a nikdo vám za to neuspořádá přehlídku."],["Vzít si hotovost i práva na pojmenování","Osmnáctá jamka se teď jmenuje Jamka číslo jedna. Nenápadné."],["Trvat na tom, že budete zaplaceni ve zlatých cihlách","Celníci mají k té paletě spoustu otázek."]]},"p-money-2":{"t":"Spuštění memecoinu","x":"Váš syn chce spustit prezidentský memecoin, ještě než dokončíte ranní briefing. „Není to úplatek, tati, je to komunita,“ říká, už oblečený v mikině s logem. Velcí hráči se řadí, aby nakoupili za cenu, kterou už nikdy nikdo jiný neuvidí.","c":[["Nechat ho to spustit, vzít si podíl","Graf jde vertikálně nahoru, pak do strany, pak do skupinového chatu o žalobách."],["Zastavit to, než to začne","Syn se durdí. Etičtí právníci si poprvé po týdnech oddechnou."],["Spustit to a přidat sadu NFT k tomu","Někde si muž zastaví dům kvůli obrázku kresleného orla."],["Přejmenovat to po svém psovi","Psí mince do úterý předčí skutečnou měnu."]]},"p-money-3":{"t":"Výhodný pozemek","x":"Developer vám chce prodat pobřežní pozemek za dolar a pak potichu přeplánovat zbytek pobřeží kolem něj. Váš právník to nazývá „dárkem s výborným načasováním“. Ani nemrkne, když to řekne.","c":[["Koupit pozemek za dolar, schválit přeplánování","Teď vlastníte pláž. Také několik nových nepřátel na stavebním úřadě."],["Zaplatit plnou tržní cenu, vyloučit se z rozhodování","Developer je zmatený. Vaše jmění se sotva pohne."],["Vzít si pozemek a rozprodat celý poloostrov","Poloostrov se teď jmenuje resort. Slovo „pobřeží“ je teď historický pojem."],["Žádat platbu v pobřežních kabinách místo hotovosti","Vlastníte jedenáct kabin a nemáte tušení, co s nimi."]]},"p-money-4":{"t":"Hra na skořápky","x":"Vaše generální prokurátorka potřebuje podpis na formalizaci holdingové společnosti, která na papíře existuje jen kvůli přijímání zahraničních konzultačních poplatků. „Je to formalita,“ říká a poklepává na složku. „Ta formalita jen náhodou pere peníze.“","c":[["Podepsat bez čtení","Papíry zmizí v šuplíku úřadu ve státě, kam nikdo nejezdí."],["Odmítnout a složku skartovat","Prokurátorka vypadá zklamaně, ale dnes nic nezákonného nepodá."],["Podepsat a přidat další dvě skořápky","Teď máte firemní rodokmen, na který se žádný auditor nechce šplhat."],["Pojmenovat skořápkovou firmu po sobě, bez maskování","Nenápadnost nikdy nebyla vaše silná stránka."]]},"p-money-5":{"t":"Etický spis","x":"Úřad pro vládní etiku potichu otevřel spis k vašim financím. Vedoucí kanceláře se ptá, jestli byste to nechtěl „předběhnout“, než to udělá novinář. „Předběhnout“ v té větě dře jako mezek.","c":[["Zamést spis pod koberec, přeřadit vyšetřovatele","Vyšetřovatel je teď náměstek zástupce náměstka někde v mrazu."],["Zveřejnit své finance dobrovolně","Čísla jsou nudná. Nudné je, výjimečně, vítězství."],["Zamést spis pod koberec a místo toho prověřit novináře","Novinářovy daně jsou najednou pro finanční úřad velmi zajímavé."],["Přejmenovat spis na performativní umění","Galerie v Berlíně nabízí vystavit vaše bankovní výpisy."]]},"p-money-6":{"t":"Honorář za přednášku","x":"Obchodní sdružení vám chce zaplatit čtyři sta tisíc dolarů za dvacetiminutovou „hlavní řeč“ týden poté, co podepíšete jejich oblíbenou daňovou výjimku. Vedoucí kanceláře trvá na tom, že „tak to na okruhu prostě chodí“.","c":[["Vzít honorář, přednést řeč","Dvacet minut potlesku, čtyři sta tisíc dolarů, žádné poznámky."],["Odmítnout honorář, podepsat zákon na základě jeho merit","Sdružení je zmatené. Zmatek se, ukazuje se, dá mít zdarma."],["Vzít honorář a přidat knižní smlouvu","Kniha se jmenuje Vítězství a skládá se hlavně z poděkování."],["Žádat, ať je honorář zaplacen formou publicity","Publicita, ukazuje se, není zákonné platidlo, ale i tak si ji vezmete."]]},"p-money-7":{"t":"Licence na věž","x":"Zahraniční developer chce nalepit vaše jméno na napůl postavenou luxusní věž v zemi s pochybnou historií lidských práv. Váš tamní velvyslanec to nazývá „brandingovou příležitostí s výbornou marží“. O zřícení lešení se nezmiňuje.","c":[["Poskytnout licenci na jméno, vybrat poplatek","Věž je do čtvrtka přejmenována. Lešení zůstává nevyřešené."],["Licenci úplně odmítnout","Developer si najde jiné jméno k nalepení. Nějak je to v pořádku."],["Poskytnout licenci a přidat hotelové křídlo","Teď jsou tam dvě budovy s vaším jménem a jeden funkční výtah."],["Trvat na tom, že věž bude mít tvar vaší tváře","Řízení letového provozu žádá o přehodnocení nosu."]]},"p-money-8":{"t":"Skulina v zákoně","x":"Váš tým na financích navrhl daňové ustanovení tak specifické, že se v praxi vztahuje na jediný rodinný trust v Americe. Váš. „Zní to obecně,“ trvá ministryně. „Vztahuje se to na jakoukoli kvalifikující víceoborovou pohostinskou entitu s přesně vašimi vlastnostmi.“","c":[["Propašovat to do zákona, který musí projít","Nikdo si nepřečte stránku čtyři sta dvanáct. Vy si ji přečtete třikrát."],["Ustanovení sám škrtnout","Váš účetní tiše pláče ve vedlejší místnosti."],["Propašovat to a zpětně to rozšířit","Šek s vratkou dorazí dřív, než kdokoli dočte zákon."],["Pojmenovat skulinu po fiktivním voliči","Muž jménem Gary Skulina neexistuje, a přesto tu jsme."]]},"p-money-9":{"t":"Rodinná zakázka","x":"Startup vašeho syna, který nikdy nevydal žádný produkt, právě vyhrál devítimístnou federální zakázku na „modernizaci“ něčeho, co nikdo pořádně nedovede definovat. Novináři začali používat slovo „nepotismus“, jako by to byla nová informace.","c":[["Nechat zakázku platit","Startup najme recepční. Jistý druh pokroku."],["Zrušit ji a otevřít skutečné výběrové řízení","Syn s vámi týden nemluví. Pravděpodobně to stojí za to."],["Nechat ji platit a přidat druhou zakázku","Startup má teď dvě zakázky a pořád žádný produkt."],["Nechat ho se přerebranovat na neziskovku","Neziskovky si, jak se ukazuje, pořád mohou koupit pěknou loď."]]},"p-money-10":{"t":"Darovaná jachta","x":"Lodní magnát vám „daroval“ dvěstěstopovou jachtu a trvá na tom, že je to „jen půjčka, na neurčito, navždy“. Vedoucí kanceláře ji v podkladech k briefingu už přejmenovala, aby se vyhnula vyslovení slova „dar“.","c":[["Přijmout jachtu, potichu ji zakotvit","Jachta je teď technicky muzeum, což technicky není úplatek."],["Odmítnout ji, nabídku nahlásit","Magnát je ohromený. Odmítání darů je zjevně vzácnost."],["Přijmout ji a odpovídající helikoptéru k tomu","Na klimatické summity teď přiletíte helikoptérou. Tým pro image dá výpověď."],["Přejmenovat jachtu na „Prezidentský čas“","„Prezidentský čas“ je za týden spatřen u tří různých pobřeží."]]},"p-money-11":{"t":"Vděčná obálka","x":"Muž, kterého jste na jaře omilostnili, nechal u vašeho osobního asistenta tašku „pro nadaci“. Nikdo se nezeptal pro kterou. Váš právník jemně naznačuje, že tašky hotovosti jsou „přinejmenším otázka image“.","c":[["Nechat si to, mlčet","Taška zmizí v trezoru, který se neobjeví v žádném inventáři."],["Vrátit ji a nahlásit toho, kdo o milost žádal","Muž je zuřivý. Právník, výjimečně, vypadá úlevně."],["Nechat si to a zeptat se, jestli přijde víc","Přijde skutečně víc. A pravidelně, jak se ukáže."],["Darovat to nadaci, kterou jste si právě vymyslel","Nadace má jediného zapsaného zaměstnance, a to jste vy."]]},"p-money-12":{"t":"Blokové rezervace","x":"Zahraniční delegace si právě zarezervovala celý váš hotel na státní návštěvu, za noční sazbu, kterou vlastní personál nazývá „ambiciózní“. Váš poradce pro vnitřní bezpečnost věcně poznamenává, že Ústava k tomuto téma má názor.","c":[["Přijmout rezervaci za plnou sazbu","Lobby voní čerstvými penězi a mírným porušením ústavy."],["Přesměrovat je do konkurenčního hotelu","Váš generální manažer je zdrcený. Ústava méně."],["Přijmout to a nabídnout jim navíc prezidentský apartmán","Apartmán stojí víc než dům většiny lidí. Týdně."],["Pokoj poskytnout zdarma a účtovat jim minibar","Účet za minibar sám o sobě financuje malé velvyslanectví."]]},"p-money-13":{"t":"Národní kryptorezerva","x":"Ministryně financí navrhuje, aby vláda držela „strategickou rezervu“ mince, které náhodou vlastníte velké množství vy osobně. „Je to progresivní krok,“ říká. „Je to taky vaše mince,“ říkáte. Nesouhlasí.","c":[["Oznámit rezervu","Vaše podíly ztrojnásobí hodnotu ve chvíli, kdy tisková zpráva vyjde."],["Nápad úplně zrušit","Trh zívne. Vaše portfolio zívá s ním."],["Oznámit to a nejdřív si přikoupit víc","Načasování, jak se říká, je vše, a to vaše bylo bezchybné."],["Přejmenovat rezervu po budově ministerstva financí","FortKnoxCoin trenduje šest hodin, pak z právních důvodů potichu skončí."]]},"p-money-14":{"t":"Předstih","x":"Váš zpravodajský briefér skoro jistě omylem prozradil detail o přezkumu fúze, který ještě nebyl oznámen. Váš makléř je jednu esemesku od přesné vědomosti, co koupit dřív, než to udělá trh.","c":[["Poslat tu esemesku","Obchod projde. Algoritmus SEC bohužel taky vnímá vzorce."],["Zprávu smazat, nikoho neinformovat","Nic se nestane, což je přesně smyslem toho cvičení."],["Poslat ji a zapojit dva sponzory","Tři portfolia přes noc rozkvetou. Jeden analytik klade příliš mnoho otázek."],["Obchodovat opačným směrem jako klamnou stopu","Klamná stopa prodělá peníze, což je nějak nejpřesvědčivější část."]]},"p-money-15":{"t":"Charitativní gala","x":"Nadace vaší dcery vybrala na včerejším gala jedenáct milionů dolarů. Záznamy ukazují, že dva miliony šly do stipendijního fondu a devět milionů do „provozu“, kategorie, která se skládá hlavně ze samotného gala.","c":[["Nechat účetnictví tak, jak bylo podáno","Stipendijní fond dostane pěknou tabulku. Zbytek dostane ještě lepší párty."],["Nařídit plný nezávislý audit","Audit je nemilosrdný. Tabulka naštěstí přežije."],["Přidat do správní rady další dva příbuzné","Nadace teď zaměstnává víc rodiny než skutečného personálu."],["Přejmenovat ji na Fond prezidentské excelence","Excelence, podle výkazů, stojí docela dost na správu."]]},"p-money-16":{"t":"Aukce členství","x":"Váš golfový klub potichu draží členství lobbistům za absurdní přirážky se šeptaným příslibem „přístupu“. Vedoucí kanceláře žádá váš souhlas s ceníkem před pondělními tee-timy.","c":[["Schválit ceník","Pořadník se zaplní muži, kteří nikdy nedohráli pod devadesát ran."],["Omezit poplatky za členství na tržní úroveň","Klub je náhle mnohem méně ziskový a mnohem méně zajímavý."],["Schválit to a přidat úroveň jen pro lobbisty","Nová úroveň zahrnuje skříňku a zjevně i vaše telefonní číslo."],["Prodávat členství formou tomboly místo toho","Penzionovaná učitelka vyhraje skříňku vedle vojenského dodavatele."]]},"p-money-17":{"t":"Merch kolekce","x":"Vaše ředitelka sociálních sítí chce spustit limitovanou edici tenisek, hodinek a balíčku s pamětní Biblí, prodávanou výhradně přes firmu, kterou náhodou vlastníte. „Vlastenectví,“ říká, „se zdravou přirážkou.“","c":[["Spustit kolekci","Bible se vyprodají. Nikdo nekontroluje, kdo je tiskl, ani kde."],["Místo toho darovat zisk na charitu","Prodeje klesnou ve chvíli, kdy zisk přestane téct k vám. Zvláštní."],["Spustit to a přidat kolínskou","Kolínská se jmenuje Autorita. Voní vzdáleně po kůži a žalobách."],["Prodávat tenisky jen členům Kongresu","Polovina sněmovny teď nosí do práce stejné boty."]]},"p-money-18":{"t":"Zlaté vízum","x":"Ministerstvo zahraničí navrhuje nový investiční vízový program s neobvykle velkorysou výjimkou: žadatelé, kteří investují přímo do nemovitostí vaší rodiny, projdou frontou za poloviční čas. Ministr zahraničí to nazývá „pilotním programem“.","c":[["Schválit rychlou linku","Pořadník na vaše nemovitosti je najednou mnohem kratší a mnohem bohatší."],["Před schválením výjimku odstranit","Program projde čistě. Vašemu účetnímu to nějak připadá skoro zklamáním."],["Schválit to a výjimku rozšířit","Polovina žadatelů teď uvádí vaše budovy jako celou svou investiční strategii."],["Požadovat, aby si žadatelé taky koupili tenisky","Imigrační právo a obuv se spojí způsobem, který nikdo nečekal."]]},"p-money-19":{"t":"Podcastové impérium","x":"Nová podcastová síť vašeho syna chce prodávat „přístupové balíčky“ hostům, kteří chtějí sedět s vámi na rozhovoru. Sazba za přátelských třicet minut je vysoká a stoupá. „Je to jen obsah,“ říká.","c":[["Schválit přístupové balíčky","Rozvrh rozhovorů teď vypadá jako velmi drahá seznamka."],["Zpřístupnit rozhovory zdarma a rovnocenně všem","Rezervace se propadnou. Stejně tak, nápadně, i příjmy sítě."],["Schválit to a přidat VIP after-party úroveň","VIP úroveň zahrnuje fotku, podání ruky a velmi vysokou fakturu."],["Vyměňovat rozhovory za podíly ve firmách místo peněz","Teď spoluvlastníte tři startupy, které nedokážete úplně vysvětlit."]]},"p-money-20":{"t":"Mince s tváří","x":"Mincovna chce razit pamětní minci s vaším profilem, prodávanou sběratelům za vysokou přirážku, s tantiémami vedenými přímo na váš osobní účet. Ministryně financí přísahá, že je to „pro mincovnu úplně normální“.","c":[["Schválit minci, vzít si tantiémy","Mince se vyprodá do hodiny. Numismatici k tomu mají co říct."],["Schválit minci, tantiém se vzdát","Mincovna vydělá. Vy ne. Titulek je tam nějak stejně."],["Schválit to a přidat i zlatou edici","Zlatá edice stojí víc než auto většiny lidí."],["Dát na rub svého psa","Psí mince do týdne prodejně předčí prezidentskou."]]},"p-money-21":{"t":"Slepý fond, který slepý není","x":"Správce vašeho „slepého fondu“ vám právě volal zeptat se, cituji, „které nemovitosti byste chtěl tento kvartál koupit“. Váš právník připomíná, že celý smysl slepého fondu je, že tohle nemáte vědět.","c":[["Potichu dál radit","Fond funguje podezřele dobře na něco, co nevidí."],["Předat skutečnou kontrolu nezávislému správci","Vaše portfolio je nudné. Váš právník poprvé po měsících spí."],["Dál to řídit a rozšířit portfolio","Fond, který není slepý, teď nevidí ještě víc nemovitostí."],["Přejmenovat fond na „Rozhodně slepý s.r.o.“","Jméno neoklame vůbec nikoho, nejméně ze všech auditory."]]},"p-money-22":{"t":"Fond na knihovnu","x":"Zahraniční miliardáři se řadí do fronty, aby financovali vaši budoucí prezidentskou knihovnu, žádné podmínky, kromě těch, kteří se o ní zmíní těsně předtím, než regulační rozhodnutí dopadne v jejich prospěch. Váš dvorní historik nazývá ten vzorec „náhodou hodnou studia“.","c":[["Přijmout každý dar","Slavnostní výkop má nezvykle mezinárodní seznam hostů."],["Omezit dary a zveřejnit všechny dárce","Fundraising se zpomalí na plazivé tempo. Zeď se jmény je najednou mnohem méně zajímavá."],["Přijmout každý dar a přidat křídlo pro každého miliardáře","Knihovna má teď čtyřicet křídel a zhruba čtyři skutečné knihy."],["Prodat i práva na pojmenování obchodu se suvenýry","Obchod se suvenýry generuje víc příjmů než archiv, ke kterému patří."]]},"p-phone-1":{"t":"Ospalý spojenec","x":"Vedoucí kanceláře vás budí ve tři ráno, protože jste už vytočil premiérku Halvorsenovou a ta je teď na lince a ptá se, proč křičíte kvůli narušení hranice. „Pane prezidente,“ říká, „to je mýval.“ Vedoucí kanceláře bezhlesně artikuluje „zavěste už“, zatímco drží telefon na délku paže.","c":[["Nařídit jí mobilizovat vojáky proti mývalovi","Sedmnáct vojáků obklíčí popelnici. Mýval vítězí."],["Omluvit se, zavěsit, nechat tu ženu spát","Odpustí vám. Také vaše číslo umlčí."],["Obvinit ji, že mývala kryje jako špiona","Menší spojenec je teď velká bolest hlavy."],["Oslovovat mývala křestním jménem a nabídnout mu azyl","Mýval, Gerald, má teď osobní ochranku."]]},"p-phone-2":{"t":"Dnešní body k diskusi","x":"Moderátor Chip Bellamy volá dvacet minut před vysíláním a žádá, ať mu osobně nadiktujete dnešní titulek. „Dej mi něco s ostrými zuby,“ říká, „sledovanost klesá a producent hrozí, že mě nahradí zlatým retrívrem.“ Vaše tisková mluvčí se už potí skrz sako.","c":[["Nakrmit ho skandálem, který technicky ještě neexistuje","Titulek zní PŘELOMOVÁ ZPRÁVA a nic dalšího na tom není pravda."],["Odmítnout, odkázat ho na skutečný tiskový úřad","Zlatý retrívr dostane segment. Zvládá to skvěle."],["Nakrmit ho skandálem o konkrétním senátorovi","Senátor se to dozví živě ve vysílání od Chipa."],["Nabídnout se jako spoluhostitel, bez scénáře, hned teď","Sledovanost se ztrojnásobí. Nikdo neumí vysvětlit, co bylo řečeno."]]},"p-phone-3":{"t":"Medaile, kterou jste si nezasloužili","x":"Předseda Chen volá pogratulovat vám k vyjednání míru v regionálním konfliktu, o kterém jste v životě neslyšeli. „Vaše diplomacie,“ říká vřele, „bude připomínána po generace.“ Váš poradce pro národní bezpečnost horečně googluje, o jaký konflikt by mohlo jít.","c":[["Přijmout zásluhu a naznačit kampaň na Nobelovu cenu","Teď dlužíte Chenovi laskavost za válku, kterou jste neukončili."],["Přiznat, že netušíte, o čem mluví","Chen je nadšený. Zmatek, jak se ukazuje, respektuje."],["Přijmout zásluhu a žádat summit na vaši počest","Summit se naplánuje. Válka, stále probíhající, na něj pozvána není."],["Požádat Chena, ať vám detaily jednoduše pošle mailem později","Mail nikdy nedorazí. Jasno taky ne."]]},"p-phone-4":{"t":"Sponzor na lince jedna","x":"Bradlee Wickham, který osobně financoval čtyři billboardy a pochodovou kapelu, volá připomenout vám, že jistá ekologická regulace „zabíjí americká pracovní místa, nebo aspoň moje kvartální čísla“. Letos už dvakrát přispěl na vaši reelekci. Ministr financí drží ceduli s nápisem KONFLIKT ZÁJMŮ.","c":[["Slíbit, že regulaci do pátku vykucháte","Pátek přijde. Stejně tak žaloba."],["Poděkovat mu za podporu a nic neměnit","Billboardy jdou dolů. Pochodová kapela se rozpustí."],["Regulaci vykuchat a pojmenovat ji po něm","Wickhamův zákon do měsíce otráví řeku."],["Požádat ho, ať si radši rovnou koupí tu řeku","Koupí ji. Je nadšený. Ryby ne."]]},"p-phone-5":{"t":"Uražený emír","x":"Emír, kterého jste na mítinku minulý týden nazval „chlapíkem v hábitu s příliš velkým balíkem naftových peněz“, je na lince a slyšitelně se nesměje. „Omluvíte se,“ říká, „nebo je dohoda o ropovodu mrtvá.“ Váš velvyslanec stojí za vámi a tiše se modlí.","c":[["Bohatě se omluvit a slíbit mu státní večeři","Přijme to. Poznámka o hábitu se v jeho zemi stane potiskem na tričku."],["Nabídnout vyváženou, profesionální omluvu a hovor ukončit","Ropovod přežije. Nikdo se nebaví."],["Přitvrdit a nazvat ho chlapíkem v hábitu znovu, do očí, v hovoru","Dohoda o ropovodu je mrtvá. Ceny ropy si toho okamžitě všimnou."],["Pochválit konkrétně ten hábit a zeptat se, kde ho sehnal","Řekne vám to. Je z obchoďáku. Oba jste nadšení."]]},"p-phone-6":{"t":"Uniklý hovor","x":"Nahrávka včerejšího hovoru, ve které jste tři světové lídry nazval „smutný, hlasitý a Steve“, unikla současně do všech sítí. Vaše tisková mluvčí drží čtyři zvonící telefony a nezvedá žádný. „Steve to nebere s humorem,“ hlásí.","c":[["Tvrdit, že nahrávka je falešná, vytvořená AI, hluboce lichotivá pro Steva","Steve zveřejní vlastní nahrávku. Je pravá."],["Přiznat to, omluvit se všem třem, hlavně Stevovi","Steve to přijme. Měl, jak se ukázalo, náročný týden."],["Uniknout ještě horší nahrávkou někoho jiného, aby se to zamlžilo","Šest hodin to funguje. Pak unikne i tohle."],["Ze solidarity si začít sám říkat Steve","Matoucí. Také, podivně, se vám to počítá v průzkumech."]]},"p-phone-7":{"t":"Linka s rukojmími","x":"Vyjednavač FBI je uprostřed hovoru s mužem, který drží tři bankovní úřednice, když vás k hovoru omylem někdo připojí. „Tady prezident,“ řeknete, protože se nedokážete udržet, a vyjednavačova tvář zbledne jako kancelářský papír. Únosce, potěšený, se ptá, jestli by to nešlo streamovat živě.","c":[["Souhlasit, mohla by z toho být skvělá televize","Sledovanost je historická. Stejně tak zpráva FBI o incidentu."],["Okamžitě zavěsit a nechat pracovat profesionála","Úřednice se v pořádku vrátí domů. Vaše vystoupení si nikdo nepamatuje."],["Vyjednávat osobně, nabídnout únosci milost","Vzniká precedens. Každá banka v zemi si toho všimne."],["Zazpívat happy birthday tomu, kdo v bance má nejblíž narozeniny","Všichni jsou zmatení natolik, že se trochu uklidní."]]},"p-phone-8":{"t":"Zelená, tak nějak","x":"Generál Ostrander volá pro povolení k útoku, na kterém už technicky začal pracovat. „Pane prezidente, potřebuju ano nebo ne do devadesáti vteřin,“ říká. Vy jste zrovna sledoval dokument o rybaření na okouny a zachytili jste tak čtyřicet procent z toho, co právě řekl.","c":[["Říct ano s naprostou jistotou, ptát se později","Útok proběhne. Stejně tak kongresové slyšení."],["Žádat ho, ať vás pořádně informuje před rozhodnutím","Okno se zavře. Generál je zuřivý. Ústava méně."],["Říct ano a přidat dva cíle, které vás právě napadly","O druhý cíl nikdo nežádal. Ani o třetí."],["Nechat ho čekat, než dokoukáte pořad o rybaření","Generál čeká. Okoun bohužel unikne."]]},"p-phone-9":{"t":"Laskavost","x":"Trent Halloway ze Silicon Valley volá zeptat se, velmi ledabyle, jestli by se regulátoři nemohli „podívat na“ aplikaci jeho konkurenta. „Nic šíleného,“ říká, „jen trochu přátelské antimonopolní pozornosti.“ Bez vyzvání také zmíní, že příští měsíc pořádá fundraiser.","c":[["Slíbit, že na konkurenta pošlete regulátory","Konkurentova aplikace záhadně neprojde třemi audity."],["Říct mu, že regulátoři takhle nefungují, zavěsit","Halloway je ohromený, že peníze nezafungovaly okamžitě."],["Slíbit laskavost a žádat ještě větší fundraiser","Laskavost se udělí. Dopad na image je katastrofální."],["Požádat Hallowaye, ať vám místo toho postaví aplikaci","Postaví ji za víkend. Sleduje něco znepokojivého."]]},"p-phone-10":{"t":"Špatná země","x":"Uprostřed hovoru se zahraničním ministrem sebejistě poděkujete Belgii za podporu v tichomořském dějišti. Nastane dlouhá pauza. „Pane prezidente,“ říká ministr opatrně, „my jsme Bolívie.“ Vaše vedoucí kanceláře fyzicky opustila místnost.","c":[["Trvat na tom, že jste celou dobu myslel Bolívii","Bolívie tomu nevěří. Belgie taky ne, jakmile se to doslechla."],["Omluvit se za záměnu jako dospělý člověk","Ministr to velkoryse přijme. Klip se stejně odvysílá."],["Nahlas v hovoru obvinit svůj personál","Personál slyší každé slovo. Morálka, už tak křehký zdroj, klesá."],["Požádat ho, ať vám po zbytek hovoru prostě říká, s kým vlastně mluvíte","Řekne vám to. Pomůže to. Trochu."]]},"p-phone-11":{"t":"Kapesní vytáčení","x":"Váš komorník vám s výrazem hlubokého osobního utrpení oznámí, že jste kapsou vytočil čtyřicetiminutovou nelichotivou tirádu o viceprezidentovi přímo investigativní novinářce. Novinářka je pořád na lince. Říká: „Prosím, pokračujte.“","c":[["Pokračovat v mluvení, ona je vlastně skoro jako tiskový sbor","Čtyřicet minut se stane čtyřicetiminutovou titulní story."],["Okamžitě zavěsit a zavolat právníkovi","Story vyjde stejně, pod titulkem CO JSME NEMĚLI SLYŠET."],["Pokračovat v mluvení a jít ještě dál, jmenovat konkrétní věci","Konkrétní věci se stanou titulkem. Viceprezident si to přečte dvakrát."],["Pozvat ji na oběd, probrat to neoficiálně","Přijme to. Nic na tomhle není neoficiální."]]},"p-phone-12":{"t":"Mnoho šťastných návratů","x":"Prezident Volkov volá popřát vám k narozeninám, hlas vřelý jako čerstvý asfalt. „Šedesát let,“ říká, „jaký křehký věk pro muže s tolika nepřáteli.“ Pak se, pořád vřele, zeptá, jestli vaše kódy k raketové obraně letos „dobře vydržely“.","c":[["Odbýt to smíchem a pozvat ho na inauguraci příští rok","Pozvání přijme. Vaše ochranka týden nespí."],["Zavěsit a informovat Radu národní bezpečnosti","Nic se nestane. Paranoia byla tentokrát oprávněně cvičná."],["Vyhrožovat mu zpátky, zmínit, že jeho narozeniny se taky blíží","Volkovovy narozeniny jsou v prosinci. Tenhle hovor si dobře zapamatuje."],["Zazpívat si happy birthday sám sobě, zatímco poslouchá","Hluboce zvláštní. Volkov, výjimečně, nemá co dodat."]]},"p-phone-13":{"t":"Hovor od někoho, koho obdivujete","x":"Polní maršál Baako, muž, kterého jste soukromě na třech různých večeřích nazval „efektivním“, volá nabídnout „přátelskou radu ohledně zvládání disentu“. Váš ředitel rozvědky poslouchá s vypnutým mikrofonem a v duchu sepisuje výpověď.","c":[["Podrobně si zapisovat, upřímně mu poděkovat","Poznámky unikají o osmnáct měsíců později. Znějí přesně tak zle, jak se obáváte."],["Zdvořile radu odmítnout a hovor ukončit","Baako je uražený. Ředitel rozvědky poprvé po deseti minutách vydechne."],["Požádat ho, ať radu pošle písemně, na hlavičkovém papíře","Hlavičkový papír je pravý. Stejně tak nakonec i předvolání k němu."],["Stočit hovor na jeho péči o pleť","Sdílí ji, nevyžádaně a zeširoka. Zahrnuje spoustu vaječných bílků."]]},"p-phone-14":{"t":"Špatné číslo","x":"Vytočíte číslo, o kterém si myslíte, že patří ministru vnitřní bezpečnosti, a místo toho zastihnete penzionovanou dentální hygienistku jménem Carol z Toleda. O čtyřicet minut později znáte celou fotbalovou sezónu jejího vnuka a ona ví víc o přezkumu jaderné doktríny než většina senátorů. Váš hlavní komorník stojí ve dveřích a neví, co si s tím počít.","c":[["Pozvat Carol na kávu do Bílého domu","Carol přijde. Carol má názory na záclony."],["Omluvit se, zavěsit, skutečně vytočit ministra","Ministr je zmatený, že už o přezkumu doktríny víte."],["Zeptat se Carol, co byste podle ní měl s doktrínou udělat","Carolina rada je, znepokojivě, přijata na příštím briefingu."],["Dát Carol na místě vymyšlený oficiální titul","Zvláštní vyslankyně Carol má teď parkovací místo u Pentagonu."]]},"p-phone-15":{"t":"Ultimátum předsedy","x":"Předseda centrální banky Otis Brandt volá znovu vám oznámit, že nemůžete jen tak „poprosit hezky“ o snížení sazeb. „Nezávislost,“ říká, „je tak trochu celý smysl mé existence.“ Tento týden jste už čtyřikrát napsal, že je „slabý, ospalý a možná špión“.","c":[["Přesto žádat snížení a vyhrožovat výpovědí","Trhům se ta hrozba nelíbí. Technicky ani zákonu."],["Přijmout jeho nezávislost a zavěsit zdvořile","Sazby zůstávají. Stejně tak, většinou, i váš krevní tlak."],["Žádat snížení a uniknout jeho domácí adresu do rozhlasu","Brandt si najme víc ochranky. Sazba zůstává stejná stejně tak."],["Nabídnout mu výměnou za snížení sazby vstupenky na rybářský výlet","Odmítne. Doporučí vám ale dobré jezero."]]},"p-phone-16":{"t":"Volání jasnovidce","x":"Vaše dcera si z legrace do vašeho telefonu naprogramuje psychickou linku pod jménem „PORADCE PRO NÁRODNÍ BEZPEČNOST“. Madame Delphine na druhém konci vám sdělí, že „vás před úplňkem sklizně zradí muž s knírem“. Váš skutečný poradce pro národní bezpečnost knír má.","c":[["Preventivně propustit poradce s knírem","Byl až do této chvíle naprosto loajální."],["Zavěsit, zasmát se, zavolat dceři si postěžovat","Dcera je nekajícná. Stálo to za to."],["Zeptat se Madame Delphine i na politickou radu, když už ji máte na lince","Její předpověď se nesplní. Váš kabinet zjistí, že jste se ptal."],["Dát Madame Delphine smlouvu jako oficiální poradkyni","Znepokojivě má v pár věcech později pravdu."]]},"p-phone-17":{"t":"Obchodní příležitost","x":"Váš syn vás propojí s mužem jménem Chaz, který chce probrat „vážně vzrušující energetickou dohodu, naprosto košer, sotva nějaký Kazachstán v tom“. Syn mu už teď říká „parťáku“. Váš právní poradce Bílého domu si u stolu začal nalévat něco tvrdšího.","c":[["Přijmout schůzku, vyslechnout Chaze celou","Chazova naprosto košer dohoda je ve skutečnosti pod několika prkny."],["Zarazit to a říct synovi, ať takové hovory přestane brát","Syn se durdí. Chaz si najde jiného člena rodiny."],["Přijmout schůzku a zapojit syna jako konzultanta","Slovo „konzultant“ v té větě odvede spoustu práce."],["Požádat Chaze, ať pomalu vysvětlí, čím se vlastně živí","Nedokáže to. To řekne úplně všechno."]]},"p-phone-18":{"t":"Všechno se nahrává","x":"Váš šéf rozvědky vás upřed vytáčením varuje, že zahraniční prezident, kterému máte zavolat, prezident Alenko, je znám tím, že nahrává a nakonec zveřejňuje každý hovor jako páku. Voláte stejně, protože má skvělé drby o vzájemném rivalovi. Zvedne to už se smíchem.","c":[["Mluvit volně, drby stojí za to riziko","Drby byly skvělé. Přepis o šest měsíců později ne."],["Držet hovor krátký a bolestně profesionální","Alenko se nudí. Nudné je, výjimečně, tou strategií."],["Mluvit volně a přidat vlastní drb o senátorovi","Ten senátor se to nakonec dozví z Alenkových pamětí."],["Požádat Alenka, ať vám nahrávku pošle do vašeho vlastního alba","Pošle ji. Je, nějak, ještě horší, než jste si pamatoval."]]},"p-phone-19":{"t":"Lidový hrdina žertéř","x":"Muž, který si říká Vévoda z Toleda, tento měsíc jedenáctkrát prankově volal na ústřednu Bílého domu s neuvěřitelně věrnou imitací zahraniční hlavy státu. Tentokrát se dostane přímo k vám, uprostřed imitace, a internet ho už prohlásil za národní poklad. Vaše ředitelka sociálních sítí drží telefon se čtyřmi miliony zhlédnutí.","c":[["Hrát to naživo, udělat z něj oficiální hvězdu","Vévoda z Toleda dostane vlastní talk show. Vy dostanete bolest hlavy."],["Zpřísnit ústřednu a jít dál","Žertíky přestanou. Bohužel s nimi i jediná zábava, kterou kdokoli měl."],["Nabídnout mu jako odměnu skutečné vládní místo","Vévoda z Toleda je teď nějak náměstek tiskového mluvčího."],["Zkusit mu vrátit vlastní imitaci, bez přípravy","Stane se virální. Podle žádného měřítka to není dobrá imitace."]]},"p-phone-20":{"t":"Garda pro průvod","x":"Guvernér Ellsbury volá požádat o zápůjčku Národní gardy, ne kvůli nouzi, ale hlavně kvůli image, na přestřižení stuhy na krajském veletrhu. „Tanky na místních zprávách vážně fungují,“ vysvětluje. Asistent ministra obrany se někde mimo záběr viditelně modlí.","c":[["Schválit to, tanky na přestřižení stuhy zní zábavně","Stuha se přestřihne. Tank přejede stánek s trdelníky."],["Žádost zamítnout, garda není průvodová dekorace","Přestřižení stuhy proběhne, tragicky, jen s nůžkami."],["Schválit to a přidat i přelet pro dobrou míru","Přelet rozechvěje každé okno v kraji."],["Nabídnout mu místo toho vlastní pochodovou kapelu","Žádnou pochodovou kapelu nemáte. Teď ji budete muset sehnat."]]},"p-phone-21":{"t":"Hovor o záchraně","x":"Starostka Denise Okaforová volá při večeři vysvětlit, že její město je technicky bez peněz a mohlo by se opravdu hodit trochu federálního „něco“, žádné podmínky, nejsme vybíraví. Starostkou je šest týdnů. Dluh vznikl o dekádu dřív, než nastoupila.","c":[["Okamžitě poslat peníze, být hrdina","Šek projde. Podstata problému zůstává nedotčena."],["Vysvětlit správný rozpočtový proces a zavěsit","Město zůstává na mizině. Proces je aspoň respektován."],["Poslat dvojnásobek peněz a žádat sochu na oplátku","Socha je nelichotivá. Je také, technicky, nosná konstrukce."],["Nabídnout se, že rozpočet města osobně proauditujete hned po telefonu","Najdete čtrnáct chyb a žádná řešení. Všichni jsou vyčerpaní."]]},"p-phone-22":{"t":"Modlitební linka","x":"Pastor Michael Rourke chce, abyste hned teď živě vstoupil do jeho rozhlasového vysílání kvůli spontánní modlitbě za národ, kterou zjevně jeho producent předem naskriptoval. „Řekněte prostě, co máte na srdci,“ říká a drží kartičky, které nevidíte, ale rozhodně slyšíte šustit.","c":[["Přečíst každou kartičku slovo od slova, hlasitě a srdečně","Národ je požehnán. Národ si taky všimne toho šustění."],["Nabídnout krátké, upřímné, neskriptované slovo a odejít z vysílání","Krátké a důstojné. Sledovanost s důstojností bohužel nesouhlasí."],["Odchýlit se od scénáře a proměnit to v kampaňový projev","Pastor Rourke tohle s FCC nekonzultoval. Nikdo to nekonzultoval."],["Požádat celé publikum, ať se modlí konkrétně za váš golfový hendikep","Modlitby jsou zjevně vyslyšeny. Hendikep se zlepší o dvě rány."]]},"p-press-1":{"t":"Tři zdroje, jedna noční můra","x":"Beacon-Herald tvrdí, že tři nezávislé zdroje potvrzují, že jste osobně schválil plán nahradit Národní gardu ostrahou obchodních center. Dva ze zdrojů jsou stejný chlap, jen s jinými e-mailovými adresami.","c":[["Nazvat to koordinovaným podvodem","Vymyslíte pojem „falešné zdrojování“ a do oběda trenduje."],["Potvrdit ty nudné pravdivé části a jít dál","Story se scvrkne na jeden odstavec a do čtvrtka na ni všichni zapomenou."],["Zažalovat Beacon-Herald do bankrotu","Žaloba neuspěje, ale samotné právní poplatky jim naruší hlavičku listu."],["Oznámit, že strážní obchodních center dostanou federální penze","Sedmnáct hlídačů se přes noc stane lidovými hrdiny."]]},"p-press-2":{"t":"Fotka za tisíc rozzuřených slov","x":"Fotka, jak se smějete na státním pohřbu, je všude. Ve skutečnosti jste se smál asistentovu vyzvánění. Asistent si od té doby změnil vyzvánění i kariérní plány.","c":[["Trvat na tom, že fotku zfalšoval samotný zármutek","Nikdo technicky nedokáže vyvrátit, že zármutek má editor fotek."],["Zveřejnit celé video ukazující to vyzvánění","Klip je mírně vtipný a story potichu umře na kontext."],["Zakázat kamery do padesáti stop od jakékoli rakve","Pohřební ústavy teď vyžadují povolení a detektor kovů."],["Tvrdit, že jste ve skutečnosti plakal, jen s vyceněnými zuby","Bulvár otiskne titulek PLAKAL S VYCENĚNÝMI ZUBY."]]},"p-press-3":{"t":"Někdo v téhle budově má telefon na jedno použití","x":"Přepis schůzky vrcholného personálu se objeví online během hodiny, i s překlepy. Kdokoli to unikl, také potichu opravil vaši gramatiku, což nějak působí ještě hůř.","c":[["Svalit to na gramatické šprty z Hlubokého státu","Korektoři po celé zemi hlásí nárůst nenávistných dopisů."],["Nařídit tichou, zákonnou vnitřní kontrolu","Dva asistenti raději dají výpověď, než by si sedli na pohovor."],["Podrobit celý vrcholný personál polygrafu naživo na kameru","Sledovanost skvělá. Morálka personálu ne."],["Uniknout druhý, falešný přepis, aby se to zamlžilo","Tři zpravodajské servery teď stahují tři různé story."]]},"p-press-4":{"t":"Číslo, které nikdo nechce vyslovit nahlas","x":"Nový průzkum dává vaší popularitě dvacet dva procent, statisticky vyrovnaně s regionálním stažením vadné polévky z prodeje. Váš odborník na průzkumy popisuje tu polévku jako „na vzestupu“.","c":[["Prohlásit veškeré průzkumy za zahraniční spiknutí","Agentury pro výzkum veřejného mínění začnou cestovat se soukromou ochrankou."],["Uznat to číslo a nastínit skutečný plán","Politologové souhlasně přikyvují. Nikdo jiný si toho nevšimne."],["Zadat vlastní průzkum jen mezi příbuznými","Váš strýc bez vyzvání hlásí devadesát jedna procent podpory."],["Vyzvat polévku na veřejnou odvetu","Polévka nemůže legálně reagovat, a přesto to nějak vyhraje."]]},"p-press-5":{"t":"Noční talk show má scénku","x":"Skečová show odvysílá celé hudební číslo o jednáních vaší vlády, celé zahrané loutkami. Loutka hrající vás statečně zpívá falešně, což je celý vtip.","c":[["Vyhrožovat vysílací licenci té stanice","Právníci obou stran si koupí chaty na dovolenou."],["Poslat loutce vstřícný fanouškovský dopis","Klip se stane virálním právě proto, že je proti očekávání vstřícný."],["Žádat stejný vysílací čas pro protiloutku","Vaše protiloutka je všeobecně uznávaná za méně šarmantní."],["Loutku rovnou koupit","Loutka je teď placenou mluvčí vlády. Pořád zpívá falešně."]]},"p-press-6":{"t":"Oprava, kterou odmítáte otisknout","x":"The Ledger vás žádá o opravu tvrzení, že nezaměstnanost je na „nejnižším čísle, jaké kdy bylo vymyšleno“. Mají skutečná čísla. Vy máte sebevědomí.","c":[["Odmítnout a to číslo zopakovat hlasitěji","Číslo se pravdivějším nestane, ale rozhodně slavnějším."],["Potichu opravu vydat sami","Jeden řádek v zítřejším briefingu. Nikdo si nevšimne, kromě všech, na kom záleží."],["Žádat, ať Ledger opraví svou opravu","Vypukne opravová válka. Nikdo nevyhraje. Všichni jsou vyčerpaní."],["Uvést zbrusu nové, neověřitelné číslo","„Nejnižší číslo, jaké si kdo dokázal představit“ vstoupí do slovníku národa."]]},"p-press-7":{"t":"Novinářka položí skutečnou otázku","x":"Na dnešním briefingu se novinářka z malého regionálního listu zeptá na konkrétní, dobře prozkoumanou, nezodpověditelnou otázku o rozpočtu. V místnosti je ticho. Něčí telefon začne nahrávat.","c":[["Nazvat její otázku falešnou a její list malým","Počet předplatitelů se ze vzdoru ztrojnásobí."],["Skutečně odpovědět, jak nejlíp umíte","U dvou čísel se spletete, ale v duchu věci máte pravdu."],["Odejmout jí na místě tiskovou akreditaci","Stovka dalších novinářů se teď ptá přesně na tu samou otázku."],["Odpovědět kompletně formou haiku","Kritici poezie jsou nečekaně dojatí."]]},"p-press-8":{"t":"Video, kde přiznáte úplně všechno","x":"Hyperrealistický deepfake ukazuje, jak klidně oznamujete rezignaci, abyste se „věnoval polévkovému impériu“. Je to nesmírně přesvědčivé. I vaše vedoucí kanceláře se na vteřinu zarazila.","c":[["Prohlásit veškeré video důkazy vás navždy za falešné","Náhodou jste si vytvořili trvalé alibi na cokoli."],["Zveřejnit skutečné, nudné video, které to klidně vyvrátí","Vyvrácení dostane jedenáct procent zhlédnutí, co dostal falzifikát."],["Zažalovat videoplatformu kvůli samotnému konceptu videa","Právní vědci o tom píší studie. Video zůstává online."],["Oznámit, že skutečně spouštíte polévkovou řadu","Předobjednávky přesáhnou vaši skutečnou popularitu."]]},"p-press-9":{"t":"Vaše oblíbená televize chce laskavost","x":"Proslule přátelská televize vám nabízí celou hodinu, žádné tvrdé otázky, výměnou za exkluzivní přístup na Velikonoční vajíčkovou slavnost. Jejich slova: „měkké otázky to ani zdaleka nevystihují.“","c":[["Udělat rozhovor a v něm sjet každou jinou stanici","Ostatní stanice odvysílají společný segment s názvem „Měkké otázky, doslova“."],["Dát rovný přístup férovému mixu médií","Pokrytí je férové, vyvážené a naprosto zapomenutelné."],["Dát přátelské televizi trvalý exkluzivní přístup","Každý jiný novinář teď slavnost pokrývá z blízkého parkoviště."],["Nechat celý rozhovor vést dětskou reportérku","Osmiletá dívka klade znatelně lepší otázky než kdokoli z personálu."]]},"p-press-10":{"t":"Prezidentský překlep vyvolá celonárodní zmatek","x":"Vaše oficiální prohlášení o „obraně svrchovanosdi národa“ obsahuje překlep ve slově svrchovanost. Je z toho už hashtag, tričko a údajně i drobná kryptoměna.","c":[["Tvrdit, že překlep je tajný kód pro vlastence","Tisíc lidí teď věří, že komunikujete výhradně v překlepech."],["Smazat to, znovu zveřejnit správně, dál nic neříkat","Nudné. Účinné. Finančně zničující pro výrobce triček."],["Vyhodit stážistu, který to napsal","Stážista dostane do týdne knižní smlouvu."],["Ochránkovat si ten překlep sám","Teď vlastníte „svrchovanosd“ v jedenácti kategoriích merche."]]},"p-press-11":{"t":"Zapsal si úplně všechno","x":"Váš bývalý náměstek vedoucího kanceláře vydal knihu se vším všudy. Kapitoly se jmenují „Incident s mixérem“ a „Nikdo mu neřekl, co znamená NATO“. Předobjednávky jdou svižně.","c":[["Nazvat ho v televizi zahořklým, zneuctěným lhářem","Prodeje knihy se zdvojnásobí. Znovu jste jeho marketingovým oddělením."],["Potvrdit historku s mixérem a smát se tomu","Vypadáte jako sportovec, jednou za čas. Váš personál je z toho hluboce znejistělý."],["Nechat u soudu vymáhat jeho dohodu o mlčenlivosti","Žaloba se stane druhou kapitolou brožovaného vydání."],["Napsat vlastní konkurenční knihu o něm","Dvě knihy, jedna vendeta, nekonečný obsah."]]},"p-press-12":{"t":"Tohle jste je fakt neměl nechat natočit","x":"Dokumentární štáb, který jste pozval na „bezprecedentní přístup“, zachytil jedenáct nehlídaných minut, jak křičíte na tiskárnu. Editoři jsou prý „rozmazlení výběrem“.","c":[["Tvrdit, že záběr zinscenovala výrobní firma tiskáren","Výrobce tiskáren vydá prohlášení, které je nějak důstojnější než to vaše."],["Nechat záběr odvysílat, přidat sebeironický klip","Na chvíli působíte lidsky. Nevydrží to."],["Koupit celý dokument a nechat ho v šuplíku","Pirátské kopie kolují stejně do týdne."],["Uspořádat tiskovou konferenci k formální omluvě tiskárně","Tiskárna omluvu nemůže přijmout, jelikož je to tiskárna."]]},"p-press-13":{"t":"Čtyřicet vteřin, které nechtějí zemřít","x":"Čtyřicetivteřinový klip, na kterém třemi různými způsoby v jedné větě špatně vyslovujete slovo „infrastruktura“, má sto milionů zhlédnutí a stále přibývá.","c":[["Trvat na tom, že výslovnost je regionální a správná","Lingvisté zdvořile, ale zeširoka nesouhlasí, v několika komentářích."],["Udělat si z toho vtip na příští tiskovce","Klip dostává druhý život: vy se mu smějete. Mírně sympatické."],["Zakázat slovo „infrastruktura“ v oficiálních prohlášeních","Zákony teď popisují silnice jako „ty dlouhé rovné tvrdé věci“."],["Vydat remixový singl toho klipu","Umístí se v žebříčcích. Jste teď, technicky vzato, hudební umělec."]]},"p-press-14":{"t":"Titulek, který nepřestává počítat","x":"Zpravodajská stanice teď vysílá živý, trvalý spodní pruh počítající vaše nepravdivá tvrzení. Dnes ráno, během reportáže o počasí, překročil čtyři tisíce.","c":[["Nazvat počítadlo samotné čtyřtisícátou lží","Metalži jsou zjevně pořád lži. Počítadlo je to jedno."],["Začít být opravdu opatrnější se svými tvrzeními","Tempo růstu počítadla se zpomaluje. Někde se nudou rozplakal fact-checker."],["Žádat, aby stanice nainstalovala stejné počítadlo i pro vaše soupeře","Jejich počítadlo začíná na nule a zůstává otravně nízké."],["Nechat přesné číslo počítadla prohlásit za utajované","Počítadlo teď ukazuje jen UTAJENO, což je nějak ještě horší."]]},"p-press-15":{"t":"Váš nekrolog už je napsaný","x":"Redakce jednoho velkého deníku píše nekrology pro úřadující vůdce dopředu, pro případ náhlé události. Ten váš unikl. Poradci poznamenávají, že je „překvapivě férový“.","c":[["Žádat propuštění autora nekrologu za morbiditu","Každý autor nekrologů v zemi teď pracuje z utajeného místa."],["Požádat o revizi jen kvůli faktické přesnosti","Opravíte si rodiště. Zbytek zůstává beze změny."],["Vydat vlastní, mnohem lichotivější nekrolog předem","Teď kolují dva nekrology. Ani jeden neuklidňuje."],["Zúčastnit se vlastního fingovaného pohřbu kvůli publicitě","Účast je hojná. Smuteční řeči jsou trefné."]]},"p-press-16":{"t":"Mikrofon byl zapnutý, a jak","x":"Mezi segmenty zachytí nezavřený mikrofon, jak říkáte asistentovi, že navštěvující delegace „smrdí jako auto z půjčovny“. Delegace písemně žádá vysvětlení.","c":[["Tvrdit, že to byl kompliment v jiném jazyce","Takový jazyk neexistuje. Tvrzení to vůbec nezpomalí."],["Zavolat velvyslanci a osobně se omluvit","Velvyslanec omluvu velkoryse přijme a nikdy vám to úplně nezapomene."],["Popírat, že by se kdy nějaký mikrofon k vám přiblížil","Zvukaři po celé zemi se dávají na těžké pití."],["Poslat delegaci bednu osvěžovačů vzduchu jako dárek","Delegace si není jistá, jestli je to omluva, nebo eskalace."]]},"p-press-17":{"t":"Válka o akreditace","x":"Zrušili jste akreditaci novináři za to, že kladl „příliš mnoho doplňujících otázek“. Soudce z toho, co se týče prvního dodatku, evidentně nadšený není.","c":[["Pro jistotu zrušit akreditaci ještě pěti dalším","Tisková místnost je teď hlavně prázdné židle a jeden velmi tvrdohlavý stážista."],["Vrátit akreditaci a potichu se omluvit","Novinářka to přijme. Její doplňující otázky jsou pak ze vzdoru ještě ostřejší."],["Odvolat se proti soudcovu rozhodnutí až na nejvyšší instanci","Prohráváte na každé úrovni, což se nějak samo stává novinovou senzací."],["Vytvořit novou kategorii akreditací s názvem „Opravdu dobří novináři“","Nikdo se nepřihlásí. Zůstáváte jediným členem této kategorie."]]},"p-press-18":{"t":"Váš soupeř má názory, písemně, s poznámkami pod čarou","x":"Váš hlavní politický soupeř publikuje ostrý komentář nazvaný „Skromný návrh na kompetenci“. Má poznámky pod čarou. Několik poradců soukromě přiznává, že je dobře argumentovaný.","c":[["Napsat zuřivou odpověď a nazvat ho zrádcem","Odpověď nemá jedinou poznámku pod čarou a pár překlepů."],["Věcně reagovat v klidném veřejném prohlášení","Uznáte jeden bod. Je to jako operace bez anestezie."],["Žádat, aby noviny denně tiskly stejně dlouhou odpověď","Noviny souhlasí a pak váš text zahrabou vedle křížovky."],["Vyzvat soupeře na veřejnou soutěž v psaní poznámek pod čarou","Nikdo nechápe pravidla. Všichni se přesto dívají."]]},"p-press-19":{"t":"Spis, o který nikdo nežádal","x":"Kariérní státní úředník podává formální oznámení, že jste Situační místnost použil ke sledování finále telenovely. Oznámení obsahuje i hodnocení: „poutavá televize, sporná státnická moudrost“.","c":[["Zdiskreditovat oznamovatele jako zahořklého fanouška konkurenčního seriálu","Sledovanost konkurenčního seriálu vzroste. Té vaší telenovely méně."],["Plně spolupracovat s prošetřením","Šetření vás zprošťuje viny a potvrzuje, že jste finále skutečně viděl."],["Prohlásit celé oznámení za věc národní bezpečnosti","Kongres teď chce vědět, co je na telenovele tak tajného."],["Pozvat oznamovatele, aby se s vámi podíval na příští finále","Přijme pozvání. Prý je to milý večer."]]},"p-press-20":{"t":"Každý má prý svou cenu","x":"Asistent hlásí, že středně známý novinář proslulý tvrdým zpravodajstvím je „koupitelný“ za místo blízko vlády a pěknou kancelář. Právně vzato je to krajně nevhodné.","c":[["Udělat to potichu a v případě dotazů navždy vše popírat","Přijme místo. Bývalí kolegové mu, ani vám, už nikdy úplně nedůvěřují."],["Odmítnout a nabídku nahlásit jako nevhodnou","Nic se nestane, kromě toho, že vaše integrita je, na chvíli, neporušená."],["Nabídnout to místo veřejně jen abyste viděl, kdo se chytí","Přihlásí se čtrnáct novinářů. Žádný z nich nebyl ten tvrdý."],["Přijmout ho a hned přeřadit na počasí","Jeho předpovědi teď procházejí přísnější kontrolou faktů než celá vaše vláda."]]},"p-press-21":{"t":"Parodie, co nechce skončit","x":"Komikova imitace vás, samý přimhouřený pohled a mumlání, je teď rozpoznatelnější než vy sám. Malé děti ji prý dělají lépe než komik.","c":[["Žalovat komika za krádež vaší osobnosti","Právníci poznamenávají, že osobnost se přesně vzato ukrást nedá. Žaloba je zamítnuta s viditelným pobavením."],["Na veřejné akci zahrát imitaci sám na sebe, s nadhledem","Sklidí největší smích týdne, na váš vlastní účet, což je vzácné a cenné."],["Zakázat komikovi vstup na všechny budoucí tiskové akce","Komik pak dělá imitaci jen zvenku za zábranami, hlasitěji."],["Najmout komika jako svého nového spisovatele projevů","Vaše projevy jsou najednou mnohem vtipnější a citelně méně srozumitelné."]]},"p-press-22":{"t":"Internet vyhlašuje soutěž o nejlepší popisek","x":"Fotka, na které mžouráte na desky s nápisem NALÉHAVÉ, držíte je vzhůru nohama, spustila celostátní soutěž o popisek. Aktuálně vede: „Muž zjišťuje, že gravitace platí i na papír“.","c":[["Žádat, aby platforma smazala každý příspěvek","Samotné smazání vyhrává soutěž o popisek pro svou ironii."],["Vybrat si oblíbený příspěvek a sám ho sdílet","Na jedno odpoledne jste v obraze. Sklízí to překvapivě dobrý ohlas."],["Žalovat platformu za emoční újmu","Soudkyně by se prý sama nejraději do soutěže přihlásila."],["Vyhlásit peněžní odměnu za vítězný popisek","Počet příspěvků vzroste o čtyři sta procent. Kvalita ne."]]},"p-war-1":{"t":"Signál z Volkovie","x":"Radarová stanice u hranice v úterý večer něco zachytila. Výbuch, test rakety, nebo ohňostroj k narozeninám generála Oseie, nikdo si není jistý. Náčelníci štábů chtějí rozhodnutí, než jim vychladne káva.","c":[["Nazvat to válečným aktem a mobilizovat flotilu","Flotila vyplouvá. Důkazy nikoli."],["Nařídit skutečné vyšetření, než cokoli oznámíte","Nic se nestalo. Všichni jsou naštvaní, že to trvalo tak dlouho zjistit."],["Uniknout informaci, že šlo jistojistě o útok, fakta se doplní později","Únik se stává příběhem. Příběh se stává válkou."],["Svalit to na zbloudilý meteorologický balon a žádat, aby se národu omluvil úřad ČHMÚ","Úřad se omluví. Meteorologové si potichu aktualizují životopisy."]]},"p-war-2":{"t":"Generál chce přehlídku","x":"Generál Halbrook chce tanky na hlavní třídě, „aby svět připomněl, že tanky ještě máme“. Ministerstvo obrany odhaduje, že přehlídka bude dražší než několik malých válek.","c":[["Schválit celou přehlídku, tanky a vše ostatní","Tanky dorazí. Stejně tak účet za výtluky."],["Nařídit místo toho jen skromný přelet, ušetřit peníze","Proletí tři letadla. Nikdo netleská."],["Přehlídku zdvojnásobit, přidat raketu ve tvaru vaší tváře","Vůz s raketou zabodoval přesně u jedné cílové skupiny: u vás."],["Nechat generála Halbrooka jet na koni místo v tanku","Kůň krade titulky. Generál Halbrook žádá pro koně povýšení."]]},"p-war-3":{"t":"Dron čeká","x":"Dron má na mušce cíl někde poblíž hranice Osei-Volkov. Rozvědka je „docela přesvědčená“, že jde o konvoj se zbraněmi, a „o něco méně přesvědčená“, že nejde o svatbu.","c":[["Dát rozkaz, lepší to jistit","Konvoj je zničen. Prý i dort."],["Počkat se střelbou, dokud si rozvědka nebude jistá","Konvoj se ukáže jako svatba. Nevěsta posílá ostře formulovaný dopis."],["Udeřit hned a udeřit znovu pro jistotu","Dva útoky, jeden konvoj, žádné zbraně nakonec nenalezeny."],["Rozhodnutí přenechat hodu mincí, vysílanému živě","Mince padne na hlavu. Váleční etici hromadně podávají výpověď."]]},"p-war-4":{"t":"Úterní puč generála Oseie","x":"Generál Osei obsadil palác ve spřátelené zemi, odvolává se na „vibrace“ a přeje si být oslovován Nejvyšší velitel. Washington musí rozhodnout, jestli ho uzná.","c":[["Ihned Oseie uznat, působí schopně","Osei posílá dárkový koš s ovocem. Demokracie posílá své politování."],["Odsoudit puč, podpořit svrženou vládu","Prohlášení je vydáno. Oseie to nechává klidným a upřímně stále u moci."],["Potichu Oseie vyzbrojit výměnou za přístup k základně","Získáte základnu. Osei získá soukromou armádu. Dějiny získají poznámku pod čarou."],["Pozvat Oseie do Camp Davidu probrat to při golfu","Osei podvádí v golfu a vy se oba nějak shodnete, že to je v pořádku."]]},"p-war-5":{"t":"Šest turistů a jedna stížnost","x":"Šest amerických turistů zajala v horách milice, která tvrdí, že jí osobně dlužíte omluvu za něco, co váš dědeček možná řekl v roce 1961.","c":[["Poslat speciální jednotky, žádná vyjednávání","Turisté jsou zachráněni. Dvě kozy nikoli."],["Tiše vyjednávat přes zadní kanály","Turisté se vrátí domů. Nikdo neuvidí ty skvělé záběry ze záchrany."],["Veřejně vyhrožovat celé zemi milice","Milice se zakope. Velvyslanec té země si vyhrabe právníka."],["Omluvit se jejich jménem za cokoli, co dědeček řekl","Ani oni nevědí, co řekl. Omluva se přesto vysílá."]]},"p-war-6":{"t":"Nejvyšší vůdce chce koupit stíhačky","x":"Nejvyšší vůdce země pod šesti různými sankčními režimy chce koupit stíhačky, hotově předem, žádné otázky, „na obranné pozorování ptáků“.","c":[["Schválit prodej, hotovost je hotovost","Stíhačky odlétají. Tvrzení o pozorování ptáků neobstojí ani týden."],["Zablokovat prodej a předat věc sankčnímu úřadu","Prodej je zablokován. Nejvyšší vůdce najde jiného dodavatele do čtvrtka."],["Prodat stíhačky a přidat výcvikový balíček","Výcvikový balíček obsahuje věci, které nikdo nechtěl mít písemně."],["Prodat mu vyřazené dvouplošníky a nazvat to slevou","Nejvyšší vůdce zuří. Dvouplošníky jsou, technicky vzato, dodány."]]},"p-war-7":{"t":"Výstřely u plotu","x":"Vojáci na obou stranách sporné hranice si přes noc vyměnili palbu kvůli něčemu, co zpráva popisuje jen jako „nedorozumění kolem kozy“.","c":[["Posílit hranici o tři další divize","Hranice je zajištěna. Osud kozy zůstává neznámý."],["Otevřít horkou linku s druhou stranou k uklidnění situace","Linka funguje. Obě strany se shodnou, že to začala koza."],["Nařídit symbolickou demonstraci síly, tanky k plotu","Tanky dorazí. Koza, nerušeně, se dál pase mezi nimi."],["Nabídnout se, že spor o kozu osobně zprostředkujete","Zprostředkujete. Koza dostane společnou péči."]]},"p-war-8":{"t":"Síť zablikala","x":"Polovina elektrické sítě ve třech státech byla jedenáct minut ve tmě. Kybernetická bezpečnost tvrdí, že to může být Volkovia, může to být teenager ve sklepě, může to být obojí.","c":[["Veřejně obvinit Volkovii a připravit odvetné údery","Volkovia vše popírá. Teenager drží nízký profil."],["Zahájit forenzní vyšetřování, než kohokoli obviníte","Teenager je nalezen. Dostane zaracha, ne vydání."],["Odvetit vlastním kybernetickým útokem, bez potřeby důkazů","Protiúder zasáhne špatnou síť. V Ohiu."],["Oznámit, že výpadek byl od začátku plánované cvičení","Nikdo tomu nevěří. Lež přesto nějak působí uklidňujícím dojmem."]]},"p-war-9":{"t":"Volkov testuje raketu, špatně","x":"Prezident Volkov testoval novou raketu, která podle satelitních záběrů zavrávorala, dvakrát se zatočila a dopadla na pšeničné pole ve vlastní zemi. Státní média to nazývají triumfem.","c":[["Odpovědět ještě větším testem, ten samý týden","Vaše raketa se taky zavrtí. Nikdo o tom neinformuje."],["Tiše selhání zaznamenat a nic nedělat","Výnos pšenice na Volkovově poli stoupá o devět procent díky hnojivu."],["Volkova veřejně zesměšnit a hrozit preventivním úderem","Ponížený Volkov slibuje druhý test. Ještě větší pšeničné pole."],["Poslat Volkovovi kondolenční kartu kvůli pšeničnému poli","Volkov není pobavený. Karta získá víc pozornosti než samotná raketa."]]},"p-war-10":{"t":"Mírová dohoda, kterou nikdo nechtěl pokazit","x":"Vaši vyjednavači potichu dokončili mírovou dohodu, která ukončuje desetiletý konflikt. Bohužel je to nudná televize.","c":[["Oznámit, že živě v éteru přidáte „tvrdší“ podmínky, ať se dohoda sesype","Dohoda se na živém vysílání zhroutí. Sledovanost je, uznejme, silná."],["Nechat vyjednavače dohodu potichu podepsat a slavit výhru","Válka končí. Přenos sleduje devět diváků, všichni s úlevou."],["Podpis zadržet, dokud tam nepřidají vaše jméno","Dohoda je po vás přejmenována. Druhá strana všechno znovu zvažuje."],["Proměnit podpisový ceremoniál v soutěžní show","Rebelové vyhrají topinkovač. Mír, nějak, ze vzdoru vydrží."]]},"p-war-11":{"t":"Přeběhlík žádá o azyl","x":"Vysoký úředník z vlády Nejvyššího vůdce se objevil na velvyslanectví s flash diskem a žádostí o pěkný dům na Floridě.","c":[["Udělit azyl a ihned ho předvést v televizi","Nejvyšší vůdce zuří. Přeběhlík si tu pozornost náramně užívá."],["Nejdřív ho v klidu vyslechnout řádnými kanály","Flash disk obsahuje hlavně dovolenkové fotky a jednu užitečnou mapu."],["Prozradit jeho totožnost, aby to zatlačilo na jeho starou vládu","Tlak funguje. Stejně tak skoro i pokus o atentát."],["Vyměnit ho za dvě pandy, bez otázek","Pandy dorazí. Přeběhlík je hluboce uražen tímto směnným kurzem."]]},"p-war-12":{"t":"Lodě v úžině","x":"Volkovský torpédoborec a americká letadlová skupina jsou v úžině dost blízko na to, aby si vyměnily ostře formulované vlajkové signály. Ani jedna strana nechce mrknout první.","c":[["Nařídit letadlové skupině držet pozici, se zbraněmi připravenými","Nikdo nemrkne. Všem alarmujícím tempem klesá stav paliva."],["Přesměrovat letadlovou skupinu, aby se konfrontaci vyhnula","Lodě proplují bezpečně. Admirál je potichu zklamaný."],["Nařídit ostrostřeleckou přehlídku přímo tam, pro zdůraznění","Přehlídka je velmi hlasitá a velmi blízko. Volkov posílá formální stížnost, ještě hlasitější."],["Vyzvat volkovského kapitána na partii šachů po rádiu","Vyhrajete. Kapitán tvrdí, že mu dámu zablokoval radar."]]},"p-war-13":{"t":"Povstání potřebuje kapesné","x":"Povstalecká koalice bojující proti vládě Nejvyššího vůdce chce zbraně, hotovost a „morální podporu“, v tomto pořadí.","c":[["Financovat je naplno, tajně, bez dohledu","Povstání postupuje. Stejně tak papírová stopa."],["Nabídnout jen humanitární pomoc, žádné zbraně","Povstalci jsou vděční za deky a nepříliš nadšení strategií."],["Financovat je i obě jejich rivalské povstalecké frakce, pro jistotu","Tři frakce teď tráví víc času bojem mezi sebou než proti vládě."],["Financovat je pomocí televizního sbírkového maratonu","Maraton vybere miliony. Celebritní moderátor se teď prohlašuje za experta na zahraniční politiku."]]},"p-war-14":{"t":"Skromný návrh ze sklepa","x":"Poradce, velmi potichu, se zavřenými dveřmi, navrhuje, že by se dal zařídit „menší incident“, který by ospravedlnil válku, kterou už stejně všichni chtějí.","c":[["Schválit to, s odepíratelností, mimo záznam","Incident se stane. Nakonec i vyšetřování."],["Poradce vyhodit a návrh nahlásit","Poradce je pryč. Válka, prozatím, čeká na skutečný důvod."],["Schválit to a rozšířit plán na dva incidenty, pro jistotu","Redundance dosažena. Stejně tak nakonec i federální vyšetřování."],["Nafingovat incident pomocí herců a pronajatého tanku","Herci jsou přesvědčiví. Půjčovna chce tank zpátky."]]},"p-war-15":{"t":"Summit, který byste raději vynechal","x":"Výroční summit aliance je tento víkend. Účast znamená společné fotky a sdílená komuniké. Vynechání znamená, že o vás všichni mluví stejně, jen míň zdvořile.","c":[["Vynechat ho a uspořádat místo toho shromáždění, větší dav","Aliance si toho všimne. Dav na shromáždění je to jedno."],["Zúčastnit se, podepsat komuniké, usmát se na fotku","Fotka je nevýrazná. Aliance drží, sotva si vás všimne."],["Zúčastnit se a odmítnout cokoli podepsat, z principu, nespecifikovaného","Fotka je trapná. Princip nikdy nikdo nepojmenuje."],["Poslat na vaše místo lepenkovou figurínu","S figurínou zachází diplomacie s větším respektem, než se čekalo."]]},"p-war-16":{"t":"Vesmírné síly chtějí vlajku na Měsíci","x":"Nově zřízené Vesmírné síly chtějí na povrch Měsíce zapíchnout vlajku s vaší tváří, „kvůli odstrašení“.","c":[["Financovat misi naplno, start příští čtvrtletí","Vlajka dosáhne oběžné dráhy. Tvář je podle NASA „rozpoznatelná jen z nízké oběžné dráhy“."],["Přesměrovat rozpočet na skutečnou výzkumnou misi","Výzkumná mise tiše odstartuje. Vaši tvář nikde nikdo nevidí."],["Přidat i laser, odstrašení potřebuje laser","Laser funguje bez problémů. Sedmnáct zemí přesto podá formální protest."],["Financovat misi s vlajkou crowdfundingem","Crowdfunding se povede. Přispěvatelé dostanou certifikát a mírnou lítost."]]},"p-war-17":{"t":"Práva na pojmenování","x":"Váš tiskový tým navrhuje probíhající zahraniční konflikt oficiálně přejmenovat po vás, „kvůli odkazu“.","c":[["Přejmenování ihned schválit, s plnou ceremonií","Válka teď nese vaše jméno. Stejně tak každá zpráva o obětech."],["Odmítnout, války by neměly nést vaše jméno","Válka si podrží staré, nudné jméno. Dějiny zůstávají stejně nedotčené."],["Přejmenovat ji a nechat razit pamětní minci","Mince je vyražena. Válka pokračuje, teď s merchem."],["Nechat o jméně hlasovat veřejnost","Veřejnost hlasuje pro něco netisknutelného. Potichu se to zamítne."]]},"p-war-18":{"t":"Ten velmi velký tlačítko","x":"Asistenti nainstalovali na váš stůl velké červené tlačítko, „kvůli morálce“, jak tvrdí, ačkoli je napojené na něco, co dřív vyžadovalo tři klíče a generálův podpis.","c":[["Vyhrožovat, že ho v televizi stisknete, ať se uvidí, co se stane","Nikdo nic nestiskne. Všem se spí trochu hůř."],["Nechat tlačítko odstranit a obnovit původní protokol","Tlačítko je pryč. Stůl vypadá podivně prázdný."],["Stisknout ho napůl, „jen na zkoušku“, před novináři","Naštěstí bylo odpojené. Záběry nikoho neuklidňují."],["Nahradit ho tlačítkem, které jen objedná pizzu","Pizza dorazí. Morálka, proti všem očekáváním, opravdu stoupne."]]},"p-war-19":{"t":"Muž v moc pěkném obleku","x":"Soukromý vojenský dodavatel nabízí, že vyřeší „celou tu situaci s Volkovem“ za paušální poplatek, bez dohledu Kongresu, bez papírování, bez otázek.","c":[["Najmout dodavatele, hotově předem, potichu","Situace je vyřešena. Nikdo přesně neví jak."],["Odmítnout a věc předat ministerstvu obrany","Ministerstvo postupuje pomalu. Muž v obleku odejde jinam se svým podnikáním."],["Najmout dodavatele a dát mu ještě druhou, nesouvisející zakázku","Obě zakázky jsou vyřízeny. Ani jedna se neobjeví v žádném rozpočtu."],["Vyjednat mu nižší odměnu jeho vlastními taktikami","Respektuje váš um. Příště si taky zdvojnásobí sazbu."]]},"p-war-20":{"t":"Ostrov na prodej","x":"Malý tichomořský stát je ochotný prodat strategicky umístěný ostrov pro námořní základnu, pokud bude cena správná a papíry zůstanou vágní.","c":[["Koupit ho rovnou, oznámit novou základnu do pátku","Základna je postavena. Místní obyvatelé nejsou, jak se ukazuje, konzultováni."],["Vyjednat pronájem místo přímé koupě","Nájemní smlouva je podepsána. Všichni uznávají, že jde o tu nudnou správnou volbu."],["Koupit ho i tři sousední ostrovy, pro jistotu","Teď vlastníte čtyři ostrovy a rychle se zhoršující vztahy s celým regionem."],["Zkusit ho vyměnit za přebytečný trajekt z Guamu","Nabídka je odmítnuta. Kapitán trajektu si oddechne."]]},"p-war-21":{"t":"Ponorka přestala volat","x":"Americká ponorka poblíž volkovských vod zmeškala poslední dvě plánovaná hlášení. Může jít o poruchu spojení. Může jít o něco horšího. Nikdo to nechce vyslovit nahlas.","c":[["Mobilizovat flotilu a okamžitě žádat od Volkova odpovědi","Flotila se mobilizuje. Ponorka měla, jak se ukáže, jen mrtvou vysílačku."],["Potichu vyslat záchranné plavidlo a počkat","Ponorka se vynoří podle plánu o tři hodiny později. Tisk se to nedozví."],["Veřejně oznámit, že americká ponorka možná zmizela, pravděpodobně vyprovokována","Světové trhy panikaří šest hodin. Vysílačka byla, znovu, prostě mrtvá."],["Poslat ponorce ostře formulovaný fax","Ponorky nemají faxy. Toto se teď stává obecně známým faktem."]]},"p-war-22":{"t":"Generál nahlas odstupuje","x":"Generál Halbrook rezignoval na protest proti „směřování zahraniční politiky této vlády“ a dává o tom rozhovory, což je novinka.","c":[["Veřejně napadnout Halbrookovu povahu v televizi","Halbrook odpoví smlouvou na knihu. Smlouva odpoví prodejností."],["Rezignaci přijmout s grácií, popřát mu vše dobré","Halbrook odchází potichu. Novináři ho zklamaně shledávají také velkorysým."],["Ze vzteku ho připravit o penzi","Penze je pryč. Stejně tak jakákoli zbývající přízeň celého sboru důstojníků."],["Nabídnout Halbrookovi talk show, aby měl co dělat","Halbrook přijme. Jeho sledovanost, k vzteku, poráží tu vaši."]]},"p-street-1":{"t":"Tábor Ústava","x":"Protestující obsadili náměstí Svobody v centru Columbusu už šest dní, přejmenovali ho na Tábor Ústava a jmenovali čestným starostou mývala Steva. Steve má lepší preference než skutečný starosta.","c":[["Poslat tam zásahovku","Tábor je vyklizen do svítání. Steve je propuštěn bez obvinění, což je víc, než se dá říct o všech ostatních."],["Rozumný krok","Místo štítů pošlete přenosné toalety a příběh se najednou točí kolem vaší překvapivé slušnosti."],["Horší nápad","Náměstí necháte srovnat buldozery ve tři ráno. Tábor Ústava se o dva bloky dál znovu otevírá jako Tábor Ústava Dva."],["Rovnou náměstí odkoupit","Koupíte náměstí Svobody za jedenáct milionů dolarů a přejmenujete ho na Národní muzeum hraček. Návštěvnost zklamává."]]},"p-street-2":{"t":"Všichni jsou venku","x":"Dvanáct odborů vyhlašuje koordinovanou generální stávku. Hromadí se odpadky, vlaky stojí a barista z Toleda se přes noc stává lidovým hrdinou za odmítnutí uvařit vaší tiskové mluvčí ovesné latté.","c":[["Prohlásit stávku za nezákonnou","Organizátoři jsou zatčeni do večera. Odpadky zůstávají přesně tam, kde byly."],["Rozumný krok","Zahájíte vyjednávání a nabídnete skromné ústupky. Vlaky, neochotně, znovu jezdí."],["Přivézt autobusy se stávkokazy","Stávkokazi nemohou najít depo, pak se nemohou najít mezi sebou, pak jdou domů."],["Vyhlásit náhle celostátní svátek","Oznámíte Den uznání pracujících, s okamžitou platností, takže stávka teď vypadá, jako by si všichni prostě vzali volno."]]},"p-street-3":{"t":"Incident s bazénkem","x":"Záznam z tělové kamery, na kterém policista se značnou silou zabavuje dítěti nafukovací bazének za „blokování hydrantu“, má čtyřicet milionů zhlédnutí ještě před vaším ranním briefingem.","c":[["Postavit se za policistu","Kritiky nazvete změkčilými vůči zločinu. Bazének zůstává nekonečně dlouho v úschově důkazů."],["Rozumný krok","Nařídíte nezávislé prošetření a veřejnou omluvu. Dítě dostane bazének zpátky, lehce vyfouknutý."],["Povýšit policistu naživo v televizi","Ceremonie má hojnou účast, přesně toho publika, které jste pro obrázky nechtěl."],["Poslat dítěti podepsaný bazének","Pošlete podepsaný nafukovací bazének s lístkem „bez zášti“. Internet se neuklidní."]]},"p-street-4":{"t":"Shromáždění na vaši počest","x":"Milice nazvaná Minutemen Redux plánuje pochod s pochodněmi „na podporu prezidenta“, s maskáčovým oblečením, energetickými nápoji a nafukovacím hradem ve tvaru orla.","c":[["Nechat je pochodovat, bez omezení","Nafukovací orel uprostřed akce splaskne. Fotky z jeho pádu přežijí samotné shromáždění."],["Rozumný krok","Potichu je požádáte, ať to zruší, a poděkujete jim za podporu jinak. Většina uposlechne, s mumláním."],["Poslat oficiální čestnou stráž","Fotky vojáků vedle nadšenců v maskáčích běží ráno na každé titulní straně."],["Poslat podepsaný chladicí box energetických nápojů","Dar je vřele přijat. Několik účastníků tři dny nespí."]]},"p-street-5":{"t":"Generál padá","x":"Dav strhne sochu dávno zesnulého generála před starou soudní budovou, odtáhne ji čtyři bloky a hodí do fontány, kde teď vypadá, jako by plavala.","c":[["Zatknout každého na záznamu","Čtyřicet zatčení. Socha zůstává ve fontáně a plave si znak."],["Rozumný krok","Potichu souhlasíte, že socha může být přemístěna do muzea. Fontána je vypuštěna a vyčištěna."],["Nařídit ji postavit dvakrát větší","Nová socha je o půlnoci dovezena jeřábem pod ozbrojenou stráží. Do týdne je znovu stržena."],["Prohlásit fontánu za historickou plaveckou expozici","Turisté teď platí pět dolarů, aby viděli generála uprostřed kraulu. On nic nenamítá."]]},"p-street-6":{"t":"Volání po zákazu vycházení","x":"Starostka Delgado chce po třech nocích nepokojů celoměstský zákaz vycházení. Vaši poradci jsou rozdělení mezi „ano, zjevně“ a „přesně takhle vznikne mnohem větší protest“.","c":[["Zavést zákaz vycházení, tvrdě","Zákaz vydrží jednu noc, než deset tisíc lidí usoudí, že devátá hodina je jen doporučení."],["Rozumný krok","Zákaz odmítnete a necháte město, ať si poradí samo. Většinou se to podaří."],["Zákaz plus kontrolní stanoviště na každém bloku","Doprava se celoměstsky zastaví. Stejně tak i jakékoli sympatie k vám."],["Zákaz vycházení, ale jen pro holuby","Vyhláška o zákazu vycházení holubů je podle právníků naprosto nevymahatelná a hlavně vtip, který zabírá."]]},"p-street-7":{"t":"Doklady, prosím","x":"Noční razie cílí na nedokumentované pracovníky ve skladu zeleniny a zajmou i několik skutečných občanů, kteří si prostě zapomněli peněženku, včetně jednoho bývalého soudce.","c":[["Rozšířit razie","Bývalý soudce je propuštěn s omluvným dopisem. Sklad už nikdy neotevře."],["Rozumný krok","Razie pozastavíte do prošetření. Zelenina, bohužel, dál plánovaně shnívá."],["Provést razii i v soudní budově, pro jistotu","Několik soudců je čtyři hodiny zadrženo, než někdo zkontroluje jejich odznaky."],["Nabídnout soudci formální omluvný koš od státu","Koš obsahuje ovoce pocházející přímo z toho vyplundrovaného skladu."]]},"p-street-8":{"t":"Kleknout, nebo se postavit","x":"Půlka stadionu kleká při hymně na mistrovském zápase, zatímco druhá půlka bučí tak hlasitě, že je to slyšet v přenosu. Váš kancléř chce prohlášení ještě před poločasem.","c":[["Žádat, aby liga viníky potrestala","Liga odmítá s odkazem na smlouvu, kterou jste nečetl. Dohledáte si ji, je neprůstřelná."],["Rozumný krok","Neřeknete vůbec nic, což se ukáže jako nejméně mediálně zajímavá možnost ze všech."],["Vyhrožovat vysílacím právům ligy","Tři televizní sítě potichu zvažují přesun budoucích zápasů do zahraničí."],["Zúčastnit se příštího zápasu a ironicky si sám kleknout","Nikdo se neshodne, co vaše klečení znamenalo, včetně vás."]]},"p-street-9":{"t":"Karavana, která nebyla","x":"Kabelová televize hlásí „masivní karavanu“ blížící se k jižní hranici. Po bližším ohledání jde o mikrobus mládežnické skupiny z kostela na výletě, ale panika už je na vzestupu.","c":[["Okamžitě nasadit na hranici vojáky","Tři tisíce vojáků vítají kostelní mikrobus a velmi zmateného mládežnického faráře."],["Rozumný krok","Veřejně uvedete fakta na pravou míru. Panika splaskne, stejně jako celý mediální cyklus."],["Přesto vyhlásit formální hraniční mimořádný stav","Nouzový stav přežije mikrobus o několik měsíců."],["Pozvat mládežnickou skupinu do Bílého domu","Sedmnáct teenagerů prohlídne Růžovou zahradu. Dva z nich kladou překvapivě dobré otázky."]]},"p-street-10":{"t":"Kampus nechce ustoupit","x":"Studenti na třech velkých univerzitách obsazují budovy vedení a vydávají seznam požadavků, který kromě reformy školného obsahuje i „lepší svačiny v automatech“.","c":[["Poslat federální agenty na vyklizení kampusů","Okupace končí. Do semestru s ní končí i většina darů od absolventů."],["Rozumný krok","Necháte to na univerzitách a potichu poznamenáte, že požadavek na automaty má opravdu něco do sebe."],["Vyhrožovat odebráním veškerého federálního výzkumného financování","Několik děkanů zpanikaří po telefonu. Několik dalších volá, že už stejně rezignovali."],["Doplnit automaty sám","Svačiny jsou výborné. Ostatní požadavky zůstávají neřešeny."]]},"p-street-11":{"t":"Osmnáct kol vzteku","x":"Kamioňáci blokují dálnici ve třech státech na protest proti nové palivové dani, parkují, troubí a na krajnici grilují ohromné množství klobás.","c":[["Nařídit dálnici vyklidit silou","Odtahovky přijíždí odtahovat odtahovky. Klobásy jsou zabaveny jako důkaz."],["Rozumný krok","Palivovou daň pozastavíte do přezkoumání. Dálnice se do večera otevře, provoněná klobásami."],["Pověřit státní policii, ať zabaví soupravy","Zabavit čtyři sta kamionů vyžaduje odstavnou plochu, na které je momentálně čtyři sta kamionů."],["Poslat jako mírové gesto bednu hořčice","Kamioňáci hořčici přijmou a z principu zůstanou zaparkovaní dál."]]},"p-street-12":{"t":"Pomník sám sobě","x":"Chcete na National Mall dvě stě stop vysokou sochu sebe sama. Inženýři říkají, že je to konstrukčně možné. Všichni ostatní říkají, že je to hrozný nápad.","c":[["Urychlit výstavbu, ignorovat námitky","Socha vyroste podle plánu. Holubi si nárokují hlavu do týdne."],["Rozumný krok","Potichu nápad odložíte a necháte ho zemřít ve výboru, kam tyhle věci patří."],["Udělat ji tři sta stop vysokou, ze zlata","Zlaté obložení je odcizeno šrotovníky ještě před slavnostním přestřižením pásky."],["Postavit ji, ale nechat občany hlasovat o póze","Vítězná póza, zvolená veřejným hlasováním, je vy na losovi. Výstavba pokračuje."]]},"p-street-13":{"t":"Povolání Národní gardy","x":"Nepokoje ve čtyřech městech vedou vaše generály k doporučení plného povolání Národní gardy. Je to typ rozhodnutí, které skvěle vypadá na briefingu a hrozně na titulní straně.","c":[["Plné povolání, do všech čtyř měst","Nasadí se dvanáct tisíc vojáků. Fotky vojáků na hlavních třídách běží celý týden."],["Rozumný krok","Spolehnete se na místní policii a komunitní vůdce. Je to pomalejší, ale funguje to."],["Povolat gardu a zároveň zfederalizovat místní policii","Místní šéfové nesou převzetí pravomocí těžce. Dva rezignují veřejně a zdlouhavě, přímo před kamerou."],["Nasadit gardu, ale jen na úklid","Vojáci týden sbírají odpadky. Podivně to všechny uklidní."]]},"p-street-14":{"t":"Když protiprotest protestuje proti protiprotestu","x":"Shromáždění, které jste sám zorganizoval na svou podporu, přitáhne protiprotest, ten přitáhne proti-protiprotest, a teď si nikdo na místě nepamatuje, na které straně vlastně začal.","c":[["Poslat policii chránit jen vaše příznivce","Optika jednostranné ochrany přežije shromáždění o celé týdny v každém zpravodajském cyklu."],["Rozumný krok","Vyzvete ke klidu na všech stranách a myslíte to vážně, což naprosto všechny zmate."],["Poslat policii zatknout jen protiprotestující","Vazební příjem třídí lidi podle toho, jakou drželi ceduli, což prostě není zákonná kategorie."],["Shromáždění zrušit, svalit to na kolizi termínů","Všichni jdou domů zmatení, ale, důležité, nikdo se nepere."]]},"p-street-15":{"t":"Starostka Delgado říká ne","x":"Starostka Delgado veřejně odmítá vymáhat váš nejnovější pouliční příkaz, stojí na schodech soudní budovy a čte megafonem nahlas Ústavu velmi zaujatému davu.","c":[["Odvolat ji z funkce federálním nařízením","Odvolávací příkaz spustí soudní spor, který přežije celé vaše funkční období, možná i vás samotného."],["Rozumný krok","Příkaz potichu zrušíte, než abyste bojoval se starostkou vyzbrojenou megafonem a Ústavou."],["Odříznout jejímu městu veškeré federální financování","Silnice ve městě zůstávají neopravené. Preference starostky Delgado nikoli."],["Vyzvat ji na veřejnou debatu na schodech soudní budovy","Okamžitě souhlasí a přinese si kartičky s poznámkami. Vy jste si kartičky nepřinesl."]]},"p-street-16":{"t":"Žena s cedulí","x":"Jedna žena tiše stojící u trasy vaší kolony s ručně psanou cedulí se stává nejsdílenějším obrázkem měsíce, nějak virálnější než cokoli, co vyprodukoval váš tým.","c":[["Nechat ji z trasy odstranit","Odstranění jedné tiché ženy s cedulí jí zajistí zhruba čtyřicetkrát větší publikum, než měla původně."],["Rozumný krok","Cestou kolem ní zamáváte. Je to malé gesto a poněkud funguje."],["Nechat tým vyprodukovat konkurenční virální moment","Konkurenční moment je široce zesměšněn jako nastrojený, protože skutečně nastrojený byl."],["Pozvat ji na kávu","Přijme, cedulí se po celou dobu nevzdá, a stává se druhým nejsdílenějším obrázkem měsíce."]]},"p-street-17":{"t":"Pochod místních","x":"Odborový pochod se vine hlavním městem a žádá vyšší mzdy, lepší pracovní dobu a nevysvětlitelně také státní svátek na jarní rovnodennost.","c":[["Nařídit pochod rozehnat","Pochod se přeskupí o dva bloky dál, teď s novou stížností a větším davem."],["Rozumný krok","Setkáte se s odborovými vůdci a nabídnete skutečné ústupky. Svátek rovnodennosti zůstává na seznamu přání."],["Nařídit pochod rozehnat jízdní policií","Koně a pochodující se moc nesnesou. Ani záznam z toho nakonec nevyšel dobře."],["Udělit svátek rovnodennosti, nic víc","Zaměstnanci dostanou jarní svátek a žádné přidání. Výměnu si všimnou okamžitě."]]},"p-street-18":{"t":"Zatrub, pokud miluješ pořádek","x":"„Vlastenecká kolona“ pickupů a vlajek objíždí hlavní město už třetí den v kuse, blokuje dopravu na vaši podporu a čím dál víc i vám samotnému v cestě.","c":[["Nechat je policejně doprovázet donekonečna","Rozpočet na doprovod nabobtná. Kolona nejeví žádné známky konce ani odjezdu."],["Rozumný krok","Veřejně jim poděkujete a požádáte je, ať se vrátí domů. Většina to nakonec udělá."],["Nařídit koloně eskalovat směrem do centra","Zácpa v centru dosahuje nového osobního rekordu. Doručovatelé zuří, na kameru."],["Udělit koloně ceremoniální povolení k pochodu","Povolení dělá zácpu oficiální a nějak i legální."]]},"p-street-19":{"t":"Guvernérka Frostová říká rozhodně ne","x":"Guvernérka Frostová odmítá váš příkaz přijmout ve svém státě federální jednotky, odvolává se na svrchovanost státu, několik soudních precedentů a tón, který napovídá, že na tenhle spor čekala.","c":[["Nasadit jednotky navzdory jejím námitkám","Nasazení okamžitě spustí soudní spor a velmi citovatelnou tiskovou konferenci od Frostové."],["Rozumný krok","Ustoupíte a necháte to na státu. Frostová vám nečekaně veřejně poděkuje."],["Vyhrožovat odříznutím veškerého federálního financování jejímu státu","Frostová vaše vydírání veřejně v televizi zavolá. Bylo to, fakticky, hlavně blaf."],["Vyzvat Frostovou, ať to vyřeší při večeři se steakem","Večeře probíhá zdvořile. Otázka jednotek zůstává i po dezertu nevyřešena."]]},"p-street-20":{"t":"Sezení u bran","x":"Koalice duchovních usedne před palácovou bránu, na směny zpívá hymny a odmítá odejít, dokud se s nimi nesejdete kvůli bytovému zákonu, který jste měsíce ignoroval.","c":[["Nechat je odstranit silou","Záběry duchovních odnášených uprostřed hymnu jsou, taktikou, přesně tak zlé, jak to zní."],["Rozumný krok","Setkáte se s nimi do hodiny. Bytový zákon se konečně pohne z výboru."],["Nechat je zatknout za vniknutí na cizí pozemek","Kauci během chvíle složí konkurenční kongregace, čistě ze vzdoru vůči vaší vládě."],["Poslat jim skládací židle a limonádu","Sezení se stává citelně pohodlnějším a podstatně delším."]]},"p-street-21":{"t":"Popel na schodech","x":"Veterán pálí vlajku na schodech kapitolu na protest proti škrtům v dávkách, čímž vyvolá pobouření u někoho, potlesk u jiných a záplavu kamer od naprosto všech.","c":[["Tlačit na okamžité stíhání","Stíhání znovu otevírá desítky let starý spor o svobodu projevu, který nikdo tento týden nechtěl znovu otevírat."],["Rozumný krok","Veřejně obnovíte škrtnuté dávky a necháte právní otázku ležet. Funguje to."],["Prosazovat ústavní dodatek zakazující pálení vlajky","Snaha o dodatek uvázne ve výboru, jak se takovým snahám spolehlivě děje už desítky let."],["Poslat veteránovi náhradní vlajku, zabalenou jako dárek","Vlajku vděčně přijme a týden nato ji z principu znovu spálí."]]},"p-street-22":{"t":"Balada o Cooperu Vanceovi","x":"Folkový zpěvák Cooper Vance je zatčen za neautorizované provedení protestní písně před federální budovou a píseň kvůli tomu okamžitě ztrojnásobí popularitu.","c":[["Prosadit plné obvinění, dát příklad","Soud dá písni druhý refrén a Vanceovi smlouvu s nahrávací společností."],["Rozumný krok","Obvinění se potichu stáhne. Píseň, když už řekla své, podle plánu vypadne z žebříčků."],["Zakázat mu vystupovat kdekoli na federální půdě","Vance vystupuje z veslice těsně mimo federální jurisdikci, před velmi početným davem."],["Pozvat Coopera Vance, ať headlinuje vaše shromáždění","Přijme, a pak na vašem shromáždění zahraje přesně tu protestní píseň, slovo od slova."]]},"p-congress-1":{"t":"Zaujměte postoj (jakýkoli postoj)","x":"Předseda Sněmovny Grimsby potřebuje váš postoj k Zákonu o modernizaci zemědělství hodinu před hlasováním v plénu. Nečetl jste ho. Nikdo ho nečetl. Termínu to zjevně nevadí.","c":[["Prohlásit, že jste zákon napsal osobně, ručně, brkem","Tvrzení o brku špatně stárne, jakmile někdo najde pod textem font psacího stroje."],["Požádat o čtyřicet osm hodin, abyste to skutečně přečetl","Kongres respektuje řádnou obezřetnost. Vaše základna nerespektuje z tohohle vůbec nic."],["Veřejně se zavázat k postoji, který zrovna vede ve večerních průzkumech","Váš oficiální postoj se čtyřikrát změní ještě před samotným otevřením hlasování."],["Prohlásit zákon za „duchovně správný“ a detaily nechat na štábu","„Duchovně správné“ se stává trvalou kategorií ve vašich tiskových briefinzích."]]},"p-congress-2":{"t":"Zaslechnuté řeči o impeachmentu","x":"Poslankyně Vandersloot potichu sbírá podpisy pro vyšetřování impeachmentu. Potichu ve smyslu, že to řekla šesti novinářům a jedné velmi upovídané baristce.","c":[["Vyhrožovat, že proti každému signatáři postavíte vlastního vybraného protikandidáta","Tři signatáři okamžitě uhnou. Tři další svolají kvůli té hrozbě tiskovou konferenci."],["Plně spolupracovat a vydat každý požadovaný dokument","Vyšetřování vyhasne kvůli nedostatku skandálu, což se samo stává malým skandálem."],["Uniknout falešné dokumenty naznačující, že skutečnou zločinkyní je Vandersloot","Únik je vystopován rovnou do vaší kanceláře, k tiskárně, i s cartridge."],["Pozvat Vandersloot na celostátně vysílaný „přátelský summit“","Přijme. Vysílá se přesně proti finále mistrovství světa."]]},"p-congress-3":{"t":"Světla se za chvíli zhasnou","x":"Ministryně financí Boonová vás informuje, že financování vlády o půlnoci vyprší, pokud Kongres do té doby něco, cokoli, neschválí.","c":[["Nařídit úřadům, ať zůstanou otevřené stejně, a účtovat to na „vibrace“","Úřad pro odpovědnost vlády napíše ostře formulovanou zprávu. Necháte si ji zarámovat."],["Podepsat ošklivý dvoustranický nouzový zákon, kompromisy a vše","Nouzový zákon nikoho nenadchne. Nikoho ale ani nepošlou domů bez výplaty."],["Nechat vládu záměrně padnout do výluky a viníka jmenovat: předsedu Sněmovny","Federální zaměstnanci přijdou o výplatu. Vaše preference nějak ne."],["Platit „nezbytný“ personál z pokladny suvenýrového obchodu Bílého domu","V pokladně je čtyřicet jedna dolarů. Na moc dlouho to nevystačí."]]},"p-congress-4":{"t":"Trocha navíc pro prezidentovu položku","x":"V návrhu rozpočtu je, jak říká ministryně Boonová, místo přesně na jednu nestydatou položku navíc. Nějakou dobu už přemýšlíte o fontánách.","c":[["Nařídit vložení položky s fontánou a vyzvat kohokoli, ať se ji odváží škrtnout","Fontány se postaví. Novináři jim navždy říkají Marnivostní bazény."],["Škrtnout svůj oblíbený projekt a nechat peníze jít na skutečnou infrastrukturu","Opraví se pár mostů. Nikdo vám za to samozřejmě nepoděkuje."],["Vložit potichu ještě tři další položky, dokud jsou všichni rozptýlení tou první","Auditoři nakonec najdou všechny čtyři. O každé vyjde samostatná analýza."],["Přejmenovat položku s fontánou na „Vodní iniciativu pro veterány“","Žádný veterán o to nežádal. Několik veteránů je teď zcela oprávněně naštvaných."]]},"p-congress-5":{"t":"Senátor Fitch má na mysli číslo","x":"Senátor Fitch dodá rozhodující hlas pro novou přehradu ve svém státě výměnou za sochu sebe sama a skromné místo v kabinetu pro svého synovce.","c":[["Dát mu jen přehradu, bez sochy a synovce, a hrozit odebráním místa ve výboru","Fitch hlasuje ano, zuřivě, a od té doby vám v rozhovorech říká „ten pronajímatel“."],["Odmítnout celou dohodu a hlas získat poctivě","Zabere to o šest dní déle. Zákon nakonec projde bez úprav."],["Dát mu vše, včetně synovcova místa v kabinetu","Synovci je dvacet dva let a teď nějak dohlíží na jadernou regulaci."],["Nabídnout výměnou lamu místo sochy","Fitch lamu přijme. Nikdo zúčastněný na tomhle vyjednávání není hrdý."]]},"p-congress-6":{"t":"Senátor Alcott objevuje telefonní seznam","x":"Senátor Alcott už šest hodin nahlas čte na půdě Senátu telefonní seznam Delaware, aby zablokoval váš zákon. Momentálně je někde u písmene L.","c":[["Změnit pravidla sněmovny uprostřed obstrukce, ať zmlkne","Funguje to okamžitě. Také se to stává přesně tím pravidlem, které příště použijí proti vám."],["Nechat ho domluvit a hlasování vyhrát čistě, na základě obsahu","Domluví ve tři ráno. Zákon projde o čtyři minuty později."],["Poslat rivalizujícího senátora, ať obstruuje tu obstrukci","V sále teď dva dospělí muži zároveň nahlas čtou telefonní seznamy."],["Objednat pizzu pro celý sál, „pro udržení morálky“","Alcott sní pizzu a klidně čte dál. Špatně mířený úplatek."]]},"p-congress-7":{"t":"Chtějí zástupkyni šéfa štábu Pruettovou","x":"Sněmovní výbor předvolal vaší zástupkyni šéfa štábu, paní Pruettovou, která náhodou ví, kde jsou pohřbená mrtvá těla, finanční i jiná.","c":[["Uplatnit exekutivní výsadu a odvážit se je vyzvat, ať ji vymáhají","Vaši právníci ten argument milují. Hlasování o pohrdání Kongresem se přesto koná okamžitě."],["Nechat Pruettovou vypovídat a poctivě ji připravit","Vypovídá dobře. Je to nudná televize, což je přesně ten nejlepší možný výsledek."],["Poslat vypovídat místo Pruettové dvojnici","Dvojnice je odhalena během devíti minut kvůli vlastní zapomenuté jmenovce."],["Nechat Pruettovou předstírat náhlou, dramatickou, kariéru zachraňující ztrátu hlasu","Čtyřicetkrát zašeptá „bez komentáře“. Nějak horší, než kdyby mluvila."]]},"p-congress-8":{"t":"Soudkyně Kesslingová má minulost","x":"Vaše kandidátka na odvolací soud, soudkyně Kesslingová, kdysi ve vysokoškolských novinách napsala sloupek „Proč by úterky měly být nezákonné“. Senátoři jsou tím bohužel nesmírně zaujatí.","c":[["Protlačit nominaci výborem dřív, než si to kdokoli přečte dál","Kesslingová je potvrzena. Sloupek o úterku se na týdny stane titulkem kabelových zpráv."],["Nominaci stáhnout a vybrat místo ní někoho gloriózně nudného","Nový kandidát nikdy neměl názor na pracovní dny. Potvrzen jednomyslně."],["Nechat Kesslingovou veřejně obhajovat sloupek jako „vizionářský“","„Vizionářský“ je velkorysé slovo. Potvrzena přesto, ale těsně a hořce."],["Nominovat druhého, odváděcího soudce, aby se pobouření rozdělilo napůl","Kongres teď nemá rád dva soudce stejně silně. Svým způsobem efektivní."]]},"p-congress-9":{"t":"Přílepek, ke kterému se nikdo nehlásí","x":"Váš nezbytný zákon o infrastruktuře má na sobě přílepek rušící cla na dovoz lam, vložený neznámou osobou. Teď je to nějak problém úplně všech.","c":[["Prosadit celý zákon i s přílepkem a viníka svalit na lamí lobby","Zákon projde. Lamí dovozní lobby, jak se ukáže, skutečně existuje a je pořádně naštvaná."],["Přílepek vyškrtnout a schválit čistý infrastrukturní zákon","Silnice se opraví. Záhada lamího přílepku zůstane navždy nevyřešena."],["Přidat druhý přílepek, aby to odvedlo pozornost od prvního","Teď jsou tam dva záhadné přílepky a nula odpovědí o kterémkoli z nich."],["Veřejně oznámit, že jste vždy osobně miloval lamy","Tohle neuspokojí naprosto nikoho a zmate skoro každého."]]},"p-congress-10":{"t":"Incident kolem pošty Sylvie P. Renwickové","x":"Rutinní zákon přejmenovávající malou poštu po oblíbené místní knihovnici se nějak proměnil ve tříwelký boj v plénu kvůli nesouvisejícím, desítky let starým zášti.","c":[["Vynutit hlasování a veřejně zostudit každé „ne“ jako protiknihovnické","Zákon projde. Několik poslanců zůstává hluboce dotčeno tím, že je nazvali protiknihovnickými."],["Zprostředkovat tichou dohodu, aby to prošlo bez dalšího dramatu","Pošta dostane své jméno. Nikdo si toho nevšimne, což je přesně ta výhra."],["Připojit vlastní jméno k budově jako spolupočestněného","Teď je to Pošta Renwickové-a-Vás. Renwickova rodina zuří."],["Navrhnout přejmenování po vašem psovi místo toho","Pes má napříč politickým spektrem lepší preference než vy. Mírně znepokojivé."]]},"p-congress-11":{"t":"Senátorka Duchampová si najde svou chvíli","x":"Senátorka Duchampová přednese dvouhodinový projev v plénu, katalogizující každé vaše selhání, dokonale načasovaný na hlavní vysílací čas, i s plakáty na stojanech.","c":[["Vypnout jí uprostřed projevu mikrofon kvůli formalitě","Klip s umírajícím mikrofonem získá desetkrát víc zhlédnutí, než kolik by kdy získal samotný projev."],["Nechat ji domluvit a klidně reagovat fakty druhý den","Vaše odpověď je přesná a tragicky ji sleduje skoro nikdo."],["Naplánovat vlastní konkurenční projev přesně ve stejnou dobu","Celý večer se vysílá rozdělená obrazovka. Oba projevy prohrávají v souboji o sledovanost."],["Poslat jí koš ovoce „v duchu obousměrné spolupráce“","Zvedne koš ovoce v plénu jako Důkaz A něčeho."]]},"p-congress-12":{"t":"Poslankyně Okaforová mění tým","x":"Dosud spolehlivá spojenkyně, poslankyně Okaforová, oznamuje přechod na druhou stranu, s odkazem na „svědomí“, což pro nikoho zúčastněného není dobré znamení.","c":[["Veřejně jí sebrat výborová místa ještě před koncem tiskovky","Tiskovku přesto dokončí, teď s další stížností, kterou může citovat."],["Veřejně jí poděkovat za službu a popřát vše dobré","Elegantní a naprosto neúčinné v zabránění tomu, aby ji následovali další dva."],["Uniknout starý memoranda naznačující, že vždy byla tajně neloajální","Memorandum je pravé, a datované ještě před tím, než jste vůbec nastoupil do úřadu."],["Nabídnout její staré křeslo tomu, kdo proti ní povede nejtvrdší primárku","Teď máte místo tiché spojenkyně velmi hlasitého a velmi neprověřeného spojence."]]},"p-congress-13":{"t":"Předsedovi Tolliverovi naroste páteř","x":"Předseda výboru Tolliver, dřív spolehlivý jako nábytek, odmítá posunout váš zákon dál bez úprav. Zjevně si ho přečetl. Celý.","c":[["Vyhrožovat, že mu před celým výborem seberete kladívko","Okamžitě couvne. Také už vám nikdy nebude věřit a všem to řekne, proč."],["Přijmout jeho pozměňovací návrhy, protože byly stejně rozumné","Zákon je díky tomu lepší. Bolestně, trapně lepší."],["Obejít ho a protlačit zákon jiným výborem","Tolliver to v kabelových zprávách nazve pučem. Ne zcela se mýlí."],["Pozvat Tollivera do Camp Davidu „to probrat“ o víkendu","Vrátí se s dalšími pozměňovacími návrhy, ne méně. Camp David se pořádně vymstil."]]},"p-congress-14":{"t":"Velmi konkrétní most nikam konkrétně","x":"Významný dárce chce účelovou dotaci na most spojující jeho dvě soukromé nemovitosti. Poblíž není žádné město. Není tam žádná řeka. Je tam cesta pro golfový vozík.","c":[["Nařídit vložení a vyzvat auditora, ať to vůbec někdy najde","Auditor to najde asi za čtyři minuty. Na plánech je i jeho jméno."],["Dárci říct ne a přesměrovat peníze na skutečný most","Dárce je na dalším fundraiseru k vám chladný. Postaví se skutečný most."],["Schválit to a přidat druhý most pro jeho druhou cestu na golfový vozík","Teď existují dva mosty nikam. Místní zprávy tomu říkají „ten rozliv“."],["Přejmenovat to na „koridor odolnosti“ a doufat, že si toho nikdo nevšimne","Někdo si toho všimne okamžitě. Zůstává to nezaměnitelně cestou pro golfový vozík."]]},"p-congress-15":{"t":"Slyšení má špatné osvětlení a ještě horší otázky","x":"Jste předvolán svědčit před dozorčí výbor, podle toho, koho se zeptáte, ohledně naprosto všeho, co jste kdy udělal.","c":[["Na každou otázku odpovědět „to je utajené“, ať je to pravda, nebo ne","Polovina toho nikdy utajovaná nebyla. Teď je to titulek o lhaní pod přísahou."],["Odpovídat na vše upřímně a nechat věci dopadnout, jak dopadnou","Je to náročné odpoledne. Naštěstí je do večeře u konce."],["Přinést si připravený „gotcha“ moment na zesměšnění tazatelky","Gotcha moment se obrátí proti vám, když předloží stejný dokument, s dřívějším datem."],["Na každou otázku odpovědět lidovou historkou o dědečkově farmě","Nikdo se nedozví jediný fakt. Sledovanost, nepochopitelně, přesto stoupá."]]},"p-congress-16":{"t":"Malý dodatek o věčnosti","x":"Skupina spojenců potichu navrhuje zrušení funkčních limitů, jemně nazvané „modernizace kontinuity vedení“. Míní tím, že zůstanete, natrvalo.","c":[["Tvrdě přesvědčit hlasy a protlačit to výborem hned tento týden","Projde výborem. Fráze „věčný prezident“ se stane trendem a už nikdy nevymizí."],["Veřejně nápad odmítnout a požádat je, ať ho zcela stáhnou","Republika si tiše oddechne. Vaše základna si oddechne mnohem hlasitěji."],["Nechat to potichu postupovat, přitom vždy popírat, že jste o to žádal","Popření nevěří nikdo ani na vteřinu. Zákon přesto postupuje dál."],["Navrhnout „kompromis“ jen jednoho dalšího období, jako laskavost","Jedno další období se okamžitě stává novým základním požadavkem pro příští cyklus."]]},"p-congress-17":{"t":"Národní den uznání prezidenta","x":"Mladý kongresman, dychtivý po pozornosti, předkládá rezoluci vytvářející federální svátek na vaši počest. Alarmujícím způsobem už má i znělku.","c":[["Nahlas ho podpořit a tlačit na vedení, ať ho urychlí","Projde. Znělka hraje v každé federální budově dalších deset let."],["Požádat ho, ať to laskavě stáhne, tohle je trochu přehnané","Stáhne to, viditelně zklamaný. Znělka naštěstí umírá s ním."],["Navrhnout, aby svátek zahrnoval i povinné přehlídky","Účast na povinných přehlídkách je, mírně řečeno, řídká."],["Navrhnout přejmenování svátku na počest založení země, ale znělku si nechat","Technicky už to není svátek na vaši počest. Znělka nepochopitelně zůstává o vás."]]},"p-congress-18":{"t":"Ostře formulovaný kus papíru","x":"Opozice předkládá návrh na pokárání, převážně symbolický a naprosto ponižující, kvůli komentáři, který jste pronesl o účesu zahraničního vůdce.","c":[["Přesvědčit vlastní poslance, ať to jednomyslně zamítnou","Čistě neprojde na straně stran, což se samo stává vlastním typem titulku."],["Vydat upřímnou omluvu a nechat celý návrh potichu vyprchat","Omluva zabere. Komentář o účesu je do týdne zapomenut."],["Ještě přitvrdit komentář o účesu během rozpravy v plénu","Zahraniční vůdce veřejně odpoví komentářem o vaší vysoké čelo."],["Poslat zahraničnímu vůdci poukaz do kadeřnictví jako mírové gesto","Nějak je to přijato jako ještě těžší urážka, než ten původní komentář."]]},"p-congress-19":{"t":"Opozice opouští budovu","x":"Rozzuřena kvůli manipulaci s harmonogramem, opozice úplně opustí sál, čímž zabrání usnášeníschopnosti, a co hůř, odnese si i většinu kávy.","c":[["Poslat pořádkovou stráž, ať je fyzicky přivede zpět","Přivedou je. Okamžitě také kvůli tomu podávají žalobu."],["Hlasování odložit a poctivě vyjednat jejich návrat","Vrátí se za dva dny. Hlasování nakonec proběhne, čistě a se záznamem."],["Hlasovat i tak a tvrdit usnášeníschopnost kreativním počítáním","Kreativní počítání nepřežije ani první soudní podání."],["Objednat do sálu pizzu a živě streamovat, jak sám čekáte a jíte","Stream je podivně poutavý. Legislativně tím nevyřešíte vůbec nic."]]},"p-congress-20":{"t":"Devět set stran, nula čtenářů","x":"Souhrnný zákon má devět set stran, hlasování o něm je za tři hodiny, a jediný člověk, který ho celý přečetl, je prý stážista jménem Diaz.","c":[["Hlasování prosadit i tak, Diaz může v případě potřeby odpovídat na otázky","Přijde to na přetřes. Diaz se na chvíli stává nejmocnějším člověkem v budově."],["Hlasování odložit, dokud si to poslanci skutečně nepřečtou","Odklad je nudný. Zákon, který nakonec projde, je mnohem méně trapný."],["Přidat dalších dvě stě stran, dokud se nikdo nedívá","Diaz si žádá přidat plat. Diaz si ho, upřímně, zaslouží."],["Nechat štáb udělat z toho jeden přátelský infografický přehled","Infografika zcela záměrně vynechává několik důležitých škrtů ve financování."]]},"p-congress-21":{"t":"Hlasování v hodinu, kdy by nikdo hlasovat neměl","x":"Vedení naplánuje závěrečné hlasování na druhou hodinu ranní, sázeje na to, že polovina Kongresu bude příliš unavená, nebo příliš zaneprázdněná něčím jiným, na to, aby řádně protestovala.","c":[["Nechat termín druhé ráno a hlasy protlačit i přes únavu","Projde. Několik poslanců později tvrdí, že si vůbec nepamatují, že hlasovali."],["Přesunout hlasování na rozumnou denní hodinu","Hlasování proběhne transparentně, ve dne, jako u funkční vlády."],["Přesunout hlasování ještě později, na čtvrtou ráno, pro jistotu","Dva senátoři to celé prospí. Jejich hlasy zůstávají měsíc sporné."],["Zásobit sál neomezenou kávou, „aby to bylo férové“","Káva to férovým nedělá. Jen tím udrží všechny vzhůru, ať si mohou stěžovat."]]},"p-congress-22":{"t":"Teambuilding v nejhorší možnou chvíli","x":"Výjezdní zasedání vaší strany, které mělo posílit jednotu před klíčovým hlasováním, se zvrhlo v tříwelkou hádku kvůli nehodě na kánoi a karaoke automatu.","c":[["Zasedání zrušit a nařídit všem okamžitý návrat do Kapitolu","Vrátí se sjednoceni přesně v jedné věci: v osobní nevraživosti vůči vám."],["Nechat je to dořešit, vydiskutovat a vrátit se soudržní","Vrátí se o dva dny později, upřímně bližší než předtím. Upřímně řečeno, ohromující."],["Připojit se k zasedání osobně, „obnovit morálku“ sám","Váš výběr karaoke písně se stává nejpamátnější, a nejhorší, částí celého výjezdu."],["Poslat místo sebe motivační zpívaný telegram","Zpívaný telegram si od výjezdního sboru vyslouží víc respektu, než byste si vysloužil vy sám."]]},"p-base-1":{"t":"Pojmenujte nepřítele","x":"Interní průzkumy ukazují, že vaše základna nechce politiku, chce padoucha. Váš odborník na průzkumy drží krátký seznam jmen, který vaši spisovatelé projevů zjevně napsali po půlnoci.","c":[["Přečíst jméno z kartičky, pomalu, pro kamery","Padouch, vyděšená úřednice na radnici, dostane do oběda tři výhrůžky smrtí."],["Říct, že skutečné problémy jsou složité a nikdo jednotlivý za ně nemůže","Dav bučí přesně tím způsobem, jakým davy bučí na domácí úkol."],["Jmenovat úřednici, jejího manžela a jejich zlatého retrívra","Wikipedie retrívra je do hodiny vandalizována."],["Svalit vinu na oblak ve tvaru vašeho předchůdce","Meteorologové jsou teď považováni za součást spiknutí."]]},"p-base-2":{"t":"Zakázaný medvěd","x":"Dětskou obrázkovou knížku o medvědovi, který se dělí o med se zvířátky z lesa různého původu, označily tři facebookové skupiny za, cituji, propagandu grooming. Váš ředitel sociálních sítí chce prohlášení ještě před obědem.","c":[["Žádat stažení medvěda ze všech knihoven v zemi","Autor medvěda dostane knižní smlouvu třikrát vyšší, než byla jeho záloha."],["Říct, že je to jen kniha o medvědovi, co se dělí o med, a nechat to být","Kabelový komentátor vás obviní z toho, že jste vůči medvědům měkký."],["Žádat stažení medvěda, vyšetření autora a přejmenování medu","Prodej medu ve vašich nejsilnějších okresech se ze vzdoru ztrojnásobí."],["Oznámit, že medvěd byl tajně vyznamenaný válečný hrdina, a udělit mu milost","Medvěd, jsa fiktivní, milost vděčně přijímá."]]},"p-base-3":{"t":"Problém s merchem","x":"Váš kancléř hlásí, že internetový obchod má vyprodanou položku, která se prodává třikrát líp než cokoli jiného: hrnek s vaší tváří photoshopnutou na řvoucího orla.","c":[["Narychlo objednat padesát tisíc dalších, označit je jako limitovanou edici","Vyprodá se za jedenáct minut a několik jich dorazí už rozbitých."],["Žádat merch, který má důstojnost. Třeba slušnou sponu na kravatu","Spona se prodá čtyři kusy, všechny vašemu právníkovi."],["Přidat sesterský hrnek s plačícím soupeřem","Federální etický úřad otevře spis, který nikdy nezavře."],["Dát svou tvář na orla A na vlajku A na monster truck","Verze s monster truckem je stažena z prodeje kvůli konstrukčním důvodům, které s vaší tváří nesouvisí."]]},"p-base-4":{"t":"Skandování","x":"Dav na včerejším shromáždění bez vyzvání vymyslel skandování požadující uvěznění úřadujícího federálního soudce. Váš spisovatel projevů to zachytil na video a nemůže si to přestat pouštět dokola.","c":[["Vést skandování sám na příštím shromáždění, pomaleji, ať se může přidat každý","Soudce žádá o ochranku a dostane ji."],["Říct davu, že soudy takhle nefungují, a požádat je, ať přestanou","Vypískají vás z pódia o devět minut dřív."],["Přidat druhou sloku se jmény soudcových asistentů","Dva asistenti se potichu stáhnou z veřejného života."],["Tvrdit, že skandování ve skutečnosti mluví o maskotovi ligy nižší třídy se stejným jménem","Maskot, zmatený mýval, se odmítá vyjádřit."]]},"p-base-5":{"t":"Teorie o sklepě","x":"Podstatná část vaší základny je přesvědčena, že viceprezident je hologram ovládaný ze sklepa ve státě, který, přísně vzato, žádné sklepy nemá kvůli hladině spodní vody. Váš tiskový poradce potřebuje instrukce.","c":[["Na tiskovce na to mrkněte a nechte to bujet.","Hologramové zboží se prodává lépe než to skutečné."],["Jasně prohlaste, že viceprezident je skutečná, fyzická osoba.","Věřící usoudí, že přesně tohle by hologram řekl."],["Naznačte, že hologramy jsou možná DVA, střídají se na směny.","Sklep v onom bezesklepém státě je pod dohledem amatérů."],["Nechte skutečného viceprezidenta žonglovat naživo, aby dokázal svou tělesnost.","V přímém přenosu mu upadne kuželka a teorie se, jaksi, jen posílí."]]},"p-base-6":{"t":"Světec z parkoviště","x":"Muž, kterého mírně obtěžovali na úřadě dopravní evidence o tři státy dál, byl vaší základnou svatořečen jako mučedník hnutí, včetně svíček a hashtagu. On sám z toho vypadá zmateně. Vaše tisková mluvčí potřebuje formulaci.","c":[["Pozvěte ho na pódium a udělte mu medaili, kterou jste vymysleli před hodinou.","Medaili přijme, přestože stále netuší, co vlastně udělal."],["Jemně poznamenejte, že dlouhá fronta na úřadě není, historicky vzato, mučednictvím.","Jste obviněni z neúcty k jeho oběti."],["Vyhlaste na jeho počest státní svátek a přejmenujte úřad.","Přejmenovaný úřad má pořád dlouhou frontu."],["Odhalte, že je náhodou váš bratranec z třetího kolena.","Genealogové žádnou takovou příbuznost nenajdou, a nikdo si toho nevšímá."]]},"p-base-7":{"t":"Seznam k bojkotu","x":"Vaše základna chce bojkotovat řetězec kaváren za zločin duhového posypu na sezónním donutu. Vaše poradkyně pro vnitřní bezpečnost, zmatená, jak se jí to dostalo na stůl, vám to přesto přeposílá.","c":[["Tweetněte název řetězce a nazvěte to neamerickým donutařstvím.","Akcie řetězce den klesají, donut se vyprodá na týden."],["Řekněte, že posyp neohrožuje republiku.","Jste obviněni, že jste se postavili na stranu posypu."],["Jmenujte tři další řetězce a pekárnu, která kdysi použila duhový ubrousek.","Rodinná pekárna, fungující od roku 1962, do měsíce zavírá."],["Ohlaste rivalský, vlastenecký donut bez posypu, jen s hvězdičkami.","Hvězdičky se prý špatně prokusují."]]},"p-base-8":{"t":"Špatně složená vlajka","x":"Virální fotka ukazuje dobrovolníka na stadionu, jak skládá vlajku s, podle vaší základny, o jeden záhyb méně. Kancelář vašeho generálního prokurátora obdržela čtyřicet formálních stížností s požadavkem na federální obžalobu.","c":[["Požadujte zveřejnění jména dobrovolníka.","Sedmnáctiletý dobrovolník je na týden vyloučen ze školy."],["Řekněte, že špatné složení vlajky není zločin.","Jeden kongresman vás nazve slabým ve věcech vlajky."],["Navrhněte federální Radu pro standardy skládání vlajky s pravomocí předvolávat svědky.","První slyšení rady trvá čtyři hodiny navíc kvůli jedinému záhybu."],["Osobně přeskládejte vlajku v přímém přenosu, špatně, ale sebevědomě.","Nikdo se neodváží zmínit, že vaše má stejný počet záhybů."]]},"p-base-9":{"t":"Zmizelý betlém","x":"Nákupní centrum o tři státy dál nahradilo svůj betlém obyčejným vánočním stromkem a vaše základna to považuje za zahajovací bitvu koordinovaného národního útoku na samotné svátky.","c":[["Vyhlaste nouzový stav Válka o Vánoce a požadujte navrácení betléma.","Centrum betlém vrátí a hlásí rekordní návštěvnost."],["Poznamenejte, že obchodní centra mění výzdobu každý rok a vždy tomu tak bylo.","Jste obviněni, že nenávidíte Vánoce i obchodní centra."],["Vyžadujte přísahu věrnosti od každého maloobchodníka ohledně sváteční výzdoby.","Nafukovací sněhulák jednoho železářství je vyšetřován pro nedostatečnou úctu."],["Osobně přivezte betlém do centra na valníku, naživo.","Jeden z tří králů poblíž food courtu spadne."]]},"p-base-10":{"t":"Žába v obleku","x":"Kreslená žába v obleku a kravatě jako vy se stala neoficiálním maskotem vašeho hnutí, objevuje se na vlajkách, tetováních i na dodávce jednoho velmi odhodlaného muže. Váš syn to považuje za skvělé a chce to zoficiálnit.","c":[["Přijměte žábu jako oficiálního maskota kampaně.","Žabí zboží do týdne překoná to vaše skutečné."],["Řekněte, že politické hnutí by nemělo zastupovat kreslená žába.","Základna usoudí, že vy osobně nejste žábin největší fanoušek, a to je podezřelé."],["Nechte žábu vystoupit na příštím mítinku v plném kostýmu a mávat.","Dítě v první řadě pláče, ze strachu nebo z nadšení, není jasné."],["Nechte si žábu právně ochránit ochrannou známkou, než na ní vydělá někdo jiný.","Během pár dní přichází žaloba od nesouvisející značky žabích cereálií."]]},"p-base-11":{"t":"Zjevně příliš umírněný","x":"Neznámý poslanec zastupitelstva má v primárkách, které nikdo nevypsal, šest procent proti vám a kandiduje napravo od vás na programu, který váš stratég popisuje jen jako hlasitější.","c":[["Útočte na něj osobně, každou noc, dokud nezmizí.","Jeho sbírka peněz se díky té pozornosti ztrojnásobí."],["Ignorujte ho a soustřeďte se na vládnutí.","Základna usoudí, že mlčení znamená, že má pravdu."],["Předběhněte ho politikou tak extrémní, že to i on nazve extrémismem.","Obrátí se a nazve vás napodobitelem, správně."],["Nabídněte mu vymyšlené velvyslanectví v zemi bez pobřeží.","Nadšeně přijme a už o něm nikdy nikdo neuslyší."]]},"p-base-12":{"t":"Pastor Combs chce laskavost","x":"Pastor Combs z dvanáctitisícové arény Liberty Now Arena Church je připraven vás v neděli podpořit z kazatelny. Rád by si ale promluvil o územní výjimce pro svou novou parkovací budovu.","c":[["Potichu schvalte výjimku a přijměte podporu.","Parkovací budova vyroste vedle mokřadu, o kterém už nikdo nikdy nemluví."],["Odmítněte laskavost a požádejte o podporu na základě jejích vlastních zásluh.","Pastor Combs se slzami v očích podpoří vašeho protikandidáta v primárkách."],["Schvalte výjimku, plus daňovou úlevu, plus druhou parkovací budovu.","Mokřad je teď oficiálně parkovací budova."],["Požádejte pastora Combse, aby vás znovu pokřtil, na pódiu, kvůli sledovanosti.","Voda byla podle několika svědků podezřele teplá."]]},"p-base-13":{"t":"Test loajality","x":"Prominentní příznivec zveřejnil online test čistoty o dvanácti otázkách. Váš viceprezident v něm získal osm z dvanácti bodů a lidé, kteří neumí definovat slovo měkkýš, ho tak nyní nazývají.","c":[["Vyplňte test veřejně a odpovídejte na každou otázku s maximální extrémností.","Získáte dvanáct z dvanácti a mírně vyděsíte vlastní personál."],["Řekněte, že testy čistoty rozkládají jakoukoli skutečnou koalici.","Autor testu napíše jízlivou reakci nazvanou Já Vám To Říkal."],["Zveřejněte VLASTNÍ test o třiceti otázkách a nechte viceprezidenta test opakovat.","Tentokrát skóruje ještě hůř, na testu, který jste napsali sami."],["Prohlaste samotný test za operaci hlubokého státu a požadujte jeho stažení.","Návštěvnost testu se přes noc zečtyřnásobí."]]},"p-base-14":{"t":"Pověst","x":"Váš tiskový asistent slyšel, z druhé ruky, že se mezi základnou šíří pověst, že jste ve dvaceti letech osobně zápasili s pumou a porazili ji. Není to pravda. Chce vědět, co s tím má dělat.","c":[["Nic nepotvrzujte ani nevyvracejte a nechte legendu růst.","Pamětní mince s pumou se čile prodává."],["Vydejte prosté, nudné popření. Nikdy jste s pumou nezápasili.","Popření samo je bráno jako další důkaz, že se souboj konal."],["Potvrďte to, přidejte medvěda a řekněte, že jste medvěda ze soucitu nechali žít.","Organizace na ochranu zvěře vás zdvořile žádá, abyste přestal."],["Předveďte svědka, starého muže, který tvrdí, že u toho byl.","Svědek si nevzpomíná, na které hoře k tomu vlastně došlo."]]},"p-base-15":{"t":"Falešná zpráva","x":"Vymyšlený titulek tvrdící, že váš protikandidát chce zdanit dešťovou vodu, se šíří vaší základnou tempem, které váš ředitel sociálních sítí obdivně nazývá bezprecedentní.","c":[["Sdílejte to sami s poznámkou někteří lidé říkají.","Oprava od ověřovatele faktů dosáhne jen desetiny záběru falešné zprávy."],["Veřejně uveďte věc na pravou míru. Nikdo dešťovou vodu nezdaňuje.","Jste obviněni z ověřování faktů proti vlastní straně, což je kardinální hřích."],["Přidejte navazující tvrzení, že chce zdanit i SNÍH.","Meteoroložka je v obchodě s potravinami napadena z důvodů, které se nikdy nedozví."],["Tvrďte, že jste osobně zachytili zákon o dani z dešťové vody a roztrhali ho.","Žádný takový zákon nikdy neexistoval, detail, na který se nikdo neptá."]]},"p-base-16":{"t":"Zákaz slova","x":"Slovo, dříve zcela nevýrazné, prohlásila jedna frakce vaší základny za urážlivé poté, co ho ve svém projevu použil politický soupeř. Váš právník potřebuje vědět, zda federální vláda může slovo skutečně zakázat. Nemůže.","c":[["Oznamte, že zvažujete všechny právní možnosti, jak ho zakázat.","Vyhledávání slova ve slovníku vzroste o devět set procent."],["Trpělivě vysvětlete, že existuje první dodatek ústavy.","Jste obviněni, že to slovo osobně milujete."],["Zakažte slovo ve federálních budovách i jeho blízká synonyma.","Tezaurus je krátce, docela vážně, považován za kontraband."],["Vymyslete nové slovo jako náhradu a nařiďte jeho používání ve svých projevech.","Nikdo, včetně vás, ho neumí vyslovovat pokaždé stejně."]]},"p-base-17":{"t":"Buck chce požehnání","x":"Vůdce milice, který si říká Buck, se objevil už na třech mítincích s dvěma tucty ozbrojených mužů ve stejných vestách a rád by od vás dostal veřejné uznání. Vaše zástupkyně pro záležitosti veteránů, sama veteránka, je z toho nesvá.","c":[["Ze pódia Bucka pochvalte jako skutečné vlastence.","Buckova skupina se do měsíce ztrojnásobí."],["Odmítněte Buckovu skupinu jakkoli uznat.","Buck vás do mikrofonu na livestreamu nazve podvodníkem."],["Pozvěte Buckovy muže, aby sloužili jako neoficiální ostraha mítinku.","Novinář je krátce zadržen muži, kteří k tomu nemají žádnou zákonnou pravomoc."],["Udělte Buckovi čestný titul bez skutečné moci, třeba Polní maršál v.v.","Buck si do hodiny nechává vytisknout vizitky."]]},"p-base-18":{"t":"Velká latte panika","x":"Váš stratég hlásí sílící přesvědčení mezi základnou, že pobřežní elity potichu rozmisťují pražírny řemeslné kávy do každého města v zemi, aby, slovy jednoho respondenta, nahradily skutečné Američany lidmi, kteří říkají artisanal.","c":[["Na příštím mítinku ponuře varujte před kávou, která si jde po jejich jídelnách.","Jídelna o tři města dál hlásí čtyřicetiprocentní nárůst prodeje kávy, ironicky ze zvědavosti."],["Poukažte, že kavárny ve skutečnosti nejsou demografickou hrozbou.","Jste obviněni, že jste se postavili na stranu ovesného mléka."],["Navrhněte clo na nadutá nápoje podle definice výboru, který sami jmenujete.","Výbor se nedokáže shodnout, co je nadutost, a věnuje tématu sedm zasedání."],["Otevřete si na příštím mítinku rivalský stánek s jídelní kávou, deset dolarů za šálek.","Vyprodá se, přesně za cenu, ze které si dělal legraci."]]},"p-base-19":{"t":"Vyhoďte toho intelektuála","x":"Vysoce kvalifikovaná poradkyně z ministerstva zahraničí na briefingu třikrát použila slovo nuance. Vaše základna ji chce mít pryč do západu slunce.","c":[["Veřejně ji vyhoďte a jako důvod uveďte její elitářskou slovní zásobu.","Další tři přijatí na ministerstvu jsou znatelně horší ve své práci a mnohem hlasitější."],["Nechte ji. Nuance, poznamenáte, je v zahraniční politice obecně užitečná.","Rozhlasový moderátor stráví celou reláci zesměšňováním samotného slova nuance."],["Vyhoďte ji a pak i dva kolegy, kteří se jí zastali.","Zbylý personál ministerstva ze samé opatrnosti přestává na poradách používat víceslabičná slova."],["Přesuňte ji do kanceláře bez oken, ať studuje jednu extrémně nevýznamnou smlouvu.","Dokončí o ní definitivní zprávu, kterou si nikdo nikdy nepřečte."]]},"p-base-20":{"t":"Patnáctimetrový vy","x":"Občanský výbor, devět lidí, jeden z nich váš bratranec, vybral z drobných darů dost na patnáctimetrovou sochu vás na dálničním odpočívadle. Váš šéf kanceláře potřebuje rozhodnutí o odhalení.","c":[["Zúčastněte se odhalení a nechte se vyfotit u paty sochy.","Několik řidičů hlásí, že výraz sochy je z jistých úhlů dálnice znepokojivý."],["Požádejte je, ať peníze místo toho věnují na opravu silnic.","Výbor je zmatený a mírně dotčený."],["Schvalte sochu plus druhou na hranici státu, mávající.","Mávající ruka sochy se při bouři do měsíce utrhne."],["Požádejte, aby socha byla o pět metrů vyšší, než se původně plánovalo.","Nyní vyžaduje vlastní územní výjimku, která je samozřejmě udělena."]]},"p-base-21":{"t":"Tvář na jeho paži","x":"Superfanoušek si nechal na předloktí vytetovat překvapivě věrný portrét vašeho obličeje a právě teď stojí u zábrany, s vyhrnutým rukávem, v naději, že si toho všimnete. Váš asistent si není jistý, že je tohle normální.","c":[["Podepište to tetování přímo, permanentní fixou, v přímém přenosu.","Tetovací salon o tři státy dál hlásí náhlý, velmi konkrétní nárůst zákazníků."],["Zdvořile mu řekněte, že to je na politika docela závazek.","Vypadá opravdu zraněně, a nějak tak i celá základna."],["Pozvěte ho na pódium, ať tetování ukáže celé aréně.","Do rána si stejný motiv nechá udělat čtyřicet lidí u stejného tatéra."],["Nechte si na oplátku udělat malé, nenápadné tetování jeho tváře.","Podle všech je to, se vší úctou, dost špatná podobizna."]]},"p-base-22":{"t":"Vůdce skandování chce místo v kabinetu","x":"Muž, který vede skandování davu na úplně každém mítinku už rok, funkce bez formálního titulu a bez kvalifikací kromě obrovského hlasu, by rád byl zvažován na post ministra něčeho. Váš syn to považuje za skvělý nápad.","c":[["Jmenujte ho do skutečné funkce v kabinetu s kamennou tváří.","Jeho první politické memorandum je, slovo od slova, pokřik."],["Poděkujte mu za službu a vysvětlete, že práce vyžaduje přinejmenším relevantní zkušenosti.","To odpoledne vede dav v pokřiku o vaší nevděčnosti."],["Jmenujte ho A udělejte ze skandování oficiální vládní funkci s vlastním rozpočtem.","Úřad pro vedení skandování si do týdne žádá další personál."],["Jmenujte ho čestným Vícevůdcem skandování a nechte skutečné místo neobsazené.","Je nadšený; nikdo neumí vysvětlit, co ten titul znamená."]]},"p-pardon-1":{"t":"Kruh zakladatele","x":"Právní zástupce vysvětluje, že Trevor Bulwark, zakladatel zkrachovalého penzijního fondu Pinnacle Retirement Trust, vyvedl osmdesát milionů dolarů z penzí důchodců, aby si koupil flotilu vodních skútrů. \"Říká, že je duchovně napravený,\" poznamenává právník. \"Také říká, že by chtěl zpátky svou jachtu.\"","c":[["Podepište milost","Bulwark otevírá Pinnacle Retirement Trust Dva pod mírně pozměněným logem."],["Odmítněte, ať se potí","Důchodci dostanou zpět zlomek svých peněz a přísně formulovaný dopis."],["Udělte milost a jmenujte ho ředitelem pro bezpečnost důchodů","Jeho první politické memorandum doporučuje víc vodních skútrů pro všechny."],["Udělte mu milost, ale musí každému důchodci osobně vrátit peníze u bankomatu, naživo","Přenos má víc diváků než projev o stavu unie."]]},"p-pardon-2":{"t":"Prostředí bohaté na cíle","x":"Generální prokurátor čte spis generála Marcuse Thorna, odsouzeného za nařízení útoku na svatbu, kterou nazval \"bohatou na cíle\". Thornův dopis o milost má čtyři strany stížností a jednu fotku, na které salutuje. \"Je oblíbený u základny,\" říká prokurátor, \"tak jako je oblíbený ohňostroj.\"","c":[["Podepište milost","Thorne pořádá uvítací mítink v bowlingové hale, kterou trvá na tom, že je \"strategicky významná.\""],["Odmítněte","Rodiny obětí vydávají prohlášení. Skoro nikdo si ho nepřečte."],["Udělte milost a jmenujte ho zvláštním vyslancem pro mír","Jeho první čin v zahraničí je, že se ministra zeptá, jestli \"chce problémy.\""],["Udělte mu milost pod podmínkou, že napíše omluvné paměti","Paměti se čile prodávají pod názvem \"Udělal bych to znovu, asi.\""]]},"p-pardon-3":{"t":"Přítel rodiny","x":"Sal Marchetti, odsouzený v jedenácti bodech za organizovaný zločin, byl podle žádosti o milost, kterou mu určitě nepsal jeho právník, po desetiletí \"drahým přítelem a štědrým podporovatelem\". \"Posílá pozdravy,\" říká právník, \"a velmi velkou šunku.\"","c":[["Podepište milost","Šunka byla ve skutečnosti nacpaná hotovostí. Nikdo se neptá, odkud ty peníze jsou."],["Odmítněte","Marchettiho společníci vyjadřují nespokojenost skrze několik malých, popiratelných požárů."],["Udělte milost a jmenujte ho velvyslancem na Maltě","Maltská vláda podává formální, nesmírně zdvořilou stížnost."],["Udělte mu milost výměnou za rodinný recept na calzone","Recept je skutečný. Je také, nezaměnitelně, výhrůžkou."]]},"p-pardon-4":{"t":"Slon v porcelánu","x":"Šerif \"Bull\" Haney podstrkoval důkazy desítkám obžalovaných a provozoval soukromou mýtnou budku pro řidiče bez dokladů projíždějící jeho okresem. Jeho příznivci tomu říkají \"policejní práce staré školy\". Předseda Nejvyššího soudu tomu říká několik federálních zločinů. \"Chce zpátky svůj odznak,\" říká předseda, \"konkrétně.\"","c":[["Podepište milost","Bull dostane zpátky odznak a tričko s nápisem \"Znovu ve službě.\""],["Odmítněte","Jeho oběti konečně dostanou slyšení, které není zmanipulované."],["Udělte milost a jmenujte ho pohraničním carem","Do týdne se objeví mýtné budky na třech dalších okresních hranicích."],["Udělte mu milost, přeřaďte ho k hlídání dárkového obchodu Bílého domu","Je, znepokojivě, velmi dobrý v prodeji hrnečků."]]},"p-pardon-5":{"t":"Offshore a na vaší straně","x":"Chip Renfro, velký dárce, ukryl před finančním úřadem zhruba dvě miliardy dolarů v devíti krycích firmách pojmenovaných podle jeho golfového handicapu. \"Rád by to nazval chybou ve výkazu,\" říká prokurátor, \"chybou ve výkazu za dvě miliardy dolarů.\"","c":[["Podepište milost","Renfro okamžitě otevírá desátou krycí firmu, tentokrát pojmenovanou podle vaší popularity."],["Odmítněte","Finanční úřad skutečně jednou vybere daně a nikdo mu nepoděkuje."],["Udělte milost a jmenujte ho poradcem ministerstva financí pro zjednodušení daní","Jeho plán zjednodušení má jednu stránku a prospívá přesně jednomu daňovému poplatníkovi."],["Udělte mu milost výměnou za \"manipulační poplatek\" deset procent","Je to podle jakékoli definice úplatek. Je to ale také, technicky, zpracované."]]},"p-pardon-6":{"t":"Na Měsíc a zpátky do vězení","x":"Dex Bramwell vytáhl peníze čtyřiceti tisícům investorů svým tokenem CoinDaddy a pak si koupil ponorku. \"Říká, že ta technologie předběhla svou dobu,\" hlásí váš syn se širokým úsměvem. \"Také říká, že vás nechá vydělat na CoinDaddy Dva.\"","c":[["Podepište milost","CoinDaddy Dva startuje do hodiny. Do dne se zhroutí."],["Odmítněte","Čtyřicet tisíc lidí dostane zhruba jedenáct centů každý a jedno ponaučení."],["Udělte milost a jmenujte ho krypto carem","Jeho první regulační pokyn je jediné emoji rakety."],["Přijměte poplatek za milost celý zaplacený jeho bezcennou mincí","Mince do večera nemá žádnou hodnotu. Ponorka je, jaksi, skutečná."]]},"p-pardon-7":{"t":"Mrazák plný dvacetidolarovek","x":"Kongresman Delbert Cranch byl přistižen se čtyřmi sty tisíci dolary v hotovosti nacpanými v kuchyňském mrazáku, zabalenými, jak trvá na tom, \"kvůli čerstvosti\". Tisková mluvčí čte žádost o milost nahlas s viditelnou fyzickou nevolností.","c":[["Podepište milost","Cranch si kupuje druhý, větší mrazák."],["Odmítněte","Cranch je vyloučen z kongresu a podle všeho vystěhován kvůli účtu za opravu mrazáku."],["Udělte milost a jmenujte ho předsedou etické komise","Jeho úvodní slovo je, jaksi, o správné organizaci mrazáku."],["Udělte mu milost, ale mrazák putuje do Smithsonova muzea","Je nyní nejnavštěvovanějším exponátem muzea."]]},"p-pardon-8":{"t":"Rodinný podnik","x":"Váš bratranec Wade předstíral vlastní únos kvůli pojistnému plnění a pak zveřejnil fotky ze \"zajetí\" z letoviska v Cabu. \"Říká, že rodina drží pohromadě,\" hlásí váš syn. \"Také říká, že letovisko má skvělý bar u bazénu.\"","c":[["Podepište milost","Wade vám na Díkůvzdání hlasitě poděkuje před kamerami, které jste nepozvali."],["Odmítněte","Wade si odsedí skutečný trest. Rodinná skupinová konverzace mlčí měsíc."],["Udělte milost a udělejte z něj regionálního styčného úředníka FEMA","Jeho první krizový briefing obsahuje podezřele mnoho doporučení baru u bazénu."],["Udělte mu milost, ale musí naživo předstírat, že ho tentokrát opravdu našli živého","Sledovanost je vynikající. Důvěryhodnost není."]]},"p-pardon-9":{"t":"Sleva ze skladu důkazů","x":"Detektiv Ray Kessler podstrkoval důkazy podezřelým, které neměl rád, a bral hotovost od kartelu za ty, které měl. Ředitel FBI mu přes stůl podává spis. \"Žádá o úplnou milost a, chci to zdůraznit, o své staré parkovací místo.\"","c":[["Podepište milost","Kessler dostane odznak, místo a okamžitě nového klienta."],["Odmítněte","Devět nespravedlivých odsouzení je díky jeho případu znovu otevřeno."],["Udělte milost a jmenujte ho šéfem interního vyšetřování","Stížnosti na interní vyšetřování vůči interním vyšetřovatelům se zečtyřnásobí."],["Udělte mu milost, natrvalo ho přeřaďte na inventarizaci skladu důkazů","Ukáže se, že je mimořádně dobrý v třídění ukradeného zboží."]]},"p-pardon-10":{"t":"Obležení soudu","x":"Plukovník Gid Strother držel okresní soud pod hlavní zbraně šest hodin kvůli sporu o územní plán. Viceprezident osobně doručuje žádost o milost, z nevysvětlených důvodů v maskáčové kravatě. \"Jeho muži ho milují,\" říká viceprezident. \"Stejně tak průzkumy.\"","c":[["Podepište milost","Strother pořádá vítězný mítink u stejného soudu, znovu ozbrojený."],["Odmítněte","Úřednice soudu, kterou ohrožoval, konečně může v klidu spát."],["Udělte milost a jmenujte ho oficiálním styčným důstojníkem pohraniční milice","Do měsíce hlásí tři další soudy podobné \"spory o územní plán.\""],["Udělte mu milost pod podmínkou, že jeho milice přejde na soutěžní patchwork","Přikrývky jsou, proti všem očekáváním, docela dobré."]]},"p-pardon-11":{"t":"Buvol se vrací","x":"Chad \"Buvol\" Merkins zaútočil na Kapitol s rohy na hlavě a vestou, na které nic konkrétního nestálo. Stal se lidovým hrdinou lidí, kteří na dvorku vlastní aspoň jednu vlajku na tyči. \"Chce zpátky své rohy z úschovy důkazů,\" říká váš tiskový asistent. \"Chybí mu.\"","c":[["Podepište milost","Rohy jsou vráceny. Merkins je nosí na brunch."],["Odmítněte","Merkins si odsedí trest a napíše z vězení ostře formulované, plné pravopisných chyb paměti."],["Udělte milost a udělejte z něj oficiálního průvodce po Kapitolu","Jeho prohlídka zahrnuje podrobnou rekonstrukci. Dvakrát denně. S rohy."],["Udělte mu milost a pak prodávejte rohy jako oficiální merchandise","Vyprodá se za hodinu. Merkins požaduje tantiémy."]]},"p-pardon-12":{"t":"Přirážka na inzulin","x":"Marlon Vance, generální ředitel farmaceutické firmy a spolehlivý dárce kampaně, ztrojnásobil ceny inzulinu během nedostatku, který sám osobně vyvolal. Jeho dopis o milost to popisuje jako \"reaktivní cenotvorbu\". Šéf personálu to soukromě nazývá \"zločinem s prezentací.\"","c":[["Podepište milost","Vance okamžitě oznamuje \"reaktivní cenotvorbu\" pro tři další léky."],["Odmítněte","Ceny inzulinu skutečně klesnou. Vance to nazve \"zásahem státu.\""],["Udělte milost a jmenujte ho poradcem pro zdravotní náklady","Jeho doporučení na snížení nákladů je, jaksi, vyšší ceny."],["Udělte mu milost, ale týden musí sám rozvážet inzulin od dveří ke dveřím","Nesnáší každou vteřinu. Fotky jsou ovšem skvělé."]]},"p-pardon-13":{"t":"Poslední z orlů","x":"Duke Callahan zastřelil poslední hnízdící pár chráněné kolonie orlů bělohlavých, protože, jeho slovy, \"jeden z nich se na mě divně díval\". Dokonce i pastor se cítí nesvůj, když tlumočí jeho žádost. \"Žádá o odpuštění,\" říká pastor, \"a o svou pušku zpátky.\"","c":[["Podepište milost","Callahan dostane pušku zpátky. Kolonie orly zpátky nedostane."],["Odmítněte","Ochránci přírody to nazývají vzácným vítězstvím. Callahan to nazývá \"pronásledováním.\""],["Udělte milost a jmenujte ho komisařem pro divokou zvěř","Jeho první politický návrh zkracuje seznam ohrožených druhů tím, že z něj druhy odstraňuje."],["Udělte mu milost, ale na každém mítinku musí nosit orlí kostým","Nosí ho. Nesnáší to. Dav ho, znepokojivě, miluje."]]},"p-pardon-14":{"t":"Fond na archu","x":"Reverend Silas Thorpe přesvědčil svou kongregaci, aby mu odevzdala své penzijní úspory na stavbu skutečné, plavbyschopné archy, a pak za peníze koupil menší, neplavbyschopnou jachtu. \"Říká, že Pán se pohybuje tajemnými cestami,\" povzdechne si pastor. \"Většinou směrem k jeho jachtě.\"","c":[["Podepište milost","Thorpe oznamuje Fond na archu Dva, \"tentokrát se skutečnou lodí.\""],["Odmítněte","Jeho kongregace dostane náhradu a konečně i trochu skepse."],["Udělte milost a jmenujte ho poradcem pro víru při administrativě","Jeho první kázání pro personál je nezaměnitelně sbírkovou kampaní."],["Udělte mu milost výměnou za osobní požehnání","Požehnání je nezvykle konkrétní a zahrnuje desátek."]]},"p-pardon-15":{"t":"Devatenáct let","x":"Odell Pruitt si odseděl devatenáct let za loupež, kterou nyní DNA důkazy prokazují, že nespáchal. Jeho právnička, nezvykle mlčenlivá, jen přisune přes stůl složku. \"Není v tom žádný chytrý úhel pohledu,\" říká. \"Je prostě nevinný.\"","c":[["Nechte ho tam, kde je","Základna jásá nad \"pořádkem a zákonem\". Pruitt zůstává v cele, která nikdy neměla být jeho."],["Propusťte ho","Pruitt vychází ven do světa, který je o devatenáct let jinde. Základna to nazývá měkkostí."],["Potichu mu zmírněte trest, bez zásluh, bez tiskové zprávy","Je volný, ale záznam ho pořád vede jako odsouzence. Nikdo si toho stejně nevšimne."],["Propusťte ho, ale jen pokud vám osobně na kameru poděkuje","Udělá to skrz zaťaté zuby. Devatenáct let koupilo velmi krátký proslov."]]},"p-pardon-16":{"t":"Kvůli pojistce","x":"Nadia Volkovová vypálila vlastní dům s regulovaným nájemným kvůli pojistnému plnění a při tom vystěhovala čtyřicet rodin. Předseda Nejvyššího soudu prochází spis s nevzrušeným výrazem. \"Ona tomu říká 'zpoždění renovace,'\" říká.","c":[["Podepište milost","Volkovová si kupuje druhou budovu. Zasvěcení očekávají druhý požár."],["Odmítněte","Čtyřicet rodin dostane náhradu. Volkovová dostane, co si zaslouží."],["Udělte milost a jmenujte ji do komise pro dostupné bydlení","Její první doporučení se týká zápalek, metaforicky, jak trvá na tom."],["Udělte jí milost pod podmínkou, že dům vlastnoručně znovu postaví","Ukáže se, že je opravdu mizerná tesařka."]]},"p-pardon-17":{"t":"Interní zpráva","x":"Ingrid Halvorsenová vynesla interní zprávu dokazující, že firma zakryla kontaminaci pitné vody, a byla odsouzena za \"krádež majetku vlády\" za papír, na kterém byla vytištěna. \"Neexistuje verze, ve které je záporák,\" přiznává váš mluvčí pro projevy, \"což je pro projev problém.\"","c":[["Nechte ji shnít","Základna ji nazve zrádkyní. Voda je pořád kontaminovaná."],["Propusťte ji","Halvorsenová vychází na svobodu a okamžitě pokračuje v odhalování. Základna zuří."],["Potichu jí udělte milost, bez tiskové zprávy, bez zásluh","Je volná. Nikdo z vaší základny se to nikdy nedozví, o to jde."],["Propusťte ji, ale utajte fakt, že jste to udělal","Milost je skutečná. Papíry, které to dokazují, oficiálně neexistují."]]},"p-pardon-18":{"t":"Kotec","x":"Chester Voss, spolehlivý dárce, provozoval ve stodole, kterou ve sbírkových e-mailech popisoval jako \"wellness ústraní\", psí zápasy. Generální prokurátorka čte obžalobu s viditelným odporem. \"Rád by to měl z krku před volbami v polovině období,\" říká.","c":[["Podepište milost","Voss stodolu znovu otevírá. Cedule teď hlásá \"wellness ústraní, fáze dvě.\""],["Odmítněte","Psi jsou umístěni do nových domovů. Vossovy sbírkové e-maily citelně utichnou."],["Udělte milost a jmenujte ho poradcem pro rozvoj venkova","Jeho první návrh zahrnuje federální dotace na \"wellness ústraní.\""],["Udělte mu milost pod podmínkou, že si osobně adoptuje každého psa","Nyní vlastní čtyřicet psů a podle všeho nesnáší úplně každého z nich stejnou měrou."]]},"p-pardon-19":{"t":"Eunice","x":"Eunice Radleyová, sedmdesát osm let, si odpykává doživotní trest za prodej malého množství marihuany podle zákona, který mezitím zrušili všude kromě jejího spisu. \"Nežádá o peníze ani o titul,\" poznamenává předseda Nejvyššího soudu. \"Jen chce znovu vidět svou zahradu.\"","c":[["Nechte ji tam, kde je","Základna tleská tvrdosti. Eunice zmešká další narozeniny za mřížemi."],["Propusťte ji","Eunice znovu uvidí svou zahradu. Základna reptá o \"měkkosti vůči zločinu.\""],["Propusťte ji jen pokud vám na kameru poděkuje","Udělá to, zdvořile, se slzami, které nejsou zcela vděčné."],["Propusťte ji a pak si ji najměte, ať peče pro Bílý dům","Její koláč je podle jednomyslného hlasování personálu lepší než ten od kuchaře Bílého domu."]]},"p-pardon-20":{"t":"Dokonalejší padělek","x":"Percival Ott prodal třem muzeím padělaný koncept Deklarace nezávislosti, ručně zestárlý čajovými sáčky a údajně opravdovou láskou k řemeslu. \"Není mu to líto,\" hlásí mluvčí pro projevy. \"Je na to hrdý. Chce, aby to bylo v milosti výslovně uvedeno.\"","c":[["Podepište milost","Ott okamžitě začíná pracovat na padělané Listině práv."],["Odmítněte","Muzea dostanou své peníze zpět. Ott dostane skutečný, nefalšovaný trest."],["Udělte milost a jmenujte ho kurátorem Národního archivu","Návštěvnost stoupá. Stejně tak, potichu, i počet padělků v archivu."],["Udělte mu milost, ale musí místo toho zfalšovat lichotivou biografii o vás","Stává se bestsellerem. Historikové poznamenávají, že je to přinejmenším ze sedmdesáti procent fikce."]]},"p-pardon-21":{"t":"Stál u popelnice","x":"Marcus Ibe byl obviněn z domácího terorismu za to, že stál poblíž hořící popelnice na pokojném shromáždění, které nezaložil a snažil se uhasit. \"Uhasil ten oheň,\" říká ředitel FBI. \"Je to ve zprávě. Tu část si nikdo nepřečetl.\"","c":[["Nechte ho shnít","Základna ho nazve hrozbou. Zůstává ve vězení za uhašení požáru popelnice."],["Propusťte ho","Ibe vychází na svobodu. Základna trvá na tom, že to dokazuje, že systém je \"nastaven ve prospěch zločinců.\""],["Potichu ho propusťte, ale obvinění z terorismu zůstává v jeho záznamu","Je venku, ale každá prověrka po zbytek jeho života ho označí jako hrozbu."],["Propusťte ho a nabídněte mu reality show o tom všem","Pilotní díl se jmenuje \"Požár v popelnici\". Dostane objednávku na celou sezónu."]]},"p-pardon-22":{"t":"Doktor cukrových pilulek","x":"Doktor Warrick Slate prodal tisícům onkologických pacientů chemoterapeutické pilulky, které podle laboratorního rozboru byly převážně cukr. \"Nazývá to 'obchodním modelem blízkým placebu,'\" čte jeho právník nahlas a pak papír odloží, jako by byl radioaktivní.","c":[["Podepište milost","Slate do týdne ohlašuje novou řadu pilulek \"blízkých wellness.\""],["Odmítněte","Oběti se konečně dočkají svého dne u soudu a svých peněz zpět."],["Udělte milost a jmenujte ho do poradního sboru úřadu pro potraviny a léčiva","Jeho první hlas je proti přísnějším požadavkům na označování pilulek."],["Udělte mu milost pod podmínkou, že nejdřív sní vlastní pilulky","Bez váhání je sní. To vypovídá o všem."]]}};
